return {
  ["00:26f2"] = "Object event",
  ["03:4d41"] = "{STRBUF} used\nSTRENGTH!",
  ["03:4d46"] = "{STRBUF} can\nmove boulders.",
  ["03:4d69"] = "A POKéMON may be\nable to move this.\012Want to use\nSTRENGTH?",
  ["03:4d6e"] = "Boulders may now\nbe moved!",
  ["03:4d73"] = "A POKéMON may be\nable to move this.",
  ["03:4f58"] = "{STRBUF} used\nROCK SMASH!",
  ["03:4f72"] = "Maybe a POKéMON\ncan break this.",
  ["03:4f77"] = "This rock looks\nbreakable.\012Want to use ROCK\nSMASH?",
  ["09:6f9b"] = "It's the TOWN MAP.",
  ["09:6fa3"] = "It's a poster of a\ncute PIKACHU.",
  ["09:6fab"] = "It's a poster of a\ncute CLEFAIRY.",
  ["09:6fb3"] = "It's a poster of a\ncute JIGGLYPUFF.",
  ["09:6fd8"] = "It's an adorable\n{STRBUF}.",
  ["09:6fe6"] = "A giant doll! It's\nfluffy and cuddly.",
  ["15:4122"] = "Hi! I'm WHITNEY!\012Everyone was into\nPOKéMON, so I got\011into it too!\012POKéMON are\nsuper-cute!\012You want to bat-\ntle? I'm warning\011you--I'm good!",
  ["15:41a5"] = "Sob…\012…Waaaaaaah!\nYou're mean!\012You shouldn't be\nso serious! You…\011you child, you!",
  ["15:41f4"] = "Waaaaah!\012Waaaaah!\012…Snivel, hic…\n…You meanie!",
  ["15:4222"] = "…Sniff…\012What? What do you\nwant? A BADGE?\012Oh, right.\nI forgot. Here's\011PLAINBADGE.",
  ["15:4273"] = "{PLAYER} received\nPLAINBADGE.",
  ["15:428b"] = "PLAINBADGE lets\nyour POKéMON use\012STRENGTH outside\nof battle.\012It also boosts\nyour POKéMON's\011SPEED.\012Oh, you can have\nthis too!",
  ["15:4302"] = "It's ATTRACT!\nIt makes full use\012of a POKéMON's\ncharm.\012Isn't it just per-\nfect for a cutie\011like me?",
  ["15:4360"] = "Ah, that was a\ngood cry!\012Come for a visit\nagain! Bye-bye!",
  ["15:439b"] = "Don't let my\nPOKéMON's cute\012looks fool you.\nThey can whip you!",
  ["15:43d6"] = "Darn… I thought\nyou were weak…",
  ["15:43f6"] = "Do my POKéMON\nthink I'm cute?",
  ["15:4411"] = "I like cute POKé-\nMON better than\011strong POKéMON.\012But I have strong\nand cute POKéMON!",
  ["15:445f"] = "Oh, no, no, no!",
  ["15:4470"] = "I'm trying to beat\nWHITNEY, but…\011It's depressing.\012I'm okay! If I\nlose, I'll just\012try harder next\ntime!",
  ["15:44d4"] = "Oh, no. You made\nWHITNEY cry.\012It's OK. She'll\nstop soon. She\012always cries when\nshe loses.",
  ["15:452d"] = "Oh, you are a cute\nlittle trainer! \012I like you, but I\nwon't hold back!",
  ["15:4574"] = "Let's see… Oops,\nit's over?",
  ["15:458f"] = "Wow, you must be\ngood to beat me!\011Keep it up!",
  ["15:45be"] = "Give it your best\nshot, or I'll take\011you down!",
  ["15:45ed"] = "No! Oh, MEOWTH,\nI'm so sorry!",
  ["15:460b"] = "I taught MEOWTH\nmoves for taking\011on any type…",
  ["15:463a"] = "Yo! CHAMP in\nmaking!\012This GYM is home\nto normal-type\011POKéMON trainers.\012I recommend you\nuse fighting-type\011POKéMON.",
  ["15:46a7"] = "You won? Great! I\nwas busy admiring\011the ladies here.",
  ["15:4787"] = "…sigh… I moved\nhere, but I can't\012sell my BICYCLES.\nWhy is that?\012Could you ride a\nBICYCLE and adver-\011tise for me?",
  ["15:47f8"] = "Really? Great!\012Give me your name\nand phone number,\012and I'll loan you\na BICYCLE.",
  ["15:4848"] = "{PLAYER} borrowed a\nBICYCLE.",
  ["15:485f"] = "My BICYCLES are\nfirst-rate! You\012can ride them\nanywhere.",
  ["15:4898"] = "…sigh… Oh, for\nthe kindness of\011people…",
  ["15:48ed"] = "It's a shiny new\nBICYCLE!",
  ["15:49a3"] = "If you treat your\nPOKéMON nicely,\012they will love you\nin return.\012Oh? Let me see\nyour {STRBUF}…",
  ["15:49fc"] = "It looks really\nhappy! It must\011love you a lot.",
  ["15:4a2c"] = "I get the feeling\nthat it really\011trusts you.",
  ["15:4a5a"] = "It's friendly to-\nward you. It looks\011sort of happy.",
  ["15:4a8e"] = "It's quite cute.",
  ["15:4a9f"] = "You should treat\nit better. It's\011not used to you.",
  ["15:4ad1"] = "It doesn't seem to\nlike you at all.\011It looks mean.",
  ["15:4b04"] = "I keep losing in\nbattles, and my\012POKéMON end up\nfainting…\012Maybe that's why\nmy POKéMON don't\011like me much…",
  ["15:4b67"] = "When I use an item\non my POKéMON, it\011acts really glad!",
  ["15:4c74"] = "BILL: Hi, {PLAYER}!\nDo us a favor and\011take this EEVEE.\012It came over when\nI was adjusting\011the TIME CAPSULE.\012Someone has to\ntake care of it,\012but I don't like\nbeing outside.\012Can I count on you\nto play with it,\011{PLAYER}?",
  ["15:4d3f"] = "BILL: I knew you'd\ncome through!\012Way to go! You're\nthe real deal!\012OK, I'm counting\non you.\012Take good care of\nit!",
  ["15:4dae"] = "{PLAYER} received\nEEVEE!",
  ["15:4dc1"] = "BILL: PROF.ELM\nclaims EEVEE may\012evolve in new and\nunknown ways.",
  ["15:4e02"] = "Whoa, wait. You\ncan't carry any\011more POKéMON.",
  ["15:4e2d"] = "Oh… Now what to\ndo?",
  ["15:4e42"] = "BILL: My pop, he\nwon't work. All he\012does is goof off\nall day long.\012He's getting to be\na real headache…",
  ["15:4ea8"] = "Oh, you collect\nPOKéMON? My son\011BILL is an expert.\012He just got called\nto the POKéMON\012CENTER in ECRUTEAK\nCITY.\012My husband went\noff to the GAME\012CORNER without\nbeing called…",
  ["15:4f4e"] = "My husband was\nonce known as a\012POKéMANIAC.\nBILL must have\012taken after his\nfather.",
  ["15:4f9e"] = "Are you a trainer?\012I've got a useful\nphone number for\011you.",
  ["15:4fd9"] = "{PLAYER} recorded\nBILL's number.",
  ["15:4ff3"] = "My brother made\nthe PC POKéMON\011storage system.\012I was going to\ngive you BILL's\011number…",
  ["15:5046"] = "You can't record\nany more numbers.",
  ["15:5069"] = "My big brother\nBILL made the PC\012POKéMON storage\nsystem.",
  ["15:5160"] = "The train hasn't\ncome in…\012I know! I'll carry\nthe passengers on\011my back!\012That won't work.",
  ["15:51b7"] = "We'll soon depart\nfor SAFFRON.\012Are you coming\naboard?",
  ["15:51ed"] = "May I see your\nrail PASS, please?\012OK. Right this\nway, please.",
  ["15:522c"] = "Sorry. You don't\nhave a rail PASS.",
  ["15:524f"] = "We hope to see you\nagain!",
  ["15:526a"] = "We have arrived in\nGOLDENROD.\012We hope to see you\nagain.",
  ["15:52a3"] = "I'm the PRESIDENT.\012My dream was to\nbuild a train that\012is faster than any\nPOKéMON.\012It really brings\nJOHTO much closer\011to KANTO.",
  ["15:53d4"] = "Have you seen that\nwiggly tree that's\012growing on ROUTE\n36?\012My little sister\ngot all excited\012and went to see\nit…\012I'm worried… Isn't\nit dangerous?",
  ["15:5463"] = "Do you want to\nborrow the water\012bottle too?\nI don't want you\012doing anything\ndangerous with it.",
  ["15:54c2"] = "Oh, you're better\nthan WHITNEY…\012You'll be OK,\nthen. Here's the\011SQUIRTBOTTLE!",
  ["15:550d"] = "Don't do anything\ntoo dangerous!",
  ["15:552e"] = "Lalala lalalala.\nHave plenty of\011water, my lovely!",
  ["15:5561"] = "When I told my sis\nabout the jiggly\012tree, she told me\nit's dangerous.\012If I beat WHITNEY,\nI wonder if she'll\012lend me her water\nbottle…",
  ["15:55e6"] = "Wow, you beat\nWHITNEY? Cool!",
  ["15:5604"] = "So it really was a\nPOKéMON!",
  ["15:5659"] = "Once while I was\nbattling, my\012POKéMON couldn't\nmake any moves.\012The POWER POINTS,\nor PP, of its\012moves were all\ngone.",
  ["15:56ca"] = "Sometimes, a\nhealthy POKéMON\012may be unable to\nuse its moves.\012If that happens,\nheal it at a POKé-\011MON CENTER or use\011an item.",
  ["15:5993"] = "Welcome to GOLDEN-\nROD DEPT.STORE.",
  ["15:59b7"] = "The DEPT.STORE\nhas a decent se-\011lection.\012But some items\nare only available\012as GAME CORNER\nprizes.",
  ["15:5a1a"] = "I'm raring to shop\nagain today!",
  ["15:5a3a"] = "Mom's good at\nbargain hunting.\012She always buys\nstuff at lower\011prices.",
  ["15:5a80"] = "1F SERVICE COUNTER\0122F TRAINER'S\n   MARKET\0123F BATTLE\n   COLLECTION\0124F MEDICINE BOX\0125F TM CORNER\0126F TRANQUIL SQUARE\012ROOFTOP LOOKOUT",
  ["15:5c25"] = "POKéGEAR can store\nup to ten phone\011numbers.\012It's hard to de-\ncide which numbers\011to keep.",
  ["15:5c7b"] = "I got my ABRA at\nthe GAME CORNER.\012Now it's my best\npartner.",
  ["15:5cb7"] = "This DEPT.STORE\nmakes me realize\012that GOLDENROD is\na big city.\012The selection here\nis unmatched any-\011where else.",
  ["15:5d28"] = "Your Travel\nCompanion\0122F TRAINER'S\n   MARKET",
  ["15:5dcc"] = "I, I, I'm really\nimpatient!\012I use X SPEED in\nbattle to speed up\011my POKéMON.",
  ["15:5e15"] = "Hey! When you bat-\ntle, do you use X\011SPECIAL?\012It's awesome. It\nreally jacks up\011SPECIAL ATTACK!",
  ["15:5e74"] = "For Victory\nSeekers\0123F BATTLE\n   COLLECTION",
  ["15:5f08"] = "Hey. I love strong\nPOKéMON.\012I feed them PRO-\nTEIN to crank up\011their ATTACK.",
  ["15:5f52"] = "IRON adds to your\nPOKéMON's DEFENSE.",
  ["15:5f74"] = "Some POKéMON\nevolve only by\012being traded via a\nGame Link cable.\012I know of four:\nMACHOKE, KADABRA,\012HAUNTER and, um,\nGRAVELER.\012I heard there are\nothers too.",
  ["15:600d"] = "Let Us Pump Up\nYour POKéMON!\0124F MEDICINE BOX",
  ["15:6143"] = "Hello. Oh, your\nPOKéMON…",
  ["15:615a"] = "It's very attached\nto you.\012This move should\nbe perfect for a\011pair like you.",
  ["15:61a6"] = "It's adorable!\012You should teach\nit good TM moves.",
  ["15:61d8"] = "It looks evil. How\nabout this TM for\011it?",
  ["15:6202"] = "There are sure to\nbe TMs that are\012just perfect for\nyour POKéMON.",
  ["15:6241"] = "MYSTERY GIFT.\012With just a\nlittle beep, you\011get a gift.",
  ["15:6279"] = "The MYSTERY GIFT\noption requires a\011Game Boy Color.",
  ["15:62ad"] = "On Sundays, a lady\ncomes to check out\011POKéMON.\012She even gives\naway TMs!",
  ["15:62f3"] = "You can't rename a\nPOKéMON you get in\011a trade.\012The name is a re-\nflection of the\012original trainer's\nfeelings for it.",
  ["15:6364"] = "Customize Your\nPOKéMON\0125F TM CORNER",
  ["15:64cb"] = "A vending machine!\nHere's the menu.",
  ["15:64ef"] = "Clang! A can of\n{STRBUF}\011popped out!",
  ["15:6512"] = "Oops, not enough\nmoney.",
  ["15:652b"] = "There's no more\nroom for stuff.",
  ["15:654b"] = "Do you listen to\nLUCKY CHANNEL?\012If you want to\nwin, trade POKéMON\012with as many peo-\nple as possible to\012get different ID\nnumbers.",
  ["15:65ca"] = "If you're tired,\ntry the vending\011machine's drinks.\012Your POKéMON will\nlove them too.",
  ["15:661a"] = "Take a Break from\nShopping!\0126F TRANQUIL SQUARE",
  ["15:677f"] = "Whew, I'm tired.\012I sometimes come\nup to the rooftop\012to take a break\nfrom shopping.",
  ["15:67d2"] = "Pardon? Who says\nan adult can't get\011into this?\012I'm going to be\nback every day to\012collect all the\ndolls!",
  ["15:6839"] = "They have bargain\nsales here every\011so often.",
  ["15:6867"] = "Oh, wow!",
  ["15:6871"] = "Will you quit\nbothering me?",
  ["15:688e"] = "There's something\nI really want, but\012I don't have the\nnecessary cash…\012Maybe I'll sell\noff the BERRIES\011I've collected…",
  ["15:6901"] = "Oh, everything is\nso cheap!\012I bought so much,\nmy PACK's crammed!",
  ["15:6942"] = "My POKéMON always\nget paralyzed or\012poisoned when the\nchips are down…\012So I came to buy\nsome FULL HEAL.\012I wonder if\nthere's any left?",
  ["15:69c3"] = "These binoculars\nlet me see far\012away. Maybe I can\nsee my own house.\012Is it the one with\nthe green roof?",
  ["15:6a2b"] = "Hey! Some trainers\nare battling on\011the road!\012A POKéMON fired a\nflurry of leaves!\012That makes me feel\nlike battling\011right now!",
  ["15:6aa6"] = "A FISHER caught a\nlot of MAGIKARP…\012They're SPLASHing\nat the same time!\012Look at the water\ngoing everywhere!",
  ["15:6b11"] = "A vending machine\nfor POKéMON dolls?\012Insert money, then\nturn the crank…\012But it's almost\nempty…",
  ["15:6e50"] = "Welcome!\012We exchange your\ngame coins for\011fabulous prizes!",
  ["15:6e8b"] = "Which prize would\nyou like?",
  ["15:6ea8"] = "{STRBUF}.\nIs that right?",
  ["15:6ebd"] = "Here you go!",
  ["15:6ecb"] = "Sorry! You need\nmore coins.",
  ["15:6ee8"] = "Sorry. You can't\ncarry any more.",
  ["15:6f09"] = "OK. Please save\nyour coins and\011come again!",
  ["15:6f35"] = "Oh? You don't have\na COIN CASE.",
  ["15:6f55"] = "I always play this\nslot machine. It\012pays out more than\nothers, I think.",
  ["15:6f9e"] = "I just love this\nnew slot machine.\012It's more of a\nchallenge than the\011ones in CELADON.",
  ["15:6ff4"] = "Life is a gamble.\nI'm going to flip\011cards till I drop!",
  ["15:702b"] = "Card flip…\012I prefer it over\nthe slots because\012it's easier to\nfigure the odds.\012But the payout is\nmuch lower.",
  ["15:7097"] = "I won't quit until\nI win!",
  ["15:70b1"] = "I taught BLIZZARD\nto my POKéMON.\012It was hard to get\nenough coins for\012it, but it was\nworth it.",
  ["15:710d"] = "I couldn't win at\nthe slots, and I\012blew it on card\nflipping…\012I got so furious,\nI tossed out my\012COIN CASE in the\nUNDERGROUND.",
  ["15:718a"] = "Wahahah! The coins\nkeep rolling in!",
  ["15:71af"] = "Someone left their\ndrink.\012It smells sweet.",
  ["16:40c7"] = "Hm? That's a POKé-\nDEX, isn't it?\011May I see it?\012There are so many\nkinds of POKéMON.\012Hm? What's this?\012What is this\nPOKéMON?\012It looks like the\nstrange writing on\012the walls of the\nRUINS.\012If those drawings\nare really POKé-\011MON, there should\011be many more.\012I know! Let me up-\ngrade your POKé-\011DEX. Follow me.",
  ["16:42eb"] = "Hmmm… This is a\nstrange place.",
  ["16:430e"] = "I like thinking\nhere.",
  ["16:4325"] = "MYSTERY STONE\nPANEL CHAMBER",
  ["16:4342"] = "RUINS OF ALPH\nVISITORS WELCOME",
  ["16:4362"] = "RUINS OF ALPH\nRESEARCH CENTER\012THE AUTHORITY ON\nTHE RUINS OF ALPH",
  ["16:43a4"] = "While exploring\nthe RUINS, we\012suddenly noticed\nan odd presence.\012We all got scared\nand ran away.\012You should be\ncareful too.",
  ["16:4420"] = "The RUINS hide a\nhuge secret!\012…I think…",
  ["16:4449"] = "There are many\nkinds of UNOWN, so\012we use them for\nour secret codes.",
  ["16:448e"] = "A… H… E… A… D…\nHmm…\012What?\012I'm decoding this\nmessage!",
  ["16:4612"] = "Patterns appeared\non the walls…",
  ["16:4644"] = "Patterns appeared\non the walls…",
  ["16:4665"] = "There's a big hole\nin the wall!",
  ["16:4685"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:46aa"] = "A POKéMON that\nflew gracefully on\012rainbow-colored\nwings.",
  ["16:4800"] = "Welcome to this\nchamber.\012There are sliding\npanels that depict\012a POKéMON drawn by\nthe ancients.\012Slide the panels\naround to form the\011picture.\012To the right is a\ndescription of the\011POKéMON.\012Scientists in the\nback are examining\012some newly found\npatterns.",
  ["16:48f5"] = "Recently, strange,\ncryptic patterns\011have appeared.\012It's odd. They\nweren't here a\011little while ago…\012You should take a\nlook at the walls.",
  ["16:497c"] = "Ah! Here's another\nhuge hole!\012It's big enough to\ngo through!",
  ["16:49b8"] = "That tremor was\npretty scary!\012But I'm more\nconcerned about\011this wall here…",
  ["16:4aa7"] = "Patterns appeared\non the walls…",
  ["16:4ad9"] = "Patterns appeared\non the walls…",
  ["16:4afa"] = "There's a big hole\nin the wall!",
  ["16:4b1a"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:4b3f"] = "A POKéMON that hid\non the sea floor.\012Eyes on its back\nscanned the area.",
  ["16:4c8e"] = "Patterns appeared\non the walls…",
  ["16:4cc0"] = "Patterns appeared\non the walls…",
  ["16:4ce1"] = "There's a big hole\nin the wall!",
  ["16:4d01"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:4d26"] = "This POKéMON\ndrifted in the\012sea by twisting\nits ten tentacles.",
  ["16:4e4f"] = "Patterns appeared\non the walls…",
  ["16:4e81"] = "Patterns appeared\non the walls…",
  ["16:4ea2"] = "There's a big hole\nin the wall!",
  ["16:4ec2"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:4ee7"] = "This flying POKé-\nMON attacked its\012prey with saw-like\nfangs.",
  ["16:4f89"] = "There is a strange\npresence here…",
  ["16:4fac"] = "This is a big\nroom, but there's\011nothing here.",
  ["16:4fda"] = "This place has a\nmystical quality\011to it.\012It feels sort of\nethereal even.",
  ["16:5024"] = "Ancient buildings\nare often tombs of\011kings.\012Like the pyramids,\nfor instance.",
  ["16:5072"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:5278"] = "Done!\012I modified your\nPOKéDEX.\012I added an\noptional POKéDEX\012to store UNOWN\ndata.\012It records them in\nthe sequence that\011they were caught.",
  ["16:52fa"] = "{PLAYER}'s POKéDEX\nwas upgraded.",
  ["16:5311"] = "The UNOWN you\ncatch will all be\011recorded.\012Check to see how\nmany kinds exist.",
  ["16:535f"] = "You caught all the\nUNOWN variations?\012That's a great\nachievement!\012I've set up the\nprinter here for\011handling UNOWN.\012Feel free to use\nit anytime.",
  ["16:53ed"] = "The RUINS are\nabout 1500 years\011old.\012But it's not known\nwhy they were\011built--or by whom.",
  ["16:5445"] = "I wonder how many\nkinds of POKéMON\011are in the RUINS?",
  ["16:5478"] = "POKéMON appeared\nin the RUINS?\012That's incredible\nnews!\012We'll need to\ninvestigate this.",
  ["16:54cb"] = "Our investigation,\nwith your help, is\012giving us insight\ninto the RUINS.\012The RUINS appear\nto have been built\012as a habitat for\nPOKéMON.",
  ["16:554f"] = "There are odd pat-\nterns drawn on the\012walls of the\nRUINS.\012They must be the\nkeys for unravel-\011ing the mystery\011of the RUINS.",
  ["16:55cb"] = "The strange POKé-\nMON you saw in the\011RUINS?\012They appear to be\nvery much like the\012drawings on the\nwalls there.\012Hmm…\012That must mean\nthere are many\011kinds of them…",
  ["16:5769"] = "Why did those\nancient patterns\012appear on the wall\nnow?\012The mystery\ndeepens…",
  ["16:57b6"] = "RUINS OF ALPH\012Exploration\nYear 10",
  ["16:57d9"] = "Mystery POKéMON\nName: UNOWN\012A total of 26\nkinds found.",
  ["16:580e"] = "This doesn't seem\nto work yet.",
  ["16:582d"] = "UNOWN may be\nprinted out.",
  ["16:5886"] = "There are many\nacademic books.\012Ancient Ruins…\nMysteries of the\011Ancients…",
  ["16:5923"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:59ad"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:5a37"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:5ac1"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["16:5c0b"] = "You're headed to\nAZALEA, are you?\012Let my POKéMON see\nif you are good\011enough to battle.",
  ["16:5c5f"] = "Oh, oh, oh!",
  ["16:5c6c"] = "All right, then!\nI've decided.\012I'm not leaving\nuntil my POKéMON\011get tougher!",
  ["16:5cb5"] = "I roam far and\nwide in search of\011POKéMON.\012Are you looking\nfor POKéMON too?\012Then you're my\ncollecting rival!",
  ["16:5d1b"] = "Ugh. My poor POKé-\nMON…",
  ["16:5d31"] = "Every Friday, you\ncan hear POKéMON\012roars from deep\ninside the cave.",
  ["16:5d73"] = "Whoa! What a\nsurprise!\012I didn't expect to\nsee anyone here!",
  ["16:5dae"] = "Whoa! I'm beaten\nbig time!",
  ["16:5dc9"] = "I was conned into\nbuying a SLOWPOKE-\011TAIL.\012I feel sorry for\nthe poor POKéMON.",
  ["16:5e15"] = "ZUBAT's SUPERSONIC\nkeeps confusing\011my POKéMON.\012I'm seriously\nupset about that!",
  ["16:5e60"] = "I flamed out!",
  ["16:5e6f"] = "On weekends, you\ncan hear strange\012roars from deep in\nthe cave.",
  ["16:5eaf"] = "If it's light, a\ncave isn't scary.\012If you're strong,\nPOKéMON aren't\011scary.",
  ["16:5ef4"] = "FLASH!",
  ["16:5efc"] = "It's my POKéMON's\nfire that lights\011up this cave.",
  ["16:601d"] = "It's been a while\nsince I last saw\011another person.\012Don't be shy.\nLet's battle!",
  ["16:606a"] = "Uurggh…",
  ["16:6073"] = "I've been lost for\na long time…\012I don't mind it\nhere, but I am\011soooo hungry!",
  ["16:60bf"] = "What do you know!\nA visitor!",
  ["16:60dd"] = "Wahahah! You're a\nfeisty one!",
  ["16:60fb"] = "I live down here.\012You can, too, if\nyou'd like.\012There's plenty of\nroom, you see.",
  ["16:614a"] = "Who's there?\012Leave me and my\nPOKéMON alone!",
  ["16:6173"] = "Go…\nGo away!",
  ["16:6181"] = "Just me and my\nPOKéMON. I'm de-\011lirious with joy.",
  ["16:61b0"] = "I came all the way\nhere to conduct my\011POKéMON research.\012Let me demonstrate\nmy findings in a\011real battle!",
  ["16:6217"] = "You demonstrated\non me!",
  ["16:6230"] = "I should compile\nand announce my\011study findings.\012I might even be-\ncome famous like\011PROF.ELM.",
  ["16:636e"] = "There are two\nkinds of people.\012Those who have\nstyle, and those\011who don't.\012What kind of\nperson are you?",
  ["16:63d5"] = "You've got\ndazzling style!",
  ["16:63f0"] = "Your POKéMON style\nis stunning and\011colorful, I admit.\012You'll just keep\ngetting better!",
  ["16:6444"] = "I'm in training.\nCare for a round?",
  ["16:6467"] = "Aww, no! You're\ntoo good for me.",
  ["16:6488"] = "I'm going to train\nby myself until I\011improve.",
  ["16:64b6"] = "If the POKéMON I\nliked were there,\011I'd go anywhere.\012That's what a real\ntrainer does.",
  ["16:6507"] = "I'd rather pet my\nbabies than this!",
  ["16:652b"] = "Just once a week,\na POKéMON comes to\011the water's edge.\012I wanted to see\nthat POKéMON…",
  ["16:66b5"] = "KURT: Hey there,\n{PLAYER}!\012The guard up top\ntook off when I\011shouted at him.\012But then I took a\ntumble down the\011WELL.\012I slammed down\nhard on my back,\011so I can't move.\012Rats! If I were\nfit, my POKéMON\012would've punished\nthem…\012Ah, it can't be\nhelped.\012{PLAYER}, show them\nhow gutsy you are\011in my place!",
  ["16:67ca"] = "KURT: Way to go,\n{PLAYER}!\012TEAM ROCKET has\ntaken off.\012My back's better\ntoo. Let's get out\011of here.",
  ["16:6825"] = "Darn! I was stand-\ning guard up top\012when some old coot\nyelled at me.\012He startled me so\nmuch that I fell\011down here.\012I think I'll vent\nmy anger by taking\011it out on you!",
  ["16:68cc"] = "Arrgh! This is NOT\nmy day!",
  ["16:68e8"] = "Sure, we've been\nhacking the tails\012off SLOWPOKE and\nselling them.\012Everything we do\nis for profit.\012That's right!\nWe're TEAM ROCKET,\012and we'll do any-\nthing for money!",
  ["16:698b"] = "What do you want?\012If you interrupt\nour work, don't\011expect any mercy!",
  ["16:69d0"] = "You did OK today,\nbut wait till next\011time!",
  ["16:69fc"] = "Yeah, TEAM ROCKET\nwas broken up\011three years ago.\012But we continued\nour activities\011underground.\012Now you can have\nfun watching us\011stir up trouble!",
  ["16:6a8d"] = "Quit taking SLOW-\nPOKETAILS?\012If we obeyed you,\nTEAM ROCKET's rep\011would be ruined!",
  ["16:6adf"] = "Just…\nToo strong…",
  ["16:6af2"] = "We need the money,\nbut selling SLOW-\011POKETAILS?\012It's tough being a\nROCKET GRUNT!",
  ["16:6b43"] = "Stop taking TAILS?\012Yeah, just try to\ndefeat all of us!",
  ["16:6b7b"] = "You rotten brat!",
  ["16:6b8d"] = "SLOWPOKETAILS\ngrow back fast!\012What's wrong with\nselling them?",
  ["16:6bcb"] = "A SLOWPOKE with\nits TAIL cut off…\012Huh? It has MAIL.\nRead it?",
  ["16:6c09"] = "{PLAYER} read the\nMAIL.\012Be good and look\nafter the house\012with Grandpa and\nSLOWPOKE.\012Love, Dad",
  ["16:6c61"] = "A SLOWPOKE with\nits TAIL cut off…",
  ["16:6d2a"] = "I'm waiting to see\nSLOWPOKE's moment\011of evolution.\012Through observa-\ntion, I made a new\011discovery.\012A SLOWPOKE with a\nKING'S ROCK often\012gets bitten by a\nSHELLDER.\012Here, I'll share a\nKING'S ROCK with\011you.",
  ["16:6df2"] = "I'm going to be\nlike SLOWPOKE.\012I'll wait patient-\nly, so I can see\011one evolve.",
  ["16:6e6d"] = "People train at\nthis LIGHTHOUSE.\012It's not easy to\nclimb because of\011all the trainers.",
  ["16:6ec2"] = "In the past, POKé-\nMON used to light\012the sea around\nOLIVINE at night.\012The LIGHTHOUSE was\nmade in honor of\011those POKéMON.",
  ["16:707a"] = "Men of the sea are\nalways spoiling\011for a good fight!",
  ["16:70b0"] = "Urf!\nI lose!",
  ["16:70f8"] = "Hm? This is no\nplace for playing.",
  ["16:711b"] = "Ah! I can see that\nyou're serious.",
  ["16:713e"] = "Up top is a POKé-\nMON that keeps the\011LIGHTHOUSE lit.\012But I hear that\nit's sick now and\012can't be cured by\nordinary medicine.",
  ["16:71b6"] = "Man! You're as\ntough as ever!\012Anyway, here's\nthat medicine from\011before.",
  ["16:727b"] = "Why are you here?\nAre you just going\012to gawk? I suggest\nthat you leave!",
  ["16:72c4"] = "You really are\nconcerned…",
  ["16:72df"] = "How the heck do\nyou go up?\012I want to visit\nthe sick POKéMON,\012but I can't get up\nthere…",
  ["16:7333"] = "Sailors are both\nkind and strong.\011How about you?",
  ["16:7365"] = "You are both kind\nand strong…",
  ["16:7384"] = "Every time I come\nback to OLIVINE, I\011visit the GYM.\012The GYM LEADER's\nPOKéMON type has\012changed without me\nnoticing.",
  ["16:73f4"] = "I travel the world\nto train my POKé-\011MON. I wish to\011battle with you.",
  ["16:7437"] = "…sigh… I must\ntrain some more…",
  ["16:7457"] = "JASMINE used to\nuse rock POKéMON\011like ONIX.",
  ["16:7512"] = "JASMINE must be\nworried sick about\011the POKéMON here.\012She won't even\nsmile these days.",
  ["16:7565"] = "I can't manage a\nsmile either…",
  ["16:7584"] = "Speaking of sick,\nI've heard there's\012a good PHARMACY in\nCIANWOOD.",
  ["16:75c5"] = "JASMINE is this\ncity's GYM LEADER.\012I mean to bring\nher back with me.\012Nobody had better\nget in my way!",
  ["16:762b"] = "Aaack! My POKéMON!",
  ["16:763c"] = "Right. Anybody\nwould be worried\011if his or her own\011POKéMON were hurt.\012I'll pray for the\nPOKéMON here, so\012JASMINE can come\nback to the GYM.",
  ["17:41d3"] = "Look! Check out my\nbag!\012I printed out my\nfavorites from my\012POKéDEX and stuck\nthem on my bag.",
  ["17:422e"] = "This is MAIL I got\nfrom my daughter.\011It cheers me up.",
  ["17:4265"] = "Pay attention,\nplease!\012…Oops, I have to\nquit thinking like\012a teacher all the\ntime.\012You must be a\nPOKéMON trainer.\012Since you're work-\ning so hard, I\012want you to have\nthis.",
  ["17:430d"] = "Let a POKéMON hold\nthat QUICK CLAW.\012Sometimes it will\nstrike first\011during battle.",
  ["17:435d"] = "I'm playing with\nstickers I printed\011from my POKéDEX.",
  ["17:438f"] = "I get the other\nguy's POKéDEX\011sticker if I win.",
  ["17:43bc"] = "I take walks in\nthe PARK, but I\012never go into the\ngrass.\012Trainers always\nwant to battle…",
  ["17:4416"] = "PERSIAN: Fufushaa!",
  ["17:442a"] = "I'm printing out\nmy POKéDEX.\012You can also print\nout stuff like\012MAIL and your PC\nBOXES.",
  ["17:447e"] = "The world of\nPOKéMON is deep.\012There are still\nlots of things we\011don't know.\012But I know more\nthan you do!",
  ["17:44e4"] = "Wha-wha-what?",
  ["17:44f3"] = "There is a lot\nto learn.\012For example…\012There are 50 kinds\nof TMs.\012Traded POKéMON\nlevel up faster.",
  ["17:4552"] = "My POKéMON are\nsimply darling.\012Let me tell you\nhow proud my\011darlings make me.",
  ["17:459e"] = "I can beat you in\npride, but…",
  ["17:45bd"] = "I must say, your\nPOKéMON are quite\011cute, too.",
  ["17:45e9"] = "We adore our POKé-\nMON, even if they\011dislike us.\012That's what being\na FAN is about.",
  ["17:4639"] = "M-my POKéMON!",
  ["17:4645"] = "I lost the battle,\nbut my POKéMON win\012the prize for\nbeing most lovely.",
  ["17:468a"] = "My friend keeps a\nMARILL!\012I find them very\nendearing.\012Oh, I wish for a\nMARILL of my own…",
  ["17:46e4"] = "Hello? Why are you\nstaring at me?\012Oh, a battle?",
  ["17:4715"] = "…Hmmm…",
  ["17:471d"] = "I thought you were\nstaring at me\011because I'm cute!",
  ["17:4750"] = "RELAXATION SQUARE\nNATIONAL PARK",
  ["17:4771"] = "What is this\nnotice?\012Please battle only\nin the grass.\012NATIONAL PARK\nWARDEN'S OFFICE",
  ["17:47c6"] = "TRAINER TIPS\012Print out MAIL by\nopening it then\011pressing START.",
  ["17:494c"] = "DON: I'm going to\nwin! Don't bother\011me.",
  ["17:4973"] = "ED: My PARASECT\nputs POKéMON to\011sleep with SPORE.",
  ["17:49a3"] = "NICK: I'm raising\nfast POKéMON for\011battles.",
  ["17:49cc"] = "WILLIAM: I'm not\nconcerned about\011winning.\012I'm just looking\nfor rare POKéMON.",
  ["17:4a15"] = "BENNY: Ssh! You'll\nscare off SCYTHER.\012I'll talk to you\nlater.",
  ["17:4a52"] = "BARRY: You should\nweaken bug POKéMON\012first, then throw\na BALL.",
  ["17:4a8f"] = "CINDY: I love bug\nPOKéMON.\012I guess you must\nlike them too.",
  ["17:4ac8"] = "JOSH: I've been\ncollecting bug\012POKéMON since I\nwas just a baby.\012There's no way I'm\ngoing to lose!",
  ["17:4b25"] = "SAMUEL: If you've\ngot the time to\012chat, go find some\nbug POKéMON.",
  ["17:4b64"] = "KIPP: I've studied\nabout bug POKéMON\011a lot.\012I'm going to win\nfor sure.",
  ["17:4ba7"] = "RELAXATION SQUARE\nNATIONAL PARK",
  ["17:4bc8"] = "What is this\nnotice?\012Please battle only\nin the grass.\012NATIONAL PARK\nWARDEN'S OFFICE",
  ["17:4c1d"] = "TRAINER TIPS\012Print out MAIL by\nopening it then\011pressing START.",
  ["17:4e77"] = "Welcome!",
  ["17:4e81"] = "Hello. I'm sorry,\nbut we're not\011offering any tours\011today.",
  ["17:4eba"] = "Hi, are you here\nfor the LUCKY NUM-\011BER SHOW?\012Want me to check\nthe ID numbers of\011your POKéMON?\012If you get lucky,\nyou win a prize.",
  ["17:4f3a"] = "This week's ID\nnumber is {STRBUF}.",
  ["17:4f5a"] = "Let's see if you\nhave a match.",
  ["17:4f7e"] = "Please come back\nnext week for the\011next LUCKY NUMBER.",
  ["17:4fb5"] = "Wow! You have a\nperfect match of\011all five numbers!\012We have a grand\nprize winner!\012You have won a\nMASTER BALL!",
  ["17:5023"] = "Hey! You've\nmatched the last\011three numbers!\012You've won second\nprize, an EXP.\011SHARE!",
  ["17:5076"] = "Ooh, you've\nmatched the last\011two numbers.\012You've won third\nprize, a PP UP.",
  ["17:50c0"] = "Nope, none of your\nID numbers match.",
  ["17:50e6"] = "You've got no room\nfor your prize.\012Make room and come\nback right away.",
  ["17:512d"] = "We have a special\nquiz campaign on\011right now.\012Answer five ques-\ntions correctly to\011win a RADIO CARD.\012Slide it into your\nPOKéGEAR to play\012the radio anytime,\nanywhere.\012Would you like to\ntake the quiz?",
  ["17:51f2"] = "Question 1:\012Is there a POKéMON\nthat appears only\011in the morning?",
  ["17:5231"] = "Correct!\nQuestion 2:\012Is this statement\ncorrect?\012You can't buy a\nBERRY at a MART.",
  ["17:5282"] = "Bull's-eye!\nQuestion 3:\012Does HM01 contain\nthe move FLASH?",
  ["17:52bc"] = "So far so good!\nQuestion 4:\012Is FALKNER the\nVIOLET GYM LEADER\012who uses bird\nPOKéMON?",
  ["17:530e"] = "Wow! Right again!\nHere's the final\011question:\012Do GOLDENROD GAME\nCORNER's slots\012have CHARMANDER\non their reels?",
  ["17:537b"] = "Bingo! You got it!\nCongratulations!\012Here's your prize,\na RADIO CARD!",
  ["17:53c0"] = "{PLAYER}'s POKéGEAR\ncan now double as\011a radio!",
  ["17:53e5"] = "Please tune in to\nour radio shows.",
  ["17:5409"] = "Oh, dear.\nSorry, but you\012got it wrong.\nPlease try again!",
  ["17:5443"] = "Oh. I see. Please\nsee me if you\011change your mind.",
  ["17:5476"] = "BEN is a fabulous\nDJ.\012His sweet voice\nmakes me melt!",
  ["17:54ac"] = "I love MARY, from\nPOKéMON TALK.\012I only know what\nshe sounds like,\011though.",
  ["17:54f4"] = "We've finally\ntaken over the\011RADIO TOWER!\012Now everyone will\nget to experience\012the true terror of\nTEAM ROCKET!\012We'll show you\nhow scary we are!",
  ["17:5582"] = "Too strong! We\nmust watch you…",
  ["17:55a2"] = "You're too strong.\012Our plan could be\nruined. I must\011warn the others…",
  ["17:55e7"] = "1F RECEPTION\n2F SALES\0123F PERSONNEL\n4F PRODUCTION\0125F DIRECTOR'S\n   OFFICE",
  ["17:5631"] = "LUCKY CHANNEL!\012Win with POKéMON\nID numbers!\012Trade your POKéMON\nto collect differ-\011ent ID numbers!",
  ["17:5924"] = "You can listen to\nthe radio any-\011where. Tune in!",
  ["17:5956"] = "Lullabies on the\nradio may make\011POKéMON sleep.",
  ["17:5983"] = "Why would they\nwant to take over\011the RADIO TOWER?",
  ["17:59b6"] = "JIGGLYPUFF:\nJiggly…",
  ["17:59cb"] = "Sorry. Authorized\npersonnel only\011beyond this point.\012It wasn't that way\nbefore.\012There's something\nwrong with the\011DIRECTOR…",
  ["17:5a44"] = "Feel free to look\naround anywhere.\012The DIRECTOR is\nnice again, just\011as he was before.",
  ["17:5a9b"] = "Three years ago,\nTEAM ROCKET was\011forced to disband.\012But we're making a\ncomeback here!",
  ["17:5af1"] = "Gwah! Don't get\ncute!",
  ["17:5b07"] = "We won't let you\nruin our plans\011for our comeback!",
  ["17:5b39"] = "We're TEAM ROCKET,\nthe exploiters of\011POKéMON!\012We love being\nevil! Scared?",
  ["17:5b80"] = "You think you're a\nhero?",
  ["17:5b99"] = "We're not always\nevil. We just do\011whatever we like.",
  ["17:5bcd"] = "Hey, hey! Keep out\nof our way!",
  ["17:5bed"] = "Arggh. I give up.",
  ["17:5c00"] = "Our EXECUTIVES are\ntrying to take\011this place over.\012They have some big\nplan. I wonder\011what that is?",
  ["17:5c64"] = "Hahaha!\012How boring.\nIt was far too\012easy to take over\nthis place!\012Come on, keep me\namused!",
  ["17:5cbf"] = "Wh-who are you?",
  ["17:5cd0"] = "You beat me, and\nI won't forget it!",
  ["17:5cf4"] = "BUENA: Hi! I'm\nBUENA!\012Do you know about\na radio program\011called PASSWORD?\012If you can tell me\nthe password from\012the program, you\nwill earn points.\012Save up those\npoints and trade\012them to that sweet\nyoung lady over\012there for some\nchoice prizes!\012Here you go!\012It's your very own\npoint card!",
  ["17:5e10"] = "BUENA: Tune in to\nmy PASSWORD SHOW!",
  ["17:5e35"] = "BUENA: Hi!\nDid you tune in to\011my radio show?\012Do you remember\ntoday's password?",
  ["17:5e84"] = "BUENA: Oh, wow!\nThank you!\012What was your name\nagain?\012…{PLAYER}, OK!\012Come on, {PLAYER}.\nJoin the show.",
  ["17:5edd"] = "BUENA: Everyone\nready?\012I want to hear you\nshout out today's\012password for\n{PLAYER}!",
  ["17:5f29"] = "BUENA: Come back\nafter you listen\012to my show, OK?\nCatch ya later!",
  ["17:5f6c"] = "BUENA: Sorry…\012You get just one\nchance each day.\012Come back tomorrow\nfor another try!",
  ["17:5fc1"] = "BUENA: YIPPEE!\nThat's right!\012You did tune in!\nI'm so happy!\012You earned one\npoint! Congrats!",
  ["17:601c"] = "BUENA: Aww…\nThat's not it…\012Did you forget the\npassword?",
  ["17:6054"] = "BUENA: Yup! Our\ncontestant was\012{PLAYER}.\nThanks for coming!\012I hope all you\nlisteners will\012come too!\nI'll be waiting!",
  ["17:60c2"] = "BUENA: Huh?\nToday's password?\012HELP, of course!",
  ["17:60f1"] = "BUENA: Your BLUE\nCARD's full.\012Trade it in for a\nfabulous prize!",
  ["17:6131"] = "BUENA: Tune in to\nPASSWORD every\012night from six to\nmidnight!\012Tune in, then drop\nin for a visit!",
  ["17:6192"] = "BUENA: Oh? You\nforgot to bring\011your BLUE CARD?\012I can't give you\npoints if you\011don't have it.",
  ["17:61ee"] = "BUENA: Oh! Your\nBLUE CARD reached\01230 points today!\nThat's so wild!\012Hmm… There isn't a\nprize for hitting\01130 points, but…\012You came by so\noften, {PLAYER}.\012I'll make you a\nspecial deal!\012How would you like\nmy phone number?",
  ["17:62bf"] = "BUENA: {PLAYER},\ndo you want to\012register my phone\nnumber?",
  ["17:62f3"] = "{PLAYER} registered\nBUENA's number.",
  ["17:6310"] = "BUENA: I look\nforward to hearing\011from you!",
  ["17:633c"] = "BUENA: Aww… It's a\nspecial prize…",
  ["17:635e"] = "BUENA: {PLAYER},\nyour phone list\012has no room left\nfor me…",
  ["17:6392"] = "You can cash in\nyour saved points\012for a lovely prize\nof your choice!",
  ["17:63d8"] = "You can't trade in\npoints without\011your BLUE CARD.\012Don't forget your\nBLUE CARD!",
  ["17:6426"] = "2F SALES",
  ["17:6430"] = "PROF.OAK'S POKéMON\nTALK\012The Hottest Show\non the Air!",
  ["17:6463"] = "Anywhere, Anytime\nPOKéMON Radio",
  ["17:6621"] = "We have recordings\nof the cries of\012all POKéMON that\nhave been found.\012We must have about\n200 kinds.",
  ["17:6682"] = "To trainers, POKé-\nMON are their\011beloved partners.\012It's terrible how\nTEAM ROCKET is\012trying to control\nPOKéMON.",
  ["17:66eb"] = "We run 24 hours a\nday to broadcast\012entertaining pro-\ngrams.\012I'll do my best to\nrun around the\011clock too!",
  ["17:6754"] = "The TEAM ROCKET\nboss has locked\011himself in.\012But the DIRECTOR\ncan open it.\012He's up on the\nfifth floor.\012Please save him!",
  ["17:67cb"] = "Is the DIRECTOR\nsafe?",
  ["17:67e2"] = "Thank you!\nYou're my hero!\012This is a token of\nmy appreciation.",
  ["17:6821"] = "It's SUNNY DAY.\nIt powers up fire-\011type moves for a\011while.",
  ["17:685c"] = "You were simply\nmarvelous!",
  ["17:6878"] = "I've been given\nstrict orders.\012I'm to crush any-\none who challenges\011TEAM ROCKET!",
  ["17:68c8"] = "What?!",
  ["17:68d0"] = "I failed in my\nduties…\012I'll be docked pay\nfor this…",
  ["17:6904"] = "It feels great\nordering POKéMON\011to commit crimes.",
  ["17:6934"] = "You're kidding!",
  ["17:6944"] = "I feel lousy over\nlosing!\012Darn it! I hate\nuseless POKéMON!",
  ["17:697d"] = "Why did the shut-\nter open? Did you\012have something to\ndo with this?",
  ["17:69c2"] = "I'm done for!",
  ["17:69d0"] = "What?! You made it\npast our men in\011the UNDERGROUND?\012How could you?",
  ["17:6a14"] = "An unknown child\nwandering here?\012Who are you?",
  ["17:6a43"] = "Tch! I took you\ntoo lightly!",
  ["17:6a61"] = "Bwahahaha…\012I can transmit as\nstrong a signal as\011I need from here.",
  ["17:6aa4"] = "It's the CARD KEY\nslot.",
  ["17:6abc"] = "{PLAYER} inserted\nthe CARD KEY.",
  ["17:6ad6"] = "3F PERSONNEL",
  ["17:6ae4"] = "POKéMON MUSIC with\nHost DJ BEN",
  ["17:6c12"] = "I listened to the\nradio while I was\011at the RUINS.\012I heard a strange\nbroadcast there.",
  ["17:6c68"] = "MARY: Why? Why do\nI have to suffer\011through this?\012MEOWTH, help me!",
  ["17:6cab"] = "MARY: Oh! You're\nmy little savior!\012Will you take this\nas my thanks?",
  ["17:6cef"] = "MARY: It's just\nright for POKéMON\012that know normal-\ntype moves.",
  ["17:6d2c"] = "MARY: Please tune\ninto me on PROF.\012OAK'S POKéMON TALK\nshow.",
  ["17:6d66"] = "MEOWTH: Meowth…",
  ["17:6d77"] = "You plan to rescue\nthe DIRECTOR?\012That won't be pos-\nsible because I'm\011going to beat you!",
  ["17:6dcf"] = "No! Unbelievable!",
  ["17:6de2"] = "I don't believe\nit! I was beaten!",
  ["17:6e04"] = "Stop! I'm known as\nthe TEAM ROCKET\011fortress!\012You're not taking\nanother step!",
  ["17:6e50"] = "The fortress came\ndown!",
  ["17:6e69"] = "You've earned my\nrespect, so here's\011some advice.\012It's not too late.\nYou can still turn\011back.",
  ["17:6ec4"] = "Don't I think\nPOKéMON are cute?\012I'll think my\nPOKéMON are cute--\012after they beat\nyours!",
  ["17:6f15"] = "Oh, no! They're so\nuseless!",
  ["17:6f31"] = "I love my\nbeautiful self!\012Who cares about\nPOKéMON?",
  ["17:6f62"] = "Most excellent.\012This RADIO TOWER\nwill fulfill our\011grand design.",
  ["17:6fa3"] = "Hmmm…\012All grand plans\ncome with snags.",
  ["17:6fcb"] = "Do you honestly\nbelieve you can\011stop TEAM ROCKET?",
  ["17:6ffe"] = "4F PRODUCTION",
  ["17:700d"] = "4F STUDIO 2",
  ["18:4128"] = "Y-you! You came to\nrescue me?",
  ["18:4147"] = "Is that what you\nwere expecting?\012Wrong!\nI'm an imposter!\012I pretended to be\nthe real thing to\012prepare for our\ntakeover.\012Do you want to\nknow where we hid\011the real DIRECTOR?\012Sure, I'll tell\nyou. But only if\011you can beat me!",
  ["18:4223"] = "OK, OK. I'll tell\nyou where he is.",
  ["18:4246"] = "We stashed the\nreal DIRECTOR in\012the UNDERGROUND\nWAREHOUSE.\012It's at the far\nend of the UNDER-\011GROUND.\012But I doubt you'll\nget that far.",
  ["18:42cb"] = "Remember me from\nthe HIDEOUT in\011MAHOGANY TOWN?\012I lost then, but I\nwon't this time.",
  ["18:431e"] = "This can't be\nhappening!\012I fought hard, but\nI still lost…",
  ["18:4358"] = "{PLAYER}, isn't it?\012A brat like you\nwon't appreciate\012the magnificence\nof TEAM ROCKET.\012That's too bad.\nI really admire\011your power.",
  ["18:43d1"] = "Oh? You managed to\nget this far?\012You must be quite\nthe trainer.\012We intend to take\nover this RADIO\012STATION and an-\nnounce our come-\011back.\012That should bring\nour boss GIOVANNI\012back from his solo\ntraining.\012We are going to\nregain our former\011glory.\012I won't allow you\nto interfere with\011our plans.",
  ["18:44f3"] = "No! Forgive me,\nGIOVANNI!",
  ["18:450e"] = "How could this be?\012Our dreams have\ncome to naught.\012I wasn't up to the\ntask after all.\012Like GIOVANNI did\nbefore me, I will\012disband TEAM\nROCKET here today.\012Farewell.",
  ["18:45b2"] = "DIRECTOR: {PLAYER},\nthank you!\012Your courageous\nactions have saved\012POKéMON nation-\nwide.\012I know it's not\nmuch, but please\011take this.",
  ["18:462c"] = "There used to be a\ntower right here\011in GOLDENROD CITY.\012But it was old and\ncreaky.\012So we replaced it\nwith our RADIO\011TOWER.\012We dug up that\nbell during\011construction.\012I heard that all\nsorts of POKéMON\012lived in GOLDENROD\nin the past.\012Perhaps…\012That bell has some\nconnection to the\012TIN TOWER in\nECRUTEAK CITY…\012Ah!\012That reminds me…\012I overheard TEAM\nROCKET whispering.\012Apparently, some-\nthing is going on\011at the TIN TOWER.\012I have no idea\nwhat is happening,\012but you might look\ninto it.\012OK, I better go to\nmy OFFICE.",
  ["18:4824"] = "DIRECTOR: Hello,\n{PLAYER}!\012You know, I love\nPOKéMON.\012I built this RADIO\nTOWER so I could\012express my love\nof POKéMON.\012It would be nice\nif people enjoyed\011our programs.",
  ["18:48be"] = "BEN: Do you listen\nto our music?",
  ["18:48e0"] = "5F DIRECTOR'S\n   OFFICE",
  ["18:48f9"] = "5F STUDIO 1",
  ["18:49b3"] = "I wanted to battle\nJASMINE, but she's\012not up to it now.\nSo, how about you?",
  ["18:49fe"] = "Whoa, whoa. You're\noverwhelming!",
  ["18:4a1f"] = "A GYM LEADER isn't\njust about being\012strong. A LEADER\nalso needs to be\011compassionate.",
  ["18:4a74"] = "We're pretty high\nup here. My bird\012POKéMON are in\nprime form.",
  ["18:4aaf"] = "Oops…They crashed…",
  ["18:4ac3"] = "My POKéMON learned\nhow to use FLY in\011CIANWOOD.\012Well, since I'm a\nloser, I'll FLY\011across the sea…",
  ["18:4c81"] = "JASMINE: … This\nPOKéMON always\012kept the sea lit\nat night.\012…But it suddenly\ngot sick… It's\011gasping for air…\012…I understand\nthat there is a\012wonderful PHARMACY\nin CIANWOOD…\012But that's across\nthe sea…\012And I can't leave\nAMPHY unattended…",
  ["18:4d64"] = "…May I ask you to\nget some medicine\011for me? Please?",
  ["18:4d99"] = "JASMINE: …Will\nthat medicine cure\011AMPHY?",
  ["18:4dc3"] = "{PLAYER} handed the\nSECRETPOTION to\011JASMINE.",
  ["18:4dea"] = "JASMINE: …Um,\nplease don't be\011offended…\012…AMPHY will not\ntake anything from\011anyone but me…",
  ["18:4e44"] = "JASMINE: …\012AMPHY, how are you\nfeeling?",
  ["18:4e6c"] = "JASMINE: …Oh, I'm\nso relieved…\012This is just so\nwonderful…\012Thank you so very,\nvery much.\012…I will return to\nthe GYM…",
  ["18:4edf"] = "JASMINE: …I see…",
  ["18:4ef1"] = "…AMPHY, hang on!",
  ["18:4f03"] = "AMPHY: …\n…Pa… paloo…",
  ["18:4f19"] = "Its breathing is\nterribly labored…",
  ["18:4f3d"] = "AMPHY: Palu!\nPalulu!",
  ["18:6105"] = "The COLOSSEUM\nupstairs is for\011link battles.\012Battle records are\nposted on the\012wall, so I can't\nafford to lose.",
  ["18:6260"] = "A higher level\nPOKéMON doesn't\011always win.\012After all, it may\nhave a type dis-\011advantage.\012I don't think\nthere is a single\012POKéMON that is\nthe toughest.",
  ["18:62f0"] = "{PLAYER}, isn't it?\012Congratulations!\012As a special deal,\na GS BALL has been\011sent just for you!\012Please accept it!",
  ["18:6359"] = "Please do come\nagain!",
  ["18:63fb"] = "Oh my, your pack\nlooks so heavy!\012Oh! Do you happen\nto have something\011named EON MAIL?\012My daughter is\nafter one.\012You can part with\none, can't you?",
  ["18:648c"] = "Give away an EON\nMAIL?",
  ["18:64a4"] = "Oh, that's great!\nThank you, honey!\012Here, this is for\nyou in return!",
  ["18:64e9"] = "My daughter will\nbe delighted!",
  ["18:6509"] = "Oh? You don't have\none? Too bad.",
  ["18:652a"] = "Oh… Well, another\ntime, then.",
  ["18:6549"] = "{PLAYER} gave away\nthe EON MAIL.",
  ["18:6674"] = "POKéCOM CENTER and\nMOBILE CENTER were\012built to satisfy\ndemands for trades\012and battles with\ntrainers far away\012and with total\nstrangers.",
  ["18:66f9"] = "When you linked\nwith someone by\012mobile phone for\nthe first time,\012weren't you\nimpressed?\012When my first try\nworked, I was so\012impressed that I\ngot the shakes!",
  ["18:6795"] = "They were able to\nbuild this huge\012facility thanks to\nadvances in wire-\011less technology.",
  ["18:67ee"] = "It's a notice\nabout where MOBILE\012ADAPTERS are to be\nused…",
  ["18:6828"] = "There's a POKéCOM\nCLUB upstairs in\012any POKéMON\nCENTER.\012There, you can\nbattle or trade\012with a friend far\naway by using a\011MOBILE ADAPTER.\012To link up, your\nfriend must have\012the same kind of\nMOBILE ADAPTER as\011you.",
  ["18:68f4"] = "To use the TRADE\nCORNER or read the\012POKéMON NEWS, you\nneed to phone the\011MOBILE CENTER.\012You must register\nat the MOBILE\012CENTER before\nconnecting there.",
  ["18:6989"] = "It's a notice\nabout using the\011phone…",
  ["18:69ae"] = "Please ensure that\nyour phone and\012MOBILE ADAPTER are\nproperly linked.\012Please make sure\nthe wireless phone\011signal is strong.\012Don't touch or\nhang up the phone\011while linking.",
  ["18:6a5a"] = "If the server is\nbusy, it may not\012be possible to log\non.\012If so, please call\nback later.\012If you are unable\nto log on or don't\012understand the\nerror messages,\012call a support\ncenter or read the\011instructions.",
  ["18:6b26"] = "The ADMINISTRATION\nOFFICE received an\011e-mail. It says…\012…… …… ……\012To the POKéCOM\nCENTER staff…\012Wireless communi-\ncation has enabled\012POKéMON trainers\nto interact across\012the nation. Let's\nkeep working for\012the day when all\nthe trainers in\012the world can link\nwithout barriers!\012…… …… ……",
  ["18:6c80"] = "ILEX FOREST is\nbig. Be careful!\011Don't get lost.",
  ["18:6cb0"] = "The FOREST is\nwatched over by\011its protector.\012Stay out of\nmischief!",
  ["18:6d9d"] = "Oh, honey. You're\nmaking a POKéDEX?\012It must be hard if\nPOKéMON won't\012appear. Try using\nthis TM.",
  ["18:6df6"] = "It's SWEET SCENT.\012Use it wherever\nPOKéMON appear.\012POKéMON will be\nenticed by it.",
  ["18:6e41"] = "Something's wrong\nin ILEX FOREST…\012You should stay\naway right now.",
  ["18:6e83"] = "BUTTERFREE: Freeh!",
  ["18:6e97"] = "Did you see the\nshrine honoring\011the protector?\012It watches over\nthe FOREST from\011across time.\012I think that it\nmust be a grass-\011type POKéMON.",
  ["18:6fda"] = "Gramps was looking\nfor you.",
  ["18:70ce"] = "I'm the DAY-CARE\nMAN.\012Do you know about\nEGGS?\012I was raising\nPOKéMON with my\011wife, you see.\012We were shocked to\nfind an EGG!\012How incredible is\nthat?\012Well, wouldn't you\nlike this EGG?\012Then fine, this is\nyours to keep!",
  ["18:71ae"] = "{PLAYER} received\nODD EGG!",
  ["18:71c3"] = "I found that when\nI was caring for\012someone's POKéMON\nbefore.\012But the trainer\ndidn't want the\012EGG, so I'd kept\nit around.",
  ["18:7237"] = "You've no room for\nthis.",
  ["19:4000"] = "I hate having to\nhang up on you!\012Call you later!",
  ["19:4032"] = "{PLAYER}, have you\nheard?\012GOLDENROD's RADIO\nTOWER has been\012taken over by TEAM\nROCKET!\012…Um… What's TEAM\nROCKET?",
  ["19:4099"] = "{PLAYER}, I heard!\012You defeated that\nWHITNEY?\012It makes me proud\nto be your friend!",
  ["19:40e6"] = "Hey, I heard about\nyou!\012You saved that\nPOKéMON at the\012LIGHTHOUSE, didn't\nyou?\012{PLAYER}, I wish\nyou'd come see me\012when I'm sick in\nbed with a cold!",
  ["19:416d"] = "I heard, I heard,\nI heard!\012You smashed TEAM\nROCKET's hideout!\012You're like a\nmovie hero, even!\012But um… What was\nTEAM ROCKET?",
  ["19:41e8"] = "I heard, I heard,\nI heard!\012About your heroic\nliberation of the\012RADIO TOWER! You\nrock so hard!",
  ["19:4247"] = "I saw, I saw!\012I saw you go into\nthe DRAGON'S DEN!\012I'm certain you\npassed! Aww, no\012need to be modest!\nYou can't fail!",
  ["19:42bb"] = "Yesterday, I went\nout to NEW BARK\012TOWN.  There was a\nlady who looked a\012lot like you,\n{PLAYER}.\012What? That lady\nwas your mom?\012Aww, I should've\nintroduced myself!\012I bet your mom's\nreally proud of\012all that you've\naccomplished.\012Heh, put it this\nway. I'd be proud\012if I were your\nmom, believe me!",
  ["19:43d4"] = "I saw, I saw,\nI saw!\012You striding onto\na ship, {PLAYER}!\012I can't get over\nhow good you look\012with the sea as\nyour backdrop!",
  ["19:4448"] = "I heard, I heard!\012You got a MAGNET\nTRAIN PASS!\012When I saw you\ndeparting on the\012ship, I felt sad\nthat I wouldn't be\012able to see you\nfor a while.\012But since you have\nthat PASS, you can\012zip back anytime!\nThat's reassuring!\012What? You can FLY\nback anytime?\012What do you mean\nby FLY?",
  ["19:455b"] = "I saw, I saw!\012You waking up\nSNORLAX!\012I was watching you\nfrom afar, so I\012couldn't tell what\nyou did exactly.\012Did you play a\nflute to wake it?\012Wow! That's like\nmagic!",
  ["19:45ff"] = "I hear rumors\nabout you all over\011the place.\012It just makes me\nsigh, {PLAYER}.\012How did you get so\nstrong?\012Go for the world\nchampionship now!\012I'll always be\ncheering you on!",
  ["19:46a3"] = "Hehe, I called\nright away!\012I think we can be\ngood friends!",
  ["19:46df"] = "I saw, I heard!\012You beat MORTY of\nECRUTEAK GYM!\012Th-that's just\nincredible!\012I actually went to\nthe GYM's entrance\012to cheer you on.\nDid you know that?\012But everyone was\nfloating, and\012there were ghosts\nall over! So I\012chickened out and\ntook off for home…",
  ["19:47d8"] = "{PLAYER}, I heard!\012You're kicking up\na mighty ruckus\012over in KANTO!\nWhat a glorious\012rampage it must\nbe!\012You so rock!",
  ["19:4846"] = "Hearing about your\nescapades rocks my\012soul!\nIt sure does!",
  ["19:4881"] = "I'm so glad you\ncalled!\012I was just about\nto call you too!\012I guess we must be\na good match!",
  ["19:48dc"] = "How are you?\012What are you\ndoing?\012Where are you?\012How many BADGES do\nyou have now?\012How much money\nhave you saved?\012How's your mom?\012Have you got lots\nof POKéMON?\012Is it going to be\nsunny tomorrow?\012Arrgh, there's so\nmuch I want to\012chat about! This\nis going nowhere!",
  ["19:49dc"] = "I'm always with my\n{STRBUF}!\012It's so cute!\nI just love it!",
  ["19:4a13"] = "Changing the topic\nhere, I saw this\012{STRBUF} for the\nfirst time.\012It was easy to\nbeat, actually.",
  ["19:4a71"] = "I was wondering,\ndo you happen to\011have {STRBUF}?\012I can't seem to\ncatch one. What is\012its weakness, I\nwonder.",
  ["19:4ada"] = "Hey, let's battle\nour POKéMON!\012I won't lose to\nyou battling or in\012the Bug-Catching\nContest!\012I'll be here on\n{STRBUF}!",
  ["19:4b48"] = "Let's talk again,\nhuh?",
  ["19:4b5f"] = "Boy, am I glad I\ncaught you!\012A whole bunch of\n{STRBUF} have\012appeared around\n{STRBUF}!\012You have to see\nthis!",
  ["19:4bc6"] = "I haven't had any\nluck seeing rare\011POKéMON lately…\012But I know they're\nout there!",
  ["19:4c13"] = "Hey, where are you\nnow?\012Let's battle. I'll\nbe waiting for you\011on {STRBUF}!",
  ["19:4c5a"] = "Hello? Are you\ncoming or what?\012You're missing out\non seeing YANMA!\012Get down to ROUTE\n35 right now!",
  ["19:4cbd"] = "My {STRBUF}'s\ngetting stronger,\012exactly as I\ncalculated!",
  ["19:4cf3"] = "By the way, we\nknocked out a wild\012{STRBUF} just\nthe other day.\012Studying up in\nadvance worked!",
  ["19:4d4f"] = "By the way, a wild\n{STRBUF} escaped\011on me yesterday.\012A computational\nerror on my part…",
  ["19:4da4"] = "I've studied quite\na bit since then,\012and I've gotten a\nlot better!\012I'm hanging out on\n{STRBUF}.\012Can you come down\nfor a battle?",
  ["19:4e1f"] = "See you later!",
  ["19:4e2f"] = "Hehehe, I picked\nup something nice!\012You can have it!\nWhy don't you come\012to {STRBUF}\nand pick it up?",
  ["19:4e90"] = "I haven't picked\nup anything yet.\012I'll call you if I\nfind something.",
  ["19:4ed4"] = "If we don't battle\nsoon, I'll forget\011my strategy!\012I'm waiting on\n{STRBUF}!",
  ["19:4f1a"] = "I have to do my\nhomework, so can\012you come get your\ngift right away?\012I'm waiting on\n{STRBUF}!",
  ["19:4f74"] = "My {STRBUF} is\ngetting prettier!\012I've been taking\nphotos galore!",
  ["19:4fb2"] = "It took only an\ninstant to KO a\011wild {STRBUF}.\012It must be because\nyou gave me some\012battling tips last\ntime.",
  ["19:501c"] = "You know what?\nA wild {STRBUF}\012got away from me\nagain.\012It was so close!\nReally, just a\012little bit more,\nand I would've…",
  ["19:5091"] = "Right now, I'm on\n{STRBUF}.\012If you're close\nby, let's battle!\012I'll be waiting\nfor you!",
  ["19:50e2"] = "See you!",
  ["19:50ec"] = "You know what?\nI got a good gift!\012As I promised,\nit's yours!\012I'm sure you'd\nlike it. Come get\012it! I'm waiting on\n{STRBUF}!",
  ["19:5161"] = "Oh! You wanted a\ngift, right?\012I got one, but I\nwant to keep this.\012Can you wait a bit\nlonger?",
  ["19:51bf"] = "Hi! You haven't\nforgotten about\012your promise to\nbattle me?\012I'm waiting on\n{STRBUF}!",
  ["19:520f"] = "Hello?\012If you don't come\nget your present\012soon, I'll give it\nto someone else.\012I'm waiting on\n{STRBUF}!",
  ["19:5271"] = "I recently began\nobserving wild\011{STRBUF}.\012I've been learning\nall sorts of new\012things through my\nobservations.\012I wish I could\nbecome a POKéMON\012researcher like\nPROF.OAK soon.",
  ["19:5318"] = "Oh yes, I managed\nto knock out a\012wild {STRBUF} a\nwhile back.\012Well, considering\nall the studying I\012do every day, it\nwas inevitable.",
  ["19:5399"] = "Oh yes, I came\nclose to catching\012a wild {STRBUF},\nbut it got away.\012For the longest\ntime, I've been\012wanting to observe\n{STRBUF}. Rats…",
  ["19:5419"] = "Want to battle?\nI have to battle\012every so often to\navoid rusting out.\012I'll be on\n{STRBUF}!",
  ["19:5471"] = "See you later!",
  ["19:5481"] = "Do you know BLUE?\012He's PROF.OAK's\ngrandson and a\012former POKéMON\nLEAGUE CHAMPION!\012He's one super\nPOKéMON trainer!",
  ["19:54ea"] = "PROF.OAK has a\ngranddaughter\011named DAISY.\012When she's around,\neven the most\012ferocious POKéMON\ncalm right down.",
  ["19:5555"] = "Everyone's talking\nabout PROF.ELM.\012He used to be an\nassistant to the\011great PROF.OAK!\012That is so cool!\nI envy him!",
  ["19:55c7"] = "PROF.OAK's dream\nis to compile a\012comprehensive\nPOKéDEX.\012I envy you for\ntaking part in\011that project…",
  ["19:5628"] = "Do you know KURT,\nthe BALL creator?\012He and PROF.OAK go\nback a long way.\012I guess great\npeople attract one\011another!",
  ["19:569b"] = "POKéMON LEAGUE is\nthe great gather-\011ing place for all\012trainers who wish\nto become CHAMP.\012PROF.OAK acts as\nan advisor to the\012POKéMON LEAGUE's\nheadquarters.\012He really is a\ngreat man.",
  ["19:574a"] = "PROF.OAK'S POKéMON\nTALK is a popular\011radio show, right?\012Did you know that\nhe was going to\012turn down the show\nat first?\012But MARY's energy\nand persistence\011wore him down.\012So we have MARY to\nthank for it!",
  ["19:5810"] = "PROF.OAK used to\nbe a trainer a\011long time ago.\012But rather than\nbattling, he found\012POKéMON themselves\nto be interesting.\012So he abandoned\nhis training to\012focus on becoming\na researcher.",
  ["19:58c6"] = "PROF.OAK has a\ngranddaughter\011named DAISY.\012She has tea every\nday for an hour\012from three in the\nafternoon.\012I wish I could\njoin her for tea\012and chat about\nPROF.OAK.",
  ["19:5969"] = "Did you know?\nPROF.OAK traveled\012all over the world\nwhen he was young.\012While traveling,\nhe must've learned\012about POKéMON\nnaturally.\012I envy him…\nI'd like to travel\012and learn about\nthings too…",
  ["19:5a23"] = "I'm going to study\nhard so PROF.OAK\012will make me his\nassistant!",
  ["19:5a63"] = "Do you remember\nabout our battle?\012The place is\n{STRBUF}.\012Hurry over--I'm\nwaiting.",
  ["19:5ab2"] = "Listen to this.\nMy {STRBUF}\012grins happily when\nI pinch its cheek.\012But it never grins\nfor anyone else.\012I must be special.",
  ["19:5b29"] = "Oh, and recently,\nmy PIKACHU beat a\011wild {STRBUF}!\012A wild {STRBUF},\nI tell you!\012Don't you think\nthat's astounding?\012My PIKACHU is\nawesome!\012My PIKACHU is the\ngreatest!",
  ["19:5bc8"] = "Oh, and I saw a\nwild {STRBUF} a\011little while ago.\012But it wasn't very\ncute, so I left\012it…\nPOKéMON have to be\012cute. They're no\ngood otherwise.",
  ["19:5c4e"] = "Well, let's talk\nagain!",
  ["19:5c66"] = "Did you remember?\nThe Bug-Catching\011Contest is today.\012You're going to\ngo, aren't you?\012I think I'll\nparticipate with\012PIKACHU to show\noff its cuteness.",
  ["19:5cf9"] = "I'd like you to\nhave a NUGGET.\012My PIKACHU just\nloves it.\012I'm certain your\nPIKACHU will love\011it too!",
  ["19:5d5c"] = "How is your\nPIKACHU doing?\012Let's get together\nand brag about our\011PIKACHU!",
  ["19:5da6"] = "What's wrong?\012I'm waiting on\n{STRBUF}.\012Come pick this up\nanytime.",
  ["19:5de4"] = "My {STRBUF} has\ngrown again.\012It was only about\nso big when I\012caught it, but now\nit's way bigger.",
  ["19:5e42"] = "Oh yeah, I KO'd a\nwild {STRBUF}.\012It was huge, like\nthis big even.\012Heh, I guess you\ncan't tell over\011the phone…",
  ["19:5eac"] = "Oh yeah, I lost a\nwild {STRBUF}.\012It was huge, like\nthis big even.\012Heh, I guess you\ncan't tell over\011the phone…",
  ["19:5f17"] = "We should get a\nbattle going!\012I'll be fishing on\n{STRBUF}.\012Swing by if you\nhave the time.",
  ["19:5f6e"] = "Well, I'll be\nseeing you.",
  ["19:5f88"] = "I picked up a good\nlittle thing at\011the water's edge.\012Like I promised,\nit's yours.\012I'll be waiting on\n{STRBUF}.",
  ["19:5ff2"] = "Have I found\nanything good?\012Nope, not yet.\012It's like fishing,\nyou need patience.",
  ["19:6043"] = "Yup, TULLY here…\012{PLAYER}? What?\nYou're lost?\012Our battle will be\non {STRBUF}.",
  ["19:6087"] = "I've got something\ngood for you.\012Hustle over to\n{STRBUF}.",
  ["19:60be"] = "Oh yeah, I got an\nextremely rare\012POKéMON in a trade\na while back.\012Do you want to\nknow what it is?\012Hehe, I'm keeping\nit a secret!",
  ["19:613c"] = "Oh yeah, I took\ndown this wild\012{STRBUF}.\nIt wasn't rare\012enough to bother\ncatching.",
  ["19:618c"] = "Oh yeah, I saw a\nrare POKéMON about\011an hour ago.\012It was my first\nsighting. But I\012didn't have any\nPOKé BALLS…\012Would BILL laugh\nat my mistakes?",
  ["19:6214"] = "You've got time\nlike usual, right?\012Feel like having a\nbattle?\012It'll be a chance\nto see my rare\012POKéMON. It'll be\nworth your time!\012You know where--\n{STRBUF}.",
  ["19:62a9"] = "So that's it then.",
  ["19:62bc"] = "Did you know…?\nBILL's father is\012supposed to be a\ngreat POKéMANIAC.",
  ["19:62fc"] = "Did you know…?\nApparently BILL's\012grandpa isn't a\nPOKéMANIAC.",
  ["19:6335"] = "Did you know…?\nBILL's originally\011from GOLDENROD.",
  ["19:6366"] = "Did you know…?\nBILL evidently\012lives on ROUTE 25\nin KANTO.",
  ["19:63a1"] = "Did you know…?\nABRA was the first\012POKéMON that BILL\nostensibly caught.",
  ["19:63e6"] = "Did you know…?\nBILL's younger\012sister apparently\ncan't wink.",
  ["19:6421"] = "Did you know…?\nBILL supposedly\012hates milk and\ncan't drink it.",
  ["19:645f"] = "Did you know…?\nEvidently, BILL\012isn't very good at\nbattling.",
  ["19:649b"] = "Did you know…?\nBILL appears to\012like the lady at\nthe FLOWER SHOP.",
  ["19:64dd"] = "Did you know…?\nBILL's mother is\012said to have been\na KIMONO GIRL.",
  ["19:651e"] = "You wanted to hear\nabout BILL?\012Sorry, but I'm too\nbusy for you.\012I'll call when I\nhave time.",
  ["19:6579"] = "You want to see my\nrare POKéMON.\012Hurry over to\n{STRBUF}.",
  ["19:65ad"] = "My {STRBUF}'s\nadorable, don't\012you think so?\nI always sleep\012with it--it's so\nfluffy and warm!",
  ["19:6605"] = "Oh, and we had to\nbattle a wild\012{STRBUF} a while\nago…\012My CLEFAIRY came\nclose to fainting!\012Isn't that awful?\012I hate those nasty\n{STRBUF}!",
  ["19:6688"] = "Oh, and we had to\nbattle a wild\012{STRBUF} a while\nago…\012My CLEFAIRY got\nfrightened, so we\012ran away as fast\nas we could!\012I just can't help\nfeeling protective\011of my CLEFAIRY.",
  ["19:6730"] = "I know this might\nsurprise you, but\012would you like to\nbattle?\012I'll be waiting\nwith CLEFAIRY on\011{STRBUF}.",
  ["19:6796"] = "{STRBUF}!\012It's awful.\nMy CLEFAIRY…\012Huh? {PLAYER}?\012Oh, sorry! I was\nin a hurry, and I…\012I have to go!\nBye-bye!",
  ["19:67f7"] = "Bye-bye!",
  ["19:6801"] = "I bought some PINK\nBOWS at GOLDENROD\012DEPT.STORE for my\nCLEFAIRY.\012I got too many, so\nI'll give you one!\012Come collect it on\n{STRBUF}.",
  ["19:6882"] = "I love dressing up\nmy CLEFAIRY!",
  ["19:68a3"] = "What's wrong?\nCan't you visit?\012CLEFAIRY got tired\nand fell asleep.\012I'm not sure if I\ncan wake it up…\012Please hurry to\n{STRBUF}!",
  ["19:691d"] = "What's wrong?\nCan't you visit?\012I'm sure this will\nlook good on your\011CLEFAIRY.\012Please hurry to\n{STRBUF}!",
  ["19:6980"] = "My {STRBUF}'s\nbecome tougher.\012We've achieved\nliftoff!",
  ["19:69b2"] = "We can easily beat\n{STRBUF}!\012…Huh? You too?\nIsn't that great?",
  ["19:69ed"] = "But get this, a\nwild {STRBUF}\012just barely eluded\nus.\012I wanted to FLY\nafter it…",
  ["19:6a3a"] = "Right now, I'm on\n{STRBUF}.\012You know, where I\nfirst met you?\012Want to battle?\nI'll wait here.",
  ["19:6a93"] = "OK, bye for now!",
  ["19:6aa5"] = "I'll be looking\nforward to our\011next battle!",
  ["19:6ad1"] = "Oh, {PLAYER}!\nHurry, hurry!\012{STRBUF}!\nFLY over now!",
  ["19:6afc"] = "My {STRBUF}'s\ngrown impressive!\012My fishing skills\nhave improved too!",
  ["19:6b3e"] = "We beat a wild\n{STRBUF}…\012You know, I have\nmore fun fishing\012than beating wild\nPOKéMON.",
  ["19:6b8f"] = "But a while back,\nwe came this close\012to landing a wild\n{STRBUF}.\012I tell you, it was\nhuge. Believe me.",
  ["19:6bf3"] = "I'm fishing on\n{STRBUF},\012but nothing's\nbiting today.\012Help me while my\ntime away, come\011over for a battle.",
  ["19:6c58"] = "All right, later.",
  ["19:6c6b"] = "I snagged an item\nwhile fishing.\012Come pick it up on\n{STRBUF}.",
  ["19:6ca7"] = "Nah, I haven't\nfound anything\012that's worth your\ntime.\012You have to have\npatience.",
  ["19:6cf7"] = "Sigh…\nThey're not biting\012like before on\n{STRBUF}…\012You have to come\nfor a battle!",
  ["19:6d45"] = "Don't you want\nthis item?\012Hah? You don't\nknow where?\012{STRBUF}…\nJust head from\012MAHOGANY toward\nBLACKTHORN!",
  ["19:6dab"] = "Anyway, we'll chat\nagain!",
  ["19:6dc5"] = "Are you still on\nyour journey?\012I remain dedicated\nto my training.\012Oooooaaarrrgh!",
  ["19:6e17"] = "I'm in training\nnow. I apologize,\012but call me back\nanother time.\012Oooooaaarrrgh!",
  ["19:6e67"] = "I apologize, but I\ndon't have time to\012chat while I am in\ntraining!\012I'll have time to\nchat tomorrow!\012Yiiihah!",
  ["19:6ed3"] = "I plan to take a\nlunch break, so\012come see me then!\nAyiiiyah!",
  ["19:6f11"] = "I'm taking a break\non ROUTE 45!\012Why not drop by if\nyou are free?",
  ["19:6f52"] = "I rested up over\nmy lunch break.\012Now it's time to\nresume training!\012Oooryaah!",
  ["19:6f9f"] = "Nothing can match\nmy {STRBUF} now.",
  ["19:6fc0"] = "Yeah, we KO'd a\nwild {STRBUF}!\012That was OK, but I\nwanted to get it…",
  ["19:7001"] = "And yesterday, we\nspotted a wild\012{STRBUF}.\nWe were debating\012whether to catch\nit or beat it.\012When along came\nanother guy who\012caught it!\nHow about that!",
  ["19:7096"] = "You're thinking\nyou'd like to\012battle me. Am I\nright or what?\012Yep! We'll meet on\n{STRBUF}!",
  ["19:70eb"] = "OK, give me a call\nagain!",
  ["19:7106"] = "You'll battle with\nme again, right?",
  ["19:712a"] = "Haven't you gotten\nto {STRBUF}?\012Waiting here isn't\nbad, but I'd sure\011like to battle!",
  ["19:717a"] = "{STRBUF}'s {STRBUF}\nis much stronger\011than before!",
  ["19:71a4"] = "And, and…\nI just battled and\011beat {STRBUF}!\012I've raised my\nPOKéMON properly!",
  ["19:71eb"] = "But, but…\012A wild {STRBUF}\ngot away from me\012again. It's just\nnot fair!",
  ["19:722e"] = "I'm ERIN. Want to\nbattle me again?\012I won't lose this\ntime!\012I'll be waiting on\n{STRBUF}!",
  ["19:7281"] = "See you. Bye-bye!",
  ["19:7294"] = "I'm working hard\nto raise my\011POKéMON!\012Come back for\nanother battle!",
  ["19:72d5"] = "Oh, {PLAYER}!\nCome battle ERIN!\012I'll be waiting on\n{STRBUF}!",
  ["1a:405a"] = "There's no cheat-\ning in POKéMON.\012Let's keep it fair\nand square!",
  ["1a:4097"] = "Huh? How did this\nhappen?",
  ["1a:40b2"] = "I fought fair and\nsquare with honor.\012I don't regret\nthis at all.",
  ["1a:40f3"] = "It itches and\ntickles a bit when\012I wear shorts in\nthe grass.",
  ["1a:4131"] = "Aiyaaah!\nI got stomped!",
  ["1a:414a"] = "I'm going to catch\nmore POKéMON in\011the grass.",
  ["1a:417b"] = "…\012I lost while I had\nmy eyes closed…",
  ["1a:41a1"] = "I can see it…\012Everything to see\nabout you…",
  ["1a:41cd"] = "I couldn't foresee\nyour power…",
  ["1a:41ec"] = "Strength in con-\nviction…\012You're strong be-\ncause you believe\011in your POKéMON.",
  ["1a:4238"] = "ROUTE 11",
  ["1a:42a2"] = "When you first\ncatch a POKéMON,\011it may be weak.\012But it will even-\ntually grow to be\011strong.\012It's important to\ntreat POKéMON with\011love.",
  ["1a:4323"] = "POKéMON can hold\nitems like POTION\011and ANTIDOTE.\012But they don't\nappear to know how\012to use manmade\nitems.",
  ["1a:4473"] = "I'm FALKNER, the\nVIOLET POKéMON GYM\011leader!\012People say you can\nclip flying-type\012POKéMON's wings\nwith a jolt of\011electricity…\012I won't allow such\ninsults to bird\011POKéMON!\012I'll show you the\nreal power of the\012magnificent bird\nPOKéMON!",
  ["1a:454a"] = "…Darn! My dad's\ncherished bird\011POKéMON…\012All right.\nTake this.\012It's the official\nPOKéMON LEAGUE\011ZEPHYRBADGE.",
  ["1a:45af"] = "{PLAYER} received\nZEPHYRBADGE.",
  ["1a:45c8"] = "ZEPHYRBADGE\nraises the attack\011power of POKéMON.\012It also enables\nPOKéMON to use\012FLASH, if they\nhave it, anytime.\012Here--take this\ntoo.",
  ["1a:4648"] = "By using a TM, a\nPOKéMON will\012instantly learn a\nnew move.\012Think before you\nact--a TM can be\011used only once.\012TM31 contains\nMUD-SLAP.\012It reduces the\nenemy's accuracy\012while it causes\ndamage.\012In other words, it\nis both defensive\011and offensive.",
  ["1a:4735"] = "There are POKéMON\nGYMS in cities and\011towns ahead.\012You should test\nyour skills at\011these GYMS.\012I'm going to train\nharder to become\012the greatest bird\nmaster!",
  ["1a:47cd"] = "The keyword is\nguts!\012Those here are\ntraining night and\012day to become bird\nPOKéMON masters.\012Come on!",
  ["1a:482f"] = "Gaaah!",
  ["1a:4837"] = "FALKNER's skills\nare for real!\012Don't get cocky\njust because you\011beat me!",
  ["1a:487f"] = "Let me see if you\nare good enough to\011face FALKNER!",
  ["1a:48b3"] = "This can't be\ntrue!",
  ["1a:48c7"] = "This is pathetic,\nlosing to some\011rookie trainer…",
  ["1a:48f9"] = "Hey! I'm no train-\ner but I can give\011some advice!\012Believe me!\nIf you believe, a\012championship dream\ncan come true.\012You believe?\nThen listen.\012The grass-type is\nweak against the\012flying-type. Keep\nthis in mind.",
  ["1a:49c8"] = "Nice battle! Keep\nit up, and you'll\012be the CHAMP in no\ntime at all!",
  ["1a:4b3b"] = "EARL, I am!\012Wonderful are\nPOKéMON, yes!\012Teach you I will\nto be a better\011trainer!\012What you want to\nknow? Want to be\011a winner is you?",
  ["1a:4bbd"] = "Good! Teach you,\nI will!\012In battle, POKéMON\ntop on list jump\011out first!\012Change order in\nlist, make battle\011easy, maybe!\012More from me you\nwant to hear?",
  ["1a:4c51"] = "So, want to know\nhow to raise\011POKéMON well?",
  ["1a:4c7b"] = "Fine! Teach you,\nI will!\012If POKéMON come\nout in battle even\012briefly, some EXP.\nPoints it gets.\012At top of list put\nweak POKéMON.\012Switch in battle\nquick!\012This way, weak\nPOKéMON strong\011become!",
  ["1a:4d31"] = "Oh! Smart student\nyou are! Nothing\011more do I teach!\012Good to POKéMON\nyou must be!",
  ["1a:4d80"] = "I'm taking notes\nof the teacher's\011lecture.\012I'd better copy\nthe stuff on the\011blackboard too.",
  ["1a:4dda"] = "I traded my best\nPOKéMON to the\011guy beside me.",
  ["1a:4e07"] = "Huh? The POKéMON I\njust got is hold-\011ing something!",
  ["1a:4e39"] = "A POKéMON holding\na BERRY will heal\011itself in battle.\012Many other items\ncan be held by\011POKéMON…\012It sure is tough\ntaking notes…",
  ["1a:4eb2"] = "The blackboard\ndescribes POKéMON\012status changes in\nbattle.",
  ["1a:4efe"] = "If poisoned, a\nPOKéMON steadily\011loses HP.\012Poison lingers\nafter the battle,\012and HP is lost as\nyou walk.\012To cure it, use an\nANTIDOTE.",
  ["1a:4f80"] = "Paralysis reduces\nspeed and may\011prevent movement.\012It remains after\nbattle, so use\011a PARLYZ HEAL.",
  ["1a:4fe2"] = "If asleep, your\nPOKéMON can't make\011a move.\012A sleeping POKéMON\ndoesn't wake up\011after battle.\012Wake it up with\nan AWAKENING.",
  ["1a:5055"] = "A burn steadily\nconsumes HP.\012It also reduces\nattack power.\012A burn lingers\nafter battle.\012Use a BURN HEAL as\nthe cure.",
  ["1a:50cb"] = "If your POKéMON is\nfrozen, it can't\011do a thing.\012It remains frozen\nafter battle.\012Thaw it out with\nan ICE HEAL.",
  ["1a:5136"] = "It's this kid's\nnotebook…\012Catch POKéMON\nusing POKé BALLS.\012Up to six can be\nin your party.\012Keep reading?",
  ["1a:5197"] = "Before throwing a\nPOKé BALL, weaken\011the target first.\012A poisoned or\nburned POKéMON is\011easier to catch.\012Keep reading?",
  ["1a:5207"] = "Some moves may\ncause confusion.\012Confusion may make\na POKéMON attack\011itself.\012Leaving battle\nclears up any\011confusion.\012Keep reading?",
  ["1a:5287"] = "People who catch\nand use POKéMON\012in battle are\nPOKéMON trainers.\012They are expected\nto visit POKéMON\012GYMS and defeat\nother trainers.\012The next page\nis… Blank!\012Boy: E-he-he…\012I haven't written\nanymore…",
  ["1a:53fa"] = "She uses the names\nof her favorite\011things to eat.\012For the nicknames\nshe gives to her\011POKéMON, I mean.",
  ["1a:545e"] = "I call my PIDGEY\nSTRAWBERRY!",
  ["1a:547c"] = "STRAWBERRY: Pijji!",
  ["1a:5555"] = "{PLAYER}, long\ntime, no see.\012PROF.ELM asked me\nto find you.\012He has another\nfavor to ask.\012Would you take the\nPOKéMON EGG?",
  ["1a:55c5"] = "We discovered that\na POKéMON will not\012hatch until it\ngrows in the EGG.\012It also has to be\nwith other active\011POKéMON to hatch.\012{PLAYER}, you're\nthe only person\011we can rely on.\012Please call PROF.\nELM when that EGG\011hatches!",
  ["1a:5693"] = "Oh, no. You can't\ncarry any more\011POKéMON with you.\012I'll wait here\nwhile you make\011room for the EGG.",
  ["1a:56f2"] = "B-but… PROF.ELM\nasked for you…",
  ["1a:5712"] = "{PLAYER}, will you\ntake the EGG?",
  ["1a:5809"] = "A guy named BILL\nmade the POKéMON\011PC storage system.",
  ["1a:583c"] = "It was around\nthree years ago.\012TEAM ROCKET was up\nto no good with\011POKéMON.\012But justice pre-\nvailed--a young\011kid broke 'em up.",
  ["1a:58b8"] = "POKéMON are smart.\nThey won't obey a\012trainer they don't\nrespect.\012Without the right\nGYM BADGES, they\012will just do as\nthey please.",
  ["1a:5997"] = "A POKéMON you get\nin a trade grows\011quickly.\012But if you don't\nhave the right GYM\012BADGE, they may\ndisobey you.",
  ["1a:5a36"] = "RUINS OF ALPH\012A Look-and-Touch\nTourist Site\012Try the sliding\nstone panels!",
  ["1a:5a81"] = "You're studying\nthe RUINS?\012I see a scientist\nin the making.",
  ["1a:5abd"] = "There are drawings\non stone panels.\012I tried moving\nthem. I wonder\011what they are.",
  ["1a:5b83"] = "This is a great\nfishing spot.\012You saw people\nfishing? How\011about you?\012Would you like one\nof my RODS?",
  ["1a:5be8"] = "Heh, that's good\nto hear.\012Now you're an\nangler too!",
  ["1a:5c1b"] = "Fishing is great!\012If there's water,\nbe it the sea or a\012stream, try out\nyour ROD.",
  ["1a:5c6c"] = "Oh. That's rather\ndisappointing…",
  ["1a:5c8d"] = "Yo, kid. How are\nthey biting?",
  ["1a:5cac"] = "What should I make\nmy POKéMON hold?\012Maybe an item that\nincreases ATTACK\011power…",
  ["1a:5ddd"] = "Excuse me, kid!\nCan you do a guy\011a favor?\012Can you take this\nPOKéMON with MAIL\011to my friend?\012He's on ROUTE 31.",
  ["1a:5e48"] = "You will? Perfect!\nThanks, kid!\012My pal's a chubby\nguy who snoozes\011all the time.\012You'll recognize\nhim right away!",
  ["1a:5eb8"] = "{PLAYER} received a\nPOKéMON with MAIL.",
  ["1a:5ed6"] = "You can read it,\nbut don't lose it!\011ROUTE 31!\012Oh, yeah. There\nwas a weird tree\011blocking the road.\012I wonder if it's\nbeen cleared?",
  ["1a:5f56"] = "You can't carry\nanother POKéMON…",
  ["1a:5f74"] = "Oh… Never mind,\nthen…",
  ["1a:5f8b"] = "Thanks, kid! You\nmade the delivery\011for me!\012Here's something\nfor your trouble!",
  ["1a:5fd9"] = "My pal was snooz-\ning, right? Heh,\011what'd I say?",
  ["1a:600a"] = "A strange tree is\nblocking the road.\012It wriggles around\nif you talk to it.\012I heard it became\nwild when someone\012watered it with a\nSQUIRTBOTTLE.",
  ["1a:609a"] = "I like the POKéMON\nLullaby they play\011on the radio.",
  ["1a:60cb"] = "I wonder how many\nkinds of POKéMON\012there are in the\nworld.\012Three years ago,\nPROF.OAK said that\012there were 150\ndifferent kinds.",
  ["1a:62eb"] = "Today's {STRBUF}.\nThat means the\012Bug-Catching Con-\ntest is on today.\012The rules are sim-\nple.\012Using one of your\nPOKéMON, catch a\012bug POKéMON to be\njudged.\012Would you like to\ngive it a try?",
  ["1a:639d"] = "Here are the PARK\nBALLS for the\011Contest.",
  ["1a:63c7"] = "{PLAYER} received\n20 PARK BALLS.",
  ["1a:63e2"] = "The person who\ngets the strong-\011est bug POKéMON\011is the winner.\012You have 20\nminutes.\012If you run out of\nPARK BALLS, you're\011done.\012You can keep the\nlast POKéMON you\011catch as your own.\012Go out and catch\nthe strongest bug\012POKéMON you can\nfind!",
  ["1a:64c6"] = "Uh-oh…\012You have more than\none POKéMON.\012You'll have to use\n{STRBUF}, the\012first POKéMON in\nyour party.\012Is that OK with\nyou?",
  ["1a:6537"] = "Fine, we'll hold\nyour other POKéMON\011while you compete.",
  ["1a:656b"] = "{PLAYER}'s POKéMON\nwere left with the\011CONTEST HELPER.",
  ["1a:6597"] = "Please choose the\nPOKéMON to be used\012in the Contest,\nthen come see me.",
  ["1a:65dc"] = "OK. We hope you'll\ntake part in the\011future.",
  ["1a:6608"] = "Uh-oh…\nThe first POKéMON\012in your party\ncan't battle.\012Please switch it\nwith the POKéMON\012you want to use,\nthen come see me.",
  ["1a:667c"] = "Uh-oh…\nBoth your party\012and your PC BOX\nare full.\012You have no room\nto put the bug\011POKéMON you catch.\012Please make room\nin your party or\012your PC BOX, then\ncome see me.",
  ["1a:671f"] = "Uh-oh…\nYou have an EGG as\012the first POKéMON\nin your party.\012Please switch it\nwith the POKéMON\012you want to use,\nthen come see me.",
  ["1a:679a"] = "You still have {STRBUF}\nminute(s) left.\012Do you want to\nfinish now?",
  ["1a:67db"] = "OK. Please wait at\nthe North Gate for\012the announcement\nof the winners.",
  ["1a:6823"] = "OK. Please get\nback outside and\011finish up.",
  ["1a:684f"] = "Today's Contest is\nover. We hope you\012will participate\nin the future.",
  ["1a:6894"] = "We hold Contests\nregularly in the\012PARK. You should\ngive it a shot.",
  ["1a:68d8"] = "When is the next\nBug-Catching Con-\011test going to be?",
  ["1a:690e"] = "The Bug-Catching\nContest is held on\012Tuesday, Thursday\nand Saturday.\012Not only do you\nearn a prize just\012for participating,\nyou also get to\012keep the bug\nPOKéMON you may\012have at the end of\nthe contest.",
  ["1a:6a20"] = "Don't you wonder\nwho'd make some-\011thing like this?\011And why?",
  ["1a:6a5b"] = "Did you see that\nstrange tree in\011the road?\012That may explain\nwhy fewer people\012are visiting the\nRUINS OF ALPH.",
  ["1a:6dd5"] = "Today's {STRBUF}.\nThat means the\012Bug-Catching Con-\ntest is on today.\012The rules are sim-\nple.\012Using one of your\nPOKéMON, catch a\012bug POKéMON to be\njudged.\012Would you like to\ngive it a try?",
  ["1a:6e87"] = "Here are the PARK\nBALLS for the\011Contest.",
  ["1a:6eb1"] = "{PLAYER} received\n20 PARK BALLS.",
  ["1a:6ecc"] = "The person who\ngets the strong-\011est bug POKéMON\011is the winner.\012You have 20\nminutes.\012If you run out of\nPARK BALLS, you're\011done.\012You can keep the\nlast POKéMON you\011catch as your own.\012Go out and catch\nthe strongest bug\012POKéMON you can\nfind!",
  ["1a:6fb0"] = "Uh-oh…\012You have more than\none POKéMON.\012You'll have to use\n{STRBUF}, the\012first POKéMON in\nyour party.\012Is that OK with\nyou?",
  ["1a:7021"] = "Fine, we'll hold\nyour other POKéMON\011while you compete.",
  ["1a:7055"] = "{PLAYER}'s POKéMON\nwere left with the\011CONTEST HELPER.",
  ["1a:7081"] = "Please choose the\nPOKéMON to be used\012in the Contest,\nthen come see me.",
  ["1a:70c6"] = "OK. We hope you'll\ntake part in the\011future.",
  ["1a:70f2"] = "Uh-oh…\nThe first POKéMON\012in your party\ncan't battle.\012Please switch it\nwith the POKéMON\012you want to use,\nthen come see me.",
  ["1a:7166"] = "Uh-oh…\nBoth your party\012and your PC BOX\nare full.\012You have no room\nto put the bug\011POKéMON you catch.\012Please make room\nin your party or\012your PC BOX, then\ncome see me.",
  ["1a:7209"] = "Uh-oh…\nYou have an EGG as\012the first POKéMON\nin your party.\012Please switch it\nwith the POKéMON\012you want to use,\nthen come see me.",
  ["1a:7284"] = "You still have {STRBUF}\nminute(s) left.\012Do you want to\nfinish now?",
  ["1a:72c5"] = "OK. Please wait\nhere for the\012announcement of\nthe winners.",
  ["1a:7300"] = "OK. Please go back\noutside and finish\011up.",
  ["1a:732b"] = "Today's Contest is\nover. We hope you\012will participate\nin the future.",
  ["1a:7370"] = "Some POKéMON can\nonly be seen in\011the PARK.",
  ["1a:7399"] = "DON: Wow, you beat\nme. You're pretty\011good.",
  ["1a:73c4"] = "DON: Luck plays a\nbig part in this.\012You never know\nwhat POKéMON will\011appear.",
  ["1a:740f"] = "ED: I envy you.\nI just couldn't\011do it this time.",
  ["1a:7440"] = "ED: Maybe you win\nwith big POKéMON?",
  ["1a:7462"] = "NICK: Well done!\nI'm going to raise\011my POKéMON better.",
  ["1a:7496"] = "NICK: Maybe you\nget a higher score\012for a POKéMON of\nan unusual color.",
  ["1a:74da"] = "WILLIAM: You're\nthe winner? What\011did you catch?",
  ["1a:750a"] = "WILLIAM: Well, I'm\nsatisfied because\012I caught a POKéMON\nthat I wanted.",
  ["1a:754e"] = "BENNY: Congrats!\nYou have earned my\011respect!",
  ["1a:757c"] = "BENNY: I caught a\nSCYTHER before,\011but I didn't win.",
  ["1a:75b0"] = "BARRY: That POKé-\nMON you caught…\011it's awesome!",
  ["1a:75dd"] = "BARRY: It's easier\nto win if you get\012a high-level bug\nPOKéMON.\012But I think they\nalso consider some\011other points.",
  ["1a:764b"] = "CINDY: You won?\nThat's great!\012Do you feel like\nlooking for bug\011POKéMON with me?",
  ["1a:7698"] = "CINDY: I really\nlove bug POKéMON!",
  ["1a:76b8"] = "JOSH: I… I can't\nbelieve I lost at\011bug-catching…",
  ["1a:76e9"] = "JOSH: I heard that\nsomebody won with\011a CATERPIE!",
  ["1a:771b"] = "SAMUEL: Next time,\nI'm going to win.",
  ["1a:7740"] = "SAMUEL: Darn.\nI thought I would\011score higher…",
  ["1a:776f"] = "KIPP: Could you\ngive me some tips?\012I want to study\nyour style.",
  ["1a:77af"] = "KIPP: I study a\nlot, but that's\012not good enough to\nwin.",
  ["1a:7910"] = "Uh-oh… Your PACK\nis full.\012We'll hold on to\nyour prize, but\011only for today.\012Please make room,\nthen come see me.",
  ["1a:797f"] = "{PLAYER}?\012Here's the prize\nwe were holding\011for you.",
  ["1b:406e"] = "We're the KANTO\nPOKéMON FEDERATION\011trainer group.\012We'll drive you\nunder our wheels!",
  ["1b:40be"] = "S-sorry!",
  ["1b:40c8"] = "The KANTO POKéMON\nFEDERATION will\011never fall!",
  ["1b:40f4"] = "The cops shut down\nour UNDERGROUND\012PATH! That really\nfries me!",
  ["1b:4134"] = "F-forgive me!",
  ["1b:4143"] = "Wiped out by some\npunk from JOHTO…",
  ["1b:4167"] = "We're the KANTO\nPOKéMON FEDERA-\011TION!\011Right on!",
  ["1b:4194"] = "Yikes! Sorry!",
  ["1b:41a3"] = "We'll try not to\ndisturb anyone\011from now on…",
  ["1b:41d0"] = "How does the MAG-\nNET TRAIN work?",
  ["1b:41f3"] = "I just want to see\nthe MAGNET TRAIN…",
  ["1b:4219"] = "The power of mag-\nnets is awesome!",
  ["1b:423d"] = "Hm… You've got\nmany GYM BADGES.",
  ["1b:425d"] = "Just as I thought…\nYou're tough!",
  ["1b:427e"] = "GYM BADGES give\nyou advantages in\011battles.",
  ["1b:42aa"] = "It's locked…",
  ["1b:42b7"] = "The flyer's torn.\012It's impossible to\nread…",
  ["1b:446b"] = "Arrgh… You found\nthe secret stair-\011way…",
  ["1b:4494"] = "Heheh! The experi-\nment worked like a\011charm.\012MAGIKARP are just\nworthless, but\012GYARADOS are big\nmoneymakers.",
  ["1b:4501"] = "Urrgh…\012That guy's dragon\nPOKéMON are tough…",
  ["1b:452a"] = "LANCE: DRAGONITE,\nHYPER BEAM.",
  ["1b:4549"] = "What took you,\n{PLAYER}?\012Just as I thought,\nthat strange radio\012signal is coming\nfrom here.",
  ["1b:459e"] = "The stairs are\nright here.",
  ["1b:45ba"] = "LANCE: {PLAYER}, we\nshould split up to\012check this place.\nI'll go first.",
  ["1b:4b12"] = "Hey!\nIntruder alert!",
  ["1b:4b28"] = "Dang… I failed…",
  ["1b:4b39"] = "It's my turn!\nThere's no escape!",
  ["1b:4b59"] = "Surveillance cams\nare in the POKéMON\011statues.\012We'll keep appear-\ning until you trip\011a secret switch.",
  ["1b:4bbb"] = "This was once a\nninja hideout.\012There are traps to\nconfound intruders\011like you.",
  ["1b:4c0b"] = "I get it…",
  ["1b:4c16"] = "All right. I'll\ndivulge a secret\011about our hideout.\012That thing on the\nfloor up ahead is\011a warp panel.\012If you step on it,\nyou'll be warped\012back to the en-\ntrance.",
  ["1b:4cb7"] = "Heheh. Feeling\nlucky, punk?\012Go ahead, take\nanother step.\012We've got traps\nset in the floor!",
  ["1b:4d12"] = "Kaboom!",
  ["1b:4d1b"] = "I don't even know\nwhere the traps\011are planted.\012You'll just have\nto collect your\011courage and walk.",
  ["1b:4d7c"] = "It's a PERSIAN\nstatue…\012Its eyes are oddly\nshiny.",
  ["1b:4dad"] = "A secret switch!\nBetter press it.",
  ["1b:4dd0"] = "The switch is\nturned off.",
  ["1b:52ad"] = "Hold it right\nthere!",
  ["1b:52c3"] = "We can't have a\nbrat like you on\011the loose.\012It's harmful to\nTEAM ROCKET's\011pride, you see.\012However strong you\nmay be, you can't\012take both of us at\nthe same time.\012Sorry, baby. Now\nget ready to be\011thrashed.",
  ["1b:538c"] = "Hey! Don't be so\nselfish. Spread\011the fun around.",
  ["1b:53bd"] = "What? You had an\naccomplice?\012Where is your\nsense of honor?\012As the interim\nboss in place of\012GIOVANNI, I'll\nshow you how wrong\012it is to meddle\nwith TEAM ROCKET!",
  ["1b:545c"] = "Tch, you really\nare strong.\012It's too bad.\012If you were to\njoin TEAM ROCKET,\012you could become\nan EXECUTIVE.",
  ["1b:54c6"] = "…This hideout is\ndone for…\012But that's fine.\nThe broadcast ex-\011periment was a\011total success.\012It doesn't matter\nwhat happens to\011this hideout now.\012We have much big-\nger plans.\012You'll come to\nappreciate TEAM\012ROCKET's true\npower soon enough.\012Enjoy yourself\nwhile you can…\012Fufufufu…",
  ["1b:55d8"] = "LANCE: That did\nit. We defeated\012all the ROCKETS\nhere.\012But I'm concerned\nabout the young\012guy I battled in\nthe process…",
  ["1b:564e"] = "Sorry, {PLAYER}.\nI saw how well you\012were doing, so I\njust hung back.\012Now all there is\nleft to do is to\012turn off that odd\nradio signal.",
  ["1b:56cf"] = "It's this machine\nthat's causing all\011the problems.\012I don't see a\nswitch on it…\012We have no choice.\nWe have to make\012all the ELECTRODE\nfaint.\012That should stop\nthis machine from\012transmitting that\nstrange signal.\012It's no fault of\nthe POKéMON, so it\012makes me feel\nguilty.\012{PLAYER}, let's\nsplit the job.",
  ["1b:57ea"] = "LANCE: Leave this\nside to me.",
  ["1b:5809"] = "LANCE: That odd\nsignal has finally\011stopped.\012The LAKE should be\nback to normal.\012You're the hero!\nLet me thank you\012on behalf of all\nthe POKéMON.\012Oh, yes. You\nshould take this.\012I found it here,\nbut I don't have\011any need for it.",
  ["1b:58f8"] = "That's WHIRLPOOL.\nTeach it to a\012POKéMON to get\nacross wild water.\012But keep this in\nmind.\012You can use that\nout of battle only\012with the BADGE\nfrom MAHOGANY GYM.",
  ["1b:5994"] = "{PLAYER}…\012The journey to be-\ncoming the POKéMON\012MASTER is long and\ndifficult.\012Knowing that, will\nyou keep going?\012…\012I see. No, you're\nright.\012If you would give\nup that easily,\012you would have\nnever chased that\012dream in the first\nplace.\012I look forward to\nseeing you again!",
  ["1b:5a97"] = "LANCE: Are you all\nright?\012Your POKéMON are\nhurt and tired.\012Here, give them\nsome of my medi-\011cine.",
  ["1b:5af7"] = "LANCE: {PLAYER},\nlet's give it our\011best for POKéMON.",
  ["1b:5b22"] = "The door won't\nopen?\012Well, duh.\nIt has to have a\012password that only\nTEAM ROCKET knows.",
  ["1b:5b79"] = "What? I lost?",
  ["1b:5b88"] = "Heh, I'm just a\nGRUNT.\012I don't know the\npassword. Too bad\011for you.",
  ["1b:5bca"] = "Oh, a kid? I don't\nreally like this,\012but eliminate you\nI must.",
  ["1b:5c09"] = "I knew I'd lose…",
  ["1b:5c1a"] = "I got wiped out on\nthe last mission\011by a kid too.\012When we were ab-\nducting POKéMON,\012this kid with long\nred hair and mean-\012looking eyes just\ncreamed me…",
  ["1b:5cb0"] = "You rotten little\npest!",
  ["1b:5cc9"] = "Grrrr…",
  ["1b:5cd1"] = "Heh, only the boss\nknows the password\011for that door.\012Where's the boss?\nWho knows? Go look\011for yourself.",
  ["1b:5d39"] = "The door's closed…\012It needs a pass-\nword to open.",
  ["1b:5d6b"] = "The door's closed…\012{PLAYER} entered\nthe password.\012The door opened!",
  ["1b:5da7"] = "It's the radio\ntransmitter that's\012sending the\nsinister signal.\012It's working at\nfull capacity.",
  ["1b:5e03"] = "The radio trans-\nmitter has finally\012stopped its evil\nbroadcast.",
  ["1b:6179"] = "LANCE: It takes\ntwo passwords to\012get into the\nboss's quarters.\012Those passwords\nare known only to\011a few ROCKETS.\012That ROCKET there\nvery graciously\011told me so.\012{PLAYER}, let's go\nget the passwords.",
  ["1b:6235"] = "Urrggh… The guy\nin the cape is\011incredibly tough…",
  ["1b:6267"] = "…\012Didn't I tell you\nthat I was going\012to destroy TEAM\nROCKET?\012…Tell me, who was\nthe guy in the\012cape who used\ndragon POKéMON?\012My POKéMON were no\nmatch at all.\012I don't care that\nI lost. I can beat\012him by getting\nstronger POKéMON.\012It's what he said\nthat bothers me…\012He told me that\nI don't love and\012trust my POKéMON\nenough.\012I'm furious that I\nlost to a bleeding\011heart like him.\012…Humph! I don't\nhave the time for\011the likes of you!",
  ["1b:6400"] = "What? Who are you?\nThis is the office\012of our leader,\nGIOVANNI.\012Since disbanding\nTEAM ROCKET three\012years ago, he has\nbeen in training.\012But we're certain\nhe will be back\012some day to assume\ncommand again.\012That's why we're\nstanding guard.\012I won't let any-\none disturb this\011place!",
  ["1b:6511"] = "I… I couldn't do a\nthing…\012GIOVANNI, please\nforgive me…",
  ["1b:6548"] = "No, I can't let\nthis affect me.\012I have to inform\nthe others…",
  ["1b:6585"] = "MURKROW: The\npassword is…\012HAIL GIOVANNI.",
  ["1b:65af"] = "Do I know the\npassword?\012Maybe.\012But no weakling's\ngoing to get it!",
  ["1b:65f1"] = "All right. Stop.\nI'll tell you.",
  ["1b:6611"] = "The password to\nthe boss's room is\012SLOWPOKETAIL.\012But it's useless\nunless you have\011two passwords.",
  ["1b:6671"] = "Hyuck-hyuck-hyuck!\012You're challenging\nme to a battle?\012Hah! You're nuts,\nbut you have guts!\012I like that!\012If you can beat\nme, I'll tell you\012a password to the\nboss's room!",
  ["1b:6717"] = "Hyuck-hyuck-hyuck!\nYou're good!",
  ["1b:6737"] = "Hyuck-hyuck-hyuck!\012The password to\nthe boss's room…\012Uh…, I think it is\nRATICATE TAIL.",
  ["1b:678d"] = "I used to work for\nSILPH, but now I\012run research for\nTEAM ROCKET.\012A meddlesome child\nlike you needs to\011be punished.",
  ["1b:6802"] = "A mere tactical\nerror cost me…",
  ["1b:6822"] = "A radio signal\nthat drives POKé-\011MON mad…\012My experiment is a\ncomplete success.\012My promotion is\nassured. This loss\012means absolutely\nnothing.",
  ["1b:68ac"] = "I don't care that\nPOKéMON are hurt\011by our experiment.",
  ["1b:68df"] = "Thinking is my\nstrong suit, not\011battling.",
  ["1b:690a"] = "If we turn up the\npower of our radio\012signal for broad-\ncast nationwide…\012The very thought\nexcites me!",
  ["1b:6970"] = "The door's closed…\012It needs two\npasswords to open.",
  ["1b:69a3"] = "The door's closed…\012{PLAYER} entered\nthe two passwords.\012The door opened!",
  ["1b:6f5c"] = "Oh, man… My boss\nis going to be\011steaming…\012The FARFETCH'D\nthat CUTS trees\012for charcoal took\noff on me.\012I can't go looking\nfor it here in the\011ILEX FOREST.\012It's too big, dark\nand scary for me…",
  ["1b:7019"] = "Wow! Thanks a\nwhole bunch!\012My boss's POKéMON\nwon't obey me be-\011cause I don't have\011a BADGE.",
  ["1b:706f"] = "It's the missing\nPOKéMON!",
  ["1b:7086"] = "FARFETCH'D: Kwaa!",
  ["1b:7099"] = "Ah! My FARFETCH'D!\012You found it for\nus, kid?\012Without it, we\nwouldn't be able\012to CUT trees for\ncharcoal.\012Thanks, kid!\012Now, how can I\nthank you…\012I know! Here, take\nthis.",
  ["1b:7141"] = "That's the CUT HM.\nTeach that to a\012POKéMON to clear\nsmall trees.\012Of course, you\nhave to have the\012GYM BADGE from\nAZALEA to use it.",
  ["1b:71c0"] = "Do you want to\napprentice as a\012charcoal maker\nwith me?\012You'll be first-\nrate in ten years!",
  ["1b:721b"] = "What am I doing?\012I'm shaking trees\nusing HEADBUTT.\012It's fun. Here,\nyou try it too!",
  ["1b:726d"] = "Rattle trees with\nHEADBUTT. Some-\011times, sleeping\011POKéMON fall out.",
  ["1b:72af"] = "Did something\nhappen to the\011forest's guardian?",
  ["1b:72de"] = "ILEX FOREST is\nso overgrown with\012trees that you\ncan't see the sky.\012Please watch out\nfor items that may\011have been dropped.",
  ["1b:7358"] = "ILEX FOREST\nSHRINE…\012It's in honor of\nthe forest's\011protector…",
  ["1b:7394"] = "ILEX FOREST\nSHRINE…\012It's in honor of\nthe forest's\011protector…\012Oh? What is this?\012It's a hole.\nIt looks like the\012GS BALL would fit\ninside it.\012Want to put the GS\nBALL here?",
  ["1b:743b"] = "{PLAYER} put in the\nGS BALL.",
  ["1b:7452"] = "Whew, wasn't that\nsomething!\012{PLAYER}, that was\nfantastic. Thanks!\012The legends about\nthat SHRINE were\011real after all.\012I feel inspired by\nwhat I just saw.\012It motivates me to\nmake better BALLS!\012I'm going!",
  ["1b:7515"] = "Don't sneak up on\nme like that!\012You frightened a\nPOKéMON away!",
  ["1b:7551"] = "I hadn't seen that\nPOKéMON before…",
  ["1b:7571"] = "A POKéMON I've\nnever seen before\012fell out of the\ntree when I used\011HEADBUTT.\012I ought to use\nHEADBUTT in other\011places too.",
  ["1c:4157"] = "This lake is full\nof GYARADOS but\011nothing else…\012So the MAGIKARP\nare being forced\011to evolve…",
  ["1c:41b4"] = "Did you come here\nbecause of the\011rumors?\012You're {PLAYER}?\nI'm LANCE, a\011trainer like you.\012I heard some ru-\nmors, so I came to\011investigate…\012I saw the way you\nbattled earlier,\011{PLAYER}.\012I can tell that\nyou're a trainer\012with considerable\nskill.\012If you don't mind,\ncould you help me\011investigate?",
  ["1c:42c6"] = "LANCE: Excellent!\012It seems that the\nLAKE's MAGIKARP\012are being forced\nto evolve.\012A mysterious radio\nbroadcast coming\012from MAHOGANY is\nthe cause.\012I'll be waiting\nfor you, {PLAYER}.",
  ["1c:4371"] = "Oh… Well, if you\nchange your mind,\011please help me.",
  ["1c:43a5"] = "LANCE: Hm? Are you\ngoing to help me?",
  ["1c:43cb"] = "GYARADOS: Gyashaa!",
  ["1c:43df"] = "{PLAYER} obtained a\nRED SCALE.",
  ["1c:43f8"] = "The GYARADOS are\nangry!\012It's a bad omen!",
  ["1c:4421"] = "Hahah! The MAGI-\nKARP are biting!",
  ["1c:4444"] = "I heard this lake\nwas made by ram-\011paging GYARADOS.\012I wonder if there\nis any connection\012to their mass out-\nbreak now?",
  ["1c:44bb"] = "Did my eyes de-\nceive me? I saw a\012red GYARADOS in\nthe LAKE…\012But I thought\nGYARADOS were\011usually blue?",
  ["1c:4522"] = "Let me battle with\nthe POKéMON I just\011caught!",
  ["1c:454e"] = "I might be an ex-\npert angler, but\012I stink as a POKé-\nMON trainer…",
  ["1c:458f"] = "I won't lose as an\nangler! I catch\011POKéMON all day.",
  ["1c:45c0"] = "No matter what I\ndo, all I catch\012are the same POKé-\nMON…",
  ["1c:45f7"] = "My line's all\ntangled up…",
  ["1c:4611"] = "Why can't I catch\nany good POKéMON?",
  ["1c:4632"] = "If a trainer spots\nanother trainer,\012he has to make a\nchallenge.\012That is our\ndestiny.",
  ["1c:4688"] = "Whew…\nGood battle.",
  ["1c:469c"] = "POKéMON and their\ntrainer become\012powerful through\nconstant battling.",
  ["1c:46df"] = "What happened to\nthe red GYARADOS?\012It's gone?\012Oh, darn. I came\nhere for nothing?\012I know--let's\nbattle!",
  ["1c:4745"] = "Good going!",
  ["1c:4752"] = "Come to think of\nit, I've seen a\011pink BUTTERFREE.",
  ["1c:4784"] = "WESLEY: Well, how\ndo you do?\012Seeing as how it's\nWednesday today,\012I'm WESLEY of\nWednesday.",
  ["1c:47dd"] = "Pleased to meet\nyou. Please take a\011souvenir.",
  ["1c:480b"] = "WESLEY: BLACKBELT\nbeefs up the power\011of fighting moves.",
  ["1c:4844"] = "WESLEY: Since you\nfound me, you must\012have met my broth-\ners and sisters.\012Or did you just\nget lucky?",
  ["1c:48a9"] = "WESLEY: Today's\nnot Wednesday.\011That's too bad.",
  ["1c:48d7"] = "LAKE OF RAGE,\nalso known as\011GYARADOS LAKE.",
  ["1c:4903"] = "FISHING GURU'S\nHOUSE",
  ["1c:49ef"] = "Hello! Welcome to\nCELADON DEPT.\011STORE!\012The directory is\non the wall.",
  ["1c:4a35"] = "This DEPT.STORE is\npart of the same\012chain as the one\nin GOLDENROD CITY.\012They were both\nrenovated at the\011same time.",
  ["1c:4aa9"] = "This is my first\ntime here.\012It's so big…\012I'm afraid I'll\nget lost.",
  ["1c:4aea"] = "1F: SERVICE\n    COUNTER\0122F: TRAINER'S\n    MARKET\0123F: TM SHOP\0124F: WISEMAN GIFTS\0125F: DRUG STORE\0126F: ROOFTOP\n    SQUARE",
  ["1c:4bc9"] = "I just recently\nbecame a trainer.\012My son encouraged\nme to do it.\012I'm impressed by\nthe selection of\011convenient items.",
  ["1c:4c3e"] = "My dad's having a\nhard time learning\012the names of items\nand how they are\012supposed to be\nused…",
  ["1c:4c9c"] = "Top Grade Items\nfor Trainers!\0122F: TRAINER'S\n    MARKET",
  ["1c:4d53"] = "I can't decide\nwhich POKéMON I\012should use this TM\non…",
  ["1c:4d86"] = "Uh-oh! I traded my\nPOKéMON without\012removing the UP-\nGRADE from it.",
  ["1c:4dc7"] = "Yeah! I'm finally\ngetting a PORYGON!\012I'm no good at the\nslots, so I could\012never get enough\ncoins…\012…Huh?\012The traded PORYGON\nturned into a dif-\011ferent POKéMON!",
  ["1c:4e61"] = "The TM SHOP sells\nsome rare moves.",
  ["1c:4e85"] = "3F: TM SHOP\012Make Your POKéMON\nStronger!",
  ["1c:4f21"] = "I'm here to buy\nSURF MAIL to send\011to my girlfriend.",
  ["1c:4f55"] = "This is the only\nplace where you\012can buy LOVELY\nMAIL.",
  ["1c:4f8c"] = "Express Yourself\nWith Gifts!\0124F: WISEMAN GIFTS",
  ["1c:5023"] = "I want to buy some\nitems that raise\012POKéMON stats, but\nI don't have\011enough money…",
  ["1c:5072"] = "I want PP UP, so I\ncan raise the PP\012of moves. But you\ncan't buy it…",
  ["1c:50b6"] = "Using items on\nthem makes POKé-\011MON happy.\012They hate certain\nitems, though…",
  ["1c:5100"] = "5F: DRUG STORE",
  ["1c:5250"] = "A vending machine!\nHere's the menu.",
  ["1c:5274"] = "Clang!\012{STRBUF}\npopped out.",
  ["1c:528e"] = "Oops, not enough\nmoney…",
  ["1c:52a7"] = "There's no more\nroom for stuff…",
  ["1c:52c7"] = "A vending machine\nwith a prize rou-\011lette…\012You never see\nthose anymore.",
  ["1c:5310"] = "Aww! There's no\ngames here!\012I wanted to play…",
  ["1c:533e"] = "6F: ROOFTOP SQUARE\nVENDING MACHINES",
  ["1c:5416"] = "My dear POKéMON\nkeep me company,\012so I don't ever\nfeel lonely.\012MEOWTH even brings\nmoney home.",
  ["1c:5470"] = "MEOWTH: Meow!",
  ["1c:547f"] = "CLEFAIRY: Clef\ncleff!",
  ["1c:5496"] = "NIDORAN: Kya\nkyaoo!",
  ["1c:54ab"] = "CELADON MANSION\nMANAGER'S SUITE",
  ["1c:5539"] = "{PLAYER} turned on\nthe PC.\012…\012Someone was in the\nmiddle of compos-\011ing an e-mail.\012…I hope you'll\ncome visit KANTO.\012I think you'll be\nsurprised at how\012much things have\nchanged here.\012You'll also see\nmany POKéMON that\012aren't native to\nJOHTO.\012To the PRODUCER\012…",
  ["1c:562c"] = "GAME FREAK\nMEETING ROOM",
  ["1c:56ce"] = "Is that right?\012I'm the GAME\nDESIGNER!\012Filling up your\nPOKéDEX is tough,\011but don't give up!",
  ["1c:5725"] = "Wow! Excellent!\nYou completed your\011POKéDEX!\012Congratulations!",
  ["1c:5763"] = "The GRAPHIC ARTIST\nwill print out a\011DIPLOMA for you.\012You should go show\nit off.",
  ["1c:57b4"] = "I'm the GRAPHIC\nARTIST.\012I drew you!",
  ["1c:57d8"] = "I'm the GRAPHIC\nARTIST.\012Oh, you completed\nyour POKéDEX?\012Want me to print\nout your DIPLOMA?",
  ["1c:5830"] = "Give me a shout if\nyou want your\011DIPLOMA printed.",
  ["1c:5895"] = "Who, me? I'm the\nPROGRAMMER.\012Play the slot\nmachines!",
  ["1c:58ca"] = "Aren't the TWINS\nadorable?\012JASMINE's pretty\ntoo.\012Oh, I love them!",
  ["1c:590b"] = "GAME FREAK\nDEVELOPMENT ROOM",
  ["1c:5928"] = "It's a detailed\ndrawing of a\011pretty girl.",
  ["1c:5952"] = "It's the game\nprogram. Messing\012with it could put\na bug in the game!",
  ["1c:5996"] = "It's crammed with\nreference materi-\011als. There's even\011a POKé DOLL.",
  ["1c:5a3f"] = "High places--I do\nlove them so!\012I'd say the only\nthing that loves\012heights as much as\nme is smoke!",
  ["1c:5aa1"] = "There's graffiti\non the wall…\012{PLAYER} added a\nmoustache!",
  ["1c:5b27"] = "Let me recount a\nterrifying tale…",
  ["1c:5b4a"] = "Then again, it's\nnot as scary while\012it's still light\noutside.\012Come back after\nsunset, OK?",
  ["1c:5ba3"] = "Once upon a time,\nthere was a little\012boy who was given\na new BICYCLE…\012He wanted to try\nit right away…\012He was having so\nmuch fun that he\012didn't notice the\nsun had set…\012While riding home\nin the pitch-black\012night, the bike\nsuddenly slowed!\012The pedals became\nheavy!\012When he stopped\npedaling, the bike\012began slipping\nbackwards!\012It was as if the\nbike were cursed\012and trying to drag\nhim into oblivion!\012…\012…\012SHRIEEEEK!\012The boy had been\nriding uphill on\011CYCLING ROAD!\012…\nBa-dum ba-dum!\012For listening so\npatiently, you may\011take this--TM03!",
  ["1c:5db3"] = "TM03 is CURSE.\012It's a terrifying\nmove that slowly\012whittles down the\nvictim's HP.",
  ["1c:5e70"] = "ERIKA is a master\nof grass POKéMON.\012She'll make you\npay if you don't\011watch yourself.",
  ["1c:5ec1"] = "TEAM ROCKET's\nhideout is in the\012basement of the\nGAME CORNER.\012Oh, wait. That was\nthree years ago.",
  ["1c:5f22"] = "EUSINE: Hi!\012I'm back visiting\nmy hometown.\012It's been quite a\nwhile.",
  ["1c:5f65"] = "{PLAYER}, have you\nheard?\012There have been\nfresh rumors of a\012rainbow-colored\nPOKéMON appearing\011at TIN TOWER.\012I've just had my\nparty healed, so\012now I'm headed to\nECRUTEAK.\012I'll be seeing\nyou, {PLAYER}!",
  ["1c:601a"] = "Oh, by the way,\n{PLAYER}.\012Have you caught\nthe legendary\012POKéMON RAIKOU and\nENTEI?\012………………\012Okay…\012If you catch even\none, I hope that\011you'll inform me.\012I'm counting on\nyou, {PLAYER}!",
  ["1c:61d0"] = "Welcome!\012You may exchange\nyour coins for\012fabulous prizes\nnext door.",
  ["1c:6215"] = "The slot machines\nare all state of\011the art.",
  ["1c:6242"] = "It's this machine\nI want.\012It cleaned me out\nyesterday, so it\012should pay out\ntoday.",
  ["1c:6295"] = "I think this slot\nmachine will pay\011out…\012The odds vary\namong machines.",
  ["1c:62dc"] = "Gahahaha!\012The coins just\nkeep popping out!\012Hm? What, kid? You\nwant to play?\012I'll share my luck\nwith you!",
  ["1c:6345"] = "Gahahaha!\012It makes me feel\ngood to do nice\012things for other\npeople!",
  ["1c:638a"] = "Hey, you don't\nhave a COIN CASE.\012How am I supposed\nto give you any\011coins, kid?",
  ["1c:63d9"] = "Hey, your COIN\nCASE is full, kid.\012You must be riding\na winning streak\011too.",
  ["1c:6425"] = "Hey! CHAMP in\nmaking!\012Are you playing\nthe slots too?\012I'm trying to get\nenough coins for a\011prize POKéMON.\012But I don't have\nenough coins yet…",
  ["1c:64ad"] = "Hmmm… The odds are\nsurely better for\012PIKACHU's line,\nbut… What to do?",
  ["1c:64f3"] = "Hey!\012Underneath this\nposter…\012There's nothing!",
  ["1c:6521"] = "Hey!\012Underneath this\nposter…\012There's nothing!",
  ["1c:654f"] = "There's a lighter\nhere.",
  ["1c:6567"] = "A can of soda…\012Someone must be\ncoming back…\012Huh? It's empty!",
  ["1c:68b8"] = "I wanted PORYGON,\nbut I was short by\011100 coins…",
  ["1c:68e9"] = "Whew…\012I've got to stay\ncalm and cool…\012I can't lose my\ncool, or I'll lose\011all my money…",
  ["1c:693e"] = "Welcome!\012We exchange your\ncoins for fabulous\011prizes!",
  ["1c:6974"] = "Which prize would\nyou like?",
  ["1c:6991"] = "OK, so you wanted\na {STRBUF}?",
  ["1c:69ad"] = "Here you go!",
  ["1c:69bb"] = "You don't have\nenough coins.",
  ["1c:69d8"] = "You have no room\nfor it.",
  ["1c:69f2"] = "Oh. Please come\nback with coins!",
  ["1c:6a14"] = "Oh? You don't have\na COIN CASE.",
  ["1c:6b28"] = "ERIKA: Hello…\nLovely weather,\012isn't it?\nIt's so pleasant…\012…I'm afraid I may\ndoze off…\012My name is ERIKA.\nI am the LEADER of\011CELADON GYM.\012…Oh? All the way\nfrom JOHTO, you\011say? How nice…\012Oh. I'm sorry, I\ndidn't realize\012that you wished to\nchallenge me.\012Very well, but I\nshall not lose.",
  ["1c:6c3e"] = "ERIKA: Oh!\nI concede defeat…\012You are remarkably\nstrong…\012I shall give you\nRAINBOWBADGE…",
  ["1c:6c96"] = "{PLAYER} received\nRAINBOWBADGE.",
  ["1c:6cb0"] = "ERIKA: That was a\ndelightful match.\012I felt inspired.\nPlease, I wish you\011to have this TM.\012It is GIGA DRAIN.\012It is a wonderful\nmove that drains\012half the damage it\ninflicts to heal\011your POKéMON.\012Please use it if\nit pleases you…",
  ["1c:6d8f"] = "ERIKA: Losing\nleaves a bitter\011aftertaste…\012But knowing that\nthere are strong\012trainers spurs me\nto do better…",
  ["1c:6dfc"] = "Do you think a\ngirls-only GYM\011is rare?",
  ["1c:6e24"] = "Oh, bleah!",
  ["1c:6e30"] = "I just got care-\nless, that's all!",
  ["1c:6e53"] = "Oh, a battle?\nThat's kind of\011scary, but OK!",
  ["1c:6e7f"] = "Oh, that's it?",
  ["1c:6e8e"] = "Oh, look at all\nyour BADGES. No\012wonder I couldn't\nwin!",
  ["1c:6ec5"] = "Were you looking\nat these flowers\011or at me?",
  ["1c:6ef2"] = "How annoying!",
  ["1c:6f01"] = "How do I go about\nbecoming ladylike\011like ERIKA?",
  ["1c:6f32"] = "We'll show you\nPOKéMON moves that\011ERIKA taught us!",
  ["1c:6f62"] = "Oh… We lost…",
  ["1c:6f70"] = "ERIKA will get you\nback for us!",
  ["1c:6f91"] = "We're going to\nprotect ERIKA!",
  ["1c:6faf"] = "We couldn't win…",
  ["1c:6fc0"] = "ERIKA is much,\nmuch stronger!",
  ["1c:70de"] = "Hi!\012We're holding an\neatathon contest.\012We can't serve you\nright now. Sorry.",
  ["1c:7129"] = "…Snarfle, chew…",
  ["1c:713a"] = "Don't talk to me!\012You'll break my\nconcentration!",
  ["1c:716a"] = "…Gulp… Chew…",
  ["1c:7178"] = "I take quantity\nover quality!\012I'm happy when I'm\nfull!",
  ["1c:71ae"] = "Munch, munch…",
  ["1c:71bd"] = "The food is good\nhere, but GOLDEN-\011ROD has the best\011food anywhere.",
  ["1c:7201"] = "Crunch… Crunch…",
  ["1c:7212"] = "Nobody here will\ngive you a COIN\012CASE. You should\nlook in JOHTO.",
  ["1c:7254"] = "Crunch… Crunch…\012I can keep eating!",
  ["1c:7278"] = "More, CHEF!",
  ["1c:7285"] = "Eatathon Contest!\nNo time limit!\012A battle without\nend! The biggest\012muncher gets it\nall for free!",
  ["1c:72e7"] = "{PLAYER} found\n{STRBUF}!",
  ["1c:72f7"] = "But {PLAYER} can't\nhold another item…",
  ["1c:7379"] = "If you cruise down\nCYCLING ROAD, you\012will end up in\nFUCHSIA CITY.",
  ["1c:7408"] = "CYCLING ROAD\nstarts here.\012It's all downhill,\nso it's totally\011exhilarating.\012It's a great sort\nof feeling that\012you can't get from\na ship or train.",
  ["1c:7496"] = "Hey! Whoa! Stop!\012You can't go out\non the CYCLING\012ROAD without a\nBICYCLE.",
  ["1c:752c"] = "Did you hear about\nthe accident at\011the POWER PLANT?\012It's located in\nthe East, close to\011LAVENDER TOWN.",
  ["1c:7592"] = "I take my GUARD\njob seriously.\012Hey! You have a\nPOKéDEX.\012OK. You can go\nthrough.",
  ["1c:762c"] = "CYCLING ROAD\nUphill Starts Here",
  ["1c:764d"] = "Hang on! Don't you\nhave a BICYCLE?\012The CYCLING ROAD\nis beyond here.\012You have to have a\nBICYCLE to go on.",
  ["1d:4008"] = "A bunch of DIGLETT\npopped out of the\012ground! That was\nshocking.",
  ["1d:4105"] = "…… …… ……\012It's been a while,\n{PLAYER}.\012…Since I lost to\nyou, I thought\012about what I was\nlacking with my\011POKéMON…\012And we came up\nwith an answer.\012{PLAYER}, now we'll\nshow you!",
  ["1d:419d"] = "…… …… ……\012I thought I raised\nmy POKéMON to be\012the best they\ncould be…\012…But it still \nwasn't enough…",
  ["1d:41fa"] = "…… …… ……\012…You won, fair\nand square.\012I admit it. But\nthis isn't the\011end.\012I'm going to be\nthe greatest POKé-\011MON trainer ever.\012Because these guys\nare behind me.\012…Listen, {PLAYER}.\012One of these days\nI'm going to prove\012how good I am by\nbeating you.",
  ["1d:42e0"] = "…… …… ……\012I've repaid my\ndebt to you.\012With my POKéMON,\nI'm going to beat\012the CHAMPION and\nbecome the world's\011greatest trainer.",
  ["1d:455f"] = "Hold it.\012…Are you going to\ntake the POKéMON\011LEAGUE challenge?\012…Don't make me\nlaugh.\012You're so much\nweaker than I am.\012I'm not like I was\nbefore.\012I now have the\nbest and strongest\012POKéMON with me.\nI'm invincible!\012{PLAYER}!\nI challenge you!",
  ["1d:463d"] = "…I couldn't win…\012I gave it every-\nthing I had…\012What you possess,\nand what I lack…\012I'm beginning to\nunderstand what\012that dragon master\nsaid to me…",
  ["1d:46ce"] = "…I haven't given up\non becoming the\011greatest trainer…\012I'm going to find\nout why I can't\012win and become\nstronger…\012When I do, I will\nchallenge you.\012And I'll beat you\ndown with all my\011power.\012…Humph! You keep\nat it until then.",
  ["1d:47aa"] = "…Humph!\012When it comes down\nto it, nothing can\011beat power.\012I don't need any-\nthing else.",
  ["1d:4a55"] = "We're departing\nsoon. Please get\011on board.",
  ["1d:4a80"] = "Sorry. You can't\nboard now.",
  ["1d:4a9c"] = "Welcome to FAST\nSHIP S.S.AQUA.\012Will you be board-\ning today?",
  ["1d:4ada"] = "May I see your\nS.S.TICKET?",
  ["1d:4af6"] = "We hope to see you\nagain!",
  ["1d:4b11"] = "{PLAYER} flashed\nthe S.S.TICKET.\012That's it.\nThank you!",
  ["1d:4b41"] = "{PLAYER} tried to\nshow the S.S.\011TICKET…\012…But no TICKET!\012Sorry!\nYou may board only\012if you have an\nS.S.TICKET.",
  ["1d:4ba8"] = "The FAST SHIP will\nsail next Monday.",
  ["1d:4bce"] = "The FAST SHIP will\nsail next Friday.",
  ["1d:4bf4"] = "SHELLDER are easy\nto catch here.\012They're kind of\nrare elsewhere.",
  ["1d:4c35"] = "How many RODS do\nyou have?\012Different RODS\ncatch different\011POKéMON.",
  ["1d:4c76"] = "S.S.AQUA uses jets\nto skim over the\011waves!",
  ["1d:4ca2"] = "There are lots of\nPOKéMON in KANTO.\012I wish I could go…",
  ["1d:4cd7"] = "We don't want you\nto fall into the\012sea, so you're not\nallowed in.",
  ["1d:4f06"] = "We're departing\nsoon. Please get\011on board.",
  ["1d:4f31"] = "Sorry. You can't\nboard now.",
  ["1d:4f4d"] = "Welcome to FAST\nSHIP S.S.AQUA.\012Will you be board-\ning today?",
  ["1d:4f8b"] = "May I see your\nS.S.TICKET?",
  ["1d:4fa7"] = "We hope to see you\nagain!",
  ["1d:4fc2"] = "{PLAYER} flashed\nthe S.S.TICKET.\012That's it.\nThank you!",
  ["1d:4ff2"] = "{PLAYER} tried to\nshow the S.S.\011TICKET…\012…But no TICKET!\012Sorry!\nYou may board only\012if you have an\nS.S.TICKET.",
  ["1d:5059"] = "The FAST SHIP will\nsail on Wednesday.",
  ["1d:5080"] = "The FAST SHIP will\nsail next Sunday.",
  ["1d:50a6"] = "You came from\nJOHTO?\012I hear many rare\nPOKéMON live over\011there.",
  ["1d:523b"] = "FAST SHIP S.S.AQUA\nis en route to\011VERMILION CITY.\012We will make an\nannouncement when\011we arrive.",
  ["1d:529b"] = "FAST SHIP S.S.AQUA\nis en route to\011OLIVINE CITY.\012We will make an\nannouncement when\011we arrive.",
  ["1d:52f9"] = "Here's your cabin.\012If your POKéMON\nare hurt, take a\011nap in the bed.\012That will heal\nthem.",
  ["1d:534f"] = "Here's your cabin.\012You can heal your\nPOKéMON by taking\011a nap in the bed.\012The ship will\narrive while\011you're sleeping.",
  ["1d:53c0"] = "The passengers are\nall trainers.\012They're all itch-\ning to battle in\011their cabins.",
  ["1d:5412"] = "Whoa! Excuse me.\nI was in a hurry!\012My granddaughter\nis missing!\012She's just a wee\ngirl. If you see\012her, please let me\nknow!",
  ["1d:548d"] = "FAST SHIP S.S.AQUA\nhas arrived in\011OLIVINE CITY.",
  ["1d:54be"] = "FAST SHIP S.S.AQUA\nhas arrived in\011VERMILION CITY.",
  ["1d:5643"] = "I'm going to KANTO\nto test my skills.",
  ["1d:5669"] = "I wanted to win!",
  ["1d:567b"] = "Trainers from\nJOHTO can battle\012with KANTO GYM\nLEADERS.",
  ["1d:56b3"] = "I'm training to\nbecome the CHAMP!",
  ["1d:56d5"] = "What's so differ-\nent between us?",
  ["1d:56f7"] = "I'm going to beat\nyou someday!",
  ["1d:5716"] = "Do you know LILY?\nShe's a hot DJ in\011KANTO.",
  ["1d:5741"] = "Gyaaaah!",
  ["1d:574b"] = "LILY's nice, but\nMARY's the best!\012I want to check\nout JOHTO's radio\011programs!",
  ["1d:5797"] = "Are you alone?\nThen let's battle!",
  ["1d:57b9"] = "That's too much to\nhandle!",
  ["1d:57d4"] = "I wonder if there\nare any mountains\012worth climbing in\nKANTO?",
  ["1d:5812"] = "Yeah, I'm a sail-\nor, all right.\012I wasn't goofing\noff!\012This cabin was\nvacant, so I just\011took a quick nap!\012Ah, forget it!\nLet's battle!",
  ["1d:5897"] = "Sorry! It's all my\nfault!",
  ["1d:58b1"] = "Being a sailor, I\nhave to do phys-\011ical labor. It's\011exhausting!",
  ["1d:58f1"] = "Oh, no. I've lost\nsomething that's\011very important.",
  ["1d:5923"] = "I… I can't find\nit…",
  ["1d:5937"] = "I give up.\nYou don't have to\012look. Just forget\nabout it!",
  ["1d:5970"] = "Yeehaw!\nLucky!",
  ["1d:5980"] = "How unlucky!\nI lost!",
  ["1d:5996"] = "I found a pretty\ncoin here.\012Someone must have\nlost it…",
  ["1d:5b04"] = "I'm going to KANTO\nto put on fire-\011breathing shows!",
  ["1d:5b38"] = "Fizzle… The\nflame's tiny…",
  ["1d:5b52"] = "I guess fire is\nweak on the sea.\012It doesn't matter?\nReally?",
  ["1d:5b8e"] = "I'm visiting my\ngrandma to catch\011me some bugs!",
  ["1d:5bbd"] = "Ooh, wow.\nYou're tough!",
  ["1d:5bd5"] = "You can find lots\nof POKéMON in the\011trees of JOHTO!",
  ["1d:5c07"] = "I'm trying to\nforget my woes.\011Let's battle!",
  ["1d:5c32"] = "My heart weeps…",
  ["1d:5c43"] = "A voyage is best\nfor getting over\011a broken heart.\012But a FAST SHIP\ntrip is too short\011for grieving.",
  ["1d:5ca6"] = "I'm going to audi-\ntion my songs at\012GOLDENROD's RADIO\nSTATION.",
  ["1d:5ce4"] = "Yowza!\nTotal distortion!",
  ["1d:5cfe"] = "I was going to\nmake my debut at\011the BATTLE TOWER…\012I should go back\nto VERMILION and\011redo my training…",
  ["1d:5d65"] = "Speaking of the\nRADIO STATION,\012what's this week's\nlucky number?",
  ["1d:5da4"] = "A comfy bed!\nTime to sleep…",
  ["1d:5dc1"] = "Ah, refreshed and\nrestored!",
  ["1d:5dde"] = "FAST SHIP S.S.AQUA\nhas arrived in\011OLIVINE CITY.",
  ["1d:5e0f"] = "FAST SHIP S.S.AQUA\nhas arrived in\011VERMILION CITY.",
  ["1d:6012"] = "Whew! Thanks for\ncoming along.\012Keeping that lit-\ntle girl amused\011was exhausting.",
  ["1d:6064"] = "How do you like\nS.S.AQUA's ride?\012She practically\nskates across the\011waves.",
  ["1d:60ae"] = "Oh, hello…\012I still can't find\nmy granddaughter.\012If she's on the\nship, that's OK.\012She's an energetic\nchild, so she may\012be bugging some-\none. I'm worried…",
  ["1d:6143"] = "{PLAYER}, was it?\nI heard you enter-\011tained my grand-\011daughter.\012I want to thank\nyou for that.",
  ["1d:619b"] = "I know! I'd like\nyou to have this!",
  ["1d:61be"] = "We're traveling\naround the world.",
  ["1d:61e0"] = "CAPTAIN, play with\nme, please?\012I'm bored! I want\nto play more!",
  ["1d:621f"] = "Hi! Will you play\nwith me?\012…Oh!\012Grandpa's worried\nabout me?\012I have to go!\012I have to go find\nGrandpa!",
  ["1d:6284"] = "Grandpa, here I\nam! I was playing\012with the CAPTAIN\nand this guy!",
  ["1d:62c6"] = "Grandpa, here I\nam! I was playing\012with the CAPTAIN\nand this big girl!",
  ["1d:630d"] = "I had lots of fun\nplaying!",
  ["1d:6329"] = "Hey, kid! Want to\nbattle with me?",
  ["1d:634c"] = "You're strong!",
  ["1d:635b"] = "You're traveling\nall alone?\012Isn't your mom\nworried?",
  ["1d:638e"] = "You think I'm a\nbaby?\011That's not fair!",
  ["1d:63b4"] = "Oh! We lost!",
  ["1d:63c2"] = "Baby is a rude\nname to call us\011girls!",
  ["1d:63e9"] = "I'm not a baby!\012That's not nice to\nsay to a lady!",
  ["1d:641a"] = "Oh! We lost!",
  ["1d:6428"] = "Sometimes, kids\nare smarter than\011grown-ups!",
  ["1d:6455"] = "Ssh! My brain is\npicking up radio\011signals!",
  ["1d:6481"] = "…I hear some-\nthing!",
  ["1d:6497"] = "I get it. You can\nhear JOHTO's radio\011on the FAST SHIP.",
  ["1d:64ce"] = "What do you think?\nMy POKéMON are\011beautiful, yes?",
  ["1d:64fe"] = "Oh, no! My beauti-\nful POKéMON!",
  ["1d:651c"] = "I must go to the\nPOKéMON SALON and\011fix them up nice!",
  ["1d:654f"] = "I'm going to shop\nat the DEPT.STORE\011and then…",
  ["1d:657d"] = "What was I going\nto do?",
  ["1d:6596"] = "Oh, yes! I have to\nget my POKéMON out\011of DAY-CARE!",
  ["1d:65c7"] = "What kinds of POKé\nBALLS do you have\011with you?",
  ["1d:65f4"] = "Wait! Stop! Don't!\nPlease!",
  ["1d:660f"] = "You should use the\nright BALLS to fit\011the situation.",
  ["1d:6645"] = "FAST SHIP S.S.AQUA\nhas arrived in\011VERMILION CITY.",
  ["1d:687b"] = "Hey, kid. Could I\nget you to look\011for my buddy?\012He's goofing off\nsomewhere, that\011lazy bum!\012I want to go find\nhim, but I'm on\011duty right now.",
  ["1d:6907"] = "Oh, gee…\012The CAPTAIN will\nbe furious…",
  ["1d:692e"] = "Thanks, kid!\nI chewed him out\012good so he'll quit\nslacking off!",
  ["1d:696d"] = "A little girl?\012I may have seen\nher go by here.",
  ["1d:699d"] = "The dining room is\nup ahead.\012The stairs at the\nend lead to the\011CAPTAIN's cabin.",
  ["1d:69ed"] = "Nothing beats a\nbattle when I'm\011on my break.",
  ["1d:6a1a"] = "Win or lose, my\nbreak's over!",
  ["1d:6a38"] = "I guess I can't\nwin if I don't get\011serious.",
  ["1d:6a63"] = "I'm so bored.\nWant to battle?",
  ["1d:6a81"] = "Yow! You're too\nstrong!",
  ["1d:6a99"] = "SAFFRON, CELADON…\nI hear there are\012many big cities\nin KANTO.",
  ["1d:6ad7"] = "Urrf…\nI'm seasick!",
  ["1d:6aea"] = "I can't move any-\nmore…",
  ["1d:6b02"] = "No more ships for\nme. Next time,\012I'm taking the\nMAGNET TRAIN.",
  ["1d:6b40"] = "This is where we\nsailors work!",
  ["1d:6b60"] = "I lost on my home\nfield…",
  ["1d:6b7a"] = "We get different\npassengers from\012VERMILION CITY to\nOLIVINE CITY.",
  ["1d:6bbc"] = "Even though we're\nout on the sea, I\011can't fish!\012This is boring!\nLet's battle!",
  ["1d:6c08"] = "I… I'm not bored\nanymore…",
  ["1d:6c22"] = "I plan to fish off\nVERMILION's pier.",
  ["1d:6c47"] = "I'm building up my\nlegs by bracing\012against the ship's\nrocking!",
  ["1d:6c85"] = "Rocked and rolled\nover!",
  ["1d:6c9e"] = "I couldn't find\nthe KARATE KING in\011JOHTO.\012He's supposed to\nbe training in a\011cave somewhere.",
  ["1d:6cf9"] = "I'm a sailor man!\012But I'm training\nPOKéMON, so I can\011become the CHAMP!",
  ["1d:6d3c"] = "My lack of train-\ning is obvious…",
  ["1d:6d5f"] = "Eight BADGES!\nThey must prove\012that you've beaten\nGYM LEADERS.\012No wonder you're\nso good!",
  ["1d:6db6"] = "Don't lay a finger\non my students!",
  ["1d:6dd9"] = "Aaack!",
  ["1d:6de1"] = "We're on a field\ntrip to the RUINS\011outside VIOLET.",
  ["1d:6e14"] = "Do you know the\nRUINS OF ALPH?",
  ["1d:6e34"] = "Yaargh!",
  ["1d:6e3d"] = "Radios pick up\nstrange signals\011inside the RUINS.",
  ["1d:6e6f"] = "There are some odd\nstone panels in\011the RUINS OF ALPH.",
  ["1d:6ea6"] = "I was done in!",
  ["1d:6eb6"] = "I read that there\nare four of those\011stone panels.",
  ["1d:6faf"] = "FAST SHIP S.S.AQUA\nsails to KANTO on\012Mondays and Fri-\ndays.",
  ["1d:701d"] = "The FAST SHIP\nsails on Wednes-\011days and Sundays\011every week.",
  ["1d:713b"] = "MT.MOON SQUARE\nDON'T LITTER",
  ["1d:71b3"] = "When the sun goes\ndown, CLEFAIRY\011come out to play.",
  ["1d:7260"] = "Shaoooh!",
  ["1e:433d"] = "This is where I do\nmy training!",
  ["1e:435e"] = "Beaten by a\npassing stranger!",
  ["1e:43d8"] = "I'm going to train\neven harder.\012After all, I'm\ntrying to become\011a GYM LEADER.",
  ["1e:4425"] = "I'm the best in my\nclass at POKéMON.",
  ["1e:4447"] = "No! There are bet-\nter trainers…",
  ["1e:4469"] = "I'm trying hard so\nI can be the star\011in my class.",
  ["1e:449b"] = "I'm confident in\nmy ability to\011raise POKéMON.\012Want to see?",
  ["1e:44d3"] = "Did I screw up my\ntraining?",
  ["1e:44f0"] = "Maybe I should\ntake one to a DAY-\012CARE. Or maybe use\nsome items…",
  ["1e:4532"] = "Shopping under the\nsky!\012It feels so nice\nup on a rooftop.",
  ["1e:456d"] = "Are you a trainer?\012Let's have a\npractice battle.",
  ["1e:459e"] = "Oh, no! I just\ncan't win…",
  ["1e:45b8"] = "You're too strong\nto be a practice\011partner.",
  ["1e:45e4"] = "Who goes there?\nWhat are you up\011to?",
  ["1e:4609"] = "You're a tough\nlittle kid.",
  ["1e:4624"] = "Yep, I see nothing\nwrong today. You\012be good and stay\nout of trouble.",
  ["1e:466a"] = "I'm on patrol for\nsuspicious indi-\011viduals.",
  ["1e:4696"] = "I just got my\nPOKéMON back from\011DAY-CARE.\012Let's see how much\nstronger it got!",
  ["1e:46e1"] = "Why does it end\nthis way?",
  ["1e:46fc"] = "My POKéMON knew\nmoves I didn't\011know it had.\012That confounded me\nto no end!",
  ["1e:4743"] = "IRENE: Kyaaah!\nSomeone found us!",
  ["1e:4765"] = "IRENE: Ohhh!\nToo strong!",
  ["1e:477f"] = "IRENE: My sister\nKATE will get you\011for this!",
  ["1e:47ad"] = "IRENE: Isn't this\nbeach great?\012It's our secret\nlittle getaway!",
  ["1e:47eb"] = "JENN: You can't\nbeat IRENE and go\011unpunished!",
  ["1e:4819"] = "JENN: So sorry,\nIRENE! Sis!",
  ["1e:4836"] = "JENN: Don't get\ncocky! My sister\011KATE is tough!",
  ["1e:4866"] = "JENN: Sunlight\nmakes your body\011stronger.",
  ["1e:4890"] = "KATE: You sure\nwere mean to my\011little sisters!",
  ["1e:48c0"] = "KATE: No! I can't\nbelieve I lost.",
  ["1e:48e2"] = "KATE: You're too\nstrong. I didn't\011stand a chance.\012Here. You deserve\nthis.",
  ["1e:492b"] = "KATE: I'm sorry we\njumped you.\012We never expected\nanyone to find us\012here. You sure\nstartled us.",
  ["1e:49a8"] = "ROUTE 34\012GOLDENROD CITY -\nAZALEA TOWN\012ILEX FOREST\nSOMEWHERE BETWEEN",
  ["1e:49ed"] = "TRAINER TIPS\012BERRY trees grow\nnew BERRIES\011every day.\012Make a note of\nwhich trees bear\011which BERRIES.",
  ["1e:4a52"] = "DAY-CARE\012LET US RAISE YOUR\nPOKéMON FOR YOU!",
  ["1e:4fb6"] = "ELM: {PLAYER}!\nThere you are!\012I needed to ask\nyou a favor.\012I'm conducting new\nPOKéMON research\012right now. I was\nwondering if you\012could help me with\nit, {PLAYER}.\012You see…\012I'm writing a\npaper that I want\012to present at a\nconference.\012But there are some\nthings I don't\012quite understand\nyet.\012So!\012I'd like you to\nraise a POKéMON\012that I recently\ncaught.",
  ["1e:50fa"] = "Thanks, {PLAYER}!\012You're a great\nhelp!",
  ["1e:511a"] = "But… Please, I\nneed your help!",
  ["1e:513a"] = "When I announce my\nfindings, I'm sure\012we'll delve a bit\ndeeper into the\012many mysteries of\nPOKéMON.\012You can count on\nit!",
  ["1e:51ae"] = "Oh, hey! I got an\ne-mail!\012………………\nHm… Uh-huh…\012Okay…",
  ["1e:51df"] = "Hey, listen.\012I have an acquain-\ntance called MR.\011POKéMON.\012He keeps finding\nweird things and\012raving about his\ndiscoveries.\012Anyway, I just got\nan e-mail from him\012saying that this\ntime it's real.\012It is intriguing,\nbut we're busy\012with our POKéMON\nresearch…\012Wait!\012I know!\012{PLAYER}, can you\ngo in our place?",
  ["1e:52ff"] = "I want you to\nraise one of the\012POKéMON contained\nin these BALLS.\012You'll be that\nPOKéMON's first\011partner, {PLAYER}!\012Go on. Pick one!",
  ["1e:5375"] = "If a wild POKéMON\nappears, let your\011POKéMON battle it!",
  ["1e:53a7"] = "ELM: Wait! Where\nare you going?",
  ["1e:53c8"] = "ELM: You'll take\nCYNDAQUIL, the\011fire POKéMON?",
  ["1e:53f3"] = "ELM: Do you want\nTOTODILE, the\011water POKéMON?",
  ["1e:541f"] = "ELM: So, you like\nCHIKORITA, the\011grass POKéMON?",
  ["1e:544d"] = "ELM: Think it over\ncarefully.\012Your partner is\nimportant.",
  ["1e:5487"] = "ELM: I think\nthat's a great\011POKéMON too!",
  ["1e:54ad"] = "{PLAYER} received\n{STRBUF}!",
  ["1e:54c0"] = "MR.POKéMON lives a\nlittle bit beyond\012CHERRYGROVE, the\nnext city over.\012It's almost a\ndirect route\012there, so you\ncan't miss it.\012But just in case,\nhere's my phone\012number. Call me if\nanything comes up!",
  ["1e:5581"] = "If your POKéMON is\nhurt, you should\012heal it with this\nmachine.\012Feel free to use\nit anytime.",
  ["1e:55db"] = "{PLAYER}, I'm\ncounting on you!",
  ["1e:55f3"] = "{PLAYER} got ELM's\nphone number.",
  ["1e:560d"] = "MR.POKéMON goes\neverywhere and\011finds rarities.\012Too bad they're\njust rare and\011not very useful…",
  ["1e:5668"] = "It contains a\nPOKéMON caught by\011PROF.ELM.",
  ["1e:5690"] = "I wonder what this\ndoes?",
  ["1e:56aa"] = "Would you like to\nheal your POKéMON?",
  ["1e:56cd"] = "ELM: {PLAYER}, this\nis terrible…\012Oh, yes, what was\nMR.POKéMON's big\011discovery?",
  ["1e:5712"] = "{PLAYER} handed\nthe MYSTERY EGG to\011PROF.ELM.",
  ["1e:5739"] = "ELM: This?",
  ["1e:5745"] = "But… Is it a\nPOKéMON EGG?\012If it is, it is a\ngreat discovery!",
  ["1e:5780"] = "ELM: What?!?\012PROF.OAK gave you\na POKéDEX?\012{PLAYER}, is that\ntrue? Th-that's\011incredible!\012He is superb at\nseeing the poten-\011tial of people as\011trainers.\012Wow, {PLAYER}. You\nmay have what it\012takes to become\nthe CHAMPION.\012You seem to be\ngetting on great\011with POKéMON too.\012You should take\nthe POKéMON GYM\011challenge.\012The closest GYM\nwould be the one\011in VIOLET CITY.",
  ["1e:58cf"] = "…{PLAYER}. The\nroad to the\012championship will\nbe a long one.\012Before you leave,\nmake sure that you\011talk to your mom.",
  ["1e:593c"] = "ELM: Don't give\nup! I'll call if\012I learn anything\nabout that EGG!",
  ["1e:597d"] = "ELM: {PLAYER}?\nDidn't you meet my\011assistant?\012He should have met\nyou with the EGG\012at VIOLET CITY's\nPOKéMON CENTER.\012You must have just\nmissed him. Try to\011catch him there.",
  ["1e:5a1b"] = "ELM: Hey, has that\nEGG changed any?",
  ["1e:5a40"] = "{PLAYER}? I thought\nthe EGG hatched.\012Where is the\nPOKéMON?",
  ["1e:5a72"] = "ELM: {PLAYER}, you\nlook great!",
  ["1e:5a8b"] = "What?\nThat POKéMON!?!",
  ["1e:5a9f"] = "The EGG hatched!\nSo, POKéMON are\011born from EGGS…\012No, perhaps not\nall POKéMON are.\012Wow, there's still\na lot of research\011to be done.",
  ["1e:5b1c"] = "Thanks, {PLAYER}!\nYou're helping\012unravel POKéMON\nmysteries for us!\012I want you to have\nthis as a token of\011our appreciation.",
  ["1e:5b8d"] = "That's an\nEVERSTONE.\012Some species of\nPOKéMON evolve\012when they grow to\ncertain levels.\012A POKéMON holding\nthe EVERSTONE\011won't evolve.\012Give it to a POKé-\nMON you don't want\011to evolve.",
  ["1e:5c37"] = "ELM: {PLAYER}, I'll\ncall you if any-\011thing comes up.",
  ["1e:5c65"] = "…sigh… That\nstolen POKéMON.\012I wonder how it's\ndoing.\012They say a POKéMON\nraised by a bad\012person turns bad\nitself.",
  ["1e:5cd0"] = "ELM: Hi, {PLAYER}!\nThanks to you, my\012research is going\ngreat!\012Take this as a\ntoken of my\011appreciation.",
  ["1e:5d31"] = "The MASTER BALL is\nthe best!\012It's the ultimate\nBALL! It'll catch\012any POKéMON with-\nout fail.\012It's given only to\nrecognized POKéMON\011researchers.\012I think you can\nmake much better\012use of it than I\ncan, {PLAYER}!",
  ["1e:5df3"] = "ELM: {PLAYER}!\nThere you are!\012I called because I\nhave something for\011you.\012See? It's an\nS.S.TICKET.\012Now you can catch\nPOKéMON in KANTO.",
  ["1e:5e6f"] = "The ship departs\nfrom OLIVINE CITY.\012But you knew that\nalready, {PLAYER}.\012After all, you've\ntraveled all over\011with your POKéMON.\012Give my regards to\nPROF.OAK in KANTO!",
  ["1e:5f38"] = "{PLAYER}, I want\nyou to have this\011for your errand.",
  ["1e:5f65"] = "There are only two\nof us, so we're\011always busy.",
  ["1e:5f95"] = "There was a loud\nnoise outside…\012When we went to\nlook, someone\011stole a POKéMON.\012It's unbelievable\nthat anyone would\011do that!\012…sigh… That\nstolen POKéMON.\012I wonder how it's\ndoing.\012They say a POKéMON\nraised by a bad\012person turns bad\nitself.",
  ["1e:6078"] = "{PLAYER}!\012Use these on your\nPOKéDEX quest!",
  ["1e:609a"] = "To add to your\nPOKéDEX, you have\011to catch POKéMON.\012Throw POKé BALLS\nat wild POKéMON\011to get them.",
  ["1e:60f0"] = "I heard a POKéMON\nwas stolen here…\012I was just getting\nsome information\011from PROF.ELM.\012Apparently, it was\na young male with\011long, red hair…\012What?\012You battled a\ntrainer like that?\012Did you happen to\nget his name?",
  ["1e:61c0"] = "OK! So {RIVAL}\nwas his name.\012Thanks for helping\nmy investigation!",
  ["1e:61fd"] = "The window's open.\012A pleasant breeze\nis blowing in.",
  ["1e:6231"] = "He broke in\nthrough here!",
  ["1e:624c"] = "{PLAYER} opened a\nbook.\012Travel Tip 1:\012Press START to\nopen the MENU.",
  ["1e:628a"] = "{PLAYER} opened a\nbook.\012Travel Tip 2:\012Record your trip\nwith SAVE!",
  ["1e:62c6"] = "{PLAYER} opened a\nbook.\012Travel Tip 3:\012Open your PACK and\npress SELECT to\011move items.",
  ["1e:6315"] = "{PLAYER} opened a\nbook.\012Travel Tip 4:\012Check your POKéMON\nmoves. Press the\012A Button to switch\nmoves.",
  ["1e:6370"] = "The wrapper from\nthe snack PROF.ELM\011ate is in there…",
  ["1e:63a6"] = "OBSERVATIONS ON\nPOKéMON EVOLUTION\012…It says on the\nscreen…",
  ["1e:6604"] = "Oh, {PLAYER}…! Our\nneighbor, PROF.\012ELM, was looking\nfor you.\012He said he wanted\nyou to do some-\011thing for him.\012Oh! I almost for-\ngot! Your POKéMON\012GEAR is back from\nthe repair shop.\012Here you go!",
  ["1e:66bd"] = "POKéMON GEAR, or\njust POKéGEAR.\012It's essential if\nyou want to be a\011good trainer.\012Oh, the day of the\nweek isn't set.\012You mustn't forget\nthat!",
  ["1e:6742"] = "Is it Daylight\nSaving Time now?",
  ["1e:6763"] = "Come home to\nadjust your clock\012for Daylight\nSaving Time.\012By the way, do you\nknow how to use\011the PHONE?",
  ["1e:67cb"] = "Don't you just\nturn the POKéGEAR\012on and select the\nPHONE icon?",
  ["1e:6807"] = "I'll read the\ninstructions.\012Turn the POKéGEAR\non and select the\011PHONE icon.",
  ["1e:6850"] = "Phone numbers are\nstored in memory.\012Just choose a name\nyou want to call.\012Gee, isn't that\nconvenient?",
  ["1e:68b5"] = "PROF.ELM is wait-\ning for you.\012Hurry up, baby!",
  ["1e:68e5"] = "So, what was PROF.\nELM's errand?\012…\012That does sound\nchallenging.\012But, you should be\nproud that people\011rely on you.",
  ["1e:6957"] = "{PLAYER}, do it!\012I'm behind you all\nthe way!",
  ["1e:697d"] = "Good morning,\n{PLAYER}!\012I'm visiting!",
  ["1e:699c"] = "Hello, {PLAYER}!\nI'm visiting!",
  ["1e:69b4"] = "Good evening,\n{PLAYER}!\012I'm visiting!",
  ["1e:69d3"] = "{PLAYER}, have you\nheard?\012My daughter is\nadamant about\012becoming PROF.\nELM's assistant.\012She really loves\nPOKéMON!",
  ["1e:6a3a"] = "Mom's specialty!\012CINNABAR VOLCANO\nBURGER!",
  ["1e:6a64"] = "The sink is spot-\nless. Mom likes it\011clean.",
  ["1e:6a91"] = "Let's see what's\nin the fridge…\012FRESH WATER and\ntasty LEMONADE!",
  ["1e:6ad0"] = "There's a movie on\nTV: Stars dot the\012sky as two boys\nride on a train…\012I'd better get\nrolling too!",
  ["1e:6c24"] = "PROF.OAK'S POKéMON\nTALK! Please tune\011in next time!",
  ["1e:6c55"] = "POKéMON CHANNEL!",
  ["1e:6c64"] = "This is DJ MARY,\nyour co-host!",
  ["1e:6c84"] = "POKéMON!\nPOKéMON CHANNEL…",
  ["1e:6d2f"] = "PIKACHU is an\nevolved POKéMON.\012I was amazed by\nPROF.ELM's find-\011ings.\012He's so famous for\nhis research on\011POKéMON evolution.\012…sigh…\012I wish I could be\na researcher like\011him…",
  ["1e:6dd4"] = "My daughter is\nadamant about\012becoming PROF.\nELM's assistant.\012She really loves\nPOKéMON!\012But then, so do I!",
  ["1e:6e3b"] = "PROF.OAK'S POKéMON\nTALK! Please tune\011in next time!",
  ["1e:6e6c"] = "POKéMON CHANNEL!",
  ["1e:6e7b"] = "This is DJ MARY,\nyour co-host!",
  ["1e:6e9b"] = "POKéMON!\nPOKéMON CHANNEL…",
  ["1e:6ef7"] = "Hi, {PLAYER}! My\nhusband's always\012so busy--I hope\nhe's OK.\012When he's caught\nup in his POKéMON\012research, he even\nforgets to eat.",
  ["1e:6f6b"] = "When I grow up,\nI'm going to help\011my dad!\012I'm going to be a\ngreat POKéMON\011professor!",
  ["1e:701b"] = "POKéMON. Where do\nthey come from? \012Where are they\ngoing?\012Why has no one\never witnessed a\011POKéMON's birth?\012I want to know! I\nwill dedicate my\012life to the study\nof POKéMON!\012…\012It's a part of\nPROF.ELM's re-\011search papers.",
  ["1e:714d"] = "Your POKéMON look\na little tired.\012You should rest\nthem a while.",
  ["1e:718b"] = "There!\012Your POKéMON are\nlooking good!\012Keep at it!",
  ["1e:71f9"] = "There's something\nwritten here.\012Read it?",
  ["1e:7222"] = "To my brothers and\nsisters:\012We take pride in\nserving POKéMON\011trainers.\012When trainers talk\nto you, give them\011something useful.\012Love,\nMONICA\012Keep reading?",
  ["1e:72b9"] = "Monday, MONICA\nROUTE 40\012Tuesday, TUSCANY\nROUTE 29\012Wednesday, WESLEY\nLAKE OF RAGE\012Thursday, ARTHUR\nROUTE 36\012Friday, FRIEDA\nROUTE 32\012Saturday, SANTOS\nBLACKTHORN CITY\012Sunday, SUNNY\nROUTE 37",
  ["1e:73c6"] = "Where are you off\nto with POKéMON?\012POKéMON LEAGUE?\012Are your POKéMON\nloyal enough for\011you to win?\012Let me see…",
  ["1e:742b"] = "Ah! Your POKéMON\ntrusts you very\011much.\012It's nice to see a\ngood trainer.\012Here. A gift for\nyour journey.",
  ["1e:748f"] = "TM37 happens to be\nSANDSTORM.\012It's a move that\ninflicts damage on\011both battlers.\012It's for advanced\ntrainers only.\012Use it if you\ndare. Good luck!",
  ["1e:751f"] = "If it doesn't come\nto trust you some\012more, it could be\ntough going.\012Trust is the tie\nthat binds POKéMON\011and trainers.",
  ["1e:75c1"] = "You can't climb\nledges.\012But you can jump\ndown from them to\011take a shortcut.",
  ["1e:760d"] = "Different kinds of\nPOKéMON appear\011past here.\012If you want to\ncatch them all,\012you have to look\neverywhere.",
  ["1f:4005"] = "POKéMON LEAGUE\012VICTORY ROAD\nENTRANCE",
  ["1f:4314"] = "I got booted out\nof the GAME COR-\011NER.\012I was trying to\ncheat using my\011POKéMON…",
  ["1f:4361"] = "…Grumble…",
  ["1f:436c"] = "I guess I have to\ndo things fair and\011square…",
  ["1f:439a"] = "Do you consider\ntype alignments in\011battle?\012If you know your\ntype advantages,\012you'll do better\nin battle.",
  ["1f:4403"] = "Ow, ow, ow!",
  ["1f:4410"] = "I know my POKéMON\ntype alignments.\012But I only use one\ntype of POKéMON.",
  ["1f:4452"] = "My POKéMON just\ngot a haircut!\012I'll show you how\nstrong it is!",
  ["1f:448e"] = "Aiyeeee!",
  ["1f:4498"] = "Your POKéMON will\nlike you more if\012you give them\nhaircuts.",
  ["1f:44d1"] = "I think you have\nsome rare POKéMON\011with you.\012Let me see them!",
  ["1f:450d"] = "Gaah! I lost!\nThat makes me mad!",
  ["1f:452f"] = "Are you making a\nPOKéDEX? Here's a\011hot tip.\012The HIKER on ROUTE\n33, ANTHONY, is a\011good guy.\012He'll phone you if\nhe sees any rare\011POKéMON.",
  ["1f:45b0"] = "The door's locked…",
  ["1f:45c3"] = "The door is open.",
  ["1f:45d6"] = "The BASEMENT KEY\nopened the door.",
  ["1f:45f9"] = "Welcome!\012I run the POKéMON\nSALON!\012I'm the older and\nbetter of the two\011HAIRCUT BROTHERS.\012I can make your\nPOKéMON beautiful\011for just ¥500.\012Would you like me\nto do that?",
  ["1f:469a"] = "Which POKéMON\nshould I work on?",
  ["1f:46b8"] = "OK! Watch it\nbecome beautiful!",
  ["1f:46d8"] = "There! All done!",
  ["1f:46ea"] = "Is that right?\nThat's a shame!",
  ["1f:4709"] = "You'll need more\nmoney than that.",
  ["1f:472b"] = "I do only one\nhaircut a day. I'm\011done for today.",
  ["1f:475c"] = "Welcome to the\nPOKéMON SALON!\012I'm the younger\nand less expen-\011sive of the two\011HAIRCUT BROTHERS.\012I'll spiff up your\nPOKéMON for just\011¥300.\012So? How about it?",
  ["1f:47f1"] = "OK, which POKéMON\nshould I do?",
  ["1f:480e"] = "OK! I'll make it\nlook cool!",
  ["1f:482a"] = "There we go!\nAll done!",
  ["1f:4842"] = "No? \nHow disappointing!",
  ["1f:485b"] = "You're a little\nshort on funds.",
  ["1f:487b"] = "I can do only one\nhaircut a day.\012Sorry, but I'm all\ndone for today.",
  ["1f:48bf"] = "{STRBUF} looks a\nlittle happier.",
  ["1f:48dc"] = "{STRBUF} looks\nhappy.",
  ["1f:48ee"] = "{STRBUF} looks\ndelighted!",
  ["1f:4904"] = "We're not open\ntoday.",
  ["1f:491a"] = "NO ENTRY BEYOND\nTHIS POINT",
  ["1f:4e9d"] = "Hold it!\012I saw you, so I\ntailed you.\012I don't need you\nunderfoot while I\012take care of TEAM\nROCKET.\012…Wait a second.\nYou beat me be-\011fore, didn't you?\012That was just a\nfluke.\012But I repay my\ndebts!",
  ["1f:4f5d"] = "…Why…\nWhy do I lose?\012I've assembled the\ntoughest POKéMON.\012I didn't ease up\non the gas.\012So why do I lose?",
  ["1f:4fc2"] = "…I don't under-\nstand…\012Is what that LANCE\nguy said true?\012That I don't treat\nPOKéMON properly?\012Love…\012Trust…\012Are they really\nwhat I lack?\012Are they keeping\nme from winning?\012I… I just don't\nunderstand.\012But it's not going\nto end here.\012Not now. Not\nbecause of this.\012I won't give up my\ndream of becoming\012the world's best\nPOKéMON trainer!",
  ["1f:5102"] = "Humph. This is my\nreal power, wimp.\012I'll make TEAM\nROCKET history.\012And I'm going to\ngrind that LANCE\011under my heels.",
  ["1f:5176"] = "I was challenged\nto a battle down-\011stairs.\012It's rough down\nthere. You'd\011better be careful.",
  ["1f:51d0"] = "There are some\nshops downstairs…\012But there are\nalso trainers.\012I'm scared to go\ndown there.",
  ["1f:522b"] = "Open one shutter,\nanother closes.\012Bet you can't get\nwhere you want!",
  ["1f:526f"] = "Drat! I was sunk\nby indecision!",
  ["1f:5290"] = "I'm confused too…\nThe switch on the\012end is the one to\npress first, but…",
  ["1f:52d8"] = "Kwahaha!\012Confounded by the\nshutters, are we?\012I'll let you in on\na secret if you\011can beat me!",
  ["1f:5335"] = "Uwww…\nI blew it.",
  ["1f:5347"] = "All right. A hint!\012Change the order\nof switching.\012That'll change the\nways the shutters\011open and close.",
  ["1f:53ae"] = "Fork over your\ngoodies!",
  ["1f:53c7"] = "Mercy!",
  ["1f:53cf"] = "Steal and sell!\nThat's basic in\011crime, kid!",
  ["1f:53fb"] = "They ditched this\nproject before\011they finished.\012I'm searching for\nleftover loot.",
  ["1f:544c"] = "Over the top!",
  ["1f:545b"] = "UNDERGROUND WARE-\nHOUSE?\012What do you want\nto go there for?\012There's nothing\ndown there.",
  ["1f:54b2"] = "I don't care if\nyou're lost.\012You show up here,\nyou're nothing but\011a victim!",
  ["1f:54fc"] = "Urk! Yeah, think\nyou're cool, huh?",
  ["1f:551f"] = "You must have ice\nin your veins to\011dis TEAM ROCKET.",
  ["1f:5554"] = "It's labeled\nSWITCH 1.",
  ["1f:556b"] = "Are you lost? No,\nyou can't be.\012You don't have\nthat scared look.\012I'll give you\nsomething to be\011scared about!",
  ["1f:55d6"] = "How could you?",
  ["1f:55e6"] = "Go wherever you'd\nlike! Get lost!\011See if I care!",
  ["1f:5617"] = "It's OFF.\nTurn it ON?",
  ["1f:562d"] = "It's ON.\nTurn it OFF?",
  ["1f:5643"] = "It's labeled\nSWITCH 2.",
  ["1f:565a"] = "It's labeled\nSWITCH 3.",
  ["1f:5671"] = "It's labeled\nEMERGENCY.",
  ["1f:57cb"] = "Hey, kid! You're\nholding us up!\012Our policy is to\nwork behind the\012scenes where no\none can see us!",
  ["1f:582c"] = "I lose my passion\nfor work if some-\011one's watching.\012Come on, kid,\nscoot!",
  ["1f:5875"] = "Oohah! Oohah!\012The stuff on the\nground's junk.\012Take it if you\nwant it!",
  ["1f:58bb"] = "MACHOKE: Maaacho!",
  ["1f:59ea"] = "How did you get\nthis far?\012I guess it can't\nbe helped. I'll\011dispose of you.",
  ["1f:5a34"] = "I got disposed of…",
  ["1f:5a48"] = "TEAM ROCKET will\nkeep going, wait-\011ing for the return\011of GIOVANNI.\012We'll do whatever\nit takes.",
  ["1f:5aa7"] = "You're not going\nany farther!\012I don't show mercy\nto my enemies, not\011even brats!",
  ["1f:5af6"] = "Blast it!",
  ["1f:5b01"] = "I lost…\012Please forgive me,\nGIOVANNI!",
  ["1f:5b27"] = "Hyuck-hyuck-hyuck!\nI remember you!\012You got me good\nat our hideout!",
  ["1f:5b6b"] = "Hyuck-hyuck-hyuck!\nSo, that's how?",
  ["1f:5b8e"] = "Hyuck-hyuck-hyuck!\nThat was a blast!\011I'll remember you!",
  ["1f:5bc6"] = "DIRECTOR: Who?\nWhat? You came to\011rescue me?\012Thank you!\012The RADIO TOWER!\012What's happening\nthere?\012Taken over by TEAM\nROCKET?\012Here. Take this\nCARD KEY.",
  ["1f:5c5b"] = "DIRECTOR: Use that\nto open the shut-\011ters on 3F.",
  ["1f:5c8d"] = "I'm begging you to\nhelp.\012There's no telling\nwhat they'll do if\012they control the\ntransmitter.\012They may even be\nable to control\012POKéMON using a\nspecial signal!\012You're the only\none I can call on.\012Please save the\nRADIO TOWER…\012And all the POKé-\nMON nationwide!",
  ["1f:5e8d"] = "I'm not losing\nthis time!",
  ["1f:5ea7"] = "I lost to some\nkid…?",
  ["1f:5ebd"] = "A while back, this\nkarate dude wanted\012to battle. He was\nridiculously good.\012He just thrashed\nus silly.\012He went in deeper\nsaying it was for\012his training. I\nwonder how he is?",
  ["1f:5f6a"] = "Hey! HUGH!",
  ["1f:5f76"] = "I mistook you for\nsomeone else…",
  ["1f:5f97"] = "I came to explore\nMT.MORTAR, but I\012got separated from\nmy partner…\012Did you run into a\ntrainer who uses a\012SEADRA that knows\nWATERFALL?",
  ["1f:60ed"] = "Yo! MARKUS!",
  ["1f:60fa"] = "Sorry, my mistake.",
  ["1f:610e"] = "I'm investigating\nMT.MORTAR, but my\011pal's gone AWOL.\012Have you seen a\ntrainer who has a\012SLOWPOKE that can\nuse STRENGTH?",
  ["1f:624d"] = "Hey!\012I am the KARATE\nKING!\012I train alone here\nin the dark!\012You!\nBattle with me!\012Hwaaarggh!",
  ["1f:62a9"] = "Waaaarggh!\nI'm beaten!",
  ["1f:62c0"] = "I… I'm crushed…\012My training is\nstill not enough…\012But a loss is a\nloss. I admit it.\012As proof that you\ndefeated me, I'll\012give you a rare\nfighting POKéMON.",
  ["1f:6355"] = "{PLAYER} received\nTYROGUE.",
  ["1f:636a"] = "TYROGUE is a\nfighting-type.\012It evolves into a\ntougher POKéMON.\012Keep up the hard\nwork. I'll keep\011training too.\012Farewell!",
  ["1f:63df"] = "You have no room\nin your party!",
  ["1f:6512"] = "The boulder fell\nthrough.",
  ["1f:65ad"] = "It's immovably\nimbedded in ice.",
  ["1f:66bd"] = "To the north of\nLAVENDER is ROCK\012TUNNEL. Go through\nit to get to the\011POWER PLANT.",
  ["1f:6710"] = "There's a radio\nprogram that plays\011POKé FLUTE music.\012Oh? Ah, your radio\nneeds an EXPN CARD\011to tune into it.",
  ["1f:6779"] = "If the POWER PLANT\nisn't running, the\012MAGNET TRAIN won't\nrun either…\012It also means the\nRADIO STATION\011can't broadcast…",
  ["1f:67ed"] = "The DIRECTOR of\nthe RADIO STATION\011sure was happy.\012He said they're\nback on the air\012because the POWER\nPLANT is running\011smoothly again.",
  ["1f:68f1"] = "MR.FUJI does live\nhere, but he's not\012home now.\012He should be at\nthe SOUL HOUSE.",
  ["1f:6940"] = "Some cold-hearted\npeople stop caring\011for their POKéMON.\012Grandpa takes in\nthe poor homeless\012POKéMON and takes\ncare of them.",
  ["1f:69b6"] = "PSYDUCK: Gu-guwa?",
  ["1f:69c9"] = "NIDORINO: Gyun!",
  ["1f:69da"] = "PIDGEY: Pijji!",
  ["1f:6a4d"] = "LAVENDER is a\ntiny, quiet town\012at the foot of the\nmountains.\012It's gotten a bit\nbusier since the\012RADIO TOWER was\nbuilt.",
  ["1f:6b29"] = "REPEL is a neces-\nsity if you are\012going to explore a\ncave.\012Even though I like\nexploring, I still\012haven't made it to\nall the caves.",
  ["1f:6bac"] = "I heard about a\ncraftsman who\012makes custom BALLS\nin the JOHTO town\012of AZALEA. I wish\nI had some.",
  ["1f:6c53"] = "MR.FUJI: Welcome.\012Hmm… You appear to\nbe raising your\012POKéMON in a kind\nand loving manner.\012POKéMON lovers\ncome here to pay\012their respects to\ndeparted POKéMON.\012Please offer con-\ndolences for the\012souls of the de-\nparted POKéMON.\012I'm sure that will\nmake them happy.",
  ["1f:6d4d"] = "There are other\ngraves of POKéMON\011here, I think.\012There are many\nchambers that only\011MR.FUJI may enter.",
  ["1f:6db1"] = "I came with my mom\nto visit POKéMON\011graves…",
  ["1f:6ddb"] = "The POKéMON that\nlived with me…\012I loved them like\nmy grandchildren…",
  ["1f:6ebf"] = "Welcome!\nFeel free to look\012around anywhere on\nthis floor.",
  ["1f:6efa"] = "Sorry, but you can\nonly tour the\011ground floor.\012Ever since JOHTO's\nRADIO TOWER was\012taken over by a\ncriminal gang, we\012have had to step\nup our security.",
  ["1f:6f90"] = "Many people are\nhard at work here\012in the RADIO\nTOWER.\012They must be doing\ntheir best to put\011on good shows.",
  ["1f:6ffb"] = "Oh, no, no, no!\012We've been off the\nair ever since the\012POWER PLANT shut\ndown.\012All my efforts to\nstart this station\012would be wasted if\nI can't broadcast.\012I'll be ruined!",
  ["1f:70a1"] = "Ah! So you're the\n{PLAYER} who solved\012the POWER PLANT's\nproblem?\012Thanks to you, I\nnever lost my job.\012I tell you, you're\na real lifesaver!\012Please take this\nas my thanks.",
  ["1f:7141"] = "With that thing,\nyou can tune into\012the radio programs\nhere in KANTO.\012Gahahahaha!",
  ["1f:7193"] = "Hey there!\012I am the super\nMUSIC DIRECTOR!\012Huh? Your POKéGEAR\ncan't tune into my\012music programs.\nHow unfortunate!\012If you get an EXPN\nCARD upgrade, you\012can tune in. You'd\nbetter get one!",
  ["1f:7248"] = "Hey there!\012I am the super\nMUSIC DIRECTOR!\012I'm responsible\nfor the gorgeous\012melodies that go\nout over the air.\012Don't be square.\nGrab your music\011off the air!",
  ["1f:72e3"] = "1F RECEPTION\n2F SALES\0123F PERSONNEL\n4F PRODUCTION\0125F DIRECTOR'S\n   OFFICE",
  ["1f:732d"] = "Perk Up POKéMON\nwith Mellow Sounds\012of the POKé FLUTE\non CHANNEL 20",
  ["1f:7419"] = "Have you been to\nLAVENDER TOWN?\012There's a tall\nRADIO TOWER there.",
  ["1f:74af"] = "I'm the FISHING\nGURU's younger\011brother.\012I can see that you\nlike fishing.\012There's no doubt\nin my mind at all!\012So? I know I'm\nright.",
  ["1f:752f"] = "Yes, yes. Just as\nI thought!\012Here, fishing fan!\nTake this--it's a\011SUPER ROD.",
  ["1f:757c"] = "Try your hand at\nfishing wherever\011there is water.\012Remember--you can\ncatch different\012POKéMON using\ndifferent RODS.",
  ["1f:75ec"] = "Huh? My own eyes\ndeceived me?",
  ["21:652c"] = "New Hall of Famer!",
  ["21:66fc"] = "    HOF Master!",
  ["21:670c"] = "    -Time Famer",
  ["24:423c"] = "Huh? Sorry, wrong\nnumber!",
  ["24:465b"] = "That number is out\nof the area.",
  ["24:4664"] = "Just go talk to\nthat person!",
  ["26:40d1"] = "TIN TOWER is off\nlimits to anyone\012without ECRUTEAK\nGYM's BADGE.\012Sorry, but you'll\nhave to leave.",
  ["26:4131"] = "TIN TOWER is off\nlimits to anyone\012without ECRUTEAK\nGYM's BADGE.\012Ah!\012ECRUTEAK's GYM\nBADGE! Please, go\011right through.",
  ["26:41a4"] = "A momentous event\nhas occurred.\012I beg your pardon,\nbut I must ask you\011to leave.\012…What soothes the\nsoul…\012The WISE TRIO say\nthings that are so\012very difficult to\nunderstand…",
  ["26:4250"] = "A momentous event\nhas occurred.\012I beg your pardon,\nbut I must ask you\011to leave.\012………………\012Ah!\012The sound of that\nCLEAR BELL!\012It… It's sublime!\012I've never heard\nso beautiful a\011sound before!\012That bell's chime\nis indicative of\011the bearer's soul.\012You…\012You may be able to\nmake it through\011TIN TOWER.\012Please, do go on.",
  ["26:437e"] = "Please, do go on.",
  ["26:4391"] = "That bell's chime\nis indicative of\011the bearer's soul.\012You…\012You may be able to\nmake it through\011TIN TOWER.\012Please, do go on.",
  ["26:440b"] = "The TIN TOWER\nahead is a nine-\012tier tower of\ndivine beauty.\012It soothes the\nsoul of all who\011see it.",
  ["26:446f"] = "The TIN TOWER\nshook! A POKéMON\012must have returned\nto the top!",
  ["26:44ab"] = "Two towers…\nTwo POKéMON…\012But when one\nburned down, both\012POKéMON flew away,\nnever to return.",
  ["26:462b"] = "Astounding…\012SUICUNE, ENTEI and\nRAIKOU have arisen\011from their sleep…\012Is the legend\ncoming true?",
  ["26:468b"] = "We train at the\nBURNED TOWER, but\012we've never heard\nof a hole opening\012up there before.\nIt must have been\012deliberately made\nby someone.",
  ["26:4712"] = "TIN TOWER may be\nentered by those\012bearing ECRUTEAK's\nGYM BADGE.\012However, now that\nSUICUNE, RAIKOU\012and ENTEI have\narisen, I ask you\012to refrain from\nentering!",
  ["26:47af"] = "We, the WISE TRIO,\nare the protectors\012of the legendary\nPOKéMON.",
  ["26:47ed"] = "Legend has it that\nupon the emergence\012of a trainer who\nhas the ability to\012touch the souls of\nPOKéMON, a POKéMON\012will come forth to\nput that trainer\012to test at the TIN\nTOWER.\012The legend has\ncome true!\012The legendary\nPOKéMON SUICUNE\011has arrived!\012We, the WISE TRIO,\nshall test your\012worthiness to go\ninside!",
  ["26:4914"] = "Stronger than we\nthought? Perhaps…",
  ["26:4938"] = "Ah, so it is you\nwho claim to have\012seen SUICUNE,\nENTEI and RAIKOU\011while they slept?\012Unbelievable!\012Legend has it that\nthey can't be seen\011while they sleep…",
  ["26:49d2"] = "Can you be trusted\nwith the truth?\012I must ascertain\nyour worthiness.",
  ["26:4a18"] = "…I will tell you\nthe truth…",
  ["26:4a35"] = "In the past, there\nwere two nine-tier\011towers here.\012The BRASS TOWER,\nwhich was said to\012awaken POKéMON,\nand the TIN TOWER,\012where POKéMON were\nsaid to rest.\012The view from the\ntops of the TOWERS\012must have been\nmagnificent.\012At the time, an\nimmense, silver-\012colored POKéMON\nwas said to make\012its roost atop the\nBRASS TOWER.\012However…\012About 150 years\nago, a lightning\012bolt struck one of\nthe TOWERS.\012It was engulfed in\nflames that raged\011for three days.\012A sudden downpour\nfinally put out\011the blaze.\012And that is how\nthe BURNED TOWER\011came to be.",
  ["26:4c42"] = "Let me see your\npower!",
  ["26:4c5a"] = "Too strong!\nWhy?",
  ["26:4c6c"] = "You… Are you the\ntrainer who is\012awaited by the\nlegendary POKéMON?",
  ["26:4cac"] = "I see…\012We, the WISE TRIO,\nhave been given \012the responsibility\nof protecting the\012legendary POKéMON.\nWe are to allow\012passage only to\nthose people who\012possess the power\nand soul of truth.\012Please, do go on\nand enter the TIN\011TOWER ahead.\012SUICUNE will put\nyou to the test.",
  ["26:4db5"] = "Please, do go on.\012SUICUNE will put\nyou to the test.",
  ["26:4ed8"] = "Hi, I'm BILL. And\nwho are you?\012Hmm, {PLAYER}, huh?\nYou've come at the\011right time.",
  ["26:4f22"] = "I just finished\nadjustments on my\011TIME CAPSULE.\012You know that\nPOKéMON can be\011traded, right?\012My TIME CAPSULE\nwas developed to\012enable trades with\nthe past.\012But you can't send\nanything that\012didn't exist in\nthe past.\012If you did, the PC\nin the past would\011have a breakdown.\012So you have to\nremove anything\012that wasn't around\nin the past.\012Put simply, no\nsending new moves\012or new POKéMON in\nthe TIME CAPSULE.\012Don't you worry.\nI'm done with the\011adjustments.\012Tomorrow, TIME\nCAPSULES will be\012running at all\nPOKéMON CENTERS.\012I have to hurry on\nback to GOLDENROD\011and see my folks.\012Buh-bye!",
  ["26:5155"] = "The way the KIMONO\nGIRLS dance is\012marvelous. Just\nlike the way they\011use their POKéMON.",
  ["26:51aa"] = "You must be hoping\nto battle more\012people, right?\nThere's apparently\012some place where\ntrainers gather.\012Where, you ask?\012It's a little past\nOLIVINE CITY.",
  ["26:5240"] = "MORTY, the GYM\nLEADER, is soooo\011cool.\012His POKéMON are\nreally tough too.",
  ["26:5286"] = "LAKE OF RAGE…\012The appearance of\na GYARADOS swarm…\012I smell a conspir-\nacy. I know it!",
  ["26:533d"] = "This happened when\nI was young.\012The sky suddenly\nturned black. A\012giant flying POKé-\nMON was blocking\011out the sun.\012I wonder what that\nPOKéMON was? \012It was like a bird\nand a dragon.",
  ["26:53ec"] = "Is there really a\nPOKéMON that big?\012If it exists, it\nmust be powerful.",
  ["26:552e"] = "You have lovely\nPOKéMON. May I see\011them in battle?",
  ["26:555f"] = "Oh, you are very\nstrong.",
  ["26:5579"] = "I enjoyed that\nbout. I would like\011to see you again.",
  ["26:55ae"] = "I always dance\nwith my POKéMON.\012Of course, I also\ntrain them.",
  ["26:55ea"] = "Oh, so close!\nI almost had you.",
  ["26:560b"] = "Rhythm is impor-\ntant for both\012dancing and POKé-\nMON.",
  ["26:563f"] = "Isn't my barrette\npretty?\012Oh. A POKéMON\nbattle?",
  ["26:566c"] = "I don't have any\nPOKéMON left…",
  ["26:5688"] = "I put a different\nflower in my bar-\011rette every month.",
  ["26:56c0"] = "Oh, you're a cute\ntrainer. Would you\011like to battle?",
  ["26:56f5"] = "You're stronger\nthan you look.",
  ["26:5714"] = "I trained a lot,\nso I thought I was\012a capable trainer.\nI guess I'm not.",
  ["26:575c"] = "Do you like my\ndancing? I'm good\011at POKéMON too.",
  ["26:578a"] = "Ooh, you're good\nat POKéMON too.",
  ["26:57a8"] = "I can keep dancing\nbecause there are\012people who enjoy\nwhat I do.\012My POKéMON keep my\nspirits up too.",
  ["26:580a"] = "Not only are the\nKIMONO GIRLS great\012dancers, they're\nalso skilled at\011POKéMON.\012I always challenge\nthem, but I've\012never even left a\nscratch…",
  ["26:5891"] = "Lad! If you can\ndefeat all the\012KIMONO GIRLS, I'll\ngive you a gift.",
  ["26:58d4"] = "Lassie, if you can\ndefeat all the\012KIMONO GIRLS, I'll\ngive you a gift.",
  ["26:591a"] = "The way you bat-\ntled, it was like\011watching a dance.\012It was a rare\ntreat to see!\012I want you to have\nthis. Don't worry\011--take it!",
  ["26:599b"] = "That's SURF.\012It's a move that\nlets POKéMON swim\011across water.",
  ["26:59d5"] = "I wish my POKéMON\nwere as elegant as\011the KIMONO GIRLS…",
  ["26:5a0a"] = "RHYDON: Gugooh\ngugogooh!",
  ["26:5a24"] = "That man's always\nwith his RHYDON.\012Says he wants a\nPOKéMON that can\011SURF and dance.\012Is he trying to\nmake a synchro-\011nized swimming\011POKéMON?",
  ["26:5aaa"] = "The KIMONO GIRLS\nare so beautiful…\012But they have to\ngo through rigor-\011ous training.\012And they have to\nlearn to follow\012customs before ap-\npearing in public.\012But if you love\nsomething, any-\011thing is possible.",
  ["26:5b79"] = "It's a fancy panel\nthat's decorated\011with flowers.",
  ["26:5c48"] = "My EEVEE evolved\ninto an ESPEON.\012But my friend's\nEEVEE turned into\011an UMBREON.\012I wonder why? We\nboth were raising\012our EEVEE in the\nsame way…",
  ["26:5cd5"] = "If you use REVIVE,\na POKéMON that's\012fainted will wake\nright up.",
  ["26:5e65"] = "Good of you to\nhave come.\012Here in ECRUTEAK,\nPOKéMON have been\011revered.\012It's said that a\nrainbow-colored\012POKéMON will come\ndown to appear\012before a truly\npowerful trainer.\012I believed that\ntale, so I have\012secretly trained\nhere all my life.\012As a result, I can\nnow see what\011others cannot.\012Just a bit more…\012With a little\nmore, I could see\012a future in which\nI meet the POKéMON\011of rainbow colors.\012You're going to\nhelp me reach that\011level!",
  ["26:600a"] = "I'm not good\nenough yet…\012All right. This\nBADGE is yours.",
  ["26:6043"] = "{PLAYER} received\nFOGBADGE.",
  ["26:6059"] = "By having FOG-\nBADGE, POKéMON up\012to L50 will obey\nyou.\012Also, POKéMON that\nknow SURF will be\012able to use that\nmove anytime.\012I want you to have\nthis too.",
  ["26:60ec"] = "It's SHADOW BALL.\nIt causes damage\012and may reduce\nSPCL.DEF.\012Use it if it\nappeals to you.",
  ["26:6145"] = "I see…\012Your journey has\ntaken you to far-\011away places.\012And you have wit-\nnessed much more\011than I.\012I envy you for\nthat…",
  ["26:61bd"] = "I spent the spring\nwith my POKéMON.\012Then summer, fall\nand winter…\012Then spring came\nagain. We have\012lived together\nfor a long time.",
  ["26:623d"] = "Wins and losses, I\nexperienced both.",
  ["26:6263"] = "Where did POKéMON\ncome from?",
  ["26:627e"] = "Can you inflict\nany damage on our\011POKéMON?",
  ["26:62a7"] = "Ah! Well done!",
  ["26:62b7"] = "We use only ghost-\ntype POKéMON.\012No normal-type\nattack can harm\011them!",
  ["26:62fb"] = "I shall win!",
  ["26:6309"] = "I, I, I lost!",
  ["26:6318"] = "The one who wants\nto win most--will!",
  ["26:633e"] = "Stumped by our in-\nvisible floor?\012Defeat me if you\nwant a hint!",
  ["26:637f"] = "Wha-what?",
  ["26:638a"] = "Fine. I shall tell\nyou the secret of\012the invisible\nfloor.\012The path is right\nbefore our eyes!",
  ["26:63e8"] = "The trainers here\nhave secret mo-\011tives.\012If you win, they\nmay tell you some\012deep secrets about\nECRUTEAK.",
  ["26:6452"] = "Whew, {PLAYER}.\nYou did great!\012I was cowering in\nthe corner out of\011pure terror!",
  ["26:649c"] = "MORTY, the GYM\nLEADER, is absent.\012Sorry, but you'll\nhave to leave.\012Hohohoho.",
  ["26:663c"] = "Ah. You're on an\nadventure with\011your POKéMON?\012Well, what's an\nadventure without\011treasure hunting?\012Am I right, or am\nI right?",
  ["26:66b5"] = "Good! You under-\nstand the true\012spirit of adven-\nture.\012I like that! Take\nthis with you.",
  ["26:670e"] = "There are many\nitems lying about\012that aren't ob-\nvious.\012Use ITEMFINDER to\ncheck if there is\012an item on the\nground near you.\012It doesn't show\nthe exact spot,\012so you'll have to\nlook yourself.\012Oh yeah--I heard\nthere are items\012in ECRUTEAK's\nBURNED TOWER.",
  ["26:6805"] = "Oh… To each his\nown, I suppose…",
  ["26:6826"] = "HISTORY OF\nECRUTEAK\012Want to read it?",
  ["26:684c"] = "In ECRUTEAK, there\nwere two towers.\012Each tower was the\nroost of powerful\011flying POKéMON.\012But one of the\ntowers burned to\011the ground.\012The two POKéMON\nhaven't been seen\011since…\012Keep reading?",
  ["26:6902"] = "ECRUTEAK was also\nhome to three\012POKéMON that raced\naround the town.\012They were said to\nhave been born of\012water, lightning\nand fire.\012But they could not\ncontain their\011excessive power.\012So they say the\nthree ran like the\012wind off into the\ngrassland.",
  ["26:6a7b"] = "BLUE: Yo! Finally\ngot here, huh?\012I wasn't in the\nmood at CINNABAR,\012but now I'm ready\nto battle you.\012…\012You're telling me\nyou conquered all\011the GYMS in JOHTO?\012Heh! JOHTO's GYMS\nmust be pretty\011pathetic then.\012Hey, don't worry\nabout it.\012I'll know if you\nare good or not by\012battling you right\nnow.\012Ready, JOHTO\nCHAMP?",
  ["26:6bae"] = "BLUE: What?\012How the heck did I\nlose to you?\012…\012Tch, all right…\nHere, take this--\011it's EARTHBADGE.",
  ["26:6c0f"] = "{PLAYER} received\nEARTHBADGE.",
  ["26:6c27"] = "BLUE: …\012All right, I was\nwrong. You're the\012real deal. You are\na good trainer.\012But I'm going to\nbeat you someday.\012Don't you forget\nit!",
  ["26:6cab"] = "BLUE: Listen, you.\012You'd better not\nlose until I beat\011you. Got it?",
  ["26:6cee"] = "Yo, CHAMP in\nmaking!\012How's it going?\nLooks like you're\011on a roll.\012The GYM LEADER is\na guy who battled\012the CHAMPION three\nyears ago.\012He's no pushover.\012Give it everything\nyou've got!",
  ["26:6da0"] = "Man, you are truly\ntough…\012That was a heck of\nan inspirational\012battle. It brought\ntears to my eyes.",
  ["26:6e54"] = "Do you put a lot\nof thought into\012naming your\nPOKéMON?\012Giving them good\nnicknames adds to\012the fun of trading\nwith others.",
  ["26:6ecb"] = "They're SPEARY--\na SPEAROW--and\011RATTEY--a RATTATA.",
  ["26:6efe"] = "SPEARY: Ch-chun!",
  ["26:6f10"] = "RATTEY: Kikiii!",
  ["26:6f7f"] = "Welcome to TRAINER\nHOUSE, the newest\012and most happening\nplace in VIRIDIAN.\012We're open to\ntrainers only.\012You can battle\nagainst the best\012of the best right\ndownstairs.",
  ["26:7025"] = "VIRIDIAN is the\ntown closest to\011INDIGO PLATEAU.\012They built this\nplace because so\012many trainers pass\nthrough on their\012way up to INDIGO\nPLATEAU.",
  ["26:70b5"] = "They hold practice\nbattles downstairs\011here.\012I would love to\nsee how well a\012trainer from JOHTO\nbattles.",
  ["26:711d"] = "I guess you can't\nbecome the CHAMP\012unless you go all\nover the place and\012battle all kinds\nof people.\012The CHAMPION from\nPALLET traveled to\012all the cities and\ntowns in KANTO.",
  ["26:71c9"] = "Whew… I'm taking a\nrest from POKéMON\011battles.",
  ["26:71f4"] = "Practice battles\nare held in the\012TRAINING HALL\ndownstairs.\012Skilled trainers\nare invited to\011participate.",
  ["26:725d"] = "There are no rules\nor regulations for\012practice matches.\nJust like in field\012battles, anything\ngoes!",
  ["26:72c1"] = "…What's this?\nA strategy memo?\012This writing looks\nlike ONIX tracks…\012It's completely\nillegible…",
  ["26:7420"] = "Hi. Welcome to our\nTRAINING HALL.\012You may battle a\ntrainer once per\011day.",
  ["26:746a"] = "{STRBUF} is your\nopponent today.",
  ["26:7487"] = "Would you like to\nbattle?",
  ["26:74a2"] = "Please go right\nthrough.\012You may begin\nright away.",
  ["26:74d6"] = "Sorry. Only those\ntrainers who will\012be battling are\nallowed to go in.",
  ["26:751d"] = "I'm sorry.\nThis would be your\012second time today.\nYou're permitted\012to enter just once\na day.",
  ["26:7578"] = "I lost…\nDarn…",
  ["26:7587"] = "I traveled out\nhere just so I\011could battle you.",
  ["26:75f4"] = "The GYM LEADER\nhere is totally\011cool.",
  ["26:761a"] = "Have you been to\nCINNABAR?\012It's an island way\nsouth of here.",
  ["26:76ad"] = "Where in the world\nis VIRIDIAN's GYM\012LEADER? I wanted\nto challenge him.",
  ["26:76f5"] = "There are no GYM\nTRAINERS at the\011VIRIDIAN GYM.\012The LEADER claims\nhis policy is to\012win without having\nany underlings.",
  ["26:776b"] = "I heard that the\nGYM in CINNABAR is\011gone.\012I wonder what be-\ncame of BLAINE,\011the GYM LEADER.",
  ["26:77c8"] = "My dream is to be-\ncome a GYM LEADER.",
  ["26:7865"] = "Hi! Wow, I'm glad\nto see you.\012You're the first\nvisitor I've had\011in a long time.\012I'm super-happy!\nLet me give you a\011little present.",
  ["26:78e5"] = "That's a NUGGET.\012I can't give you\nany nuggets of\012wisdom, so that'll\nhave to do!",
  ["26:7955"] = "Are you {PLAYER}?\012I work as PROF.\nOAK's AIDE.\012I had no idea that\nyou were out here.\012PROF.OAK's LAB is\nnearby in PALLET\011TOWN.",
  ["26:7a29"] = "Only trainers who\nhave proven them-\011selves may pass.",
  ["26:7a5f"] = "You don't have all\nthe GYM BADGES of\011JOHTO.\012I'm sorry, but I\ncan't let you go\011through.",
  ["26:7ab4"] = "Oh! The eight\nBADGES of JOHTO!\012Please, go right\non through!",
  ["26:7af1"] = "This way leads to\nMT.SILVER.\012You'll see scary-\nstrong POKéMON out\011there.",
  ["26:7b37"] = "Off to the POKéMON\nLEAGUE, are you?\012The ELITE FOUR are\nso strong it's\012scary, and they're\nready for you!",
  ["27:400e"] = "The SAILOR in the\nOLIVINE CAFE next\012door is really\ngenerous.\012He taught my\nPOKéMON STRENGTH.\012Now it can move\nbig boulders.",
  ["27:4086"] = "There's a person\nin CIANWOOD CITY\011across the sea.\012I heard him brag-\nging about his\011rare POKéMON.",
  ["27:41b9"] = "…Thank you for\nyour help at the\011LIGHTHOUSE…\012But this is dif-\nferent. Please\012allow me to intro-\nduce myself.\012I am JASMINE, a\nGYM LEADER. I use\011the steel-type.\012…Do you know about\nthe steel-type?\012It's a type that\nwas only recently\011discovered.\012…Um… May I begin?",
  ["27:42bb"] = "…You are a better\ntrainer than me,\012in both skill and\nkindness.\012In accordance with\nLEAGUE rules, I\012confer upon you\nthis BADGE.",
  ["27:433a"] = "{PLAYER} received\nMINERALBADGE.",
  ["27:4354"] = "MINERALBADGE\nraises POKéMON's\011DEFENSE.\012…Um… Please take\nthis too…",
  ["27:43a5"] = "…You could use\nthat TM to teach\011IRON TAIL.",
  ["27:43d1"] = "Um… I don't know\nhow to say this,\011but good luck…",
  ["27:4402"] = "JASMINE uses the\nnewly discovered\011steel-type.\012I don't know very\nmuch about it.",
  ["27:4451"] = "That was awesome.\012The steel-type,\nhuh?\012That was a close\nencounter of an\011unknown kind!",
  ["27:44a8"] = "JASMINE, the GYM\nLEADER, is at the\011LIGHTHOUSE.\012She's been tending\nto a sick POKéMON.\012A strong trainer\nhas to be compas-\011sionate.",
  ["27:45a2"] = "When my POKéMON\ngot sick, the\012PHARMACIST in\nECRUTEAK made some\011medicine for me.",
  ["27:45f0"] = "RHYDON: Gugooh!",
  ["27:4643"] = "Along the way to\nCIANWOOD, there\012are four deserted\nislands.\012Bad kids are taken\nto the islands as\011punishment!",
  ["27:46b1"] = "Whenever I get in\ntrouble, Daddy\011always scares me.",
  ["27:4749"] = "OLIVINE is on the\nsea!\012And if it's on the\nsea, there are\011bound to be fish!\012I've fished here\nfor 30 years.\012Would you like to\nface the sea and\011fish?",
  ["27:47db"] = "Ah, hahah!\nWe have ourselves\011a new angler!",
  ["27:4807"] = "Fish aren't found\nin the sea alone.\012They go wherever\nthere is water.",
  ["27:484c"] = "Whaaat? You don't\nlike to fish!?\011Incomprehensible!",
  ["27:487f"] = "How are things?\nLand the big one?",
  ["27:48df"] = "Hah! Your POKéMON\nsure look like\011lightweights!\012They don't have\nthe power to move\011boulders aside.\012Here, use this\nand teach them\011STRENGTH!",
  ["27:4965"] = "On the sea, the\nonly thing you can\012count on is your\nown good self!\012I'm so proud of my\nbuff bod!",
  ["27:49c5"] = "OLIVINE CAFE's\nmenu is chock full\012of hearty fare for\nbeefy SAILORS!",
  ["27:4a09"] = "Whenever I roll\ninto this town, I\012always visit the\nOLIVINE CAFE.\012Everything on the\nmenu makes me feel\012stronger. I can't\nstop eating!",
  ["27:4ad4"] = "Do your POKéMON\nalready know the\012move for carrying\npeople on water?",
  ["27:4b16"] = "My BUTTERFREE came\nfrom my boyfriend\011overseas.\012It carried some\nMAIL from him.\012Want to know what\nit says?\012Let's see… Nope!\nIt's a secret!",
  ["27:4bda"] = "Where did you say\nyou're from?\012NEW BARK TOWN?\012PROF.ELM lives\nover there, right?\012You've come a long\nway to get here.",
  ["27:4d2e"] = "MOOMOO is sick…\012She needs lots of\nBERRIES.",
  ["27:4d5a"] = "We're feeding\nMOOMOO!",
  ["27:4d70"] = "MILTANK: …Moo…",
  ["27:4d80"] = "Its cry is weak…",
  ["27:4d92"] = "MILTANK: Mooo!",
  ["27:4da2"] = "Give a BERRY to\nMILTANK?",
  ["27:4dbc"] = "{PLAYER} gave a\nBERRY to MILTANK.",
  ["27:4dd8"] = "MILTANK became a\nlittle healthier!",
  ["27:4dfc"] = "MILTANK became\nquite healthy!",
  ["27:4e1b"] = "MILTANK became\ntotally healthy!",
  ["27:4e3c"] = "{PLAYER} has no\nBERRIES…",
  ["27:4e4f"] = "{PLAYER} wouldn't\ngive a BERRY.\012MILTANK looks sad.",
  ["27:4f38"] = "My MILTANK ain't\ngivin' me milk\011n'more.\012This here FARM's\ngot famous milk.\012Most everyone\nwants a drink.\012It'll give me lots\no' milk if'n I\012feed it lots o'\nBERRIES, I reckon.",
  ["27:4fe1"] = "How'd you like my\nMOOMOO MILK?\012It's my pride and\njoy, there.\012Give it to POKéMON\nto restore HP!\012I'll give it to ya\nfer just ¥500.",
  ["27:505d"] = "Here ya go!\nDrink up'n enjoy!",
  ["27:507c"] = "Sorry, there.\nNo cash, no sale!",
  ["27:509d"] = "I reckon yer\nPACK's full.",
  ["27:50b7"] = "You don't want it?\nCome again, hear?",
  ["27:50dc"] = "I best go do my\nmilkin'.",
  ["27:50f6"] = "Our milk even goes\nout to KANTO.\012So if our own\nMILTANK won't give\012us any milk, we're\nin trouble.",
  ["27:5156"] = "You fixed our\nMILTANK, hon. Now\012it gives MOOMOO\nMILK again.\012Here's somethin'\nfer your trouble.",
  ["27:51c7"] = "That there's\nSNORE.\012It's a rare move\nthat only works\012while the POKéMON\nis asleep.\012You best think how\nyou ought to use\011it, hon.",
  ["27:5303"] = "I, I'm in shock!\012A guy about your\nage with piercing\012eyes and long hair\ncame in.\012He scared me into\ngiving him my\011prized POKéMON!\012I still have one\nleft, but what if\011he comes back?\012You look strong.\nCould you look\012after my POKéMON\nfor a while?",
  ["27:53ed"] = "Oh, thank you!\012Take good care of\nit, please!",
  ["27:541b"] = "{PLAYER} received a\nPOKéMON.",
  ["27:542f"] = "Your POKéMON party\nis full.",
  ["27:5449"] = "Oh, no… What'll\nI do if he comes\011back?",
  ["27:5470"] = "Hi! How's my POKé-\nMON?\012I think I'm safe\nnow, so may I have\011it back?",
  ["27:54b1"] = "Thank you!",
  ["27:54bd"] = "Hey, you don't\nhave my POKéMON\011with you.",
  ["27:54e3"] = "My POKéMON has\ncome to like you.\012All right, you\nshould keep it.\012But promise to\nbe good to it!",
  ["27:553f"] = "Oh, no, no… That's\nthe same as being\011robbed.",
  ["27:556c"] = "For POKéMON, hap-\npiness is being\012with a person who\ntreats them well.",
  ["27:56f9"] = "WAHAHAH!\012So you've come\nthis far!\012Let me tell you,\nI'm tough!\012My POKéMON will\ncrush stones and\011shatter bones!\012Watch this!",
  ["27:576f"] = "CHUCK: Urggh!\n…\012Oooarrgh!",
  ["27:578a"] = "There! Scared now,\nare you?\012What?\nIt has nothing to\012do with POKéMON?\nThat's true!\012Come on. We shall\ndo battle!",
  ["27:57f6"] = "Wha? Huh?\nI lost?\012How about that!\nYou're worthy of\011STORMBADGE!",
  ["27:5835"] = "{PLAYER} received\nSTORMBADGE.",
  ["27:584d"] = "STORMBADGE makes\nall POKéMON up to\012L70 obey, even\ntraded ones.\012It also lets your\nPOKéMON use FLY\012when you're not in\na battle.\012Here, take this\ntoo!",
  ["27:58da"] = "That is DYNAMIC-\nPUNCH.\012It doesn't always\nhit, but when it\012does, it causes\nconfusion!",
  ["27:5930"] = "WAHAHAH! I enjoyed\nbattling you!\012But a loss is a\nloss!\012From now on, I'm\ngoing to train 24\011hours a day!",
  ["27:5997"] = "My POKéMON and I\nare bound togeth-\011er by friendship.\012Our bond will\nnever be broken!",
  ["27:59e9"] = "This isn't real!",
  ["27:59fa"] = "You seem to have a\nstrong bond with\011your POKéMON too!",
  ["27:5a2e"] = "We martial artists\nfear nothing!",
  ["27:5a50"] = "That's shocking!",
  ["27:5a61"] = "Fighting POKéMON\nare afraid of psy-\011chics…",
  ["27:5a8a"] = "Words are useless.\nLet your fists do\011the talking!",
  ["27:5ac0"] = "I lost! \nI'm speechless!",
  ["27:5ad9"] = "My raging fists\nwill shatter your\011POKéMON!",
  ["27:5b02"] = "I got shattered!",
  ["27:5b14"] = "My POKéMON lost…\nMy… my pride is\011shattered…",
  ["27:5bed"] = "Did you meet the\nPOKéMANIAC?\012He's always brag-\nging about his\011rare POKéMON.",
  ["27:5c33"] = "The POKéMON GYM\ntrainers here are\011macho bullies.\012If I stick around,\nthey might come\011after me.\012Here's some ad-\nvice: the GYM\012LEADER uses the\nfighting-type.\012So you should\nconfound him with\011psychic POKéMON.\012Wipe out his POKé-\nMON before they\012can use their\nphysical strength.\012And those boulders\nin the middle of\011the GYM?\012If you don't move\nthem correctly,\012you won't reach\nthe GYM LEADER.\012If you get stuck,\ngo outside.",
  ["27:5dc5"] = "{PLAYER}! You won!\nI could tell by\011looking at you!",
  ["27:5ed7"] = "I love showing off\nthe POKéMON that\012I've raised.\nDon't you?\012I'm going to get\ninto a bunch of\012battles, and show\noff my POKéMON!",
  ["27:5fcd"] = "Your POKéMON ap-\npear to be fine.\012Is something wor- \nrying you?\012…\012The LIGHTHOUSE\nPOKéMON is in\011trouble?\012I got it!\012This ought to do\nthe trick.",
  ["27:6056"] = "{PLAYER} received\nSECRETPOTION.",
  ["27:6070"] = "My SECRETPOTION is\na tad too strong.\012I only offer it in\nan emergency.",
  ["27:60f9"] = "You have magnifi-\ncent POKéMON with\011you.\012How about a photo\nfor a souvenir?",
  ["27:6142"] = "OK! Big smile now!",
  ["27:6156"] = "Oh, that's too\nbad. I thought it\012would be a great\nmemento…",
  ["27:61bc"] = "You came from\nOLIVINE?\012Do you remember\nthe four islands\011along the way?\012I heard that a \nmythical sea crea-\011ture is hiding in\011them.",
  ["27:623f"] = "I heard that you\ncan only see it if\012you have a SILVER\nWING.\012It must have the\nsame scent as the\011creature.",
  ["27:62a9"] = "I've heard that\nthe whirlpools\012around the islands\nare caused by the\011sea creature.\012You might need a\nspecial move to\011get past them.",
  ["27:65ab"] = "BATTLE TOWER\nwelcomes you!\012I could show you\nto a BATTLE ROOM.",
  ["27:65ea"] = "Want to go into a\nBATTLE ROOM?",
  ["27:660a"] = "Right this way to\nyour BATTLE ROOM.",
  ["27:6886"] = "BATTLE TOWER is a\nfacility made for\011POKéMON battles.\012Countless POKéMON\ntrainers gather\012from all over to\nhold battles in\012specially designed\nBATTLE ROOMS.\012There are many\nBATTLE ROOMS in\011the BATTLE TOWER.\012Each ROOM holds\nseven trainers.\012Beat them all, and\nwin a prize.\012To interrupt a\nsession, you must\012SAVE. If not, you\nwon't be able to\012resume your ROOM\nchallenge.\012",
  ["27:6a49"] = "Thanks for\nvisiting!",
  ["27:6aef"] = "Congratulations!\012You've beaten all\nthe trainers!\012For that, you get\nthis great prize!\012",
  ["27:6b7e"] = "{PLAYER} got five\n{STRBUF}!",
  ["27:6b94"] = "Oops, your PACK is\nstuffed full.\012Please make room\nand come back.",
  ["27:6c09"] = "We hope to serve\nyou again.",
  ["27:6c26"] = "Please step this\nway.",
  ["27:6c3d"] = "Would you like to\nhear about the\011BATTLE TOWER?",
  ["27:6d3c"] = "BATTLE TOWER rules\nare written here.\012Read the rules?",
  ["27:6d72"] = "Three POKéMON may\nenter battles.\012All three must be\ndifferent.\012The items they\nhold must also be\011different.\012Certain POKéMON\nmay also have\012level restrictions\nplaced on them.",
  ["27:6e18"] = "Excuse me!\nYou didn't SAVE\012before exiting\nthe BATTLE ROOM.\012I'm awfully sorry,\nbut your challenge\012will be declared\ninvalid.",
  ["27:6e92"] = "Your POKéMON will\nbe healed to full\011health.",
  ["27:6ebc"] = "Next up, opponent\nno.{STRBUF}. Ready?",
  ["27:6f1f"] = "Before entering\nthe BATTLE ROOM,\012your progress will\nbe saved.",
  ["27:6f5e"] = "SAVE and end the\nsession?",
  ["27:6fbf"] = "Cancel your BATTLE\nROOM challenge?",
  ["27:7037"] = "We've been waiting\nfor you. This way\012to a BATTLE ROOM,\nplease.",
  ["27:7264"] = "Destroyed by the\nfirst opponent in\012no time at all…\nI'm no good…",
  ["27:72a4"] = "There are lots of\nBATTLE ROOMS, but\012I'm going to win\nthem all!",
  ["27:72e3"] = "It's a grueling\ntask, not being\012able to use items\nin battle.\012Making your\nPOKéMON hold items\012is the key to\nwinning battles.",
  ["27:735b"] = "I'm trying to see\nhow far I can go\012using just bug\nPOKéMON.\012Don't let there be\nany fire POKéMON…",
  ["27:7716"] = "Are you going to\nthe BATTLE TOWER?\012This is a secret,\nbut if you win a\012whole lot, you can\nwin special gifts.",
  ["27:77c8"] = "The levels of the\nPOKéMON I want to\012use are all\ndifferent.\012I have to go train\nthem now!",
  ["27:7930"] = "Wow, the BATTLE\nTOWER is huge!\012There must be many\nkinds of POKéMON\011in there!",
  ["27:79db"] = "You can use only\nthree POKéMON.\012It's so hard to\ndecide which three\012should go into\nbattle…",
  ["27:7a8c"] = "Hehehe, I snuck\nout from work.\012I can't bail out\nuntil I've won!\012I have to win it\nall. That I must!",
  ["27:7afc"] = "BATTLE TOWER\012Take the Ultimate\nTrainer Challenge!",
  ["28:4c28"] = "Hi, this is BUENA…\012Oh! Good morning,\n{PLAYER}!\012I'm kind of foggy\nin the morning…",
  ["28:4c72"] = "Hi, this is BUENA…\nOh! Hi, {PLAYER}!\012Do you tune into\nBUENA's show?",
  ["28:4caf"] = "This is BUENA.\nI can't come to\012the phone right\nnow.\012If you want to\nchat, tune into\012BUENA's PASSWORD\non the radio and\012give me a call\nafter midnight!",
  ["28:4d42"] = "Hi, this is BUENA…\nOh! Hi, {PLAYER}!\012I just got off\nwork. \012Let me tell you,\nI'm exhausted!",
  ["28:4d96"] = "{PLAYER}!\nHi, it's BUENA!\012I got up early, so\nI decided to call!",
  ["28:4dcf"] = "{PLAYER}!\nHi, it's BUENA!\012I needed someone\nto chat with!",
  ["28:4e01"] = "{PLAYER}!\nHi, it's BUENA!\012I'm just on my\nbreak.",
  ["28:4e29"] = "{PLAYER}!\nHi, it's BUENA!\012I couldn't sleep,\nso I called you.",
  ["28:4e5e"] = "Oh. Hi, {PLAYER}!\012You are how?\012Aiyee! This isn't\nthe time for me to\012be cracking silly\ngag greetings!\012The RADIO TOWER is\nin deep trouble!\012{PLAYER}, you'd\nbetter be careful!",
  ["28:4efb"] = "The other day, I\nwent out to eat\012with DJ BEN!\nIsn't it great?\012Not only that, he\nsaid the music on\012my program is\ncool!\012Oh, wow! Like,\nwhat should I do?\012…Oops, I have to\nget ready for my\012show! I'll catch\nyou later!",
  ["28:4fcf"] = "You know the\nreceptionist at\011the RADIO TOWER?\012'Welcome,' is all\nshe ever says.\012But she's really\nthe chattiest\012person at the\nRADIO TOWER.\012So she must be\nholding back.\012Isn't that fun to\nknow?\012Catch you later!",
  ["28:509d"] = "Tell me, {PLAYER}.\nHave you ever won\012a prize on the\nLUCKY NUMBER SHOW?\012REED moans that\nhe's never won, so\012he vows to keep\nthe show on the\011air till he does.\012Let's chat again!",
  ["28:5143"] = "You know, last\nnight…\012I was so stressed\nout from work, I\012ate a ton of junk\nfood!\012MARY and I have\nthis deal about\011losing weight…\012This won't do…\012Huh? What's the\nweight?\012This has to be a\ntotal secret!\012MARY weighs…\012Aiyee! M-MARY!\012Uh… Um… I… Sorry,\nwrong number!",
  ["28:5244"] = "Yesterday, PROF.\nOAK was in the\012studio to tape his\nshow.\012So I went over and\nintroduced myself.\012Get this--he tunes\nin to my program!\012Oh! Here comes\nPROF.OAK again!\012I'm going to chat\nhim up again!\012Catch you later!",
  ["28:5318"] = "…Cough, cough!\012Uhm sorry uh got\nuh code dite now.\012Buh uma pro so uh\nhav to cover id ub\012so no un notice\nwhile uhm on air.\012Uh fidz muh voice\nnow.\012I'll catch you on\nthe fly. This has\011been BUENA!",
  ["28:53d8"] = "Hey, {PLAYER}.\nYou won that RADIO\012CARD by beating\nthe quiz at the\012reception desk,\ndidn't you?\012Guess what? I made\nup the questions!\012…Were they too\neasy for you?\012Well, let's chat\nagain!",
  ["28:5488"] = "I'm elated that\nmore people are\012taking part in my\nPASSWORD show.\012But when PIKACHU\nwas the password,\012it was uh… whew…\noverwhelming.\012FAN CLUB people\ncame in out in\012droves, shouting\n'PIKACHU!' over\012and over. I mean,\nthey were loud.\012Anyone tuning in\naround then must\012have been shocked\nby the racket!\012Anyway, back to\nwork for me!\012Let's chat again!",
  ["28:55de"] = "Guess what?\nThe RADIO TOWER's\012DIRECTOR is a big\nfan of TV!\012A while ago, a\nfashion show on TV\012said that black\nsuits were in.\012Now all he wears\nare black suits.\012But it's a secret\nthat our DIRECTOR\012is a TV fan, so if\nyou see him, don't\012you dare mention\nit!\012Oh! The DIRECTOR\nwill be here soon!\012Later! Tune into\nmy show!",
  ["28:5717"] = "{PLAYER}, tell me.\012When do you relax\nthe most?\012For me, it has to\nbe in the studio\012right after my\nshow, enjoying a\012nice cup of tea.\nIt's so pleasant\012that it gradually\nmakes me drowsy…\012…… …… ……\012…… …… ……Zzz\012Oops, I drifted\noff just thinking\012about it! How, uh…\nembarrassing!\012Please forget this\nhappened! Later!",
  ["28:583d"] = "{PLAYER}, what was\nthe first POKéMON\011you ever caught?\012…Oh, really?\012I've seen lots of\nPOKéMON around,\012but I've never\ncaught one.\012I should give it a\ntry sometime.\012Did you know that\nthe first POKéMON\012MARY caught was a\nDROWZEE?\012Isn't that so out\nof character?\012But MARY's DROWZEE\nkept making her\012fall asleep on the\njob, so she traded\012with a fan for a\nMEOWTH.\012Let's chat about\nPOKéMON again!\012Bye-bye!",
  ["28:59b1"] = "Guess what? All of\nus from the RADIO\012TOWER are going on\na company vacation\012to the RADIO TOWER\nin LAVENDER.\012We're wasting our\nvacation on a trip\012to another RADIO\nTOWER?\012I'd much rather go\nto the beach!\012{PLAYER}, I hope\nyou have enough\012fun for both of us\non your journey!\012Bye-bye!",
  ["28:5ac0"] = "Did you know…?\012BEN and FERN talk\non the phone for\012hours about what\nPOKéMON music they\012should play on\ndifferent days of\011the week.\012One time, FERN's\nrapping style kind\012of rubbed off on\nBEN weirdly.\012So we ended up\nenduring BEN's\012silly, chilly, a\nwilly-nilly jive-\011talking shtick for\011a while.\012Let's chat again!",
  ["28:5bed"] = "I'm going shopping\nwith MARY and LILY\011soon.\012It'll be great if\nGOLDENROD DEPT.\012STORE has a sale\non when we go…\012{PLAYER}, maybe we\ncan hook up too!\012Catch you later!",
  ["28:5c88"] = "I'm thinking of\ngoing to the GAME\012CORNER tomorrow.\nIt's been a while.\012You see, I have my\nfavorite machine…\012It pays out a lot,\nI kid you not!\012Huh? Nuh-uh, it's\nmy secret!\012You have to find\nit yourself!\012Catch you later!",
  ["28:5d5f"] = "Hey, {PLAYER}. You\nuse your POKéGEAR\012to listen to the\nradio, right?\012I heard that you\ncan even display\012town maps with\nPOKéGEAR.\012I have a bad sense\nof direction, so\012POKéGEAR would be\nhandy…\012Anyway, thanks for\ncalling! Later!",
  ["28:5e2f"] = "Is it sunny\noutside today?\012When you're cooped\nup in the RADIO\012TOWER as much as I\nam, you lose touch\012with the outside.\nIt can be boring.\012Please call again!",
  ["29:4000"] = "By the way, I'm a\nHIKER, so I often\012go to mountains\nand caves.\012I occasionally see\nrare POKéMON.\012I could call you\nthe next time I\011see one.\012Feel like swapping\nphone numbers?",
  ["29:40a9"] = "I could call you\nwhen I see some\011rare POKéMON.\012Feel like swapping\nphone numbers?",
  ["29:40f8"] = "Be patient. I'll\nfind some rare\011POKéMON for you!",
  ["29:4126"] = "You're cold. I may\nas well head to\011the mountains…",
  ["29:4158"] = "Your phone's full.\012It can't register\nmy phone number.",
  ["29:418d"] = "All righty, then!\012My POKéMON and I\nare raring to go!",
  ["29:41c0"] = "From here, I can\nsee GOLDENROD's\012DEPT.STORE. They\nhave bargain sales\012up on the rooftop\nevery so often.\012Could I get your\nphone number?\012I'll call you when\nthey have a sale.",
  ["29:426a"] = "If you give me\nyour number, I'll\012call you when they\nhave a sale.",
  ["29:42ab"] = "I check GOLDENROD\nDEPT.STORE every\012day, so I know\nwhen there's a\011sale.",
  ["29:42f2"] = "Anyway…\012If you're short on\nmoney, take down\011my number.\012I'll call you when\nthere's a sale.",
  ["29:434a"] = "Your phone doesn't\nhave enough memory\011for more numbers.",
  ["29:4382"] = "I waited for you!\nI even cut back my\012shopping to raise\nmy POKéMON better!",
  ["29:4405"] = "Whenever I see a\nstrong trainer, I\012want to be their\ncheerleader.\012When I'm on my\nwalk, I sometimes\011pick up items.\012If I get anything,\nyou can have it!\012Want to give me\nyour number?\012I'll call as soon\nas I get anything.",
  ["29:44db"] = "If I find an item,\nyou can have it!\012Want to give me\nyour number?",
  ["29:451d"] = "I'll call as soon\nas I get anything!",
  ["29:4542"] = "Is that so? Well,\nI'll still be\011rooting for you!",
  ["29:4573"] = "But your phone is\nall filled up!",
  ["29:4595"] = "I've been waiting!\012I've gotten a bit\nbetter at this!",
  ["29:45c9"] = "So you're finally\nhere!\012I think this will\nmake you happy.",
  ["29:4603"] = "Your PACK looks\ncompletely full.\012I'll have to hold\non to this.",
  ["29:4642"] = "You're the best\nI've ever battled!\012Huh? You're the\none who saved all\011the SLOWPOKE?\012Well, no wonder I\ncouldn't beat you!\012Would it be OK to\nget your number?\012I don't want to\nmiss anything you\011do from now on!",
  ["29:470b"] = "You will tell me\nyour phone number?",
  ["29:4730"] = "Wow! Gee, thanks!\nNow I can call you\012anytime, whether\nanything's up or\012not. You know,\njust to chat!",
  ["29:4794"] = "Oh, but…\nI'm not dangerous!\012I just want to\ncall and chat\012about everything\nand nothing!",
  ["29:47eb"] = "Your phone list is\nalready full…\012You must be really\npopular…",
  ["29:4829"] = "Do you get the\nfeeling that there\012are more rare\nPOKéMON around?\012I'm positive there\nare, so I look all\011the time.\012If I find one, I\nwant to share the\012good news with\neveryone I know.\012I know! Give me\nyour phone number.",
  ["29:48fc"] = "I want to let\npeople know if I\011see rare POKéMON.\012Please give me\nyour phone number!",
  ["29:494d"] = "If I spot any\nawesome POKéMON,\012I'll be sure to\ngive you a call!",
  ["29:498a"] = "Aww! I want to\ntell someone about\011my discoveries!",
  ["29:49bd"] = "There's no space\nfor my number.\012If you make room,\nregister me!",
  ["29:49fc"] = "It's my turn to\nwin now!\012I've turned over a\nnew leaf!",
  ["29:4a31"] = "Reading textbooks\nis worthwhile\011every so often.\012When I'm reading\nand walking, I\011have to look down.\012So I notice items\non the ground.\012Next time I find\nsomething, I'll\011give it to you.\012May I have your\nphone number?",
  ["29:4b03"] = "If I find some-\nthing, it's yours.\012So may I have your\nphone number?",
  ["29:4b47"] = "I'll call you as\nsoon as I find\012something. You can\ncount on it!",
  ["29:4b87"] = "Oh… I thought it\nwould be a good\012break to call you\nwhen I'm studying…",
  ["29:4bcd"] = "There's no room\nfor my number.",
  ["29:4bec"] = "I waited around\nfor you!\012I'm thoroughly\nprepared today!",
  ["29:4c24"] = "This, this! This\nis yours! Ta-da!",
  ["29:4c47"] = "Whoops!\012You can't carry\nany more items!\012I'll hold it until\nnext time.",
  ["29:4c8c"] = "You're really good\nat POKéMON!\012Boys give me items\nafter battles, but\012sometimes they\ngive me too much.\012Next time, I can\nshare some if you\012want. Let me get\nyour phone number.",
  ["29:4d36"] = "I'll share my\ngifts with you.\012Let me get your\nphone number.",
  ["29:4d72"] = "Next time a boy\ngives me something\012after a battle,\nI'll share some!\012Does that make me\nbad?",
  ["29:4dcd"] = "Aww, you don't\nwant anything?\012But it's all for\nfree…",
  ["29:4e01"] = "But your phone's\nout of memory!",
  ["29:4e21"] = "You're really\nlate!\012I'm eager to get\ngoing!",
  ["29:4e4c"] = "Hi! Are you here\nfor your gift?\012This should really\nmake your day!",
  ["29:4e8f"] = "Where are you\ngoing to put this?\012I'll keep it, so\ncome get it later!",
  ["29:4ed4"] = "Huh? Is that thing\na POKéDEX? Have\011you met PROF.OAK?\012Huh? You have? \nThat's way cool!\012I have a dream of\nbecoming a POKéMON\012researcher like\nPROF.OAK.\012May I please have\nyour phone number?\012We should chat\nabout PROF.OAK.\012I'm sure it will\nbe loads of fun!",
  ["29:4fc8"] = "May I please have\nyour phone number?\012We should chat\nabout PROF.OAK.\012I'm sure it will\nbe loads of fun!",
  ["29:502e"] = "You must listen to\nPROF.OAK'S POKéMON\011TALK, right?",
  ["29:505f"] = "Oh… I wish I had a\nchance to meet\011PROF.OAK…",
  ["29:508c"] = "Your phone list is\ncompletely full!",
  ["29:50b1"] = "I've been waiting!\nLet's battle now!",
  ["29:50d5"] = "Oh, wow! PIKACHU!\nIt's so soft and\011furry! How cute!\012Let's be friends!\nPIKACHU-lovers are\011never bad people!\012Let's chat about\nPIKACHU!\012Can I get your\nphone number?",
  ["29:5175"] = "Let's chat about\nPIKACHU!\012Can I get your\nphone number?",
  ["29:51ac"] = "PIKACHU is the\none! If anything\012comes up, I'll\ngive you a jingle.",
  ["29:51ee"] = "You…\012I bet you don't\neven like PIKACHU…",
  ["29:5216"] = "Wait a sec! Your\nphone list's full!",
  ["29:523a"] = "I've been looking\nfor you! Here, see\011this? This is it!\012I'm certain your\nPIKACHU will love\011my gift too!",
  ["29:52a0"] = "Uh-oh, too bad.\nYou don't have any\012room. Be sure to\nget it later.",
  ["29:52e2"] = "Hey, you're trying\nto be the ultimate\012trainer too? Then\nwe're comrades!\012If I find any more\nitems by the\012water, I'll give\nyou some.\012Just give me your\nphone number.",
  ["29:5383"] = "If I find any more\nitems by the\012water, I'll give\nyou some.\012Just give me your\nphone number.",
  ["29:53de"] = "You'll be hearing\nfrom me if I find\011something good.",
  ["29:5412"] = "Is that so? Then\nI'll just have to\011use them myself.",
  ["29:5446"] = "Your phone list is\nall filled up.\012Come back if you\nmake room for me.",
  ["29:548c"] = "I've been doing\nmore than just\012fishing since we\nlast met.\012You're in for a\nbig surprise!",
  ["29:54e3"] = "Hey, there you\nare!\012Here's a gift, as\npromised!",
  ["29:5513"] = "Your PACK's full?\012Come back later--\nthat'll do it.",
  ["29:5545"] = "By the way, you're\na POKéMANIAC…\012I can tell.\nYes, you are.\012But your knowledge\nis shallow still!\012Do you know BILL?\nHe's an incredible\012POKéMANIAC.\nI revere him.\012I'll teach you all\nI know about BILL,\012so leave me your\nphone number.",
  ["29:5621"] = "I'll teach you all\nI know about BILL,\012so leave me your\nphone number.",
  ["29:5666"] = "BILL--he's more\nthan amazing!\012To be a POKéMANIAC\nlike him someday…\012That's my dream.",
  ["29:56b6"] = "You're going to\nregret it…\012And I won't care…",
  ["29:56e2"] = "Huh? Your phone\nlist's full.\012A POKéMANIAC has\nto be more tidy!",
  ["29:571e"] = "I've been waiting.\012Look, check out my\nPOKéMON!",
  ["29:574a"] = "Hi! You like\nCLEFAIRY too?\012They're so very\ncute, aren't they?\012I think we can be\ngood friends!\012I want to know\nyour phone number!\012Let's talk about\nCLEFAIRY!",
  ["29:57e3"] = "I want to know\nyour phone number!\012Let's talk about\nCLEFAIRY!",
  ["29:5820"] = "Isn't my CLEFAIRY\nsuper-adorable?",
  ["29:5842"] = "Aww… Oh well.\nLook for me if you\012want to talk about\nCLEFAIRY.",
  ["29:5881"] = "Oh? Your phone\nregistry is full.",
  ["29:58a3"] = "There you are!\012CLEFAIRY, I want\nyou to try hard!",
  ["29:58d5"] = "You took a long\ntime. See this?\012Isn't it cute?\nIt's a PINK BOW.",
  ["29:5914"] = "Uh-oh. Your PACK\nis crammed full.",
  ["29:5937"] = "You know, you are\nreally strong.\012But I don't want\nto just slink off…\012I know! Could I\nget your number?\012Let's meet up for\nmore battles!",
  ["29:59bc"] = "I want to battle\ntough trainers as\011often as I can!\012Could I get your\nnumber?\012Let's meet up for\nmore battles!",
  ["29:5a28"] = "Don't forget to\ncome see me when I\011challenge you!",
  ["29:5a5a"] = "A bird-user friend\nisn't a bad thing\011to have, I think…\012Won't you\nreconsider?",
  ["29:5aa6"] = "Your phone's out\nof memory. Delete\011a number for me!",
  ["29:5ada"] = "Am I happy to see\nyou! I won't lose!",
  ["29:5aff"] = "Oh, too bad. You\ndon't have room.\012I'll give it to\nyou next time!",
  ["29:5b3f"] = "You are really,\nreally strong!\012Thanks for taking\nme on so often--I\012learned a whole\nlot from you.\012I know! This will\ndo as my thanks!",
  ["29:5bc4"] = "Eh, our battle was\nfun, I'd say…\012When I'm fishing,\nI sometimes snag\012items that people\nhave dropped.\012Do you want them?\nWhat's the number?",
  ["29:5c4b"] = "If I snag an item\nwhile I'm fishing,\012it's yours. What's\nyour number?",
  ["29:5c8e"] = "If I snag anything\ngood, I'll be sure\011to let you know.",
  ["29:5cc5"] = "All right… Come\nback if you have a\011change of heart.",
  ["29:5cfa"] = "You can't register\nanother number.",
  ["29:5d1d"] = "Argh! You startled\nPOLIWAG into\011fleeing again!",
  ["29:5d4d"] = "So here you are.\012See this?\nI snagged it just\012a little while\nago. It's yours.",
  ["29:5d9a"] = "Your PACK's full?\012I'll give it to\nyou later.",
  ["29:5dc6"] = "Our battle was\nremarkable!\012I wish for some-\nthing to remember\011you by!\012Perhaps your phone\nnumber will do?\012My training makes\nit impossible to\011chat much, but…",
  ["29:5e63"] = "My training makes\nchatting tough,\012but will you take\ndown my number?",
  ["29:5ea8"] = "I must train\nharder to become\011the mightiest!",
  ["29:5ed6"] = "If you decide you\nwant my number,\011come see me.",
  ["29:5f06"] = "Your phone appears\nto be full.\012Come back later!",
  ["29:5f37"] = "I wish to thank\nyou, {PLAYER}!\012I've been training\nall alone…\012I was happy that\nyou cared to call…\012I want you to have\nthis!",
  ["29:5faa"] = "Your strength will\nnot let you carry\012another thing!\nI will hold this\012till you lighten\nyour PACK!",
  ["29:600c"] = "Sheesh, the way\nyou attacked! That\012was something! We\nshould meet again!\012How about giving\nme your number?",
  ["29:6076"] = "So you want to\nregister my phone\012number for a re-\nmatch, huh?",
  ["29:60b5"] = "I'll call you\nwhenever I feel\011like battling!",
  ["29:60e2"] = "No? That's fine.\012A definite no is\neasy to take!\012I'll be right here\nwhen you're ready\011for a rematch.",
  ["29:6144"] = "Oh? There's no\nroom to register\011my phone number.",
  ["29:6175"] = "Hey, here comes\nthe kid! Let's go!\012Ready for my usual\nno-brainer, all-\011out offense?",
  ["29:61c9"] = "Your PACK looks\nstuffed full!\012You can't have\nthis now.",
  ["29:6200"] = "Well, you're\nspecial all right.\012If only I'd begun\nPOKéMON when I was\011a tad younger…\012I want you to work\nand succeed for\012the both of us.\nSo take this, OK?",
  ["29:6295"] = "It really made me\nangry to lose.\012I'll have to train\nmuch harder…\012Here's my number.\nI'm ERIN--don't\012forget! Want to\nbattle me again?",
  ["29:6316"] = "I want to battle\nwith you again.\012Do you want to\nexchange numbers?",
  ["29:6359"] = "I'll remember to\ncall when I want\011to battle again!",
  ["29:638c"] = "Oh… I'm sad…\nIf you do want to\012battle, come see\nERIN--that's me!",
  ["29:63cc"] = "Oh no. Your phone\nis all filled up.",
  ["29:63f1"] = "Yay! I waited!\nLet's start now!",
  ["29:6411"] = "That's too bad!\nYou have no room…\012I'll give it to\nyou another time.",
  ["29:6454"] = "Aww… I lost again!\012I wonder how many\ntimes that is…\012Thanks for coming!\nHere's a present!",
  ["5d:4000"] = "Hi, {PLAYER}!\nOur BICYCLE sales\012have gone through\nthe roof!\012We owe it all to\nyour advertising\012by riding around\non our BICYCLE.\012As our way of say-\ning thanks, please\012keep that BICYCLE.\nThanks again!",
  ["5d:40c0"] = "My {STRBUF}'s\nintelligence keeps\012rising. It might\nbe smarter than\011yours!",
  ["5d:4106"] = "The other day, I\neasily defeated a\011{STRBUF}.\012I think swapping\ntips with you is\011starting to help.",
  ["5d:4165"] = "Oh, and listen.\nI missed catching\012a {STRBUF} by\njust a tiny bit.\012If I'd been a bit\nmore informed, I'm\012sure I would've\ncaught it…",
  ["5d:41e1"] = "Do you want to\nbattle? I'll show\012you how to battle\nlogically.\012I'll be in\n{STRBUF}.\012Give me a shout if\nyou're nearby.",
  ["5d:4251"] = "See you later!",
  ["5d:4261"] = "Did you know?\012When it's raining,\nTHUNDER is sure to\011strike.",
  ["5d:429d"] = "Did you know…?\012If you use DEFENSE\nCURL, ROLLOUT's\012power goes way up\npast normal.",
  ["5d:42ee"] = "Did you know…?\012If the sunlight is\nharsh, SOLARBEAM\012doesn't need to be\ncharged up.",
  ["5d:4340"] = "Did you know…?\012If the opponent\nuses MINIMIZE,\012your STOMP becomes\nmore powerful.",
  ["5d:4391"] = "Did you know…?\012If your opponent\nis FLYing, your\012GUST becomes much\nmore powerful.",
  ["5d:43e3"] = "Did you know…?\012If your opponent\nis FLYing, your\012TWISTER becomes\nmore powerful.",
  ["5d:4433"] = "Did you know…?\012If your opponent\nuses DIG, your\012EARTHQUAKE becomes\nmore powerful.",
  ["5d:4485"] = "Did you know…?\012If your opponent\nuses DIG, your\012MAGNITUDE becomes\nmore powerful.",
  ["5d:44d6"] = "Did you know…?\012The rock, ground\nand steel types\012can't be hurt by\nSANDSTORM.",
  ["5d:4522"] = "Did you know…?\012If the sunlight is\nharsh, water-type\012moves become much\nweaker.",
  ["5d:4571"] = "Did you know…?\012When it's raining,\nfire-type moves\012become much weaker\nthan usual.",
  ["5d:45c2"] = "My friend heard\nsome great tips.\012He's going to let\nme in on some.\012When he tells me,\nI'll call right\011away and tell you.",
  ["5d:4638"] = "Hey, {PLAYER}!\012Do you remember\nyour promise?\012We have to battle\nsoon!\012I'll be at\n{STRBUF}.",
  ["5d:4688"] = "I fancied up my\n{STRBUF} and\012made it even cuter\nthan before!",
  ["5d:46c3"] = "I happened to come\nacross a wild\011SNUBBULL recently.\012My SNUBBULL, I\nassure you, was\012far cuter than the\nwild one.",
  ["5d:4734"] = "I happened to see\na wild MARILL the\012other day.\nOr so I thought.\012A closer look\nshowed it was\012{STRBUF}. I was\nquite miffed.",
  ["5d:47ac"] = "You can expect a\ncall from me.",
  ["5d:47cc"] = "My husband got\nsome NUGGETS.\012If you'd like, you\ncould have one as\012thanks for helping\nme out.\012I'll be at\n{STRBUF}.\012Please come see me\nwhen you can.",
  ["5d:485b"] = "Are your POKéMON\nin prime form?\012Let's chat about\nPOKéMON again.",
  ["5d:4895"] = "Pardon?\nOh, the NUGGET?\012There's no need to\nhurry. Come see me\012in {STRBUF}\nwhen you can.",
  ["5d:48ea"] = "Hey, I challenge\nyou to a battle!\012It won't be like\nlast time!\012{STRBUF}'s\nwhere I'm waiting\012for you. Hustle\nover here pronto!",
  ["5d:4962"] = "See ya!",
  ["5d:496b"] = "We have to battle\nagain sometime.\012You can bet I'm\ngoing to keep\012challenging you\ntill I win.",
  ["5d:49c7"] = "Hey, you'd better\nnot have forgotten\011about our battle!\012{STRBUF}!\012Hustle over quick!\nI'm waiting!",
  ["5d:4a24"] = "My {STRBUF}\nmight be greater\011than I imagined.\012I doubt I'll see a\n{STRBUF} that's\011better than mine.",
  ["5d:4a80"] = "Oh, and I managed\nto barely defeat\012{STRBUF} the\nother day.\012I've never seen a\n{STRBUF} get\011that strong…\012You shouldn't let\nyour guard down,\012even against a\nPOKéMON you're\011used to seeing.",
  ["5d:4b2d"] = "And a while back,\nI tried to catch a\011wild {STRBUF}.\012But it managed to\nelude me.\012One wrong decision\ncould mean total\012failure… You ought\nto be careful too.",
  ["5d:4bc5"] = "Let's battle!\012I'll be waiting on\n{STRBUF}.\012Give me a shout\nwhen you're close.",
  ["5d:4c0e"] = "OK, I'll talk to\nyou soon!",
  ["5d:4c29"] = "I obsess over how\nto beat you.",
  ["5d:4c49"] = "{PLAYER}, why\naren't you here?\012I'll take you down\nwith {STRBUF}!",
  ["5d:4c7f"] = "Do you remember my\nsweet {STRBUF}?\012{STRBUF} runs\nvery fast.\012It's exhilarating\nto ride on its\012back when it\nreally gets going.",
  ["5d:4cf6"] = "Oh, have you ever\nseen a {STRBUF}\011before?\012I just battled\none…\012It was much faster\nthan I expected.\012I was a little\nshocked.\012I still won, of\ncourse.",
  ["5d:4d86"] = "Oh, I just saw a\nwild {STRBUF}.\012I was trying to\ncatch it when I\012noticed that I was\nall out of POKé\011BALLS.\012If you don't check\nyour items, you\012may run out at the\nworst time.\012I hope you learn\nfrom my mistake.",
  ["5d:4e4e"] = "Do you want to\nbattle? I'm going\011to win this time!\012I'll be waiting\nfor you around\012{STRBUF}.\nLook for me, OK?",
  ["5d:4eb7"] = "OK, bye-bye!",
  ["5d:4ec5"] = "Let's battle again\nsometime!",
  ["5d:4ee2"] = "Um… {PLAYER}?\nWhat's wrong?\012Did you forget our\ndeal?\012{STRBUF}.\012That's where I'm\nwaiting.",
  ["5d:4f2f"] = "Hey listen, my\n{STRBUF}'s stick\012has this really\ndelicious aroma.\012That aroma gets my\nappetite going!",
  ["5d:4f90"] = "A while ago, my\nFARFETCH'D KO'd\011this {STRBUF}.\012You should have\nseen FARFETCH'D\012wield that stick.\nAmazing stuff!",
  ["5d:4ffd"] = "I ran into a wild\n{STRBUF}…\012I was trying to\ncatch it, but it\012took off faster\nthan I thought it\012would. It was a\nbit disappointing.",
  ["5d:507d"] = "Want to battle\nagain?\012For some reason,\nmy FARFETCH'D is\012all worked up and\nraring to go.\012{STRBUF}'s\nwhere I'm at.\012Keep an eye out\nfor me, OK?",
  ["5d:5106"] = "Be seeing you!",
  ["5d:5116"] = "My FARFETCH'D had\nsomething pretty\011in its beak.\012Like I promised,\nyou can have it.\012Catch up to me on\n{STRBUF},\012and I'll let you\nhave it.",
  ["5d:519b"] = "I haven't gotten\nwhat I promised\011you yet.\012I'll call you as\nsoon as I get it,\012so could you wait\na little longer?",
  ["5d:520a"] = "{PLAYER}, could you\nhurry over?\012FARFETCH'D is\nagitated.\012If you don't come\nsoon, it might\012smack me with its\nstick!\012{STRBUF}!\012Please come as\nsoon as you can!",
  ["5d:52f5"] = "Listen, dear…\012Do you recall my\n{STRBUF}?\012Yes, exactly. That\nlovely {STRBUF}.\012Wouldn't you agree\nit's a perfect\011match for me?",
  ["5d:536b"] = "Have I ever faced\na wild {STRBUF}?\012You need to ask?\012{STRBUF} I've\nbeaten on numerous\011occasions!",
  ["5d:53c5"] = "Have I ever failed\nto catch a wild\011POKéMON?\012You need to ask?\012I would never fail\nto catch a wild\012{STRBUF}…\nOh! Never mind!",
  ["5d:543a"] = "We are going to\nbattle!\012The place shall be\n{STRBUF}!\012Don't make me\nwait! Got it?",
  ["5d:5488"] = "Fine, you may go.",
  ["5d:549b"] = "Don't be too proud\njust because you\012happened to beat\nme… \012It was a fluke!",
  ["5d:54e5"] = "What are you\ndoing?\012I told you that\nthe place was\012{STRBUF}!\nDon't try to run!",
  ["5d:5530"] = "My {STRBUF}'s\nlooking sharper\011than before!\012I doubt there's a\nPOKéMON as cool as\012this guy in your\nparty!",
  ["5d:5591"] = "Oh yeah, I took\ndown a {STRBUF}\012in the wild the\nother day.\012It was a cakewalk.\nWell, I guess it\012can't be helped,\nus being so tough.",
  ["5d:5611"] = "Oh yeah, I saw a\nwild {STRBUF}!\012I thought about\ngoing for it, but\012I decided to work\nwith my one-and-\012only right to the\nextreme end.",
  ["5d:5693"] = "Let's get together\nand battle!\012I promise things\nwill be different!\012{STRBUF}'s\nwhere I'll be.\012Give me a shout\nwhen you come.",
  ["5d:570a"] = "All right. Later!",
  ["5d:571d"] = "I'm checking out\n{STRBUF}'s moves\012and devising some\nstrategies.\012When I come up\nwith a good one,\011let's battle!",
  ["5d:5786"] = "What's keeping\nyou, {PLAYER}!\012Let's get down and\nbattle already!\012I'm waiting on\n{STRBUF}!",
  ["5d:57d4"] = "Are your POKéMON\ngrowing?\012My POKéMON are\ngrowing a bit too\012quickly for me.\nIt's overwhelming!\012{STRBUF}'s grow-\ning especially\012quickly. I think\nit'll get tough.",
  ["5d:5869"] = "Oh yeah, we KO'd a\nwild {STRBUF}\012with one hit a\nwhile back.\012It went down so\neasily, I felt a\012little sorry for\nthe poor thing.",
  ["5d:58e4"] = "Oh yeah, a wild\n{STRBUF} got\012away from me at\nthe last second.\012I know it's a\ncommon POKéMON…\012But it does annoy\nme that it got\012away when I almost\nhad it.",
  ["5d:5976"] = "Do you feel like a\nPOKéMON battle?\012It won't be like\nlast time!\012{STRBUF}'s\nwhere I'll be.\012Let me know when\nyou get there.",
  ["5d:59e7"] = "See you later!",
  ["5d:59f7"] = "The Bug-Catching\nContest is at the\012NATIONAL PARK\ntoday.\012Are you going,\n{PLAYER}?\012I'm trying to make\nup my mind.",
  ["5d:5a60"] = "I found all kinds\nof BERRIES. If you\012want, I'll share\nsome with you.\012I'll be waiting on\n{STRBUF}.",
  ["5d:5abe"] = "Huh? BERRIES?\012Sorry, I haven't\nfound any yet.\012I'll call you if I\nfind any. Will you\011please wait?",
  ["5d:5b1e"] = "Let's battle\nalready!\012{STRBUF} is\nwhere I am.\012Please get here as\nsoon as you can!",
  ["5d:5b6d"] = "How come you're\nnot here yet?\012{STRBUF} is\nwhere I am.\012Please get here as\nsoon as you can!",
  ["5d:5bc4"] = "I've been spending\nmore time with my\012{STRBUF} than I\nhave with my kids.\012That's a bit sad,\nactually.",
  ["5d:5c24"] = "I just beat a wild\n{STRBUF}.\012I told my kid, but\nhe scoffed that he\012could do the same\nthing easily.\012Boy, has he gotten\ncocky…",
  ["5d:5c9f"] = "Yesterday a wild\n{STRBUF} slipped\012away from me, in\nfront of my kid.\012I was feeling down\nabout it until he\012shared his POKé\nBALLS with me.\012Hahah, that sure\nmade my day!",
  ["5d:5d40"] = "What do you say to\na battle with me?\012Good, you're going\nto do it!\012For a kid, you're\nquite agreeable.\012{STRBUF} is\nthe spot!",
  ["5d:5db7"] = "You call your mom\nsometimes too!",
  ["5d:5dd9"] = "Listen, I… Yowch!\012Uh, sorry! See,\n{STRBUF} are\012biting like there\nis no tomorrow\012over here on\n{STRBUF}!\012Aiyee! Ouch!\nOne jabbed me!\012Heh, they're some\nkind of feisty!\012{PLAYER}, you have\nto see this rare\012sight! Get ready\nto fish!",
  ["5d:5eaf"] = "Yeah, I know.\012You're looking for\nrare POKéMON.\012Recently, all I've\nbeen catching are\011MAGIKARP, though…",
  ["5d:5f11"] = "So where are you?\nI'm waiting for\012you to show up on\n{STRBUF}.\012You shouldn't make\nyour elders wait!",
  ["5d:5f70"] = "Hey, what's the\nmatter with you?\012Aren't you coming\nover to fish for\011QWILFISH?\012I'm on ROUTE 32,\nso hurry up!",
  ["5d:5fda"] = "Oh, you have to\nhear this.\012My {STRBUF} is\nso adorable!\012It always wants to\nnuzzle me!",
  ["5d:602d"] = "And, and! Um…\012We beat a wild\n{STRBUF} with\012just one hit a\nlittle while ago.\012We felt sorry for\nit, though.",
  ["5d:6095"] = "And, and! Uh…\012We just saw a\nreally gorgeous\011{STRBUF}.\012But I was on the\nphone, so it got\012away. It made us\nreally angry!",
  ["5d:610a"] = "Hi! Do you have\nsome free time?\012I've got all sorts\nof time. If you're\012free, would you\nlike to battle?\012I'll be waiting on\n{STRBUF}.\012Let me know when\nyou get here!",
  ["5d:61a7"] = "Hi, TANIA. How are\nyou? This is LIZ.\012I'm fine, but I'm\nbored silly!\012Huh… Wrong number?\nOops! Sorry!",
  ["5d:620a"] = "OK, I'll call you\nlater!",
  ["5d:6223"] = "Listen, listen!\012I was listening to\nthe radio in the\012RUINS OF ALPH when\nan odd broadcast\012suddenly cut it on\nthe regular show.\012I wonder what it\nwas. So strange!",
  ["5d:62c3"] = "Listen, listen!\012Don't you think\nFALKNER of VIOLET\012GYM is cool and\nhandsome?\012But they say his\ndad, who's out\012training on the\nroad, is even more\012cool and handsome\nthan FALKNER.\012I wish I could\nmeet him!",
  ["5d:638a"] = "Listen, listen!\012Do you know EARL,\nthe teacher who\012runs the POKéMON\nACADEMY in VIOLET?\012I saw him doing\npirouettes while\012he was running. It\nwas wildly funny!",
  ["5d:6424"] = "Listen, listen!\012I collect POKéMON\nplush dolls.\012But I can't seem\nto get a hold of a\012SURF PIKACHU DOLL.\nNone of my friends\012have it. It must\nbe totally rare!\012You could really\nbrag about it if\011you had one.",
  ["5d:64eb"] = "Listen, listen!\012Do you know about\nMOOMOO MILK?\012You can buy it at\nMOOMOO FARM.\012It's supposed to\nbe good for health\012and beauty.\nI really want to\012try some. I bet\nit's delicious!",
  ["5d:6599"] = "Listen, listen!\012There's a POKéMON\nSALON in GOLDENROD\012that's run by two\nbrothers.\012The older brother\nis good, but the\012younger one really\nisn't.\012But sometimes the\nyounger one does a\012better job than\nhis brother.\012Every time I go, I\nhave a hard time\012trying to decide\nwhom I should use…",
  ["5d:66ac"] = "Listen, listen!\012GOLDENROD GYM's\nWHITNEY began\012battling only a\nlittle while ago!\012But the POKéMON\nLEAGUE chose her\011as a GYM LEADER!\012I bet she must be\ntotally talented.",
  ["5d:674f"] = "Listen, listen!\012Have you ever\ntaken part in a\012Bug-Catching\nContest at the\011NATIONAL PARK?\012I did once, but\nall I could catch\011was a CATERPIE.\012But guess what!\012I won with that\nCATERPIE. Isn't\011that great?",
  ["5d:6816"] = "Listen, listen!\012I saw a beautiful\n{STRBUF}!\012I wish I could\nbecome a beautiful\011{STRBUF} too.",
  ["5d:686d"] = "Listen, listen!\012Uh… Um… Whoops!\012I forgot what I\nwas going to say!",
  ["5d:68b0"] = "Listen, listen!\012My {STRBUF}…\nit… so pretty…\012and… giggle… so\nawesome… yes… but…\012very much… eeek!\nAnd… lovely…\012Just ravishing…\nOh, too much!\012…Hug it… sleeping…\nThat's right…\012pretty… sigh… So\nnice… Cute…\012…Oops! Look at the\ntime! I chatted\011too long!\012I'm sorry I took\nso much of your\012time!\nI love chatting!",
  ["5d:69da"] = "I've got too much\ntime on my hands!\012Let's battle right\naway!\012I'll be waiting on\n{STRBUF}!",
  ["5d:6a2f"] = "The other day, I\nwas watching my\012{STRBUF} eat\nsome BERRIES.\012It looked like it\nwas enjoying its\012meal, so I decided\nto try some.\012I'm not sure if\npeople should eat\012that stuff, but it\nwas delicious!",
  ["5d:6aef"] = "Lately, I've been\nrunning across\012wild {STRBUF}\nquite often.\012They're easily\ntaken care of.",
  ["5d:6b45"] = "Oh yeah, I was\nbattling this\012{STRBUF} the\nother day…\012It took off when I\ngot distracted by\011a passing BEAUTY.\012Learn from my\nmistake--always\012stay focused on\nthe job at hand!",
  ["5d:6bee"] = "Come on--let's\nbattle right now!\012{STRBUF} is\nwhere I am.\012Come on down if\nyou feel up to it!",
  ["5d:6c47"] = "All right then!\nBe good!",
  ["5d:6c61"] = "{PLAYER}! It's\nmind-blowing!\012I took a hike in\n{STRBUF}\011yesterday, see?\012Well, there were\ntons of {STRBUF}\012around! You have\nto see it!\012I get this feeling\nthat {STRBUF}\012may be timid.\nI didn't see any\012where there are\nstrong POKéMON.",
  ["5d:6d32"] = "Rare POKéMON?\012Hey, sorry! I was\ntoo focused on my\012hike, so I wasn't\npaying attention.",
  ["5d:6d85"] = "Hello! You haven't\nforgotten about\012our battle, have\nyou?\012{STRBUF}!\nI'm waiting!",
  ["5d:6dd1"] = "Hello? What? Where\nis DUNSPARCE?\012DARK CAVE! Hurry!\012I know I've said\nit before, but\012DUNSPARCE don't\nappear when there\012are strong POKéMON\naround.",
  ["5d:6e5d"] = "My {STRBUF} is\nlooking more and\012more like me. It's\ngetting cuter!",
  ["5d:6e9c"] = "And, you know?\012Now we can KO\n{STRBUF} easily.\012I should challenge\nthe GOLDENROD GYM.",
  ["5d:6eee"] = "And, you know?\nWe just failed to\012beat {STRBUF} by\na tiny margin.\012I'm guessing my\nPOKéMON's levels\012aren't high enough\nyet…",
  ["5d:6f60"] = "You must be a lot\nbetter now, huh?\012How about showing\nme your technique\012in a real battle\nwith me?\012I'll be waiting on\n{STRBUF}.",
  ["5d:6fdb"] = "See you later!",
  ["5d:6feb"] = "This is it--the\none we've all been\011waiting for!\012GOLDENROD DEPT.\nSTORE's bargain\011sale is on now!\012Want it cheap?\nWant it lots?\012Don't miss this\nGOLDENROD chance!\012Huh? I sound like\na huckster?\012Well, yeah. I was\nmimicking them…\012Anyway, you've got\nto get there as\011soon as you can!",
  ["5d:70fb"] = "I'm saving up for\nthe next bargain\012sale. When's the\nnext one?",
  ["5d:7138"] = "Where are you?\012Let's have our\nbattle soon!\012I'll be waiting on\n{STRBUF}.",
  ["5d:717c"] = "Haven't you gone\nto GOLDENROD DEPT.\012STORE? I've scoped\nit out already!\012They had some real\nbargains.\012You should get\nthere quickly.",
  ["5d:71fd"] = "My {STRBUF} and\nI are getting more\012in sync with each\nother.",
  ["5d:7237"] = "We battled a wild\n{STRBUF} and\012managed to drop it\nin a close match.\012We're getting into\nthe groove!",
  ["5d:7297"] = "But, you know?\012I still haven't\ncaught {STRBUF}.\012It's getting past\nfrustrating…",
  ["5d:72e2"] = "Would you be my\npractice partner\011again sometime?\012I'll be waiting on\n{STRBUF}.\012…Could you take it\na little easier on\011me next time?",
  ["5d:7361"] = "Bye! Let's chat\nagain!",
  ["5d:7378"] = "Have you heard\nabout TEAM ROCKET?\012They've taken over\nthe RADIO TOWER in\011GOLDENROD.\012Are the people\ninside safe?",
  ["5d:73e7"] = "I picked up some-\nthing nice today.\012I want you to have\nit, so I called!\012You will come for\nit, won't you?\012{STRBUF} is\nwhere I am.",
  ["5d:7465"] = "Sorry, I haven't\nfound anything\012useful yet…\nI promise, if I\012find anything, you\ncan have it!",
  ["5d:74c1"] = "Oh, {PLAYER}!\nHow soon can I\012expect to see you\nfor our battle?\012Don't forget,\n{STRBUF}!",
  ["5d:750e"] = "I'm getting really\nimpatient, waiting\012to give you my\npresent!\012Hurry over to\n{STRBUF}!",
  ["60:4178"] = "At the POKéMON\nLEAGUE, you'll get\012tested by the\nELITE FOUR.\012You have to beat\nthem all. If you\012lose, you have to\nstart all over!",
  ["60:41f5"] = "Hold it.\012You're going to\ntake the POKéMON\012LEAGUE challenge\nnow?\012That's not going\nto happen.\012My super-well-\ntrained POKéMON\012are going to pound\nyou.\012{PLAYER}!\nI challenge you!",
  ["60:4295"] = "…\012OK--I lost…",
  ["60:42a4"] = "…Darn… I still\ncan't win…\012I… I have to think\nmore about my\011POKéMON…\012Humph! Try not to\nlose!",
  ["60:42fd"] = "…\012Whew…\nWith my partners,\012I'm going to be\nthe CHAMPION!",
  ["60:4335"] = "Ah! You're chal-\nlenging the ELITE\012FOUR? Are you sure\nyou're ready?\012If you need to\ntrain some more,\012my ABRA can help\nyou.\012It can TELEPORT\nyou home.\012Would you like to\ngo home now?",
  ["60:43e7"] = "OK, OK. Picture\nyour house in your\011mind…",
  ["60:4411"] = "OK, OK. The best\nof luck to you!",
  ["60:4433"] = "ABRA: Aabra…",
  ["60:4531"] = "Welcome to POKéMON\nLEAGUE, {PLAYER}.\012Allow me to intro-\nduce myself. I am\011WILL.\012I have trained all\naround the world,\012making my psychic\nPOKéMON powerful.\012And, at last, I've\nbeen accepted into\011the ELITE FOUR.\012I can only keep\ngetting better!\012Losing is not an\noption!",
  ["60:462c"] = "I… I can't…\nbelieve it…",
  ["60:4644"] = "Even though I was\ndefeated, I won't\011change my course.\012I will continue\nbattling until I\012stand above all\ntrainers!\012Now, {PLAYER}, move\non and experience\012the true ferocity\nof the ELITE FOUR.",
  ["60:4793"] = "Fwahahahaha!\012I am KOGA of the\nELITE FOUR.\012I live in shadows,\na ninja!\012My intricate style\nwill confound and\011destroy you!\012Confusion, sleep,\npoison…\012Prepare to be the\nvictim of my sin-\011ister technique!\012Fwahahahaha!\012POKéMON is not\nmerely about brute\012force--you shall\nsee soon enough!",
  ["60:48a9"] = "Ah!\nYou have proven\011your worth!",
  ["60:48ca"] = "I subjected you to\neverything I could\011muster.\012But my efforts\nfailed. I must\011hone my skills.\012Go on to the next\nroom, and put your\011abilities to test!",
  ["60:49fe"] = "I am BRUNO of the\nELITE FOUR.\012I always train to\nthe extreme be-\011cause I believe in\011our potential.\012That is how we\nbecame strong.\012Can you withstand\nour power?\012Hm? I see no fear\nin you. You look\012determined. Per-\nfect for battle!\012Ready, {PLAYER}?\nYou will bow down\012to our overwhelm-\ning power!\012Hoo hah!",
  ["60:4b23"] = "Why? How could we\nlose?",
  ["60:4b3c"] = "Having lost, I\nhave no right to\011say anything…\012Go face your next\nchallenge!",
  ["60:4c27"] = "I am KAREN of the\nELITE FOUR.\012You're {PLAYER}?\nHow amusing.\012I love dark-type\nPOKéMON.\012I find their wild,\ntough image to be\012so appealing. And\nthey're so strong.\012Think you can take\nthem? Just try to\011entertain me.\012Let's go.",
  ["60:4cf8"] = "Well, aren't you\ngood. I like that\011in a trainer.",
  ["60:4d29"] = "Strong POKéMON.\012Weak POKéMON.\012That is only the\nselfish perception\011of people.\012Truly skilled\ntrainers should\012try to win with\ntheir favorites.\012I like your style.\nYou understand\011what's important.\012Go on--the CHAM-\nPION is waiting.",
  ["60:4f67"] = "LANCE: I've been\nwaiting for you.\012{PLAYER}!\012I knew that you,\nwith your skills,\012would eventually\nreach me here.\012There's no need\nfor words now.\012We will battle to\ndetermine who is\012the stronger of\nthe two of us.\012As the most power-\nful trainer and as\012the POKéMON LEAGUE\nCHAMPION…\012I, LANCE the drag-\non master, accept\011your challenge!",
  ["60:50a4"] = "…It's over.\012But it's an odd\nfeeling.\012I'm not angry that\nI lost. In fact, I\011feel happy.\012Happy that I\nwitnessed the rise\012of a great new\nCHAMPION!",
  ["60:5132"] = "…Whew.\012You have become\ntruly powerful,\011{PLAYER}.\012Your POKéMON have\nresponded to your\012strong and up-\nstanding nature.\012As a trainer, you\nwill continue to\012grow strong with\nyour POKéMON.",
  ["60:51dd"] = "MARY: Oh, no!\nIt's all over!\012PROF.OAK, if you\nweren't so slow…",
  ["60:521b"] = "PROF.OAK: Ah,\n{PLAYER}!\012It's been a long\nwhile.\012You certainly look\nmore impressive.\012Your conquest of\nthe LEAGUE is just\011fantastic!\012Your dedication,\ntrust and love for\012your POKéMON made\nthis happen.\012Your POKéMON were\noutstanding too.\012Because they be-\nlieved in you as a\012trainer, they per-\nsevered.\012Congratulations,\n{PLAYER}!",
  ["60:534b"] = "MARY: Let's inter-\nview the brand new\011CHAMPION!",
  ["60:537b"] = "LANCE: This is\ngetting to be a\011bit too noisy…\012{PLAYER}, could you\ncome with me?",
  ["60:53c5"] = "MARY: Oh, wait!\nWe haven't done\011the interview!",
  ["60:54a6"] = "LANCE: It's been a\nlong time since I\011last came here.\012This is where we\nhonor the LEAGUE\012CHAMPIONS for all\neternity.\012Their courageous\nPOKéMON are also\011inducted.\012Here today, we\nwitnessed the rise\012of a new LEAGUE\nCHAMPION--a\012trainer who feels\ncompassion for,\012and trust toward,\nall POKéMON.\012A trainer who\nsucceeded through\012perseverance and\ndetermination.\012The new LEAGUE\nCHAMPION who has\012all the makings\nof greatness!\012{PLAYER}, allow me\nto register you\012and your partners\nas CHAMPIONS!",
  ["61:40bc"] = "KANTO's POWER\nPLANT?\012It's near the end\nof ROUTE 9, the\012road that heads\neast from here.\012I think there was\nan accident of\011some sort there.",
  ["61:4144"] = "You're collecting\nevery single kind\011of POKéMON?\012That must be quite\na challenge, but\011it sounds fun too.",
  ["61:41a8"] = "The CAPE in the\nnorth is a good\012place for dates.\nGirls like it!",
  ["61:41e9"] = "SLOWBRO: Yarah?",
  ["61:41fa"] = "My SLOWBRO and I\nmake an awesome\011combination!",
  ["61:4229"] = "SLOWBRO, show me\nyour CONFUSION!",
  ["61:424e"] = "I'm a huge fan of\nCERULEAN GYM's\011MISTY.",
  ["61:4275"] = "I saw this shady\nguy go off toward\011CERULEAN's CAPE.",
  ["61:42a9"] = "There used to be a\ncave here that had\012horribly powerful\nPOKéMON in it.",
  ["61:42ee"] = "Ayuh?\012My ITEMFINDER is\nresponding…",
  ["61:4312"] = "CERULEAN CITY\012A Mysterious Blue\nAura Surrounds It",
  ["61:4345"] = "CERULEAN CITY\nPOKéMON GYM\011LEADER: MISTY\012The Tomboyish\nMermaid",
  ["61:4381"] = "There's a notice\nhere…\012The BIKE SHOP has\nmoved to GOLDENROD\011CITY in JOHTO…",
  ["61:43cc"] = "There's a notice\nhere…\012Stamp out thievery\nand make the city\012a friendlier, more\ncheerful place!\012CERULEAN POLICE",
  ["61:443b"] = "CERULEAN CAPE\nAHEAD",
  ["61:4450"] = "It's locked…",
  ["61:4523"] = "We stand guard in\nthis tower.\012Here, we express\nour gratitude to\011honor all POKéMON.",
  ["61:4574"] = "Th-Thank you!",
  ["61:4583"] = "All living beings\ncoexist through\011cooperation.\012We must always be\nthankful for this.",
  ["61:45d8"] = "Only if you reach\nthe top will you\011obtain an HM.",
  ["61:460a"] = "SPROUT TOWER was\nbuilt long ago\012as a place for\nPOKéMON training.",
  ["61:4649"] = "A BELLSPROUT over\n100 feet tall…\012People say that it\nbecame the center\011pillar here.",
  ["61:469d"] = "See the pillar\nshaking?\012People are train-\ning upstairs.",
  ["61:46d6"] = "A POKéMON statue…\012It looks very\ndistinguished.",
  ["61:47a9"] = "However hard we\nbattle, the TOWER\011will stand strong.",
  ["61:47df"] = "I fought hard but\nI'm too weak.",
  ["61:47ff"] = "The flexible pil-\nlar protects the\012TOWER, even from\nearthquakes.",
  ["61:4841"] = "…Sway like leaves\nin the wind…",
  ["61:4861"] = "Oh, I'm weak!",
  ["61:486f"] = "I tried to copy\nBELLSPROUT's\012gentle movements\nfor battle…\012But I didn't train\nwell enough.",
  ["61:48c8"] = "A POKéMON statue…\012It looks very\ndistinguished.",
  ["61:4a27"] = "ELDER: You are in-\ndeed skilled as a\011trainer.\012As promised, here\nis your HM.\012But let me say\nthis: You should\012treat your\nPOKéMON better.\012The way you battle\nis far too harsh.\012POKéMON are not\ntools of war…",
  ["61:4aec"] = "…\n…Humph!\012He claims to be\nthe ELDER but\011he's weak.\012It stands to\nreason.\012I'd never lose to\nfools who babble\012about being nice\nto POKéMON.\012I only care about\nstrong POKéMON\011that can win.\012I really couldn't\ncare less about\011weak POKéMON.",
  ["61:4bc8"] = "{RIVAL} used an\nESCAPE ROPE!",
  ["61:4be0"] = "So good of you to\ncome here!\012SPROUT TOWER is a\nplace of training.\012People and POKéMON\ntest their bonds\012to build a bright\nfuture together.\012I am the final\ntest.\012Allow me to check\nthe ties between\012your POKéMON and\nyou!",
  ["61:4cb2"] = "Ah, excellent!",
  ["61:4cc2"] = "You and your POKé-\nMON should have\012no problem using\nthis move.\012Take this FLASH\nHM.",
  ["61:4d13"] = "FLASH illuminates\neven the darkest\011of all places.\012But to use it out\nof battle, you\012need the BADGE\nfrom VIOLET's GYM.",
  ["61:4d88"] = "I hope you learn\nand grow from your\011journey.",
  ["61:4db6"] = "I train to find\nenlightenment in\011POKéMON!",
  ["61:4dde"] = "My training is\nincomplete…",
  ["61:4dfa"] = "As POKéMON grow\nstronger, so does\011the trainer.\012No, wait. As the\ntrainer grows\012stronger, so do\nthe POKéMON.",
  ["61:4e60"] = "Let me see how\nmuch you trust\011your POKéMON.",
  ["61:4e8a"] = "Yes, your trust is\nreal!",
  ["61:4ea4"] = "It is not far to\nthe ELDER.",
  ["61:4ec1"] = "The ELDER's HM\nlights even pitch-\011black darkness.",
  ["61:4ef3"] = "It is my head that\nis bright!",
  ["61:4f12"] = "Let there be light\non your journey.",
  ["61:4f37"] = "It's a powerful\npainting of a\011BELLSPROUT.",
  ["61:4f61"] = "A POKéMON statue…\012It looks very\ndistinguished.",
  ["61:5203"] = "EUSINE: Awesome!\nToo awesome, even!\012I've never seen a\nbattle that great.\012That was truly\ninspiring to see.\012SUICUNE was tough,\nbut you were even\012more incredible,\n{PLAYER}.\012I heard SUICUNE's\nmystic power\012summons a rainbow-\ncolored POKéMON.\012Maybe, just maybe,\nwhat went on today\012will cause that\nPOKéMON to appear.\012I'm going to study\nthe legends more.\012Thanks for showing\nme that fantastic\011battle.\012Later, {PLAYER}!",
  ["61:5386"] = "According to\nlegend…\012When the souls of\nPOKéMON and humans\012commune, from the\nheavens descends a\012POKéMON of rainbow\ncolors…\012Could it mean the\nlegendary POKéMON\012are testing us\nhumans?",
  ["61:5433"] = "When the BRASS\nTOWER burned down,\012three nameless\nPOKéMON were said\012to have perished.\nIt was tragic.\012However…\012A rainbow-colored\nPOKéMON…\012In other words…\012HO-OH descended\nfrom the sky and\012gave new life to\nthe three POKéMON.\012They are…\012SUICUNE, ENTEI and\nRAIKOU.\012That is what they\nsay.",
  ["61:5544"] = "The two TOWERS are\nsaid to have been\012built to foster\nfriendship and\012hope between POKé-\nMON and people.\012That was 700 years\nago, but the ideal\012still remains\nimportant today.",
  ["61:55ee"] = "HO-OH appears to\nhave descended\012upon this, the TIN\nTOWER!",
  ["61:5629"] = "This will protect\nyou. Take it.",
  ["61:564a"] = "Now, go.",
  ["61:5654"] = "I believe you are\nbeing tested.\012Free your mind\nfrom uncertainty,\011and advance.",
  ["61:56a3"] = "I knew it.\012I knew you'd get\nto see the POKéMON\012of rainbow colors,\n{PLAYER}.\012It happened just\nas I envisioned.\012My research isn't\nbad, I might say.\012I'm going to keep\nstudying POKéMON\012to become a famous\nPOKéMANIAC!",
  ["61:5765"] = "The legendary\nPOKéMON are said\012to embody three\npowers…\012The lightning that\nstruck the TOWER.\012The fire that\nburned the TOWER.\012And the rain that\nput out the fire…",
  ["61:5803"] = "When the legendary\nPOKéMON appeared…\012They struck terror\nin those who saw\011their rise.\012And…\012Some even took to\nfutile attacks.\012The legendary\nPOKéMON, knowing\012their own power,\nfled, ignoring the\011frightened people.",
  ["61:58d0"] = "Of the legendary\nPOKéMON, SUICUNE\012is said to be the\nclosest to HO-OH.\012I hear there may\nalso be a link to\012POKéMON known as\nUNOWN.\012The POKéMON UNOWN\nmust be sharing a\012cooperative bond\nwith SUICUNE.",
  ["61:5cd9"] = "…… …… ……\012…Oh, it's you.\012I came looking for\nsome legendary\012POKéMON that they\nsay roosts here.\012But there's\nnothing here!\012Nothing after all\nthe trouble of\012coming to this\ndump? No way!\012It's all your\nfault!",
  ["61:5d9b"] = "…Humph!\012This is why I hate\nbattling wimps.\012There's no\nchallenge in it.",
  ["61:5de2"] = "…Aw, whatever.\012You would never be\nable to catch a\012legendary POKéMON\nanyway.",
  ["61:5e2c"] = "…Humph!\012This is why I hate\nbattling wimps.\012It's just a waste\nof my time.",
  ["61:5e75"] = "Humph!\012What are you doing\nfalling into a\012hole? Some genius\nyou are!\012Serves you right!",
  ["61:5ecc"] = "EUSINE: My name's\nEUSINE.\012I'm on the trail\nof a POKéMON named\011SUICUNE.\012And you are…?\012{PLAYER}? Glad to\nmeet you!\012I heard rumors\nthat SUICUNE is in\012this BURNED TOWER,\nso I came to look.\012But where exactly\ncould it be?",
  ["61:5f99"] = "EUSINE: I heard\nthat SUICUNE is in\012this BURNED TOWER,\nso I came to look.\012But where exactly\ncould it be?",
  ["61:6002"] = "MORTY: ECRUTEAK's\nGYM LEADER has to\012study what are\nsaid to be the\012legendary POKéMON\n--SUICUNE, ENTEI\011and RAIKOU.\012EUSINE is here, so\nI've decided to\012investigate the\nTOWER with him.",
  ["61:626a"] = "EUSINE: I dug a\nhole here, too…\012I was shocked!\012SUICUNE raced by\nlike a blur, right\012in front of my\neyes!\012For ten years I\nchased SUICUNE,\012and I finally got\nto see it.\012I'm all choked up!\012{PLAYER}, I owe\nthis all to you!\012Thank you!\012I heard that the\nlegendary POKéMON\012of ECRUTEAK test\nchosen humans by\012allowing them to\nget close.\012I'm going to track\nSUICUNE.\012{PLAYER}, let's\nmeet again!\012Farewell!",
  ["62:4005"] = "Are you collecting\nKANTO GYM BADGES?",
  ["62:405a"] = "I heard that some\nshady character is\011skulking about.\012I won't stand for\nit if he turns out\011to be a thief.",
  ["62:40c3"] = "We were held up by\nrobbers before.",
  ["62:40e7"] = "DIGLETT: Dug dug.",
  ["62:414d"] = "My husband lives\nhappily with POKé-\011MON he got through\011trades.",
  ["62:418a"] = "Ah… I'm so happy…",
  ["62:419c"] = "KANGASKHAN: Garu\ngaruu.",
  ["62:41b5"] = "ZUBAT: Zuba zubaa.",
  ["62:4221"] = "For battles, I'd\nmuch rather use\012POKéMON I've been\nraising, even if\012they're weaker\nthan some newly\011caught POKéMON.",
  ["62:428c"] = "Do you battle by\nmobile phone?\012If time runs out\nduring a battle,\012waiting to see who\nwon is really\011nerve wracking.",
  ["62:42ff"] = "The MAGNET TRAIN\ntravels at over\012340 mph. It goes\nbetween KANTO and\012JOHTO in almost no\ntime at all.\012It really makes\nJOHTO accessible.",
  ["62:44fb"] = "Oops! I so sorry!\nYou not hurt,\011okay?\012I very busy.\nNo time for talk-\011ing with you. Not\011good for me if\011seen by somebody.",
  ["62:4574"] = "Oh no! You seen\nme already! I make\011big mistake!",
  ["62:45a5"] = "Hey, you! Forget\nyou see me, okay?\012You see, hear,\nknow nothing,\012okay?\nBye, kid! Nothing!\012Bye-bye a go-go!",
  ["62:4610"] = "Sorry, I'll be out\nfor a while.\011MISTY, GYM LEADER",
  ["62:4642"] = "Since MISTY's out,\nwe'll be away too.\011GYM TRAINERS",
  ["62:4674"] = "MISTY: I was ex-\npecting you, you\011pest!\012You may have a\nlot of JOHTO GYM\012BADGES, but you'd\nbetter not take me\011too lightly.\012My water-type\nPOKéMON are tough!",
  ["62:470c"] = "MISTY: You really\nare good…\012I'll admit that\nyou are skilled…\012Here you go. It's\nCASCADEBADGE.",
  ["62:4768"] = "{PLAYER} received\nCASCADEBADGE.",
  ["62:4782"] = "MISTY: Are there\nmany strong train-\011ers in JOHTO? Like\011you, I mean.\012I'm going to\ntravel one day, so\012I can battle some\nskilled trainers.",
  ["62:480a"] = "Sorry about being\naway. Let's get on\011with it!",
  ["62:4838"] = "I give up! You're\nthe winner!",
  ["62:4856"] = "I'll be swimming\nquietly.",
  ["62:4870"] = "Don't let my ele-\ngant swimming un-\011nerve you.",
  ["62:489f"] = "Ooh, you calmly\ndisposed of me…",
  ["62:48c0"] = "Don't be too smug\nabout beating me.\012MISTY will destroy\nyou if you get\011complacent.",
  ["62:4912"] = "Glub…\012I'm first! Come\nand get me!",
  ["62:4934"] = "This can't be…",
  ["62:4943"] = "MISTY has gotten\nmuch better in the\011past few years.\012Don't let your\nguard down, or\011you'll be crushed!",
  ["62:49a7"] = "Yo! CHAMP in\nmaking!\012Since MISTY was\naway, I went out\012for some fun too.\nHe-he-he.",
  ["62:49fa"] = "Hoo, you showed me\nhow tough you are.\012As always, that\nwas one heck of a\011great battle!",
  ["62:4acd"] = "You'll run into\nmany trainers on\012the way to CERU-\nLEAN's CAPE.\012They want to see\nhow they stack\012up against other\ntrainers.",
  ["62:4b46"] = "MISTY is about the\nonly person in\012town who can beat\nthe trainers at\011CERULEAN's CAPE.",
  ["62:4bf1"] = "A POKéMON CENTER\nnear a cave?\012That's mighty\nconvenient.",
  ["62:4c26"] = "The POWER PLANT's\nMANAGER is looking\012for a strong POKé-\nMON trainer.\012He needs help\ngetting back\012something that\nwas stolen.",
  ["62:4c9e"] = "I hear TEAM ROCKET\ngot back together\012in JOHTO but fell\napart right away.\012I didn't know any-\nthing about that.",
  ["62:4d0c"] = "When you go out-\nside, you can see\012the roof of a big\nbuilding.\012That's the POWER\nPLANT.",
  ["62:4ee0"] = "A thief broke into\nthe POWER PLANT…\012What is the world\ncoming to?",
  ["62:4f22"] = "I just got word\nfrom CERULEAN.\012It appears that a\nshady character\012has been loitering\naround.",
  ["62:4f7f"] = "Could I ask for\nyour cooperation?",
  ["62:4fa2"] = "We'll have to beef\nup our security\011presence.",
  ["62:4fcf"] = "Someone made off\nwith a part that's\012essential for the\ngenerator.\012Without it, the\nnew generator's\011useless!",
  ["62:5038"] = "The generator's up\nand running. It's\012making electricity\nto spare.",
  ["62:5079"] = "This POWER PLANT\nhad been abandoned\011in the past.\012We got it back up\nand running to\012provide power to\nthe MAGNET TRAIN.",
  ["62:50ef"] = "The generator's\nrunning again!",
  ["62:510e"] = "The POWER PLANT's\nMANAGER is up\011ahead.\012But since someone\nwrecked the gener-\011ator, he's been\011both sad and\011furious…",
  ["62:517f"] = "Since the gener-\nator's been fixed,\012the MANAGER has\nbeen cheerful.",
  ["62:51c2"] = "The MAGNET TRAIN\nconsumes a lot of\011electricity.\012It can't move if\nthe new generator\011isn't operating.",
  ["62:5225"] = "All right! We can\nfinally get the\012MAGNET TRAIN\nrunning again.",
  ["62:5264"] = "MANAGER: I, I, I'm\nready to blast\011someone!\012Who would dare\nruin my generator?\012I spent so much\ntime on it!\012If I catch him,\nhe's going to get\012a taste of my ZAP\nCANNON!",
  ["62:5308"] = "MANAGER: I won't\nforgive him!\012The culprit can\ncry and apologize,\012but I'll still\nhammer him!\012Gahahahah!",
  ["62:536e"] = "MANAGER: Ah! Yeah!\012That's the missing\nPART from my be-\011loved generator!\011You found it?",
  ["62:53c4"] = "Wahah! Thanks!\012Here! Take this TM\nas a reward!",
  ["62:53f4"] = "MANAGER: TM07 is\nmy ZAP CANNON.\012It's a powerful\ntechnique!\012It's not what any-\none would consider\012accurate, but it\npacks a wallop!",
  ["62:5475"] = "MANAGER: My be-\nloved generator!\012Keep pumping the\nelectricity out!",
  ["62:56ce"] = "Hm? You know BILL?\nHe's my grandson.\012He's in JOHTO. He\ndoes something\012with PCs, so I'm\nhouse-sitting.",
  ["62:5732"] = "If you have that\nPOKéMON, may I see\011it, please?",
  ["62:5760"] = "You will show me?\nHow good of you!",
  ["62:5784"] = "You don't have it?\nThat's too bad…",
  ["62:57a6"] = "Ah, so that is\n{STRBUF}?\012Isn't it cute!\nThat's so kind of\011you.",
  ["62:57e1"] = "Thanks!\012This is a token of\nmy appreciation.",
  ["62:580e"] = "Come visit again\nsometime.",
  ["62:582a"] = "Thanks for showing\nme so many cute\011POKéMON.\012I really enjoyed\nmyself. I'm glad\012I've lived such a\nlong life.",
  ["62:5891"] = "Hm?\012That's not the\nPOKéMON that I was\011told about.",
  ["62:58c0"] = "My grandson BILL\ntold me about a\012POKéMON that has a\nlong tongue.",
  ["62:58ff"] = "Ah, my grandson\nmentioned a round,\012green POKéMON that\nhas leaves growing\011on its head.",
  ["62:5953"] = "Do you know of a\nsea POKéMON that\012has a red sphere\nin its body?\012You know, the one\nthat's shaped like\011a star?\012I heard that it\nappears at night.\012I would surely\nlike to see it.",
  ["62:59fe"] = "BILL told me about\na POKéMON that is\012very loyal to its\ntrainer.\012It's supposed to\nROAR well.",
  ["62:5a57"] = "I heard about a\ncute POKéMON that\011has six tails.\012I would love to\nhug a cute POKéMON\011like that.",
  ["62:5ab1"] = "Do you know that\nhugely popular\011POKéMON?\012The POKéMON that\nhas a yellow body\011and red cheeks.\012I would love to\nsee what it looks\012like before it\nevolves.",
  ["62:5b6c"] = "Hello!\012KARATE KING, the\nFIGHTING DOJO's\012master, is in a\ncave in JOHTO for\011training.",
  ["62:5bc0"] = "What goes around\ncomes around!",
  ["62:5be0"] = "Enemies on every\nside!",
  ["62:5cdf"] = "SABRINA: I knew\nyou were coming…\012Three years ago I\nhad a vision of\011your arrival.\012You're after my\nBADGE.\012I don't enjoy bat-\ntling, but it's my\012duty as a LEADER\nto confer BADGES\012on anyone who has\nproven him- or\011herself worthy.\012Since you wish it,\nI will show you my\011psychic powers!",
  ["62:5df4"] = "SABRINA: Your\npower…\012It far exceeds\nwhat I foresaw…\012Maybe it isn't\npossible to fully\012predict what the\nfuture holds…\012OK, you win. You\nearned yourself\011MARSHBADGE.",
  ["62:5e95"] = "{PLAYER} received\nMARSHBADGE.",
  ["62:5ead"] = "SABRINA: MARSH-\nBADGE draws out\012your subliminal\npowers…\012Although I failed\nto accurately pre-\011dict your power,\011this much I know\011to be true.\012You will become a\ncelebrated and\011beloved CHAMPION!",
  ["62:5f6c"] = "SABRINA: Your love\nfor your POKéMON\012overwhelmed my\npsychic power…\012The power of love,\nI think, is also a\012kind of psychic\npower…",
  ["62:5fe9"] = "The power of all\nthose you defeated\011comes to me!",
  ["62:601b"] = "Strong…\nFar too strong…",
  ["62:6034"] = "What is the source\nof your power?",
  ["62:6057"] = "Psychic power is\nthe power of your\011soul.",
  ["62:6081"] = "Your soul has more\npower than mine!",
  ["62:60a6"] = "You made your soul\nstronger, not just\011your abilities.",
  ["62:60dd"] = "Fufufufu…\nI see it clearly.\012I can see into\nyour soul!",
  ["62:6114"] = "Though I read you,\nI still lost…",
  ["62:6136"] = "Darn! I forgot\nthat I predicted I\011would lose to you.",
  ["62:616c"] = "The FIGHTING DOJO\nnext door was once\011this city's GYM.",
  ["62:61a2"] = "I was no match…",
  ["62:61b3"] = "KARATE KING, the\nmaster of the\012FIGHTING DOJO, was\njust destroyed by\011SABRINA.",
  ["62:6201"] = "Yo, CHAMP in\nmaking!\012A trainer as\nskilled as you\012doesn't need to be\ntold how to deal\012with psychic-type\nPOKéMON, right?\012I expect great\nthings from you!\012Good luck!",
  ["62:62a0"] = "That was another\nfantastic battle!",
  ["62:63cc"] = "There's a big\nRADIO TOWER in\011LAVENDER.",
  ["62:63f3"] = "I want to become\nstronger, but I'm\011not good yet…\012Could you show me\nhow sometime?",
  ["62:64a3"] = "What are JOHTO's\nPOKéMON CENTERS\011like?\012…Oh, I see. So\nthey're not much\012different from the\nones in KANTO.\012I can go to JOHTO\nwithout worrying,\011then!",
  ["62:6532"] = "What are JOHTO's\nPOKéMON CENTERS\011like?\012…Oh, I see.\nSo they let you\012link with people\nfar away?\012Then I'll get my\nfriend in JOHTO to\012catch a MARILL and\ntrade it to me!",
  ["62:65d3"] = "I just happened to\ncome through ROCK\012TUNNEL. There was\nsome commotion at\011the POWER PLANT.",
  ["62:662e"] = "Caves collapse\neasily.\012Several caves have\ndisappeared in the\012past few years,\nlike the one out-\011side CERULEAN.\012As a pro HIKER,\nthat's common\011knowledge.",
  ["62:66c5"] = "SILPH CO.'s HEAD\nOFFICE and the\012MAGNET TRAIN STA-\nTION--they're the\012places to see in\nSAFFRON.",
  ["62:6798"] = "…\012…\012…\012…I got it!\012You wanted this!",
  ["62:67bb"] = "TM29 is PSYCHIC.\012It may lower the\ntarget's SPCL.DEF.",
  ["62:68a9"] = "I'm sorry, but the\nMAGNET TRAIN isn't\011operating now.",
  ["62:68dd"] = "We'll soon depart\nfor GOLDENROD.\012Are you coming on\nboard?",
  ["62:6917"] = "May I see your\nrail PASS, please?\012OK. Right this\nway, please.",
  ["62:6956"] = "Sorry, but you\ndon't have a PASS.",
  ["62:6978"] = "We hope to see you\nagain.",
  ["62:6993"] = "We have arrived in\nSAFFRON.\012We hope to see you\nagain.",
  ["62:69ca"] = "The MAGNET TRAIN\nis a super-modern\012rail liner that\nuses electricity\012and magnets to\nattain incredible\011speed.\012However, if there\nisn't any elec-\011tricity…",
  ["62:6a61"] = "Whew…\012How many times\nhave I gone back\012and forth between\nKANTO and JOHTO?",
  ["62:6aab"] = "Before the MAGNET\nTRAIN STATION was\012built, there was a\nhouse there.\012A little girl\nnamed COPYCAT used\011to live there.",
  ["62:6b20"] = "Hi. Do you have a\nrail PASS? I have\012one. All the peo-\nple in SAFFRON who\012ride the MAGNET\nTRAIN have PASSES.",
  ["62:6c03"] = "Welcome. This is\nSILPH CO.'s HEAD\011OFFICE BUILDING.",
  ["62:6c36"] = "Only employees are\npermitted to go\011upstairs.\012But since you came\nsuch a long way,\012have this neat\nlittle souvenir.",
  ["62:6ca8"] = "It's SILPH CO.'s\nlatest product.\012It's not for sale\nanywhere yet.",
  ["62:6d34"] = "My daughter likes\nto mimic people.\012Her mimicry has\nearned her the\012nickname COPYCAT\naround here.",
  ["62:6d95"] = "My daughter is so\nself-centered…\012She only has a few\nfriends.",
  ["62:6dd3"] = "She recently lost\nthe POKé DOLL that\012a boy gave her\nthree years ago.\012Ever since then,\nshe's gotten even\011better at mimicry…",
  ["62:6e4b"] = "BLISSEY: Bliisii!",
  ["62:6fda"] = "{PLAYER}: Hi! Do\nyou like POKéMON?\012{PLAYER}: Uh, no, I\njust asked you.\012{PLAYER}: Huh?\nYou're strange!",
  ["62:7028"] = "COPYCAT: Hmm?\nQuit mimicking?\012But that's my\nfavorite hobby!",
  ["62:7064"] = "{PLAYER}: Hi!\nI heard that you\012lost your favorite\nPOKé DOLL.\012{PLAYER}: If I find\nit, you'll give me\011a rail PASS?\012{PLAYER}: I'll go\nfind it for you.\012You think you lost\nit when you went\011to VERMILION CITY?",
  ["62:7116"] = "COPYCAT: Pardon?\012I shouldn't decide\nwhat you should\011do?\012But I'm really\nworried… What if\011someone finds it?",
  ["62:717f"] = "COPYCAT: Yay!\nThat's my CLEFAIRY\011POKé DOLL!\012See the tear where\nthe right leg is\012sewn on? That's\nproof!",
  ["62:71e2"] = "OK. Here's the\nMAGNET TRAIN PASS\011like I promised!",
  ["62:7214"] = "COPYCAT: That's\nthe PASS for the\011MAGNET TRAIN.\012The rail company\nman gave me that\012when they tore\ndown our old house\011for the STATION.",
  ["62:7298"] = "{PLAYER}: Hi!\nThanks a lot for\011the rail PASS!\012{PLAYER}: Pardon?\012{PLAYER}: Is it\nthat fun to mimic\011my every move?",
  ["62:72f5"] = "COPYCAT: You bet!\nIt's a scream!",
  ["62:7316"] = "{PLAYER}: Hi. You\nmust like POKéMON.\012{PLAYER}: No, not\nme. I asked you.\012{PLAYER}: Pardon?\nYou're weird!",
  ["62:7366"] = "{PLAYER}: Hi. Did\nyou really lose\011your POKé DOLL?\012{PLAYER}: You'll\nreally give me a\012rail PASS if I\nfind it for you?\012{PLAYER}: Sure,\nI'll look for it!\012You think you lost\nit when you were\011in VERMILION?",
  ["62:7415"] = "{PLAYER}: Thank you\nfor the rail PASS!\012{PLAYER}: …Pardon?\012{PLAYER}: Is it\nreally that fun to\012copy what I say\nand do?",
  ["62:7476"] = "DODRIO: Gii giii!",
  ["62:7489"] = "MIRROR, MIRROR ON\nTHE WALL, WHO'S\012THE FAIREST ONE OF\nALL?",
  ["62:74c4"] = "This is a rare\nPOKéMON! Huh?\012It's only a doll…",
  ["62:7558"] = "Many cities in\nJOHTO have long\012histories. I'd\nlove to visit!",
  ["62:75bc"] = "You're from JOHTO,\naren't you?\012How do you like\nKANTO? It's nice,\011don't you agree?",
  ["62:7655"] = "Eeyaaaah!\012I sense a sinister\nshadow hovering\011over you.\012Take this to ward\nit off!",
  ["62:76a7"] = "You were in mortal\ndanger, but you\011are protected now.",
  ["62:76de"] = "My grandma is into\nwarding off what\012she believes to be\nevil spirits.\012I'm sorry that she\nstartled you.",
  ["63:4042"] = "Have you visited\nPEWTER GYM?\012The LEADER uses\nrock-type POKéMON.",
  ["63:4080"] = "At night, CLEFAIRY\ncome out to play\011at MT.MOON.\012But not every\nnight.",
  ["63:40c6"] = "Ah, you came all\nthe way out here\011from JOHTO?\012That brings back\nmemories. When I\012was young, I went\nto JOHTO to train.\012You remind me so\nmuch of what I was\012like as a young\nman.\012Here. I want you\nto have this item\011I found in JOHTO.",
  ["63:41aa"] = "Going to new, un-\nknown places and\011seeing new people…\012Those are the joys\nof travel.",
  ["63:41ff"] = "PEWTER CITY\nA Stone Gray City",
  ["63:421e"] = "PEWTER CITY\nPOKéMON GYM\011LEADER: BROCK\012The Rock Solid\nPOKéMON Trainer",
  ["63:425e"] = "There's a notice\nhere…\012PEWTER MUSEUM OF\nSCIENCE is closed\011for renovations…",
  ["63:42a9"] = "There's a notice\nhere…\012MT.MOON GIFT SHOP\nNOW OPEN!",
  ["63:42dc"] = "WELCOME TO\nPEWTER CITY!",
  ["63:4531"] = "Gyaaas!",
  ["63:473f"] = "Whoa! You startled\nme there!\012I had my BLACK-\nGLASSES on, so I\012didn't notice you\nat all.\012What am I doing\nhere?\012Hey, don't you\nworry about it.\012I'll give you a\npair of BLACK-\011GLASSES, so forget\011you saw me, OK?",
  ["63:480c"] = "BLACKGLASSES ups\nthe power of dark-\011type moves.",
  ["63:49b8"] = "Wait!",
  ["63:49bf"] = "CLAIR: I'm sorry\nabout this.\012Here, take this as\nmy apology.",
  ["63:49fb"] = "{PLAYER} received\nTM24.",
  ["63:4a0d"] = "That contains\nDRAGONBREATH.\012No, it doesn't\nhave anything to\011do with my breath.\012If you don't want\nit, you don't have\011to take it.",
  ["63:4a8b"] = "Oh? You don't have\nany room for this.\012I'm going back to\nthe GYM, so make\012room, then come\nsee me there.",
  ["63:4af1"] = "CLAIR: What's the\nmatter? Aren't you\012going on to the\nPOKéMON LEAGUE?\012Do you know how to\nget there?\012From here, go to\nNEW BARK TOWN.\012Then SURF east to\nPOKéMON LEAGUE.\012The route there is\nvery tough.\012Don't you dare\nlose at the POKé-\011MON LEAGUE!\012If you do, I'll\nfeel even worse\012about having lost\nto you!\012Give it everything\nyou've got.",
  ["63:4c2e"] = "DRAGON SHRINE\012A shrine honoring\nthe dragon POKéMON\012said to have lived\nin DRAGON'S DEN.",
  ["63:4c83"] = "…\nWhat? {PLAYER}?\012…No, I won't\nbattle you now…\012My POKéMON aren't\nready to beat you.\012I can't push them\ntoo hard now.\012I have to be dis-\nciplined to become\012the greatest POKé-\nMON trainer…",
  ["63:4d2d"] = "…\012Whew…\012Learn to stay out\nof my way…",
  ["63:4d53"] = "You! How dare you\nenter uninvited!",
  ["63:4d77"] = "S-strong!",
  ["63:4d82"] = "The SHRINE ahead\nis home to the\012MASTER of our\ndragon-user clan.\012You're not allowed\nto just go in!",
  ["63:4de4"] = "You shouldn't be\nin here!",
  ["63:4dfe"] = "Oh yikes, I lost!",
  ["63:4e11"] = "Soon I'm going to\nget permission\012from our MASTER to\nuse dragons.\012When I do, I'm\ngoing to become an\012admirable dragon\ntrainer and gain\012our MASTER's\napproval.",
  ["63:4eab"] = "It's a stranger we\ndon't know.",
  ["63:4ec9"] = "Ouchies.",
  ["63:4ed3"] = "It was like having\nto battle LANCE.",
  ["63:4ef8"] = "Who are you?",
  ["63:4f06"] = "Meanie.",
  ["63:4f0f"] = "We'll tell on you.\012MASTER will be\nangry with you.",
  ["63:4f41"] = "{PLAYER} found\n{STRBUF}!",
  ["63:4f51"] = "But {PLAYER} can't\ncarry any more\011items.",
  ["63:52ea"] = "Hm… Good to see\nyou here.\012No need to explain\nwhy you came.\012CLAIR sent you\nhere, didn't she?\012That girl is a\nhandful…\012I am sorry, but I\nmust test you.\012Not to worry, you\nare to answer only\011a few questions.\012Ready?",
  ["63:53bc"] = "What are POKéMON\nto you?",
  ["63:53d3"] = "What helps you to\nwin battles?",
  ["63:53f3"] = "What kind of\ntrainer do you\011wish to battle?",
  ["63:5420"] = "What is most\nimportant for\011raising POKéMON?",
  ["63:544a"] = "Strong POKéMON.\nWeak POKéMON.\012Which is more\nimportant?",
  ["63:547c"] = "Hm… I see…\012You care deeply\nfor POKéMON.\012Very commendable.\012That conviction is\nwhat is important!\012{PLAYER}, don't\nlose that belief.\012It will see you\nthrough at the\011POKéMON LEAGUE.",
  ["63:5520"] = "CLAIR!\012This child is\nimpeccable, in\011skill and spirit!\012Admit defeat and\nconfer the RISING-\011BADGE!\012…Or must I inform\nLANCE of this?",
  ["63:55a3"] = "CLAIR…\012Reflect upon what\nit is that you\012lack and this\nchild has.",
  ["63:55e5"] = "Come again, if you\nso desire.",
  ["63:5604"] = "Hm… Good to see\nyou here.\012Your arrival is\nmost fortunate.\012I have something\nfor you.\012Take this DRATINI\nas proof that I\012have recognized\nyour worth.",
  ["63:5697"] = "{PLAYER} received\nDRATINI!",
  ["63:56ac"] = "Hm? Your POKéMON\nparty is full.",
  ["63:56ca"] = "Dragon POKéMON are\nsymbolic of our\011clan.\012You have shown\nthat you can be\012entrusted with\none.",
  ["63:5724"] = "CLAIR appears to\nhave learned an\012invaluable lesson\nfrom you.\012I thank you as her\ngrandfather.",
  ["63:5782"] = "A boy close to\nyour age is in\011training here.\012He is much like\nCLAIR when she was\012younger. It is a\nlittle worrisome…",
  ["63:57f6"] = "Hah? I didn't\nquite catch that…",
  ["63:5816"] = "What was it you\nsaid?",
  ["63:582d"] = "Oh, I understand…",
  ["63:5840"] = "It's been quite\nsome time since a\012trainer has gained\nour MASTER's rare\011approval.\012In fact, not since\nMaster LANCE.",
  ["63:58b1"] = "You know young\nMaster LANCE?\012He looks so much\nlike our MASTER\011did in his youth.\012It's in their\nblood.",
  ["63:5916"] = "So how did it go?\012I guess there's no\npoint in asking.\012You did fail?\012………………………………\012…What? You passed?",
  ["63:5974"] = "That can't be!",
  ["63:5983"] = "You're lying!\012Even I haven't\nbeen approved!",
  ["63:59ae"] = "I-I understand…",
  ["63:59bf"] = "Here, this is the\nRISINGBADGE…\012Hurry up! Take it!",
  ["63:59f2"] = "{PLAYER} received\nRISINGBADGE.",
  ["63:5a0b"] = "RISINGBADGE will\nenable your\012POKéMON to use the\nmove for climbing\011waterfalls.\012Also, all POKéMON\nwill recognize you\012as a trainer and\nobey your every\012command without\nquestion.",
  ["63:5b34"] = "Do your POKéMON\nknow HM moves?\012Those moves can\nbe used even if\012your POKéMON has\nfainted.",
  ["63:5bee"] = "BILL's PC can\nstore up to 20\011POKéMON per BOX.",
  ["63:5c19"] = "Do you know about\nAPRICORNS?\012Crack one open,\nhollow it out and\012fit it with a\nspecial device.\012Then you can catch\nPOKéMON with it.\012Before POKé BALLS\nwere invented,\012everyone used\nAPRICORNS.",
  ["63:5d74"] = "All the SLOWPOKE\nhave disappeared\011from the town.\012The forest's pro-\ntector may be\011angry with us…\012It may be a bad\nomen. We should\011stay in.",
  ["63:5dfd"] = "The SLOWPOKE have\nreturned…\012But my APPRENTICE\nhasn't come back\011from ILEX FOREST.\012Where in the world\nis that lazy guy?",
  ["63:5e73"] = "You chased off\nTEAM ROCKET and\012went to ILEX\nFOREST alone?\012That takes guts!\nI like that. Come\011train with us.",
  ["63:5ee0"] = "Where have all the\nSLOWPOKE gone?\012Are they out play-\ning somewhere?",
  ["63:5f25"] = "I'm sorry--I for-\ngot to thank you.\012This is CHARCOAL\nthat I made.\012Fire-type POKéMON\nwould be happy to\011hold that.",
  ["63:5f93"] = "The SLOWPOKE came\nback, and you even\011found FARFETCH'D.\012You're the cool-\nest, man!",
  ["63:5fe5"] = "FARFETCH'D: Kwaa!",
  ["63:604d"] = "There's no GREAT\nBALL here. POKé\012BALLS will have\nto do.\012I wish KURT would\nmake me some of\011his custom BALLS.",
  ["63:60b6"] = "A GREAT BALL is\nbetter for catch-\011ing POKéMON than a\011POKé BALL.\012But KURT's might\nbe better some-\011times.",
  ["63:6473"] = "Hm? Who are you?\012{PLAYER}, eh? You\nwant me to make\011some BALLS?\012Sorry, but that'll\nhave to wait.\012Do you know TEAM\nROCKET? Ah, don't\012worry. I'll tell\nyou anyhow.\012TEAM ROCKET's an\nevil gang that\012uses POKéMON for\ntheir dirty work.\012They're supposed\nto have disbanded\011three years ago.\012Anyway, they're at\nthe WELL, cutting\012off SLOWPOKETAILS\nfor sale!\012So I'm going to\ngo give them a\011lesson in pain!\012Hang on, SLOWPOKE!\nOld KURT is on his\011way!",
  ["63:6615"] = "KURT: Hi, {PLAYER}!\012You handled your-\nself like a real\011hero at the WELL.\012I like your style!\012I would be honored\nto make BALLS for\012a trainer like\nyou.\012This is all I have\nnow, but take it.",
  ["63:66c9"] = "KURT: I make BALLS\nfrom APRICORNS.\012Collect them from\ntrees and bring\011'em to me.\012I'll make BALLS\nout of them.",
  ["63:6736"] = "KURT: You have an\nAPRICORN for me?\012Fine! I'll turn it\ninto a BALL.",
  ["63:6779"] = "KURT: It'll take a\nday to make you a\012BALL. Come back\nfor it later.",
  ["63:67bc"] = "KURT: Oh…\nThat's a letdown.",
  ["63:67d8"] = "KURT: I'm working!\nDon't bother me!",
  ["63:67fb"] = "KURT: Ah, {PLAYER}!\nI just finished\011your BALL. Here!",
  ["63:682a"] = "KURT: That turned\nout great.\012Try catching\nPOKéMON with it.",
  ["63:6863"] = "KURT: Now that my\ngranddaughter is\012helping me, I can\nwork much faster.",
  ["63:68ab"] = "Wh-what is that?\012I've never seen\none before.\012It looks a lot\nlike a POKé BALL,\012but it appears to\nbe something else.\012Let me check it\nfor you.",
  ["63:6934"] = "I'm checking it\nnow.",
  ["63:6949"] = "Ah-ha! I see!\nSo…",
  ["63:695c"] = "{PLAYER}!\012This BALL started\nto shake while I\011was checking it.\012There must be\nsomething to this!",
  ["63:69b5"] = "The SLOWPOKE are\ngone… Were they\012taken away by bad\npeople?",
  ["63:69f1"] = "Grandpa's gone…\nI'm so lonely…",
  ["63:6a0f"] = "The SLOWPOKE my\ndad gave me came\012back! Its TAIL is\ngrowing back too!",
  ["63:6a55"] = "Dad works at SILPH\nwhere he studies\011POKé BALLS.\012I have to stay\nhome with Grandpa\011and SLOWPOKE.",
  ["63:6ab2"] = "I get to help\nGrandpa now!\012We'll make good\nBALLS for you, so\011please wait!",
  ["63:6afc"] = "It's fun to make\nBALLS!",
  ["63:6b14"] = "Grandpa's checking\na BALL right now.\012So I'm waiting\ntill he's done.",
  ["63:6b56"] = "SLOWPOKE: …\nYawn?",
  ["63:6b69"] = "…A young PROF.\nOAK?",
  ["63:6b7e"] = "It's a statue of\nthe forest's pro-\011tector.",
  ["63:6d0b"] = "I'm BUGSY!\nI never lose when\012it comes to bug\nPOKéMON.\012My research is\ngoing to make me\012the authority on\nbug POKéMON!\012Let me demonstrate\nwhat I've learned\011from my studies.",
  ["63:6dae"] = "Whoa, amazing!\nYou're an expert\011on POKéMON!\012My research isn't\ncomplete yet.\012OK, you win. Take\nthis BADGE.",
  ["63:6e14"] = "{PLAYER} received\nHIVEBADGE.",
  ["63:6e2b"] = "Do you know the\nbenefits of HIVE-\011BADGE?\012If you have it,\nPOKéMON up to L30\012will obey you,\neven traded ones.\012POKéMON that know\nCUT will be able\012to use it outside\nof battle too.\012Here, I also want\nyou to have this.",
  ["63:6efa"] = "TM49 contains\nFURY CUTTER.\012If you don't miss,\nit gets stronger\011every turn.\012The longer your\nbattle goes, the\011better it gets.\012Isn't that great?\nI discovered it!",
  ["63:6f98"] = "Bug POKéMON are\ndeep. There are\012many mysteries to\nbe explored.\012Study your favor-\nites thoroughly.",
  ["63:6ff8"] = "Bug POKéMON evolve\nyoung. So they get\012stronger that much\nfaster.",
  ["63:7037"] = "Just evolving\nisn't enough!",
  ["63:7053"] = "POKéMON become\nstronger if they\011evolve. Really!",
  ["63:7081"] = "Bug POKéMON are\ncool and tough!\012I'll prove it to\nyou!",
  ["63:70b4"] = "You proved how\ntough you are…",
  ["63:70d3"] = "They're so cool,\nbut most girls\012don't like bug\nPOKéMON.\012I don't know why…",
  ["63:7118"] = "You saved all the\nSLOWPOKE? Whew,\011you're mighty!\012But my grown-up\nPOKéMON are pretty\011tough too!",
  ["63:7174"] = "Urrgggh!",
  ["63:717e"] = "I guess I should\nteach them better\011moves…",
  ["63:71a9"] = "AMY: Hi! Are you\nchallenging the\011LEADER? No way!",
  ["63:71db"] = "AMY & MAY: Oh,\ndouble goodness!",
  ["63:71fc"] = "AMY: You're\nreally strong!",
  ["63:7217"] = "MAY: You want to\nsee the LEADER?\011We come first!",
  ["63:7248"] = "AMY & MAY: Oh,\ndouble goodness!",
  ["63:7269"] = "MAY: Our bug POKé-\nMON lost! Oh, what\011a shame.",
  ["63:7296"] = "Yo, challenger!\012BUGSY's young, but\nhis knowledge of\012bug POKéMON is for\nreal.\012It's going to be\ntough without my\011advice.\012Let's see… Bug\nPOKéMON don't like\011fire.\012Flying-type moves\nare super-effec-\011tive too.",
  ["63:7359"] = "Well done! That\nwas a great clash\012of talented young\ntrainers.\012With people like\nyou, the future of\011POKéMON is bright!",
  ["64:40b0"] = "Hiya, kid!\012I see you're new\nin MAHOGANY TOWN.\012Since you're new,\nyou should try a\012yummy RAGECANDY-\nBAR!\012Right now, it can\nbe yours for just\011¥300! Want one?",
  ["64:414a"] = "Good! Savor it!",
  ["64:415b"] = "You don't have\nenough money.",
  ["64:4178"] = "Oh, fine then…",
  ["64:4188"] = "You don't have\nroom for this.",
  ["64:41a6"] = "RAGECANDYBAR's\nsold out.\012I'm packing up.\nDon't bother me,\011kiddo.",
  ["64:41e5"] = "Are you off to see\nthe GYARADOS ram-\011page at the LAKE?",
  ["64:421d"] = "MAGIKARP have\nreturned to LAKE\011OF RAGE.\012That should be\ngood news for the\011anglers there.",
  ["64:4276"] = "Since you came\nthis far, take the\012time to do some\nsightseeing.\012You should head\nnorth and check\012out LAKE OF RAGE\nright now.",
  ["64:42f2"] = "Visit Grandma's\nshop. She sells\012stuff that nobody\nelse has.",
  ["64:432e"] = "MAHOGANY TOWN\012Welcome to the\nHome of the Ninja",
  ["64:435e"] = "While visiting\nMAHOGANY TOWN, try\011a RAGECANDYBAR!",
  ["64:4391"] = "MAHOGANY TOWN\nPOKéMON GYM\011LEADER: PRYCE\012The Teacher of\nWinter's Harshness",
  ["64:4790"] = "Wait up!\nWhat's the hurry?",
  ["64:47ab"] = "{PLAYER}, right?\nSome guy wearing\012glasses was look-\ning for you.\012See for yourself.\nHe's waiting for\012you at the POKéMON\nCENTER.",
  ["64:48b0"] = "Have you gone to\nthe POKéMON GYM?\012You can test your\nPOKéMON and your-\011self there.\012It's a rite of\npassage for all\011trainers!",
  ["64:4925"] = "You have some good\nPOKéMON there.\012It must be from\nthe training you\012gave them around\nVIOLET CITY.\012The training at\nthe GYM must have\012been especially\nhelpful.\012As a souvenir of\nVIOLET CITY, take\011this.\012It increases the\npower of grass-\011type moves.",
  ["64:4a15"] = "Your experiences\nin VIOLET CITY\012should be useful\nfor your journey.",
  ["64:4a59"] = "How would you like\nto have this\012tasty, nutritious\nSLOWPOKETAIL?\012For you right now,\njust ¥1,000,000!\012You'll want this!",
  ["64:4acf"] = "Tch! I thought\nkids these days\011were loaded…",
  ["64:4afc"] = "You don't want it?\nThen scram. Shoo!",
  ["64:4b21"] = "Whoa!\012You made me lose\nthat fish!",
  ["64:4b44"] = "Sploosh!",
  ["64:4b4e"] = "Calm, collected…\nThe essence of\012fishing and POKé-\nMON is the same.",
  ["64:4b8f"] = "I'm really good at\nboth fishing and\011POKéMON.\012I'm not about to\nlose to any kid!",
  ["64:4bda"] = "Tch! I tried to\nrush things…",
  ["64:4bf8"] = "Fishing is a life-\nlong passion.\012POKéMON are life-\nlong friends!",
  ["64:4c37"] = "One, two, three…\nMuahahaha, what a\012great haul!\nI'm done! Go ahead\012and catch as many\nas you can, kid!",
  ["64:4dcf"] = "My POKéMON?\nFreshly caught!",
  ["64:4de9"] = "SPLASH?",
  ["64:4df2"] = "Freshly caught\nPOKéMON are no\012match for properly\nraised ones.",
  ["64:4e2e"] = "I haven't seen you\naround before.\012So you think you\nare pretty tough?",
  ["64:4e73"] = "You're strong!",
  ["64:4e82"] = "I'm going to try\nto be the best\011with my favorites.\012I'm not using the\nsame tough POKéMON\011as everyone else.",
  ["64:4ee8"] = "I found some good\nPOKéMON in the\011grass!\012I think they'll do\nit for me!",
  ["64:4f2b"] = "Darn. I thought I\ncould win.",
  ["64:4f49"] = "The grass is full\nof clingy things.",
  ["64:4f6e"] = "That glance…\nIt's intriguing.",
  ["64:4f8c"] = "Hmmm. This is\ndisappointing.",
  ["64:4faa"] = "If you don't want\nto battle, just\011avoid eye contact.",
  ["64:4fdf"] = "Uh-huh. Yeah, and\nyou know…\012Pardon? Battle?\nI'm on the phone.\012Oh, all right. But\nmake it fast.",
  ["64:503e"] = "Oh! I've got to\nrelieve my anger!",
  ["64:5060"] = "I was having a\nnice chat too.",
  ["64:507f"] = "That BADGE! It's\nfrom VIOLET CITY!\012You beat FALKNER?",
  ["64:50b4"] = "I know what my\nweaknesses are.",
  ["64:50d4"] = "I should train\nagain at the GYM\011in VIOLET CITY.",
  ["64:5133"] = "WROOOOAR!\nPEOPLE RUN WHEN I\012ROAR! BUT YOU\nCAME LOOKING!\012THAT PLEASES ME!\nNOW TAKE THIS!",
  ["64:518c"] = "WROOOAR!\nIT'S ROAR!\012EVEN POKéMON RUN\nFROM A GOOD ROAR!",
  ["64:51c1"] = "FRIEDA: Yahoo!\nIt's Friday!\012I'm FRIEDA of\nFriday!\012Nice to meet you!",
  ["64:5204"] = "Here's a POISON\nBARB for you!",
  ["64:5222"] = "FRIEDA: Give it to\na POKéMON that has\011poison-type moves.\012Oh!\012It's wicked!\012You'll be shocked\nhow good it makes\011poison moves!",
  ["64:529a"] = "FRIEDA: Hiya! What\nday do you like?\012I love Friday. No\ndoubt about it!\012Don't you think\nit's great too?",
  ["64:52ff"] = "FRIEDA: Isn't it\nFriday today?\012It's so boring\nwhen it's not!",
  ["64:533a"] = "ROUTE 32\012VIOLET CITY -\nAZALEA TOWN",
  ["64:535e"] = "RUINS OF ALPH\nEAST ENTRANCE",
  ["64:537b"] = "UNION CAVE\nAHEAD",
  ["64:5496"] = "I am the FISHING\nDUDE, the elder of\011the FISHING BROS.\012Have you met the\nFISHING GURU at\011LAKE OF RAGE?\012He dreams about\nseeing the world's\011greatest MAGIKARP.\012If you don't mind,\ncould you show him\012any MAGIKARP you\ncatch?\012Who knows, you may\ncatch the MAGIKARP\011of his dreams.",
  ["64:55a3"] = "It's a photo of\npeople fishing…\012They're having a\ngreat time…",
  ["64:5620"] = "A sleeping POKéMON\nis lying in front\011of DIGLETT'S CAVE.\012It's a fantastic\nopportunity to get\012it, but how do you\nwake it up?",
  ["64:5698"] = "There used to be a\nsleeping POKéMON\012lying in front of\nDIGLETT'S CAVE.\012But it seems to\nhave disappeared.",
  ["64:56fe"] = "The FAST SHIP is a\ngreat place to\012meet and battle\ntrainers.",
  ["64:573b"] = "Oh? You have some\nBADGES I've never\011seen before.\012Oh, I get it. You\ngot them in JOHTO.",
  ["64:5881"] = "I'm the CHAIRMAN\nof the POKéMON FAN\011CLUB.\012I've raised over\n150 POKéMON.\012I'm very fussy\nwhen it comes to\011POKéMON.\012Did you visit just\nto hear about my\011POKéMON?",
  ["64:5911"] = "Good!\nThen listen up!\012So… my favorite\nRAPIDASH…\012It… cute… lovely…\nsmart… unbearably…\011plus… amazing… oh…\011you think so?…\011Too much… wild…\011beautiful… kindly…\011love it!\012Hug it… when…\nsleeping… warm and\011cuddly… Oh, and…\011spectacular…\011ravishing… simply\011divine…\011Oops! Look at the\011time! I've kept\011you too long!",
  ["64:5a3d"] = "Thanks for hearing\nme out. I want you\011to have this!",
  ["64:5a72"] = "It's a RARE CANDY\nthat makes POKéMON\011stronger.\012I prefer making my\nPOKéMON stronger\012by battling, so\nyou can have it.",
  ["64:5ae0"] = "Hello, {PLAYER}!\012Did you come see\nme about my POKé-\011MON again?\012No? Oh… I had more\ntales to tell…",
  ["64:5b38"] = "How disappointing…\012Come back if you\nwant to listen.",
  ["64:5b6d"] = "Our CHAIRMAN is\nvery vocal when it\011comes to POKéMON…",
  ["64:5ba0"] = "I love the way\nCLEFAIRY waggles\012its finger when\nit's trying to use\012METRONOME.\nIt's so adorable!",
  ["64:5bff"] = "I love CLEFAIRY,\nbut I could never\012catch one. So I'm\nmaking do with a\012POKé DOLL that I\nfound.",
  ["64:5c5a"] = "Oh, I see now. The\ngirl who lost this\012POKé DOLL is sad…\012OK. Could you take\nthis POKé DOLL\012back to that poor\nlittle girl?\012I'll befriend a\nreal CLEFAIRY on\012my own one day.\nNo worries!",
  ["64:5d0a"] = "{PLAYER} received\nPOKé DOLL.",
  ["64:5d1e"] = "You watch. I'm\ngoing to get a\012real CLEFAIRY as\nmy friend.",
  ["64:5d58"] = "Your PACK is\njammed full.",
  ["64:5d73"] = "Look at my darling\nBAYLEEF!\012The leaf on its\nhead is so cute!",
  ["64:5db1"] = "It's a CLEFAIRY!\nHuh?\012Oh, right. It's a\nCLEFAIRY POKé\011DOLL.",
  ["64:5de9"] = "BAYLEEF: Li liif!",
  ["64:5dfc"] = "Let's all listen\npolitely to other\011trainers.",
  ["64:5e29"] = "If someone brags,\nbrag right back!",
  ["64:5ec0"] = "Do you know about\nthe MAGNET TRAIN?\012It's a railway\nthat goes to GOL-\011DENROD in JOHTO.",
  ["64:5f16"] = "I want to go to\nSAFFRON to see\011the MAGNET TRAIN.",
  ["64:5f8b"] = "TEAM ROCKET is no\nlonger in KANTO.\012That alone makes\nme happy.",
  ["64:5fca"] = "I'm thinking about\ngoing shopping in\011SAFFRON.",
  ["64:6034"] = "Over many years,\nDIGLETT dug a\011large tunnel.\012That tunnel goes\nto a distant town.",
  ["64:6142"] = "SURGE: Hey, you\nlittle tyke!\012I have to hand it\nto you. It may not\012be very smart to\nchallenge me, but\011it takes guts!\012When it comes to\nelectric POKéMON,\011I'm number one!\012I've never lost on\nthe battlefield.\012I'll zap you just\nlike I did my\011enemies in war!",
  ["64:6238"] = "SURGE: Arrrgh!\nYou are strong!\012OK, kid. You get\nTHUNDERBADGE!",
  ["64:6277"] = "{PLAYER} received\nTHUNDERBADGE.",
  ["64:6291"] = "SURGE: THUNDER-\nBADGE increases\011POKéMON's speed. \012Consider it proof\nthat you defeated\012me. You wear it\nproudly, hear?",
  ["64:6303"] = "SURGE: Hey, kid!\nStill slugging and\011chugging away?\012My POKéMON and I\nare still at it!",
  ["64:6356"] = "You're here to\ndefeat LT.SURGE?\012Not if I can help\nit!",
  ["64:638c"] = "Sorry I failed\nyou, LT.SURGE,\011sir!",
  ["64:63b0"] = "When I was still\nin the army, LT.\012SURGE saved my\nlife.",
  ["64:63e8"] = "LT.SURGE recog-\nnized my potential\012with electric\nPOKéMON.\012Think you can beat\nme?",
  ["64:6437"] = "Ooh, how shocking!",
  ["64:644b"] = "If the GYM's traps\nwere working, you\012would have been\ntoast…",
  ["64:6487"] = "I'm going to take\nyou down! Prepare\011to be shocked!",
  ["64:64ba"] = "Gwaaah!\nI was overpowered…",
  ["64:64d6"] = "Don't get too com-\nfortable about\012beating me…\nLT.SURGE is tough.",
  ["64:6517"] = "Yo! CHAMP in\nmaking!\012You lucked out\nthis time.\012LT.SURGE is very\ncautious. He has\012traps set all over\nthe GYM.\012But--he-heh--the\ntraps aren't\011active right now.\012You'll have no\nproblem getting to\011LT.SURGE.",
  ["64:65df"] = "Whew! That was an\nelectrifying bout!\012It sure made me\nnervous.",
  ["64:661e"] = "Nope! Nothing here\nbut trash.",
  ["64:66fe"] = "Welcome to SAFFRON\nCITY, home of the\011MAGNET TRAIN!\012…That's what I'd\nnormally say, but\012the MAGNET TRAIN\nisn't running now.\012It's not getting\nany electricity\012because there's\nsomething wrong\012with the POWER\nPLANT.",
  ["64:67cb"] = "The MAGNET TRAIN\nis the most famous\012thing about SAF-\nFRON.",
  ["64:6d39"] = "Would you like to\nbattle over a GAME\012LINK cable or by\nmobile phone?",
  ["64:6d7e"] = "Would you like to\ntrade over a GAME\012LINK cable or by\nmobile phone?",
  ["64:6de0"] = "Welcome to CABLE\nCLUB COLOSSEUM.\012You may battle a\nfriend here.\012Would you like to\nbattle?",
  ["64:6e3a"] = "Welcome to CABLE\nTRADE CENTER.\012You may trade your\nPOKéMON here with\011a friend.\012Would you like to\ntrade?",
  ["64:6e9f"] = "Welcome to CABLE\nCLUB TIME CAPSULE.\012You can travel to\nthe past and trade\011your POKéMON.\012Would you like to\ntrade across time?",
  ["64:6f19"] = "Your friend is not\nready.",
  ["64:6f34"] = "Before opening the\nlink, you must\011save your game.",
  ["64:6f67"] = "Please wait.",
  ["64:6f75"] = "The link has been\nclosed because of\011inactivity.\012Please contact\nyour friend and\011come again.",
  ["64:6fd1"] = "Please come again.",
  ["64:7029"] = "You can't link to\nthe past here.",
  ["64:704a"] = "Incompatible rooms\nwere chosen.",
  ["64:706b"] = "Please come in.",
  ["64:708b"] = "Sorry--{STRBUF}\ncan't be taken.",
  ["64:70a8"] = "You can't take the\n{STRBUF} with a\011{STRBUF}.",
  ["64:70cf"] = "You can't take the\n{STRBUF} that\011has MAIL with you.",
  ["64:7100"] = "I'm sorry--the\nTIME CAPSULE is\011being adjusted.",
  ["64:712f"] = "I'm sorry--the\nTRADE MACHINE is\011being adjusted.",
  ["64:715f"] = "I'm sorry--the\nBATTLE MACHINE is\011being adjusted.",
  ["64:7190"] = "Hello! You're\n{PLAYER}, right?\012I have some-\nthing for you.",
  ["64:71c4"] = "Here you go!",
  ["64:71d2"] = "We hope to serve\nyou again.",
  ["64:71ef"] = "Oh, you have no\nspace for this.\012Stop in at any\nPOKéMON CENTER\012across the country\nto pick it up.",
  ["64:724d"] = "No? That's very\nstrange…",
  ["64:7266"] = "Oh, please wait.",
  ["64:7278"] = "We need to change\nthe look here…",
  ["64:729a"] = "How does this\nstyle look to you?",
  ["64:72bc"] = "Excuse me!\012For STADIUM rules,\nplease bring six\012different POKéMON,\nexcluding EGGS.\012The six POKéMON\nmust be different.\012Also, they must\nnot be holding\011identical items.\012Please come back\nwhen you're ready.",
  ["64:74a0"] = "Your friend is\nready.",
  ["64:7521"] = "Your friend is\nready.",
  ["64:7591"] = "Establishing\ncommunications…",
  ["64:7626"] = "Establishing\ncommunications…",
  ["64:7644"] = "Your POKéMON will\nbe fully healed\011before battle.",
  ["65:426b"] = "It's a weird tree.\nUse SQUIRTBOTTLE?",
  ["65:4290"] = "{PLAYER} used the\nSQUIRTBOTTLE.",
  ["65:42aa"] = "The weird tree\ndoesn't like the\011SQUIRTBOTTLE!\012The weird tree\nattacked!",
  ["65:42f1"] = "I'm the FLOWER\nSHOP's FLORIA!\012Listen, listen!\012When I sprinkled\nwater on that\012wiggly tree, it\njumped right up!\012It just has to be\na POKéMON.\012I bet it would be\nshocked out of its\012disguise if you\nsoaked it!\012I know! I'll tell\nmy sis and borrow\011her water bottle!",
  ["65:43ed"] = "When I told my sis\nabout the jiggly\012tree, she said\nit's dangerous.\012If I beat WHITNEY,\nI wonder if she'll\012lend me her water\nbottle…",
  ["65:446f"] = "Wa-hey!\012I was going to\nsnap that tree\012with my straight-\narm punch.\012But I couldn't!\nI'm a failure!",
  ["65:44d0"] = "Did you clear that\nwretched tree?\012I'm impressed!\nI want you to\011have this.",
  ["65:452c"] = "That happens to be\nROCK SMASH.\012You can shatter\nrocks with just a\012single well-aimed\nsmack.\012If any rocks are\nin your way, just\011smash 'em up!",
  ["65:4626"] = "An odd tree is\nblocking the way\011to GOLDENROD CITY.\012It's preventing\nme from shopping.\012Something should\nbe done about it.",
  ["65:469e"] = "That odd tree dis-\nappeared without a\011trace.\012Oh! That tree was\nreally a POKéMON?",
  ["65:46ed"] = "I'm going to read\nyour thoughts!",
  ["65:470e"] = "I misread you!",
  ["65:471e"] = "I'd be strong if\nonly I could tell\012what my opponent\nwas thinking.",
  ["65:4760"] = "Thanks to my stud-\nies, I'm ready for\011any POKéMON!",
  ["65:4790"] = "Oops! Computation\nerror?",
  ["65:47aa"] = "Darn. I study five\nhours a day too.\012There's more to\nlearning than just\011reading books.",
  ["65:4800"] = "ARTHUR: Who are\nyou?\012I'm ARTHUR of\nThursday.",
  ["65:482d"] = "Here. You can have\nthis.",
  ["65:4847"] = "ARTHUR: A POKéMON\nthat uses rock-\012type moves should\nhold on to that.\012It pumps up rock-\ntype attacks.",
  ["65:48aa"] = "ARTHUR: I'm ARTHUR\nof Thursday. I'm\012the second son out\nof seven children.",
  ["65:48f3"] = "ARTHUR: Today's\nnot Thursday. How\011disappointing.",
  ["65:4924"] = "ROUTE 36",
  ["65:492e"] = "RUINS OF ALPH\nNORTH ENTRANCE",
  ["65:494c"] = "TRAINER TIPS\012POKéMON stats\nvary--even within\011the same species.\012Their stats may be\nsimilar at first.\012However, differ-\nences will become\012pronounced as the\nPOKéMON grow.",
  ["65:49ee"] = "TRAINER TIPS\012Use DIG to return\nto the entrance of\011any place.\012It is convenient\nfor exploring\012caves and other\nlandmarks.",
  ["65:4b45"] = "One of the ELITE\nFOUR used to be\012the LEADER of\nFUCHSIA's GYM.",
  ["65:4b83"] = "KOGA's daughter\nsucceeded him as\012the GYM LEADER\nafter he joined\011the ELITE FOUR.",
  ["65:4bd3"] = "The SAFARI ZONE is\nclosed… It's sad,\012considering it's\nFUCHSIA's main\011attraction.",
  ["65:4c22"] = "FUCHSIA CITY\012Behold! It's\nPassion Pink!",
  ["65:4c4a"] = "FUCHSIA CITY\nPOKéMON GYM\011LEADER: JANINE\012The Poisonous\nNinja Master",
  ["65:4c8b"] = "There's a notice\nhere…\012SAFARI ZONE OFFICE\nis closed until\011further notice.",
  ["65:4cd5"] = "SAFARI ZONE\nWARDEN'S HOME",
  ["65:4cf0"] = "The WARDEN is\ntraveling abroad.\012Therefore, the\nSAFARI ZONE is\011closed.",
  ["65:4d37"] = "No littering.\012Please take your\nwaste with you.",
  ["65:4efa"] = "I am CLAIR.\012The world's best\ndragon master.\012I can hold my own\nagainst even the\012POKéMON LEAGUE's\nELITE FOUR.\012Do you still want\nto take me on?\012…Fine.\nLet's do it!\012As a GYM LEADER,\nI will use my full\012power against any\nopponent!",
  ["65:4fd6"] = "I lost?\012I don't believe\nit. There must be\011some mistake…",
  ["65:500e"] = "I won't admit\nthis.\012I may have lost,\nbut you're still\012not ready for the\nPOKéMON LEAGUE.\012I know. You should\ntake the dragon\011user challenge.\012Behind this GYM is\na place called\011DRAGON'S DEN.\012There is a small\nshrine at its\012center.\nGo there.\012If you can prove\nthat you've lost\012your lazy ideals,\nI will recognize\012you as a trainer\nworthy of a GYM\011BADGE!",
  ["65:5162"] = "What's the matter?\012Is it too much to\nexpect of you?",
  ["65:5196"] = "You've kept me\nwaiting!\012Here! Take this!",
  ["65:51bf"] = "{PLAYER} received\nTM24.",
  ["65:51d1"] = "That contains\nDRAGONBREATH.\012No, it doesn't\nhave anything to\011do with my breath.\012If you don't want\nit, you don't have\011to take it.",
  ["65:524f"] = "What is this? You\ndon't have room?",
  ["65:5272"] = "What's the matter?\012Aren't you headed\nto the POKéMON\011LEAGUE?\012Don't you know\nwhere it is?\012From here, go to\nNEW BARK TOWN.\012Then SURF east.\nThe route there is\011very tough.\012Don't you dare\nlose at the POKé-\011MON LEAGUE!\012If you do, I'll\nfeel even worse\012about having lost\nto you!\012Give it every-\nthing you've got.",
  ["65:5396"] = "Your first battle\nagainst dragons?\012I'll show you how\ntough they are!",
  ["65:53db"] = "My dragon POKéMON\nlost?",
  ["65:53f1"] = "LANCE told you\nthat he'd like to\012see you again?\nNot a chance!",
  ["65:542f"] = "My chance of\nlosing? Not even\011one percent!",
  ["65:545b"] = "That's odd.",
  ["65:5467"] = "I know my short-\ncomings now.\012Thanks for showing\nme!",
  ["65:549d"] = "Dragons are sacred\nPOKéMON.\012They are full of\nlife energy.\012If you're not\nserious, you won't\012be able to beat\nthem.",
  ["65:550a"] = "Way to go!",
  ["65:5516"] = "Dragons are weak\nagainst dragon-\011type moves.",
  ["65:5544"] = "Yo! CHAMP in\nmaking!\012It's been a long\njourney, but we\012are almost done!\nCount on me!\012CLAIR uses the\nmythical and sac-\011red dragon-type\011POKéMON.\012You can't damage\nthem very easily.\012But you know,\nthey're supposed\012to be weak against\nice-type moves.",
  ["65:5632"] = "You were great to\nbeat CLAIR!\012All that's left is\nthe POKéMON LEAGUE\011challenge.\012You're on the way\nto becoming the\011POKéMON CHAMPION!",
  ["65:5789"] = "It's not as if we\nall use dragon-\011type POKéMON.",
  ["65:57b6"] = "Rats! If only I\nhad a dragon!",
  ["65:57d5"] = "Members of our\ndragon-user clan\012can use dragon\nPOKéMON only after\012our MASTER allows\nit.",
  ["65:582b"] = "I can't allow a\nnameless trainer\011past me!\012CLAIR would be\nlivid if I did!",
  ["65:5874"] = "Awww… I lost…",
  ["65:5883"] = "Uh-oh… CLAIR is\ngoing to be mad…",
  ["65:58a5"] = "The boulder fell\nthrough!",
  ["65:595c"] = "A clan of trainers\nwho can freely\012command dragons\nlive right here in\011BLACKTHORN.\012As a result, there\nare many legends\012about dragons in\nthis town.",
  ["65:59ee"] = "DRATINI: Draa!",
  ["65:5a6a"] = "You can't buy MAX\nREVIVE, but it\012fully restores a\nfainted POKéMON.\012Beware--it won't\nrestore PP, the\012POWER POINTS\nneeded for moves.",
  ["65:5ae9"] = "MAX REPEL keeps\nweak POKéMON away\011from you.\012It's the longest\nlasting of the\011REPEL sprays.",
  ["65:5b85"] = "Deep inside far-\noff INDIGO PLATEAU\012is the POKéMON\nLEAGUE.\012I hear the best\ntrainers gather\012there from around\nthe country.",
  ["65:5bfd"] = "There was this\nmove I just had\012to teach my POKé-\nMON.\012So I got the MOVE\nDELETER to make it\011forget an HM move.",
  ["65:5cf5"] = "I was hoping to\nbuy some SAFARI\012ZONE souvenirs,\nbut it's closed…",
  ["65:5d36"] = "The SAFARI ZONE\nWARDEN's grand-\011daughter lives in\011town.",
  ["65:5f35"] = "Fufufufu…\012I'm sorry to dis-\nappoint you…\012I'm only joking!\012I'm the real deal!\012JANINE of FUCHSIA\nGYM, that's me!",
  ["65:5fa1"] = "JANINE: You're a\ntough one. You\011definitely won…\012Here's SOULBADGE.\nTake it.",
  ["65:5feb"] = "{PLAYER} received\nSOULBADGE.",
  ["65:6002"] = "JANINE: You're so\ntough! I have a\011special gift!\012It's TOXIC, a pow-\nerful poison that\012steadily saps the\nvictim's HP.",
  ["65:6074"] = "JANINE: I'm going\nto really apply\012myself and improve\nmy skills.\012I want to become\nbetter than both\011Father and you!",
  ["65:60e6"] = "Fufufu!\012I'm JANINE, the\nGYM LEADER!\012No, I'm not!\nGotcha, sucker!",
  ["65:6126"] = "I had you fooled…",
  ["65:6139"] = "How will you dis-\ntinguish our real\011LEADER?",
  ["65:6166"] = "Fooled you!\nHahaha!",
  ["65:617b"] = "Ooh… I lost…\nYou're not weak…",
  ["65:6199"] = "Well? Wasn't my\ndisguise perfect?",
  ["65:61bb"] = "I'm JANINE!\012How did you know I\nwas real?\012Let's battle!",
  ["65:61f1"] = "Darn it!\nI wanted to win!",
  ["65:620c"] = "You must be\ngetting tired.",
  ["65:6228"] = "Wahahaha!\012You betcha!\nI'm JANINE!",
  ["65:624a"] = "My disguise was\nright on! Dang!",
  ["65:626b"] = "Hey, you. Was my\ndisguise cute or\011what, huh?",
  ["65:6299"] = "Yo, CHAMP in\nmaking!\012Whoops! Take a\ngood look around\012you. The trainers\nall look like the\011LEADER, JANINE.\012Which of them is\nthe real JANINE?",
  ["65:6325"] = "That was a great\nbattle, trainer\011from JOHTO!",
  ["65:63c3"] = "My grandpa is at \nmy brother BILL's\011on CERULEAN CAPE.",
  ["65:63f9"] = "I saw these weird,\nslow POKéMON on\011CYCLING ROAD.",
  ["65:6494"] = "Hey! You have a\nbrand new kind of\011POKéDEX.\012Did PROF.OAK give\nthat to you?",
  ["65:64dc"] = "I got quite a\nshock at the GYM.\012There were all\nthese girls who\011looked identical.",
  ["65:652e"] = "I'm JANINE! Hocus-\npocus… Poof!",
  ["65:654e"] = "See? I look just\nlike her now!",
  ["65:65e6"] = "My grandpa is the\nSAFARI ZONE WAR-\011DEN.\012At least he was…\012He decided to go\non a vacation and\012took off overseas\nall by himself.\012He quit running\nSAFARI ZONE just\011like that.",
  ["65:6691"] = "Many people were\ndisappointed that\012SAFARI ZONE closed\ndown, but Grandpa\011is so stubborn…",
  ["65:66ea"] = "It's a photo of a\ngrinning old man\012who's surrounded\nby POKéMON.",
  ["65:6726"] = "It's a photo of a\nhuge grassy plain\012with rare POKéMON\nfrolicking in it.",
  ["65:67a1"] = "You're working on\na POKéDEX? That's\012really something.\nDon't give up!",
  ["65:6834"] = "They're fresh out\nof POKé BALLS!\012When will they get\nmore of them?",
  ["65:6873"] = "POKé BALLS are in\nstock! Now I can\011catch POKéMON!",
  ["65:68a0"] = "When I was walking\nin the grass, a\012bug POKéMON poi-\nsoned my POKéMON!\012I just kept going,\nbut then my\011POKéMON fainted.\012You should keep an\nANTIDOTE with you.",
  ["65:698a"] = "It's great. I can\nstore any number\012of POKéMON, and\nit's all free.",
  ["65:69c8"] = "That PC is free\nfor any trainer\011to use.",
  ["65:69f1"] = "The COMMUNICATION\nCENTER upstairs\011was just built.\012But they're still\nfinishing it up.",
  ["65:6a46"] = "The COMMUNICATION\nCENTER upstairs\011was just built.\012I traded POKéMON\nthere already!",
  ["65:6aea"] = "You're trying to\nsee how good you\012are as a POKéMON\ntrainer?\012You better visit\nthe POKéMON GYMS\012all over JOHTO and\ncollect BADGES.",
  ["65:6b65"] = "When I get older,\nI'm going to be a\011GYM LEADER!\012I make my POKéMON\nbattle with my\012friend's to make\nthem tougher!",
  ["65:6c0d"] = "When I was a wee\nlad, I was a hot-\011shot trainer!\012Here's a word of\nadvice: Catch lots\011of POKéMON!\012Treat them all\nwith kindness!",
  ["65:6cc3"] = "POKéMON gain expe-\nrience in battle\012and change their\nform.",
  ["65:6cfc"] = "POKéMON change?\012I would be shocked\nif one did that!",
  ["65:6d82"] = "You know, POKéMON\neat BERRIES.\012Well, my POKéMON\ngot healthier by\011eating a BERRY.\012Here. I'll share\none with you!",
  ["65:6dec"] = "Check trees for\nBERRIES. They just\011drop right off.",
  ["65:6f66"] = "Hello, hello! You\nmust be {PLAYER}.\012PROF.ELM said that\nyou would visit.",
  ["65:6fa8"] = "This is what I\nwant PROF.ELM to\011examine.",
  ["65:6fd2"] = "{PLAYER} received\nMYSTERY EGG.",
  ["65:6feb"] = "I know a couple\nwho run a POKéMON\011DAY-CARE service.\012They gave me that\nEGG.\012I was intrigued,\nso I sent mail to\011PROF.ELM.\012For POKéMON evolu-\ntion, PROF.ELM is\011the authority.",
  ["65:7092"] = "Even PROF.OAK here\nrecognizes that.",
  ["65:70b7"] = "If my assumption\nis correct, PROF.\011ELM will know it.",
  ["65:70ed"] = "You are returning\nto PROF.ELM?\012Here. Your POKéMON\nshould have some\011rest.",
  ["65:7134"] = "I'm depending on\nyou!",
  ["65:714a"] = "Life is delight-\nful! Always, new\012discoveries to be\nmade!",
  ["65:7185"] = "OAK: Aha! So\nyou're {PLAYER}!\012I'm OAK! A POKéMON\nresearcher.\012I was just visit-\ning my old friend\011MR.POKéMON.\012I heard you were\nrunning an errand\012for PROF.ELM, so I\nwaited here.\012Oh! What's this?\nA rare POKéMON!\012Let's see…\012Hm, I see!\012I understand why\nPROF.ELM gave you\012a POKéMON for this\nerrand.\012To researchers\nlike PROF.ELM and\012I, POKéMON are our\nfriends.\012He saw that you\nwould treat your\012POKéMON with love\nand care.\012…Ah!\012You seem to be\ndependable.\012How would you like\nto help me out?\012See? This is the\nlatest version of\011POKéDEX.\012It automatically\nrecords data on\012POKéMON you've\nseen or caught.\012It's a hi-tech\nencyclopedia!",
  ["65:73cc"] = "{PLAYER} received\nPOKéDEX!",
  ["65:73de"] = "Go meet many kinds\nof POKéMON and\012complete that\nPOKéDEX!\012But I've stayed\ntoo long.\012I have to get to\nGOLDENROD for my\011usual radio show.\012{PLAYER}, I'm\ncounting on you!",
  ["65:7476"] = "Hm? That SCALE!\nWhat's that?\011A red GYARADOS?\012That's rare! \nI, I want it…\012{PLAYER}, would you\ncare to trade it?\012I can offer this\nEXP.SHARE I got\011from PROF.OAK.",
  ["65:750d"] = "That's disappoint-\ning. That happens\011to be very rare.",
  ["65:7543"] = "It's packed with\nforeign magazines.\012Can't even read\ntheir titles…",
  ["65:7584"] = "It's a big com-\nputer. Hmm. It's\011broken.",
  ["65:75ac"] = "A whole pile of\nstrange coins!\012Maybe they're from\nanother country…",
  ["65:763a"] = "Hi there!\nDid you visit\011SPROUT TOWER?",
  ["65:7661"] = "I came too far\nout. I'd better\011phone home!",
  ["66:414d"] = "…Tell me some-\nthing.\012Is it true that\nTEAM ROCKET has\011returned?\012What? You beat\nthem? Hah! Quit\011lying.\012You're not joking?\nThen let's see how\011good you are.",
  ["66:41e6"] = "… Humph! Useless\nPOKéMON!\012Listen, you. You\nonly won because\012my POKéMON were\nweak.",
  ["66:4233"] = "I hate the weak.\012POKéMON, trainers.\nIt doesn't matter\011who or what.\012I'm going to be\nstrong and wipe\011out the weak.\012That goes for TEAM\nROCKET too.\012They act big and\ntough in a group.\012But get them\nalone, and they're\011weak.\012I hate them all.\012You stay out of my\nway. A weakling\012like you is only a\ndistraction.",
  ["66:435b"] = "…Humph! I knew\nyou were lying.",
  ["66:437b"] = "It's unsafe to go\nin there, so I'm\011standing guard.\012Aren't I a good\nSamaritan?",
  ["66:43c7"] = "Do you know about\nSLOWPOKETAIL? I\011heard it's tasty!\012Aren't you glad I\ntold you that?",
  ["66:441b"] = "The SLOWPOKE have\ndisappeared from\011town…\012I heard their\nTAILS are being\011sold somewhere.",
  ["66:4473"] = "The SLOWPOKE have\nreturned.\012Knowing them, they\ncould've just been\012goofing off some-\nwhere.",
  ["66:44ce"] = "Did you come to\nget KURT to make\011some BALLS?\012A lot of people do\njust that.",
  ["66:451a"] = "Cut through AZALEA\nand you'll be in\011ILEX FOREST.\012But these skinny\ntrees make it\012impossible to get\nthrough.\012The CHARCOAL MAN's\nPOKéMON can CUT\011down trees.",
  ["66:45b0"] = "SLOWPOKE: …\012…… …… ……",
  ["66:45c3"] = "…… ……Yawn?",
  ["66:45df"] = "ILEX FOREST is\nrestless!\012What is going on?",
  ["66:460b"] = "{PLAYER}, here's\nyour GS BALL back!",
  ["66:4628"] = "Could you go see\nwhy ILEX FOREST is\011so restless?",
  ["66:465a"] = "AZALEA TOWN\nWhere People and\012POKéMON Live in\nHappy Harmony",
  ["66:4693"] = "KURT'S HOUSE",
  ["66:46a1"] = "AZALEA TOWN\nPOKéMON GYM\011LEADER: BUGSY\012The Walking\nBug POKéMON\011Encyclopedia",
  ["66:46e7"] = "SLOWPOKE WELL\012Also known as the\nRAINMAKER WELL.\012Locals believe\nthat a SLOWPOKE's\011yawn summons rain.\012Records show that\na SLOWPOKE's yawn\012ended a drought\n400 years ago.",
  ["66:478d"] = "CHARCOAL KILN",
  ["66:479c"] = "ILEX FOREST\012Enter through the\ngate.",
  ["66:4a69"] = "They built the new\nRADIO TOWER to\012replace the old,\ncreaky one.",
  ["66:4aa9"] = "I know there's a\nnew BIKE SHOP, but\012I can't find it\nanywhere.",
  ["66:4ae6"] = "Is that man in\nblack dressed up\012like a TEAM ROCKET\nmember? How silly!",
  ["66:4b2d"] = "Was that man in\nblack really part\012of TEAM ROCKET? I\ncan't believe it!",
  ["66:4b73"] = "The RADIO TOWER in\nGOLDENROD CITY is\011a landmark.\012They're running a\npromotional cam- \011paign right now.\012They'll modify\nyour POKéGEAR,\012so it can also\nserve as a radio.",
  ["66:4c14"] = "Oh, your POKéGEAR\nworks as a radio!",
  ["66:4c36"] = "E-he-he-he…\012I got in trouble\nfor playing in the\012basement of the\nDEPT.STORE.",
  ["66:4c83"] = "The man at that\nhouse rates your\011POKéMON names.\012He can even rename\nyour POKéMON.",
  ["66:4ccf"] = "Whew! This is one\nbig town. I don't\012know where any-\nthing is.",
  ["66:4d0d"] = "So this is the\nRADIO TOWER…",
  ["66:4d2a"] = "What do you want,\nyou pest? Scram!",
  ["66:4d4e"] = "Stay out of the\nway! Beat it!",
  ["66:4d6d"] = "Take over the\nRADIO TOWER…\012What? It's none of\nyour business!",
  ["66:4daa"] = "POKéMON? They're\nnothing more than\012tools for making\nmoney!",
  ["66:4de2"] = "Our dream will\nsoon come true…\012It was such a long\nstruggle…",
  ["66:4e1f"] = "Hey, brat! You\ndon't belong here!\011Get lost!",
  ["66:4e4b"] = "Come taste the\ntrue terror of\011TEAM ROCKET!",
  ["66:4e77"] = "GOLDENROD CITY\nSTATION",
  ["66:4e8f"] = "GOLDENROD CITY\nRADIO TOWER",
  ["66:4eab"] = "Full Selection of\nPOKéMON Goods!\012GOLDENROD CITY\nDEPT.STORE",
  ["66:4ee4"] = "GOLDENROD CITY\nPOKéMON GYM\011LEADER: WHITNEY\012The Incredibly\nPretty Girl!",
  ["66:4f29"] = "GOLDENROD CITY\012The Festive City\nof Opulent Charm",
  ["66:4f5b"] = "The World is a\nCycle Path!\011BIKE SHOP",
  ["66:4f81"] = "Your Playground!\012GOLDENROD CITY\nGAME CORNER",
  ["66:4fae"] = "NAME RATER\012Get Your POKéMON\nNicknames Rated",
  ["66:4fd8"] = "UNDERGROUND\nENTRANCE",
  ["66:4fee"] = "UNDERGROUND\nENTRANCE",
  ["66:5022"] = "Blooming Beautiful\nFLOWER SHOP",
  ["66:5042"] = "I can teach your\nPOKéMON amazing\012moves if you'd\nlike.\012Should I teach a\nnew move?",
  ["66:5090"] = "It will cost you\n4000 coins. Okay?",
  ["66:50b4"] = "Aww… But they're\namazing…",
  ["66:50ce"] = "Wahahah! You won't\nregret it!\012Which move should\nI teach?",
  ["66:5107"] = "Hm, too bad. I'll\nhave to get some\011cash from home…",
  ["66:513a"] = "If you understand\nwhat's so amazing\012about this move,\nyou've made it as\011a trainer.",
  ["66:518b"] = "Wahahah!\nFarewell, kid!",
  ["66:51a4"] = "B-but…",
  ["66:51ac"] = "…You don't have\nenough coins here…",
  ["66:538d"] = "A little girl who\nis an expert at\012mimicking people\nlives here.\012She even mimics\nthe people she's\012conversing with.\nIt's confusing.",
  ["66:540d"] = "The COPYCAT girl\nlooked unhappy.\012She said she lost\nher favorite POKé\011DOLL--CLEFAIRY.",
  ["66:5460"] = "You came out from\nJOHTO?\012You can zip back\nhome if the MAGNET\011TRAIN's running.",
  ["66:54ae"] = "You came out from\nJOHTO?\012You can zip back\nhome by hopping on\011the MAGNET TRAIN.",
  ["66:54fe"] = "I went to the GYM,\nraring for battles\011against trainers…\012It turns out, I\nstumbled into the\012unused GYM next\ndoor.\012Boy, I was pretty\nembarrassed.",
  ["66:558e"] = "This is SILPH CO.,\nfamous for POKéMON\011merchandise.\012In the past, TEAM\nROCKET wanted the\012company because of\nthat.",
  ["66:55fc"] = "Chew… Chew…\012I hear there's big\ntrouble brewing at\011the POWER PLANT.\012Chew… Chew…",
  ["66:564b"] = "Chew… Chew…\012I hear there was\nbig trouble at the\011POWER PLANT.\012Chew… Chew…\nHaaah, I'm full!",
  ["66:56a5"] = "Going into an\nalley for the\012first time makes\nme sorta anxious.",
  ["66:56e5"] = "There's a place\ncalled TRAINER\012HOUSE in VIRIDIAN\nwhere trainers\012gather from all\nover the place.",
  ["66:5745"] = "Our city was\nfeatured on a\011radio program.\012It's nice to hear\npraise for your\012city, but it's a\nbit embarrassing\011too.",
  ["66:57b7"] = "SAFFRON CITY\012Shining, Golden\nLand of Commerce",
  ["66:57e6"] = "SAFFRON CITY\nPOKéMON GYM\011LEADER: SABRINA\012The Master of\nPsychic POKéMON!",
  ["66:5829"] = "Everyone Welcome!\nFIGHTING DOJO",
  ["66:584a"] = "SILPH CO.\nOFFICE BUILDING",
  ["66:5865"] = "MR.PSYCHIC'S\nHOUSE",
  ["66:5879"] = "SAFFRON CITY\nMAGNET TRAIN\011STATION",
  ["66:599c"] = "I heard that a red\nGYARADOS appeared\011at the LAKE.\012That's odd, since\neven ordinary\012GYARADOS are rare\nin that lake…",
  ["66:5a0e"] = "My favorite radio\nprogram? I'd say\011POKéMON MUSIC.",
  ["66:5a3d"] = "I've been hearing\nlaughter on the\012radio…\nIt's creepy.",
  ["66:5b8d"] = "POKéMON have many\nexperiences in\012their lives, just \nlike we do. \012I, too, have seen\nand suffered much\011in my life.\012Since I am your\nelder, let me show\011you what I mean.\012I have been with\nPOKéMON since\012before you were\nborn.\012I do not lose\neasily.\012I, PRYCE--the\nwinter trainer--\012shall demonstrate\nmy power!",
  ["66:5cb3"] = "Ah, I am impressed\nby your prowess.\012With your strong\nwill, I know you\012will overcome all\nlife's obstacles.\012You are worthy of\nthis BADGE!",
  ["66:5d3b"] = "{PLAYER} received\nGLACIERBADGE.",
  ["66:5d55"] = "That BADGE will\nraise the SPECIAL\011stats of POKéMON.\012It also lets your\nPOKéMON use WHIRL-\011POOL to get across\011real whirlpools.\012And this… This is\na gift from me!",
  ["66:5def"] = "That TM contains\nICY WIND.\012It inflicts damage\nand lowers speed.\012It demonstrates\nthe harshness of\011winter.",
  ["66:5e59"] = "When the ice and\nsnow melt, spring\011arrives.\012You and your POKé-\nMON will be to-\012gether for many\nyears to come.\012Cherish your time\ntogether!",
  ["66:5ee1"] = "I'll freeze your\nPOKéMON, so you\011can't do a thing!",
  ["66:5f10"] = "Darn. I couldn't\ndo a thing.",
  ["66:5f2d"] = "I think there's a\nmove a POKéMON\012can use while it's\nfrozen.",
  ["66:5f65"] = "This GYM has a\nslippery floor.\012It's fun, isn't\nit?\012But hey--we're\nnot playing games\011here!",
  ["66:5fbd"] = "Do you see how\nserious we are?",
  ["66:5fdd"] = "This GYM is great.\nI love boarding\011with my POKéMON!",
  ["66:600f"] = "I know PRYCE's\nsecret.",
  ["66:6026"] = "OK. I'll tell you\nPRYCE's secret.",
  ["66:6047"] = "The secret behind\nPRYCE's power…\012He meditates under\na waterfall daily\012to strengthen his\nmind and body.",
  ["66:60ae"] = "To get to PRYCE,\nour GYM LEADER,\012you need to think\nbefore you skate.",
  ["66:60f4"] = "I wouldn't lose to\nyou in skiing!",
  ["66:6116"] = "If you don't skate\nwith precision,\012you won't get far\nin this GYM.",
  ["66:6157"] = "Check out my\nparallel turn!",
  ["66:6174"] = "No! You made me\nwipe out!",
  ["66:618f"] = "I shouldn't have\nbeen bragging\011about my skiing…",
  ["66:61bf"] = "PRYCE is a veteran\nwho has trained\012POKéMON for some\n50 years.\012He's said to be\ngood at freezing\012opponents with\nice-type moves.\012That means you\nshould melt him\012with your burning\nambition!",
  ["66:6275"] = "PRYCE is some-\nthing, but you're\011something else!\012That was a hot\nbattle that\012bridged the gen-\neration gap!",
  ["66:6362"] = "What's this? TEAM\nROCKET has come\011back?\012I saw some men in\nblack at LAKE OF\011RAGE…",
  ["66:63b3"] = "I stop my POKéMON\nfrom evolving too\011early.\012I make them learn\ncertain moves be-\011fore I let them\011evolve.",
  ["66:6418"] = "POKéMON do become\nstronger when they\012evolve, but they\nalso learn moves\011more slowly.",
  ["66:64b8"] = "MT.MORTAR is like\na maze inside.\012Be careful. Don't\nget lost in there.",
  ["66:654b"] = "…You have strayed\nfar…\012Here I have medi-\ntated. Inside me,\012a new power has\nbeen awakened.\012Let me share my\npower with your\012POKéMON.\nTake this, child.",
  ["66:65de"] = "Do you see it? It\nis HIDDEN POWER!\012It draws out the\npower of POKéMON\011for attacking.\012Remember this: its\ntype and power de-\011pend on the POKé-\011MON using it.",
  ["66:6673"] = "I am meditating…",
  ["66:672e"] = "LAKE OF RAGE is\nactually a crater\012made by rampaging\nGYARADOS.\012The crater filled\nup with rainwater\012and the LAKE was\nformed.\012That's the story\npassed on from my\012Grandpa's great-\ngreat-grandpa.\012It used to be that\nyou could catch\012lively MAGIKARP\nthere, but…\012I don't understand\nwhat's happening.",
  ["66:684d"] = "The LAKE hasn't\nbeen normal since\012those men wearing\nblack arrived.",
  ["66:6890"] = "LAKE OF RAGE is\nback to normal.\012The MAGIKARP have\nreturned.\012I may yet realize\nmy dream of see-\011ing the world's\011largest MAGIKARP.\012Do you have a ROD?\nPlease help me if\011you do.",
  ["66:693e"] = "Ah, you have a\nMAGIKARP! Let's\012see how big that\nbaby is.",
  ["66:6977"] = "Wow! This one is\noutstanding!\012I tip my hat to\nyou!\012Take this as a\nmemento!",
  ["66:69c3"] = "The record is the\nimportant thing.\012Think of that as\na bonus!",
  ["66:6a01"] = "Wow! This one is\noutstanding!\012…I wish I could\nsay that, but I've\012seen a bigger one\nbefore.",
  ["66:6a5c"] = "What? That's not a\nMAGIKARP!",
  ["66:6a79"] = "Oh… So you didn't\nget one good\012enough to show me?\nMaybe next time.",
  ["66:6b1f"] = "Only people headed\nup to LAKE OF RAGE\012have been through\nhere lately.",
  ["66:6b65"] = "Nobody goes up to\nLAKE OF RAGE these\011days.",
  ["66:6cd2"] = "Hold it there,\nkiddo!\012The toll is ¥1000\nto go through.",
  ["66:6d0a"] = "Thank you very\nmuch!",
  ["66:6d20"] = "Then pay what you\nhave, please.",
  ["66:6d41"] = "He-he-he. We're\nmaking a bundle.\012Everyone wants to\nsee what's going\012on up at LAKE OF\nRAGE.",
  ["66:6d9b"] = "I got chased from\nmy post by these\011thugs in black.\012They left this\nbehind.\012It makes me uncom-\nfortable. Could\011you take it away?",
  ["66:6e2d"] = "Use this gate to\navoid walking in\011the grass.",
  ["66:6ec0"] = "Hi!\012RED's been away\nfor a long time.\012He hasn't called\neither, so I have\012no idea where he\nis or what he's\011been doing.\012They say that no\nword is proof that\012he's doing fine,\nbut I do worry\011about him.",
  ["66:6f81"] = "I worry about RED\ngetting hurt or\012sick, but he's a\nboy. I'm proud\012that he is doing\nwhat he wants to\012do.",
  ["66:6fe8"] = "They have programs\nthat aren't shown\011in JOHTO…",
  ["66:7050"] = "{PLAYER} played the\nN64.\012Better get going--\nno time to lose!",
  ["66:7087"] = "It looks like it\nhasn't been used\011in a long time…",
  ["66:7130"] = "DAISY: Hi! My kid\nbrother is the GYM\012LEADER in VIRIDIAN\nCITY.\012But he goes out\nof town so often,\012it causes problems\nfor the trainers.",
  ["66:71b6"] = "DAISY: Hi! Good\ntiming. I'm about\011to have some tea.\012Would you like to\njoin me?\012Oh, your POKéMON\nare a bit dirty.\012Would you like me\nto groom one?",
  ["66:7244"] = "DAISY: Which one\nshould I groom?",
  ["66:7266"] = "DAISY: OK, I'll\nget it looking\011nice in no time.",
  ["66:7296"] = "{STRBUF} looks\ncontent.",
  ["66:72aa"] = "DAISY: There you\ngo! All done.\012See? Doesn't it\nlook nice?\012It's such a cute\nPOKéMON.",
  ["66:72fa"] = "DAISY: I always\nhave tea around\012this time. Come\njoin me.",
  ["66:7334"] = "DAISY: You don't\nwant to have one\012groomed? OK, we'll\njust have tea.",
  ["66:7377"] = "DAISY: Oh, sorry.\nI honestly can't\011groom an EGG.",
  ["66:7427"] = "OAK: Ah, {PLAYER}!\nIt's good of you\012to come all this\nway to KANTO.\012What do you think\nof the trainers\012out here?\nPretty tough, huh?",
  ["66:74a2"] = "How is your POKé-\nDEX coming?\012Let's see…",
  ["66:74c8"] = "If you're in the\narea, I hope you\011come visit again.",
  ["66:74fc"] = "OAK: Wow! That's\nexcellent!\012You collected the\nBADGES of GYMS in\011KANTO. Well done!\012I was right in my\nassessment of you.\012Tell you what,\n{PLAYER}. I'll make\012arrangements so\nthat you can go to\011MT.SILVER.\012MT.SILVER is a big\nmountain that is\012home to many wild\nPOKéMON.\012It's too dangerous\nfor your average\012trainer, so it's\noff limits. But\012we can make an\nexception in your\011case, {PLAYER}.\012Go up to INDIGO\nPLATEAU. You can\012reach MT.SILVER\nfrom there.",
  ["66:76a2"] = "OAK: Hmm? You're\nnot collecting\011KANTO GYM BADGES?\012The GYM LEADERS in\nKANTO are as tough\012as any you battled\nin JOHTO.\012I recommend that\nyou challenge\011them.",
  ["66:773c"] = "OAK: Ah, you're\ncollecting KANTO\011GYM BADGES.\012I imagine that\nit's hard, but the\012experience is sure\nto help you.\012Come see me when\nyou get them all.\012I'll have a gift\nfor you.\012Keep trying hard,\n{PLAYER}!",
  ["66:77fb"] = "The PROF's POKéMON\nTALK radio program\012isn't aired here\nin KANTO.\012It's a shame--I'd\nlike to hear it.",
  ["66:7859"] = "Thanks to your\nwork on the POKé-\011DEX, the PROF's\012research is coming\nalong great.",
  ["66:78a7"] = "Don't tell anyone,\nbut PROF.OAK'S\012POKéMON TALK isn't\na live broadcast.",
  ["66:78ea"] = "Press START to\nopen the MENU.",
  ["66:7909"] = "The SAVE option is\non the MENU.\012Use it in a timely\nmanner.",
  ["66:7945"] = "There's nothing in\nhere…",
  ["66:795e"] = "There's an e-mail\nmessage on the PC.\012…\012PROF.OAK, how is\nyour research\011coming along?\012I'm still plugging\naway.\012I heard rumors\nthat {PLAYER} is\012getting quite a\nreputation.\012I'm delighted to\nhear that.\012ELM in NEW BARK\nTOWN 8-)",
  ["67:41e3"] = "You're a rookie\ntrainer, aren't\011you? I can tell!\012That's OK! Every-\none is a rookie\011at some point!\012If you'd like, I\ncan teach you a\011few things.",
  ["67:426f"] = "OK, then!\nFollow me!",
  ["67:4285"] = "This is a POKéMON\nCENTER. They heal\012your POKéMON in no\ntime at all.\012You'll be relying\non them a lot, so\012you better learn\nabout them.",
  ["67:4304"] = "This is a POKéMON\nMART.\012They sell BALLS\nfor catching wild\012POKéMON and other\nuseful items.",
  ["67:4359"] = "ROUTE 30 is out\nthis way.\012Trainers will be\nbattling their\012prized POKéMON\nthere.",
  ["67:43a7"] = "This is the sea,\nas you can see.\012Some POKéMON are\nfound only in\011water.",
  ["67:43ec"] = "Here…\012It's my house!\nThanks for your\011company.\012Let me give you a\nsmall gift.",
  ["67:4438"] = "{PLAYER}'s POKéGEAR\nnow has a MAP!",
  ["67:4451"] = "POKéGEAR becomes\nmore useful as you\011add CARDS.\012I wish you luck on\nyour journey!",
  ["67:449f"] = "Oh… It's something\nI enjoy doing…\012Fine. Come see me\nwhen you like.",
  ["67:44e2"] = "…… …… ……\012You got a POKéMON\nat the LAB.\012What a waste.\nA wimp like you.\012…… …… ……\012Don't you get what\nI'm saying?\012Well, I too, have\na good POKéMON.\012I'll show you\nwhat I mean!",
  ["67:457f"] = "Humph. Are you\nhappy you won?",
  ["67:459e"] = "…… …… ……\012My name's ???.\012I'm going to be\nthe world's great-\011est POKéMON\011trainer.",
  ["67:45e6"] = "Humph. That was a\nwaste of time.",
  ["67:4608"] = "…… …… ……\012My name's ???.\012I'm going to be\nthe world's great-\011est POKéMON\011trainer.",
  ["67:4650"] = "Did you talk to\nthe old man by the\011POKéMON CENTER?\012He'll put a MAP of\nJOHTO on your\011POKéGEAR.",
  ["67:46a8"] = "When you're with\nPOKéMON, going\011anywhere is fun.",
  ["67:46d6"] = "MR.POKéMON's house\nis still farther\011up ahead.",
  ["67:4701"] = "I battled the\ntrainers on the\011road.\012My POKéMON lost.\nThey're a mess! I\012must take them to\na POKéMON CENTER.",
  ["67:4766"] = "A POKéMON I caught\nhad an item.\012I think it's\nMYSTIC WATER.\012I don't need it,\nso do you want it?",
  ["67:47c1"] = "Back to fishing\nfor me, then.",
  ["67:47e0"] = "CHERRYGROVE CITY\012The City of Cute,\nFragrant Flowers",
  ["67:4815"] = "GUIDE GENT'S HOUSE",
  ["67:4a80"] = "I've been getting\nPOKéMON data off\012my radio. I think\nI'm good.",
  ["67:4abb"] = "I give!",
  ["67:4ac4"] = "Music on the radio\nchanges the moods\011of wild POKéMON.",
  ["67:4af8"] = "I'm gonna show my\ngirlfriend I'm hot\011stuff!",
  ["67:4b23"] = "I wish you would\nhave lost for me…",
  ["67:4b47"] = "I was humiliated\nin front of my\011girlfriend…",
  ["67:4b74"] = "My boyfriend's\nweak, so I can't\011rely on him.",
  ["67:4ba0"] = "Oh, my! You're so\nstrong!",
  ["67:4bba"] = "I can count on my\nPOKéMON more than\011my boyfriend.",
  ["67:4bea"] = "Are you going to\nthe GYM? Me too!",
  ["67:4c0d"] = "Oh. I couldn't\nwin…",
  ["67:4c21"] = "The GYM BADGES are\npretty. I collect\011them.",
  ["67:4c4d"] = "What kinds of\nBALLS do you use?",
  ["67:4c6e"] = "Yikes! Not fast\nenough!",
  ["67:4c87"] = "Some POKéMON flee\nright away.\012Try catching them\nwith KURT's FAST\011BALL.\012Whenever I find a\nWHT APRICORN, I\011take it to KURT.\012He turns it into a\ncustom BALL.",
  ["67:4d1e"] = "Behold my graceful\nBALL dexterity!",
  ["67:4d42"] = "Whew! That was a\njolt!",
  ["67:4d5a"] = "I was going to\ndazzle you with my\011prize POKéMON.\012But your prowess\nelectrified me!",
  ["67:4daa"] = "I'll go anywhere\nif bug POKéMON\011appear there.",
  ["67:4dd5"] = "Huh? I shouldn't\nhave lost that…",
  ["67:4df6"] = "My VENONAT won me\nthe Bug-Catching\012Contest at the\nNATIONAL PARK.",
  ["67:4e38"] = "Wow… Look at all\nthose YANMA!\012I'm so blown away,\nI can't move.",
  ["67:4e76"] = "I'm practicing my\nfire breathing.",
  ["67:4e98"] = "Ow! I scorched the\ntip of my nose!",
  ["67:4ebc"] = "The POKéMON March\non the radio lures\011wild POKéMON.",
  ["67:4eea"] = "Danger lurks in\nthe night!",
  ["67:4f06"] = "Whoops!",
  ["67:4f0f"] = "You know, night-\ntime is fun in its\011own ways.\012But don't overdo\nit, OK?",
  ["67:4f56"] = "Your POKéMON look\npretty tough.\012You could go any-\nwhere safely.",
  ["67:4f94"] = "ROUTE 35",
  ["67:526a"] = "I love POKéMON!\012That's why I\nstarted--and why\012I'll keep on col-\nlecting POKéMON!",
  ["67:52b4"] = "How could you do\nthis to me?",
  ["67:52d2"] = "What else do I\nlike besides\011POKéMON?\012MARY on the radio.\nI bet she's cute!",
  ["67:5319"] = "Hey! Do you have\nany rare POKéMON?",
  ["67:533a"] = "Oh, my poor POKé-\nMON! Darlings!",
  ["67:5359"] = "I'd be happy just\nto own a single\011rare POKéMON.",
  ["67:5386"] = "Would you get\nthis?\012Some {RIVAL} guy\nmade fun of my\011POKéMON!\012Darn it! My POKé-\nMON's great!",
  ["67:53d6"] = "My NIDOKING did\npretty right on!",
  ["67:53f8"] = "It's okay for\npeople to like\012different types\nof POKéMON.\012POKéMON isn't just\nabout having the\011most powerful one.",
  ["67:5461"] = "I'm in a slump.\012Maybe it's the\ngear I'm using.\012Let's battle for a\nchange of pace!",
  ["67:54b0"] = "I lost, but I feel\nbetter anyway.",
  ["67:54d3"] = "KURT's LURE BALL\nis the best for\012catching hooked\nPOKéMON.\012It's much more\neffective than a\011ULTRA BALL.",
  ["67:5535"] = "I can do so much\nwith my POKéMON--\011it's super-fun!",
  ["67:5565"] = "Losing isn't fun\nat all…",
  ["67:557e"] = "What is going on\nat LAKE OF RAGE?\012We were planning\nto camp there.",
  ["67:55c1"] = "Are you going to\nLAKE OF RAGE too?\012Let's play for a \nlittle while!",
  ["67:5604"] = "I played too much!",
  ["67:5618"] = "I'm having a pic-\nnic with POKéMON.\012Won't you join us?",
  ["67:564b"] = "Isn't my CLEFAIRY\njust the most\011adorable thing?",
  ["67:567b"] = "ROUTE 43\012LAKE OF RAGE -\nMAHOGANY TOWN",
  ["67:56a2"] = "ROUTE 43\012LAKE OF RAGE -\nMAHOGANY TOWN",
  ["67:56c9"] = "TRAINER TIPS\012All POKéMON have\npros and cons\012depending on their\ntypes.\012If their types\ndiffer, a higher-\012level POKéMON may\nlose in battle.\012Learn which types\nare strong and\012weak against your\nPOKéMON's type.",
  ["67:5a4b"] = "Aack! You made me\nlose a POLIWAG!\012What are you going\nto do about it?",
  ["67:5a91"] = "Just forget about\nit.",
  ["67:5aa8"] = "That POLIWAG that\ngot away…\011It was huge.\012I swear it must've\nbeen 16 feet long!",
  ["67:5af7"] = "I fish until I\ncan't anymore.\012I also battle\nuntil I drop.\012That's my\nrelationship\011with my POKéMON.",
  ["67:5b55"] = "Hmmmm… \nThis isn't right.",
  ["67:5b6f"] = "That's 100 wins\nto 101 losses.\012I won't battle\nagain for a while.",
  ["67:5baf"] = "Do you know about\nthe legendary bird\011POKéMON?",
  ["67:5bdb"] = "Whew! You're hot\nstuff.",
  ["67:5bf3"] = "ARTICUNO, ZAPDOS\nand MOLTRES are\012the three legend-\nary bird POKéMON.\012I heard there are\nother legendary\011birds, though.",
  ["67:5c67"] = "Why can't I ever\nbeat you?\012Oh yeah, here you\ngo. It's that gift\012I couldn't give\nyou last time.",
  ["67:5cc4"] = "I'm gonna win,\nfor sure!",
  ["67:5cdd"] = "Arrgh… That's a\nshocking loss…",
  ["67:5cfc"] = "It's important to\nhave conviction\011on your side.",
  ["67:5d2c"] = "I'll do anything\nto get my hands on\011rare POKéMON!",
  ["67:5d5b"] = "Oooh, your POKéMON\nare so appealing.",
  ["67:5d7e"] = "If a POKéMON has\ndifferent colors\012from usual, it's\nmore valuable.\012What? You mean\nthat's not true?",
  ["67:5ddc"] = "I can tell you're\na good trainer by\011looking at you.\012I'm good at POKé-\nMON, and I can see\011that you are too.",
  ["67:5e43"] = "Tch! It's a total\nloss on my part.",
  ["67:5e66"] = "Wow. You have a\nlot of BADGES.\012No wonder you're\nso tough.\012I wonder if\nECRUTEAK GYM's\012MORTY is still in\ntraining?\012He really hammered\nme.",
  ["67:5eed"] = "You look strong.\012Good trainers seek\ntough opponents\011instinctively.",
  ["67:5f31"] = "Nope! This won't\ndo at all.",
  ["67:5f4d"] = "We all get better\nby experiencing\011many battles.\012I battled a lot to\nbecome what I am\011today--an elite.",
  ["67:5fb3"] = "ROUTE 44\nICE PATH AHEAD",
  ["67:5fcc"] = "ROUTE 44\012MAHOGANY TOWN -\nBLACKTHORN CITY",
  ["67:62a1"] = "Be prepared for\nanything!\012Let me see if your\nPOKéMON have been\011raised properly!",
  ["67:62ef"] = "Oh, I lost that!",
  ["67:6301"] = "I'll head back to\nBLACKTHORN's ICE\012PATH and train\nsome more.",
  ["67:633d"] = "Yo! You're spunky!\nBut you know what?\012When it comes to\nsheer spunkiness,\011I'm the man!",
  ["67:6392"] = "My POKéMON weren't\nspunky enough!",
  ["67:63b1"] = "Boy, do I love\nHP UP! Mmmm, yum!\012I keep drinking my\nPOKéMON's!\012I can't help it!",
  ["67:63fd"] = "My POKéMON are\npower packed!",
  ["67:6418"] = "Wahahah! I'm the\nbig loser!",
  ["67:6434"] = "I'm not much good\nat thinking, see?\012So, I just plow\nahead with power!",
  ["67:647a"] = "Why do I climb\nmountains?\012Because they're\nthere.\012Why do I train\nPOKéMON?\012Because they're\nthere!",
  ["67:64d6"] = "Losses…\nThey're there too!",
  ["67:64f1"] = "The best thing to\never happen to me\012was discovering\nPOKéMON.",
  ["67:652c"] = "I just can't find\na way to win!\012Keep it up!\012Oh, and take this\n--it's the gift\012you couldn't take\nwhen we last met.",
  ["67:659c"] = "I was training\nhere alone.\012Behold the fruits\nof my labor!",
  ["67:65d7"] = "Waaaargh!",
  ["67:65e2"] = "This calls for\nextreme measures.\012I must take to the\nhills and train in\011solitude.",
  ["67:6634"] = "I'm going to train\na bit more before\011I break for lunch.",
  ["67:666c"] = "We had plenty of\nrest at lunch, so\012now we're all\nready to go again!\012We're going to\ntrain again!",
  ["67:66cb"] = "What are your\nthoughts on rais-\011ing POKéMON?",
  ["67:66f6"] = "You've won my\nrespect.",
  ["67:670d"] = "I see you're rais-\ning your POKéMON\011with care.\012The bond you build\nwill save you in\011tough situations.",
  ["67:676f"] = "What is your\nbattle strategy?\012It is foolish to\nuse strong moves\011indiscriminately.",
  ["67:67c2"] = "Fine. I lost.",
  ["67:67d1"] = "I'm not in favor\nof overly power-\011ful moves.\012I want to win, but\nI also don't want\011to harm POKéMON.",
  ["67:687f"] = "I'm really, really\ntough!",
  ["67:6899"] = "I was tough at the\nBATTLE TOWER…",
  ["67:68bb"] = "Have you been to\nthe BATTLE TOWER?\012I never, ever lose\nthere, but…",
  ["67:68fe"] = "ROUTE 45\nMOUNTAIN RD. AHEAD",
  ["67:6a7b"] = "Have you ever gone\nswimming in the\011sea at night?",
  ["67:6aad"] = "Glub…",
  ["67:6ab4"] = "At night, the sea\nturns black. It\012feels like it will\nswallow you up.",
  ["67:6afa"] = "Pant, pant…\nJust… a little…\012farther… to…\nFUCHSIA…",
  ["67:6b2d"] = "I'm drowning!",
  ["67:6b3b"] = "I… asked my girl-\nfriend to swim to\011FUCHSIA… Gasp…",
  ["67:6b6f"] = "I'm disgusted by\nwimpy people!",
  ["67:6b8e"] = "I could beat you\nat swimming…",
  ["67:6bad"] = "It's a quick swim\nbetween FUCHSIA\012and SEAFOAM IS-\nLANDS…\012Sheesh, some big\nman my boyfriend\012is! What a wimp!",
  ["67:6c19"] = "Swimming?\nI'm lousy at it.\012I'm just splashing\naround in these\011shallow waters.",
  ["67:6c66"] = "I thought I could\nwin.",
  ["67:6c7e"] = "I might be bad at\nswimming, but I\011love the sea.",
  ["67:6caf"] = "Sorry. This road\nis closed for\011construction.\012If you want to get\nto CINNABAR, you'd\012better go south\nfrom PALLET TOWN.",
  ["67:6d24"] = "I'm all sweaty.\nTime for a swim!",
  ["67:6d45"] = "Who knows how long\nit would take to\011move this boulder…",
  ["67:6d7d"] = "The roadwork is\nfinally finished.\012Now I can go\nfishing again.",
  ["67:6dbc"] = "ROUTE 19\012FUCHSIA CITY -\nSEAFOAM ISLANDS",
  ["67:6de5"] = "Please be careful\nif you are swim-\011ming to SEAFOAM\011ISLANDS.\012FUCHSIA POLICE",
  ["67:7006"] = "MISTY: Aww! Why\ndid you have to\012show up and bug us\nnow?\012Do you know what\nthey call people\011like you?\012Pests! You heard\nme right, pest!\012…\012…Oh? Those BADGES\nyou have… Are they\011JOHTO GYM BADGES?\012If you have eight,\nyou must be good.\012OK, then. Come to\nCERULEAN GYM.\012I'll be happy to\ntake you on.\012I'm MISTY, the\nGYM LEADER in\011CERULEAN.",
  ["67:714d"] = "Beat the six of us\ntrainers to win a\011fabulous prize!\012Think you've got\nwhat it takes?",
  ["67:71a2"] = "Whoo! Good stuff.",
  ["67:71b5"] = "I did my best.\nI have no regrets.",
  ["67:71d8"] = "I'm second.\nNow it's serious!",
  ["67:71f5"] = "How could I lose?",
  ["67:7208"] = "I did my best.\nI have no regrets.",
  ["67:722b"] = "Here's No. 3!\nI won't be easy.",
  ["67:7249"] = "Ow! Stomped flat!",
  ["67:725c"] = "I did my best.\nI have no regrets.",
  ["67:727f"] = "I'm No. 4!\nGetting tired?",
  ["67:7299"] = "I lost too…",
  ["67:72a6"] = "I did my best.\nI have no regrets.",
  ["67:72c9"] = "OK! I'm No. 5.\nI'll stomp you!",
  ["67:72e7"] = "Whoa! Too much.",
  ["67:72f8"] = "I did my best.\nI have no regrets.",
  ["67:731b"] = "I'm the last in\nline, but I tell\011you, I'm tough!",
  ["67:734b"] = "You're kidding.",
  ["67:735b"] = "I did my best.\nI have no regrets.",
  ["67:737e"] = "Mufufufu…\012I have nothing to\ndo with the six-\011pack trainers.\012I waited here to\nbeat you when you\012were tired out by\nall the battles.",
  ["67:7401"] = "Aren't you tired\nat all?",
  ["67:741a"] = "I'm sorry… I won't\ncheat anymore…",
  ["67:743b"] = "You took on one\nmore battle than\012you expected, but\nyou won anyway.\012As promised, you\nwin a prize.",
  ["67:749d"] = "But after seeing\nhow you battle, I\012want to see how\nI'll fare.\012How about it? Let\nme take you on.",
  ["67:74fd"] = "I've never had a\nbattle this good!",
  ["67:7520"] = "That was a great\nbattle!\012You and your POKé-\nMON are truly out-\011standing!",
  ["67:7567"] = "SEA COTTAGE\nBILL'S HOUSE",
  ["68:40f1"] = "You crossed the\nsea to get here?\012That must have\nbeen hard.\012It would be much\neasier if your\012POKéMON knew how\nto FLY…",
  ["68:4163"] = "But you can't use\nFLY without this\011city's GYM BADGE.\012If you beat the\nGYM LEADER here,\011come see me.\012I'll have a nice\ngift for you.",
  ["68:41e3"] = "That's CIANWOOD's\nGYM BADGE!\012Then you should\ntake this HM.",
  ["68:421d"] = "Teach FLY to your\nPOKéMON.\012You will be able\nto FLY instantly\012to anywhere you \nhave visited.",
  ["68:4277"] = "My husband lost to\nyou, so he needs\011to train harder.\012That's good, since\nhe was getting a\011little chubby.",
  ["68:42df"] = "If you use FLY,\nyou can get back\012to OLIVINE in-\nstantly.",
  ["68:4319"] = "Boulders to the\nnorth of town can\011be crushed.\012They may be hiding\nsomething.\012Your POKéMON could\nuse ROCK SMASH to\011break them.",
  ["68:4394"] = "CHUCK, the GYM\nLEADER, spars with\012his fighting POKé-\nMON.",
  ["68:4433"] = "EUSINE: Yo,\n{PLAYER}.\012Wasn't that\nSUICUNE just now?\012I only caught a\nquick glimpse, but\012I thought I saw\nSUICUNE running on\011the waves.\012SUICUNE is beau-\ntiful and grand.\012And it races\nthrough towns and\012roads at simply\nawesome speeds.\012It's wonderful…\012I want to see\nSUICUNE up close…\012I've decided.\012I'll battle you as\na trainer to earn\011SUICUNE's respect!\012Come on, {PLAYER}.\nLet's battle now!",
  ["68:45a1"] = "I hate to admit\nit, but you win.",
  ["68:45c3"] = "You're amazing,\n{PLAYER}!\012No wonder POKéMON\ngravitate to you.\012I get it now.\012I'm going to keep\nsearching for\011SUICUNE.\012I'm sure we'll see\neach other again.\012See you around!",
  ["68:4660"] = "CIANWOOD CITY\012A Port Surrounded\nby Rough Seas",
  ["68:468f"] = "CIANWOOD CITY\nPOKéMON GYM\012LEADER: CHUCK\012His Roaring Fists\nDo the Talking",
  ["68:46d6"] = "500 Years of\nTradition\012CIANWOOD CITY\nPHARMACY\012We Await Your\nMedicinal Queries",
  ["68:4725"] = "CIANWOOD CITY\nPHOTO STUDIO\012Take a Snapshot as\na Keepsake!",
  ["68:4760"] = "THE POKé SEER\nAHEAD",
  ["68:4a6b"] = "Hey!",
  ["68:4a71"] = "Do you know what\nyou just did?\012You've taken your\nfirst step into\011KANTO.\012Check your POKé-\nGEAR MAP and see.",
  ["68:4ad9"] = "You look pretty\nstrong.\011Let me battle you!",
  ["68:4b05"] = "Yow!",
  ["68:4b0b"] = "If you prevail on\nthis harsh trek,\012the truth will be\nrevealed!\012Heh, sorry, I just\nwanted to say\011something cool.",
  ["68:4b7c"] = "Hm? You're good,\naren't you?",
  ["68:4b98"] = "Just as I thought!",
  ["68:4bac"] = "A good trainer can\nrecognize other\011good trainers.",
  ["68:4bdf"] = "You shouldn't\nunderestimate the\012wild POKéMON in\nthese parts.",
  ["68:4c19"] = "Oh! You're much\ntoo strong!",
  ["68:4c35"] = "You're just a kid,\nbut you're not to\012be underestimated\neither.",
  ["68:4c73"] = "It's rare to see\nanyone come here.\012Are you training\non your own?",
  ["68:4cb4"] = "Oh! You're really\nstrong!",
  ["68:4cce"] = "I'm checking out\npre- and post-\011evolution POKéMON.\012Evolution really\ndoes make POKéMON\011stronger.\012But evolved forms\nalso learn moves\011later on.",
  ["68:4d55"] = "Don't say a thing!\012Let me guess what\nyou're thinking.\012Mmmmmmm…\012I got it! You're\non the POKéMON\011LEAGUE challenge!",
  ["68:4dc1"] = "You're too much!",
  ["68:4dd2"] = "With your skills,\nyou'll do well at\011the LEAGUE.\012That's what my\npremonition says.",
  ["68:4e22"] = "Tweet! Tweet!\nTetweet!",
  ["68:4e3a"] = "Tweet!",
  ["68:4e42"] = "BIRD KEEPERS like\nme mimic bird\012whistles to com-\nmand POKéMON.",
  ["68:4e7f"] = "TOHJO FALLS\012THE LINK BETWEEN\nKANTO AND JOHTO",
  ["68:50a7"] = "POKéMON hide in\nthe grass. Who\012knows when they'll\npop out…",
  ["68:50df"] = "I've seen you a\ncouple times. How\012many POKéMON have\nyou caught?\012Would you like me\nto show you how to\011catch POKéMON?",
  ["68:514d"] = "That's how you do\nit.\012If you weaken them\nfirst, POKéMON are\011easier to catch.",
  ["68:5197"] = "Oh. Fine, then.\012Anyway, if you\nwant to catch\012POKéMON, you have\nto walk a lot.",
  ["68:51e3"] = "Huh? You want me\nto show you how to\011catch POKéMON?",
  ["68:5214"] = "Yo. How are your\nPOKéMON?\012If they're weak\nand not ready for\012battle, keep out\nof the grass.",
  ["68:526c"] = "See those ledges?\nIt's scary to jump\011off them.\012But you can go to\nNEW BARK without\012walking through\nthe grass.",
  ["68:52d9"] = "I wanted to take a\nbreak, so I saved\012to record my\nprogress.",
  ["68:534c"] = "I'm waiting for\nPOKéMON that\012appear only at\nnight.",
  ["68:537c"] = "I'm waiting for\nPOKéMON that\012appear only in the\nmorning.",
  ["68:53b2"] = "TUSCANY: I do be-\nlieve that this is\012the first time\nwe've met?\012Please allow me to\nintroduce myself.\012I am TUSCANY of\nTuesday.",
  ["68:542f"] = "By way of intro-\nduction, please\012accept this gift,\na PINK BOW.",
  ["68:546f"] = "TUSCANY: Wouldn't\nyou agree that it\011is most adorable?\012It strengthens\nnormal-type moves.\012I am certain it\nwill be of use.",
  ["68:54e7"] = "TUSCANY: Have you\nmet MONICA, my\011older sister?\012Or my younger\nbrother, WESLEY?\012I am the second of\nseven children.",
  ["68:5559"] = "TUSCANY: Today is\nnot Tuesday. That\011is unfortunate…",
  ["68:558e"] = "ROUTE 29\012CHERRYGROVE CITY -\nNEW BARK TOWN",
  ["68:55b9"] = "ROUTE 29\012CHERRYGROVE CITY -\nNEW BARK TOWN",
  ["68:5806"] = "Go, RATTATA!\012TACKLE!",
  ["68:581c"] = "What? This is a\nbig battle!\011Leave me alone!",
  ["68:5849"] = "I just lost, so\nI'm trying to find\011more POKéMON.\012Wait! You look\nweak! Come on,\011let's battle!",
  ["68:58a2"] = "Ack! I lost again!\nDoggone it!",
  ["68:58c2"] = "Do I have to have\nmore POKéMON in\012order to battle\nbetter?\012No! I'm sticking\nwith this one no\011matter what!",
  ["68:5928"] = "You're a POKéMON\ntrainer, right?\012Then you have to\nbattle!",
  ["68:595f"] = "That's strange.\nI won before.",
  ["68:597d"] = "Becoming a good\ntrainer is really\011tough.\012I'm going to bat-\ntle other people\011to get better.",
  ["68:59d8"] = "Instead of a bug\nPOKéMON, I found\011a trainer!",
  ["68:5a03"] = "Argh! You're too\nstrong!",
  ["68:5a1c"] = "I ran out of POKé\nBALLS while I was\011catching POKéMON.\012I should've bought\nsome more…",
  ["68:5a6a"] = "MR.POKéMON's\nhouse? It's a bit\011farther ahead.",
  ["68:5a94"] = "Everyone's having\nfun battling!\011You should too!",
  ["68:5ac4"] = "I'm not a trainer.\012But if you look\none in the eyes,\011prepare to battle.",
  ["68:5b0b"] = "ROUTE 30\012VIOLET CITY -\nCHERRYGROVE CITY",
  ["68:5b34"] = "MR.POKéMON'S HOUSE\nSTRAIGHT AHEAD!",
  ["68:5b55"] = "MR.POKéMON'S HOUSE",
  ["68:5b66"] = "TRAINER TIPS\012No stealing other\npeople's POKéMON!\012POKé BALLS are to\nbe thrown only at\011wild POKéMON!",
  ["68:5bc0"] = "I lost again…\nGee, you're tough!\012Oh yeah, I almost\nforgot that I had\011to give you this.\012Use it to get even\ntougher, OK?\012I'm going to get\ntougher too.",
  ["68:5f35"] = "Fly high into the\nsky, my beloved\011bird POKéMON!",
  ["68:5f63"] = "I feel like just\nflying away now.",
  ["68:5f86"] = "I plan to train in\nCIANWOOD CITY to\012teach my POKéMON\nhow to FLY.",
  ["68:5fc5"] = "Let me try some-\nthing I learned\011today.",
  ["68:5fee"] = "I didn't study\nenough, I guess.",
  ["68:600e"] = "I have to take so\nmany tests, I\012don't have much\ntime for POKéMON.\012So when I do get\nto play, I really\011concentrate.",
  ["68:607d"] = "You seem to be\ngood at POKéMON.\012If you are, how\nabout giving me\011some advice?",
  ["68:60c8"] = "I see. So you can\nbattle that way.",
  ["68:60ec"] = "I know something\ngood!\012MOOMOO FARM's milk\nis famous for its\011flavor.",
  ["68:6130"] = "Hi! Aren't you a\ncute trainer!\012May I see your\nPOKéMON?",
  ["68:6164"] = "I'm glad I got to\nsee your POKéMON!",
  ["68:6185"] = "When I see POKé-\nMON, it seems to\011soothe my nerves.",
  ["68:61b7"] = "I've been over-\nseas, so I know\012about all sorts of\nPOKéMON!",
  ["68:61f0"] = "Your skill is\nworld class!",
  ["68:620c"] = "All kinds of peo-\nple around the\012world live happily\nwith POKéMON.",
  ["68:624c"] = "Don't you think my\nPOKéMON and I are\011beautiful?",
  ["68:6279"] = "We drink MOOMOO\nMILK every day.",
  ["68:629a"] = "MOOMOO MILK is\ngood for beauty\012and health, but\ninconveniently,\012they only sell a\nbottle at a time.",
  ["68:62fd"] = "ROUTE 38\012OLIVINE CITY -\nECRUTEAK CITY",
  ["68:6324"] = "TRAINER TIPS\012If a POKéMON is\ntrying to evolve,\011you can stop it.\012Press the B But-\nton during evolu-\011tion.\012That startles the\nPOKéMON and stops\011its evolution.",
  ["68:64a2"] = "Bow down before my\nregal POKéMON!",
  ["68:64c2"] = "How… How dare you\nmock royalty!",
  ["68:64e3"] = "Doesn't everyone\nwish to someday be\011a king?",
  ["68:650f"] = "Nihihi! Would you\nlike to battle my\011PIKACHU gang?",
  ["68:6542"] = "PI-PIKACHU!",
  ["68:654f"] = "You look like you\nhave many POKéMON,\012but PIKACHU is\nstill the best.",
  ["68:6591"] = "Agility is the key\nattribute of bird\011POKéMON.",
  ["68:65bd"] = "You beat me with\nyour speed…",
  ["68:65db"] = "Your POKéMON are\nremarkably well-\011trained.",
  ["68:6604"] = "Check out my POKé-\nMON. Just look at\012their coloring and\ntheir plumage.",
  ["68:6649"] = "Shoot!\nNot good enough!",
  ["68:6662"] = "If you groom them,\nPOKéMON get happy.",
  ["68:6686"] = "I should go to\nROCK TUNNEL to get\011myself an ONIX.",
  ["68:66b9"] = "I lost…",
  ["68:66c2"] = "Geological fea-\ntures don't appear\011to change.\012But they actually\nchange, little by\011little.",
  ["68:671c"] = "TRAINER TIPS\012Look! Right there,\nat the left side\011of the post.",
  ["68:675b"] = "ROUTE 13\012NORTH TO SILENCE\nBRIDGE",
  ["68:677d"] = "NORTH TO LAVENDER\nTOWN\012WEST TO FUCHSIA\nCITY",
  ["68:6814"] = "NIDORAN, shake!",
  ["68:6825"] = "NIDORAN: Gau gau!",
  ["68:68d0"] = "BROCK: Wow, it's\nnot often that we\012get a challenger\nfrom JOHTO.\012I'm BROCK, the\nPEWTER GYM LEADER.\012I'm an expert on\nrock-type POKéMON.\012My POKéMON are im-\npervious to most\012physical attacks.\nYou'll have a hard\012time inflicting\nany damage.\012Come on!",
  ["68:69bb"] = "BROCK: Your POKé-\nMON's powerful at-\011tacks overcame my\011rock-hard defense…\012You're stronger\nthan I expected…\012Go ahead--take\nthis BADGE.",
  ["68:6a3d"] = "{PLAYER} received\nBOULDERBADGE.",
  ["68:6a57"] = "BROCK: {PLAYER},\nthanks. I enjoyed\012battling you, even\nthough I am a bit\011upset.\012That BOULDERBADGE\nwill make your\012POKéMON even more\npowerful.",
  ["68:6ada"] = "BROCK: The world\nis huge. There are\012still many strong\ntrainers like you.\012Just wait and see.\nI'm going to be-\011come a lot strong-\011er too.",
  ["68:6b62"] = "The trainers of\nthis GYM use rock-\011type POKéMON.\012The rock-type has\nhigh DEFENSE.\012Battles could end\nup going a long\012time. Are you\nready for this?",
  ["68:6bf1"] = "I have to win\nthese battles…",
  ["68:6c0f"] = "Hey, you! Trainer\nfrom JOHTO! BROCK\012is tough. He'll\npunish you if you\012don't take him\nseriously.",
  ["68:6c6e"] = "Yo! CHAMP in\nmaking! You're\012really rocking.\nAre you battling\012the GYM LEADERS of\nKANTO?\012They're strong and\ndedicated people,\012just like JOHTO's\nGYM LEADERS.",
  ["68:6d07"] = "Yo! CHAMP in\nmaking! That GYM\012didn't give you\nmuch trouble.\012The way you took\ncharge was really\012inspiring. I mean\nthat seriously.",
  ["68:6dd8"] = "Hi! Check out my\nGYARADOS!\012I raised it from a\nMAGIKARP. I can't\012believe how strong\nit has become.",
  ["68:6e3a"] = "There once was a\nweird old man who\011sold MAGIKARP.\012He was saying the\nMAGIKARP from the\012LAKE OF RAGE were\nexcellent.",
  ["68:6f01"] = "…Yeah, and the\nGYM in CINNABAR's\012gone. I was really\namazed.\012…Yes? I'm on the\nphone. Go away!",
  ["68:6f5d"] = "JIGGLYPUFF: Puu\npupuu.",
  ["68:6f75"] = "Most POKéMON get\ndrowsy if they\012hear a JIGGLYPUFF\nsinging.\012There are several\nmoves that can be\012used only while a\nPOKéMON is asleep.",
  ["68:705f"] = "I like snoozing\nwith the radio on…\011…Zzzz…",
  ["69:4105"] = "ECRUTEAK used to\nhave two towers:\012one each in the\neast and west.",
  ["69:4147"] = "Ah, child.\nHave you learned\012to dance like the\nKIMONO GIRLS?\012If you go to their\nDANCE THEATER, an\012odd old man will\ngive you something\011nice, I hear.",
  ["69:41db"] = "I'm going to prac-\ntice at the DANCE\012THEATER. Care to\njoin me?",
  ["69:421a"] = "The tower that\nused to be here…\012My grandma told me\nit used to be much\011taller.",
  ["69:4269"] = "Three big POKéMON\nran off in differ-\011ent directions.\011What were they?",
  ["69:42ac"] = "I heard a rumor\nabout OLIVINE\011LIGHTHOUSE.\012The POKéMON that\nserves as the\012beacon fell ill.\nSounds like they\011are in trouble.",
  ["69:4325"] = "The POKéMON at\nOLIVINE LIGHTHOUSE\011has been cured.\012Boats can safely\nsail out to sea at\011night again.",
  ["69:4386"] = "I hear POKéMON are\nrampaging at the\012LAKE OF RAGE. I'd\nlike to see that.",
  ["69:43cb"] = "In the distant\npast…\012This tower burned\nin a fire. Three\012nameless POKéMON\nperished in it.\012A rainbow-colored\nPOKéMON descended\012from the sky and\nresurrected them…\012It's a legend that\nhas been passed\012down by ECRUTEAK\nGYM LEADERS.\012Me?\012I was a trainer\nway back when.\011Hohoho!",
  ["69:44d1"] = "ECRUTEAK CITY\nA Historical City\012Where the Past\nMeets the Present",
  ["69:4513"] = "TIN TOWER\012A legendary POKé-\nMON is said to\011roost here.",
  ["69:4548"] = "ECRUTEAK CITY\nPOKéMON GYM\011LEADER: MORTY\012The Mystic Seer of\nthe Future",
  ["69:458c"] = "ECRUTEAK DANCE\nTHEATER",
  ["69:45a4"] = "BURNED TOWER\012It was destroyed\nby a mysterious\011fire.\012Please stay away,\nas it is unsafe.",
  ["69:477a"] = "I am sorry.\012CLAIR, our GYM\nLEADER, entered\012the DRAGON'S DEN\nbehind the GYM.\012I have no idea\nwhen our LEADER\011will return.",
  ["69:47f3"] = "CLAIR, our GYM\nLEADER, is waiting\011for you.\012However, it would\nbe impossible for\012a run-of-the-mill\ntrainer to win.",
  ["69:4865"] = "You defeated\nCLAIR?\012That's amazing!\012I've never heard\nof her losing to\012anyone other than\nLANCE.",
  ["69:48c3"] = "No. Only chosen\ntrainers may train\012here.\nPlease leave.",
  ["69:48fb"] = "If CLAIR allows\nit, her grand-\011father--our MASTER\011--will also.\012You may enter.",
  ["69:494a"] = "My radio's busted?\nLately, I only get\011this weird signal.",
  ["69:4983"] = "Arooo! Voices in\nmy head!\012Huh? I'm listening\nto my radio!",
  ["69:49bd"] = "Are you going to\nmake your POKéMON\011forget some moves?",
  ["69:49f1"] = "Dragon masters all\ncome from the city\011of BLACKTHORN.",
  ["69:4a27"] = "SANTOS: …\012It's Saturday…\012I'm SANTOS of\nSaturday…",
  ["69:4a57"] = "You can have this…",
  ["69:4a6b"] = "SANTOS: …\012SPELL TAG…\012Ghost-type moves\nget stronger…\012It will frighten\nyou…",
  ["69:4ab6"] = "SANTOS: …\012See you again on\nanother Saturday…\012I won't have any\nmore gifts…",
  ["69:4b00"] = "SANTOS: Today's\nnot Saturday…",
  ["69:4b1e"] = "Wow, you came\nthrough the ICE\011PATH?\012You must be a real\nhotshot trainer!",
  ["69:4b67"] = "BLACKTHORN CITY\012A Quiet Mountain\nRetreat",
  ["69:4b91"] = "BLACKTHORN CITY\nPOKéMON GYM\011LEADER: CLAIR\012The Blessed User\nof Dragon POKéMON",
  ["69:4bd9"] = "MOVE DELETER'S\nHOUSE",
  ["69:4bef"] = "DRAGON'S DEN\nAHEAD",
  ["69:4c03"] = "TRAINER TIPS\012A POKéMON holding\na MIRACLEBERRY\012will cure itself\nof any status\011problem.",
  ["69:4ec6"] = "I'm making my\nfinal preparations\012for the POKéMON\nLEAGUE.",
  ["69:4efc"] = "I blew it!",
  ["69:4f08"] = "It's going to be\ntough to win at\011the LEAGUE.\012I need to do some\nmore training.\012I hear that the\nLEAGUE's ELITE\012FOUR are tougher\nthan GYM LEADERS.",
  ["69:4f97"] = "By experiencing\ntough battles, you\011gain power.",
  ["69:4fc7"] = "Gaah! Life is even\ntougher!",
  ["69:4fe4"] = "To get to POKéMON\nLEAGUE, you have\012to get through\nVICTORY ROAD.\012But VICTORY ROAD\nis tough.\012Practically nobody\ngoes there!",
  ["69:505c"] = "Since you've come\nthis far, you must\011be good.\012I'm going to give\nthis battle every-\011thing I've got!",
  ["69:50bd"] = "No! I don't\nbelieve this!",
  ["69:50d7"] = "I've defeated\neight GYM LEADERS,\012so I was feeling\nconfident.\012I'll have to try\nharder next time.",
  ["69:5136"] = "I lost to a train-\ner named {RIVAL}.\012He was really\nstrong, but…\012It was as if he\nabsolutely had to\011win at any cost.\012I felt sorry for\nhis POKéMON.",
  ["69:51bf"] = "POKéMON aren't\ntools of war.",
  ["69:51d9"] = "POKéMON are in-\nvaluable, lifelong\011partners.",
  ["69:5204"] = "Wow, look at all\nthose BADGES!\011I'm impressed.\012But you're not\nsatisfied by just\012collecting them,\nright?",
  ["69:526a"] = "Good battle!",
  ["69:5278"] = "People and POKéMON\ngrow from their\011experiences.\012Don't get lazy and\ncomplacent.",
  ["69:52c4"] = "I'm feeling great\ntoday!\012I feel like I\ncould boot even\011the LEAGUE CHAMP!",
  ["69:530d"] = "No! Not in this\nbattle!",
  ["69:5326"] = "Just like in fish-\ning, it's all over\012in POKéMON if you\ngive up.",
  ["69:5364"] = "ROUTE 26\012POKéMON LEAGUE\nRECEPTION GATE",
  ["69:5413"] = "ROUTE 28",
  ["69:55ff"] = "DARK CAVE…\012If POKéMON could\nlight it up, I'd\011explore it.",
  ["69:5635"] = "I caught a bunch\nof POKéMON. Let me\011battle with you!",
  ["69:5668"] = "Awwwww…",
  ["69:5671"] = "You can catch\nPOKéMON even if\012you have six with\nyou.\012If you catch one,\nit'll go to your\011BOX automatically.",
  ["69:56d9"] = "… Hnuurg… Huh?\012I walked too far\ntoday looking for\011POKéMON.\012My feet hurt and\nI'm sleepy…\012If I were a wild\nPOKéMON, I'd be\011easy to catch…\012…Zzzz…",
  ["69:5761"] = "…Zzzz… Huh?\012What's that? You\nhave MAIL for me?",
  ["69:5790"] = "{PLAYER} handed\nover the POKéMON\011holding the MAIL.",
  ["69:57ba"] = "Let's see…\012…DARK CAVE leads\nto another road…\012That's good to\nknow.\012Thanks for bring-\ning this to me.\012My friend's a good\nguy, and you're\011swell too!\012I'd like to do\nsomething good in\011return too!\012I know! I want you\nto have this!",
  ["69:5896"] = "TM50 is NIGHTMARE.\012It's a wicked move\nthat steadily cuts\012the HP of a sleep-\ning enemy.\012Ooooh…\nThat's scary…\012I don't want to\nhave bad dreams.",
  ["69:5921"] = "This MAIL isn't\nfor me.",
  ["69:5939"] = "Why is this POKé-\nMON so special?\012It doesn't have\nany MAIL.",
  ["69:5972"] = "What? You don't\nwant anything?",
  ["69:5991"] = "If I take that\nPOKéMON from you,\012what are you going\nto use in battle?",
  ["69:59d5"] = "I found a good\nPOKéMON in DARK\011CAVE.\012I'm going to raise\nit to take on\011FALKNER.\012He's the leader of\nVIOLET CITY's GYM.",
  ["69:5a45"] = "ROUTE 31\012VIOLET CITY -\nCHERRYGROVE CITY",
  ["69:5a6e"] = "DARK CAVE",
  ["69:5bf9"] = "MILTANK: Mooo!",
  ["69:5c09"] = "I just got back to\nOLIVINE.\012So how about a\nPOKéMON battle?",
  ["69:5c42"] = "Awaaargh!",
  ["69:5c4d"] = "My POKéMON were\ncaught and raised\011overseas.\012They're my compan-\nions on those long\011voyages.",
  ["69:5ca5"] = "This is a good\ntime to brag about\011my PIKACHU!",
  ["69:5cd4"] = "I had no time to\nshow off PIKACHU…",
  ["69:5cf8"] = "I'm not listening\nto your bragging!\012We POKé FANS have\na policy of not\012listening to other\npeople brag!",
  ["69:5d5b"] = "Such darling\nPOKéMON.\012Let's show our\nPOKéMON together\011at the same time.",
  ["69:5d9d"] = "I don't mind\nlosing.",
  ["69:5db2"] = "Do you know about\nbaby POKéMON?\012I bet they're just\nadorable!",
  ["69:5dec"] = "PIKACHU is it!\nDon't you agree?",
  ["69:5e0c"] = "Let me see what\nyour POKéMON are\011capable of.",
  ["69:5e37"] = "Ooh, your POKéMON\nhave potential.",
  ["69:5e57"] = "You know how POKé-\nMON have different\011abilities?\012People are like\nthat too. Every-\011one has different\011potential.",
  ["69:5ec4"] = "Ufufufu… I hope it\ngets dark soon.",
  ["69:5ee8"] = "You came at just\nthe right time.\012Let's battle.",
  ["69:5f17"] = "Oh, how disap-\npointing…",
  ["69:5f31"] = "I met my MEOWTH at\nnight, right here\011on ROUTE 39.\012I'm not sure why,\nbut it seems to\012like it when I\ntrain here.\012It seems to become\nfriendlier by\012training here than\nanywhere else.",
  ["69:5fe3"] = "ROUTE 39\012OLIVINE CITY -\nECRUTEAK CITY",
  ["69:600a"] = "MOOMOO FARM\012Enjoy Our Fresh\nand Tasty Milk",
  ["69:6036"] = "TRAINER TIPS\012Use HEADBUTT on\ntrees to shake\011POKéMON out.\012Different kinds of\nPOKéMON drop out\011of trees.\012Use HEADBUTT on\nany tree you see!",
  ["69:622f"] = "You have to warm\nup before going\011into the water.\012That's basic.",
  ["69:626e"] = "OK! Uncle! I give!",
  ["69:6282"] = "CIANWOOD CITY is\na good distance\011away from here.",
  ["69:62b4"] = "Hey, you're young\nand fit!\012Don't ride your\nPOKéMON! Swim!",
  ["69:62ea"] = "Uh-oh. I lost…",
  ["69:62fa"] = "Swimming exercises\nyour entire body.\011It's healthy.",
  ["69:632d"] = "Are you going to\nCIANWOOD?\012How about a quick\nbattle first?",
  ["69:6369"] = "I lost that one!",
  ["69:637b"] = "I'd say I'm a bet-\nter swimmer than\011you. Yeah!",
  ["69:63a9"] = "No inner tube for\nme.\012I'm hanging on to\na sea POKéMON!",
  ["69:63dd"] = "Ooh, I'm feeling\ndizzy!",
  ["69:63f5"] = "While I float like\nthis, the waves\011carry me along.",
  ["69:6429"] = "Although you can't\nsee it from here,\012CIANWOOD is across\nthe sea.",
  ["69:646a"] = "Hm! There's a big\nbuilding up ahead!\012What is it?",
  ["69:649b"] = "Hm! Look at all\nthose serious-\011looking trainers\011streaming in.\012What? What?",
  ["69:64e6"] = "I came to OLIVINE\nby ship to see the\012sights and soak up\nthe atmosphere.\012Being a port, it\nfeels so different\011from a big city.",
  ["69:6564"] = "Have you gone to\nthe BATTLE TOWER?\012I think a lot of\ntough trainers\012have gathered\nthere already.\012But since you have\nso many BADGES,\012you shouldn't do\nbadly at all.",
  ["69:6606"] = "MONICA: Glad to\nmeet you. I'm\012MONICA of Monday.",
  ["69:6636"] = "As a token of our\nfriendship, I have\011a gift for you!",
  ["69:666c"] = "MONICA: It's an\nitem that raises\012the power of fly-\ning-type moves.\012You should equip a\nbird POKéMON with\011that item.",
  ["69:66dc"] = "MONICA: My broth-\ners and sisters\012are all over the\nplace.\012See if you could\nfind them all!",
  ["69:6737"] = "MONICA: I don't\nthink today is\011Monday. How sad…",
  ["69:6767"] = "ROUTE 40\012CIANWOOD CITY -\nOLIVINE CITY",
  ["69:690f"] = "The water's warm\nhere. I'm loose\011and limber.\012Sure, I'll take\nyou on!",
  ["69:6952"] = "Yikes! I've got\nprune skin!",
  ["69:696e"] = "Isn't it relaxing\njust floating like\011this?",
  ["69:6999"] = "I'm a bit tired.\nIf I win, lend me\011your POKéMON.",
  ["69:69c7"] = "Pant, pant…",
  ["69:69d4"] = "It's so far to\nCIANWOOD.\012But it's no easy\nreturn trip to\011OLIVINE either.\012What should I do?",
  ["69:6a2e"] = "See those islands\nthat are blocked\011by whirlpools?\012There just has to\nbe a secret!",
  ["69:6a80"] = "What's the secret\nto your strength?",
  ["69:6aa4"] = "It was a dark and\nstormy night…\012I saw this giant\nPOKéMON flying\011from the islands.\012It was scattering\nfeathers from its\011silver wings.",
  ["69:6b26"] = "The waves are wild\nhere.\012They tire you out\nwhile you swim.",
  ["69:6b62"] = "I'm beat!",
  ["69:6b6c"] = "The currents keep\nme from reaching\011that island.",
  ["69:6b9d"] = "Are you seeking\nthe secrets of\011WHIRL ISLANDS?",
  ["69:6bcc"] = "Ooh, you've got\ngreat endurance!",
  ["69:6bed"] = "A secret about\nWHIRL ISLANDS…\012It's pitch-black\ninside!",
  ["69:6c24"] = "I'm on my way to\nWHIRL ISLANDS.\012I'm going explor-\ning with friends.",
  ["69:6c67"] = "Is that how you do\nit?",
  ["69:6c7f"] = "There's supposed\nto be a big POKé-\011MON deep beneath\011WHIRL ISLANDS.\012I wonder what it\ncould be?",
  ["69:6cda"] = "You look so ele-\ngant, riding your\011POKéMON.",
  ["69:6d04"] = "I'm crushed…",
  ["69:6d11"] = "Wasn't there a hit\nsong about a boy\011riding a LAPRAS?",
  ["69:6d46"] = "The weather is so\nbeautiful, I'm in\011a daze!",
  ["69:6d72"] = "Ohhh!",
  ["69:6d79"] = "A sunburn is the\nworst for skin.\012But I don't use a\nsunblock.\012I won't pollute\nthe water.",
  ["69:6dd0"] = "If you need to\nrest, just tread\011water.\012You'll get your\nwind back, so you\012can keep on going\nstrong.",
  ["69:6e33"] = "Oh! You have more\nenergy than I do.",
  ["69:6e58"] = "I heard roars from\ndeep inside the\011ISLANDS.",
  ["69:6e85"] = "At night, STARYU\ngather near the\011water's surface.",
  ["69:6eb7"] = "Oh, dear…",
  ["69:6ec2"] = "The clusters of\nSTARYU light up\011at the same time.\012It's so beautiful,\nit's scary.",
  ["69:7012"] = "Patience is the\nkey to both fish-\011ing and POKéMON.",
  ["69:7043"] = "Gwaaah!",
  ["69:704c"] = "I'm too impatient\nfor fishing…",
  ["69:706b"] = "I feel so content,\nfishing while lis-\011tening to some\011tunes on my radio.",
  ["69:70b4"] = "My stupid radio\ndistracted me!",
  ["69:70d4"] = "Have you checked\nout KANTO's radio\012programs? We get a\ngood variety here.",
  ["69:711d"] = "What's most impor-\ntant in our every-\011day lives?",
  ["69:714e"] = "The answer is\ncoming up next!",
  ["69:716d"] = "I think electric-\nity is the most\012important thing in\nour daily lives.\012If it weren't,\npeople wouldn't\012have made such a\nfuss when the\012POWER PLANT went\nout of commission.",
  ["69:7214"] = "Do you remember?",
  ["69:7226"] = "You do remember?",
  ["69:7238"] = "The tug you feel\non the ROD when\012you hook a POKé-\nMON…\012That's the best\nfeeling ever for\011an angler like me.",
  ["69:72a0"] = "ROUTE 12\012NORTH TO LAVENDER\nTOWN",
  ["69:72c1"] = "FISHING SPOT",
  ["6a:40f7"] = "Wow, your POKéGEAR\nis impressive!\012Did your mom get\nit for you?",
  ["6a:4134"] = "Wait, {PLAYER}!",
  ["6a:413e"] = "What do you think\nyou're doing?",
  ["6a:415e"] = "It's dangerous to\ngo out without a\011POKéMON!\012Wild POKéMON\njump out of the\012grass on the way\nto the next town.",
  ["6a:41c4"] = "Oh! Your POKéMON\nis adorable!\011I wish I had one!",
  ["6a:41f2"] = "Hi, {PLAYER}!\nLeaving again?\012You should tell\nyour mom if you\011are leaving.",
  ["6a:4236"] = "Call your mom on\nyour POKéGEAR to\012let her know how\nyou're doing.",
  ["6a:4274"] = "Yo, {PLAYER}!\012I hear PROF.ELM\ndiscovered some\011new POKéMON.",
  ["6a:42a6"] = "……\012So this is the\nfamous ELM POKéMON\011LAB…",
  ["6a:42cd"] = "…What are you\nstaring at?",
  ["6a:42e8"] = "NEW BARK TOWN\012The Town Where the\nWinds of a New\011Beginning Blow",
  ["6a:4328"] = "{PLAYER}'s House",
  ["6a:4332"] = "ELM POKéMON LAB",
  ["6a:4340"] = "ELM'S HOUSE",
  ["6a:4473"] = "Hello!\nYou are trainer?\012Battle GYM LEADER,\nwin you did?",
  ["6a:44ac"] = "Ooh, la la!\nVery indeed nice!",
  ["6a:44cb"] = "Is that so? Then\nstudy shall you!\011Follow me!",
  ["6a:44f9"] = "Here, teacher I\nam. Good it is\011you study here!",
  ["6a:4529"] = "Ghosts are rumored\nto appear in\011SPROUT TOWER.\012They said normal-\ntype POKéMON moves\012had no effect on\nghosts.",
  ["6a:4593"] = "Hey, you're a\nPOKéMON trainer?\012If you beat the\nGYM LEADER here,\012you'll be ready\nfor prime time!",
  ["6a:45ef"] = "FALKNER, from the\nVIOLET POKéMON\012GYM, is a fine\ntrainer!\012He inherited his\nfather's gym and\012has done a great\njob with it.",
  ["6a:4665"] = "I saw a wiggly\ntree up ahead!\012If you touch it,\nit squirms and\011dances! Cool!",
  ["6a:46b2"] = "VIOLET CITY\012The City of\nNostalgic Scents",
  ["6a:46dc"] = "VIOLET CITY\nPOKéMON GYM\011LEADER: FALKNER\012The Elegant Master\nof Flying POKéMON",
  ["6a:4724"] = "SPROUT TOWER\012Experience the\nWay of POKéMON",
  ["6a:474d"] = "EARL'S POKéMON\nACADEMY",
  ["6a:48fa"] = "…\012You again?\012There's no need to\npanic. I don't\012bother with wimps\nlike you.\012Speaking of weak-\nlings, the city's\012GYM LEADER isn't\nhere.\012Supposedly taking\ncare of a sick\012POKéMON at the\nLIGHTHOUSE.\012Humph! Boo-hoo!\nJust let sick\011POKéMON go!\012A POKéMON that\ncan't battle is\011worthless!\012Why don't you go\ntrain at the\011LIGHTHOUSE?\012Who knows. It may\nmake you a bit\011less weak!",
  ["6a:4a58"] = "Dark roads are\ndangerous at\011night.\012But in the pitch-\nblack of night,\012the sea is even\nmore treacherous!\012Without the beacon\nof the LIGHTHOUSE\012to guide it, no\nship can sail.",
  ["6a:4b04"] = "That thing you\nhave--it's a POKé-\011GEAR, right? Wow,\011that's cool.",
  ["6a:4b41"] = "Wow, you have a\nPOKéDEX!\012That is just so\nawesome.",
  ["6a:4b71"] = "The sea is sweet!\012Sunsets on the sea\nare marvelous!\012Sing with me! \nYo-ho! Blow the\011man down!…",
  ["6a:4bd0"] = "OLIVINE CITY\012The Port Closest\nto Foreign Lands",
  ["6a:4c00"] = "OLIVINE PORT\nFAST SHIP PIER",
  ["6a:4c1d"] = "OLIVINE CITY\nPOKéMON GYM\011LEADER: JASMINE\012The Steel-Clad\nDefense Girl",
  ["6a:4c60"] = "OLIVINE LIGHTHOUSE\nAlso known as the\011GLITTER LIGHTHOUSE",
  ["6a:4c99"] = "BATTLE TOWER AHEAD\nOpening Now!",
  ["6a:4e12"] = "ANN: ANNE and I\nare in this to-\011gether!",
  ["6a:4e3b"] = "ANN & ANNE: Nnn… A\nlittle too strong.",
  ["6a:4e62"] = "ANN: I can tell\nwhat my sister and\012my POKéMON are\nthinking.",
  ["6a:4e9c"] = "ANNE: ANN and I\nare in this to-\011gether!",
  ["6a:4ec5"] = "ANN & ANNE: Nnn… A\nlittle too strong.",
  ["6a:4eec"] = "ANNE: We share the\nsame feelings as\011our POKéMON.",
  ["6a:4f1b"] = "POKéMON can't do a\nthing if they are\011asleep.\012I'll show you how\nscary that is!",
  ["6a:4f65"] = "I lost. That's\npretty sad…",
  ["6a:4f80"] = "Putting POKéMON to\nsleep or paralyz-\011ing them are good\011battle techniques.",
  ["6a:4fc8"] = "SUNNY: Hi!\012I'm SUNNY of Sun-\nday, meaning it's\011Sunday today!",
  ["6a:5004"] = "I was told to give\nyou this if I saw\011you!",
  ["6a:502f"] = "I was told to give\nyou this if I saw\011you!",
  ["6a:505a"] = "SUNNY: That thing…\012Um…\012… What was it now…\012…\012Oh! I remember\nnow!\012A POKéMON that\nknows electric\012moves should hold\nit.\012My sis MONICA said\nit powers up\011electric moves!",
  ["6a:50fc"] = "SUNNY: My sisters\nand brothers are\011MONICA, TUSCANY,\011WESLEY, ARTHUR,\011FRIEDA and SANTOS.\012They're all older\nthan me!",
  ["6a:516e"] = "SUNNY: Isn't today\nSunday?\011Um… I forgot!",
  ["6a:5197"] = "ROUTE 37",
  ["6a:535f"] = "Let me demonstrate\nthe power of the\011POKéMON I caught!",
  ["6a:5393"] = "What? That's not\nright.",
  ["6a:53ab"] = "I want to become\nthe trainer CHAMP\012using the POKéMON\nI caught.\012That's the best\npart of fishing!",
  ["6a:5408"] = "Ah, it's good to\nbe outside!\011I feel so free!",
  ["6a:5435"] = "Gahahah!",
  ["6a:543f"] = "Losing feels in-\nsignificant if you\012look up at the big\nsky!",
  ["6a:547c"] = "HEY!\012This is my secret\nplace! Get lost,\011you outsider!",
  ["6a:54b3"] = "I should have used\nmy MOON STONE…",
  ["6a:54d6"] = "You're working on\na POKéDEX?\012Wow, you must know\nsome pretty rare\011POKéMON!\012May I please see\nit. Please?",
  ["6a:5537"] = "ROUTE 42\012ECRUTEAK CITY -\nMAHOGANY TOWN",
  ["6a:555f"] = "MT.MORTAR\012WATERFALL CAVE\nINSIDE",
  ["6a:5580"] = "MT.MORTAR\012WATERFALL CAVE\nINSIDE",
  ["6a:55a1"] = "ROUTE 42\012ECRUTEAK CITY -\nMAHOGANY TOWN",
  ["6a:5793"] = "Awright! I'll show\nyou the power of\011mountain POKéMON!",
  ["6a:57c6"] = "Mercy! You showed\nme your power!",
  ["6a:57e8"] = "It's over. I don't\nmind. We HIKERS\011are like that.",
  ["6a:5819"] = "I'm raising POKé-\nMON too!\012Will you battle\nwith me?",
  ["6a:584a"] = "Wha…?",
  ["6a:5851"] = "I did my best but\ncame up short.\012No excuses--I\nadmit I lost.",
  ["6a:588f"] = "I raise POKéMON\ntoo!\012Will you battle\nwith me?",
  ["6a:58bb"] = "Oh, rats!",
  ["6a:58c6"] = "I've been to many\nGYMS, but the GYM\012in GOLDENROD is my\nfavorite.\012It's filled with\npretty flowers!",
  ["6a:5927"] = "Aww… I keep losing\nall the time!\012I'll just have to\ntry harder!\012Anyway, thanks for\nbattling me again\012and again. Here's\nthat present from\011the other time.",
  ["6a:59be"] = "ROUTE 46\nMOUNTAIN RD. AHEAD",
  ["6a:5aa5"] = "Hey, kid! I just\nhad a double shot\012of espresso, and\nI am wired!\012I need to talk to\nsomeone, so you'll\011have to do!\012I might not look\nlike much now, but\012I was an expert at\ncatching POKéMON.\012Do you believe me?",
  ["6a:5b6f"] = "Good, good. Yes, I\nwas something out\012of the ordinary,\nlet me tell you!",
  ["6a:5bb7"] = "What? You little\nwhelp!\012If I were just a\nbit younger, I'd\012show you a thing\nor two. Humph!",
  ["6a:5c11"] = "This GYM didn't\nhave a LEADER\011until recently.\012A young man from\nPALLET became the\012LEADER, but he's\noften away.",
  ["6a:5c7e"] = "Are you going to\nbattle the LEADER?\012Good luck to you.\nYou'll need it.",
  ["6a:5cc4"] = "Yawn!\012I must have dozed\noff in the sun.\012…I had this dream\nabout a DROWZEE\012eating my dream.\nWeird, huh?\012Huh?\nWhat's this?\012Where did this TM\ncome from?\012This is spooky!\nHere, you can have\011this TM.",
  ["6a:5d86"] = "TM42 contains\nDREAM EATER…\012…Zzzzz…",
  ["6a:5daa"] = "I heard that there\nare many items on\012the ground in\nVIRIDIAN FOREST.",
  ["6a:5def"] = "VIRIDIAN CITY\012The Eternally\nGreen Paradise",
  ["6a:5e1b"] = "VIRIDIAN CITY\nPOKéMON GYM\011LEADER: …\012The rest of the\ntext is illegible…",
  ["6a:5e60"] = "WELCOME TO\nVIRIDIAN CITY,\012THE GATEWAY TO\nINDIGO PLATEAU",
  ["6a:5e99"] = "TRAINER HOUSE\012The Club for Top\nTrainer Battles",
  ["6a:5f7d"] = "This POLIWRATH is\nmy partner.\012I wonder if it'll\never evolve into a\011frog POKéMON.",
  ["6a:5fcb"] = "POLIWRATH: Croak!",
  ["6a:5fde"] = "I lost at the slot\nmachines again…\012We girls also play\nthe slots now.\012You should check\nthem out too.",
  ["6a:6043"] = "GRIMER have been\nappearing lately.\012See that pond out\nin front of the\012house? GRIMER live\nthere now.\012Where did they\ncome from? This is\011a serious problem…",
  ["6a:60dc"] = "Nihihi! This GYM\nis great! Only\012girls are allowed\nhere!",
  ["6a:6115"] = "Want to know a\nsecret?\012CELADON MANSION\nhas a hidden back\011door.",
  ["6a:6155"] = "They're holding an\neating contest at\011the restaurant.\012Just watching them\ngo at it makes me\011feel bloated…",
  ["6a:61bd"] = "CELADON DEPT.STORE\nhas the biggest\012and best selection\nof merchandise.\012If you can't get\nit there, you\012can't get it any-\nwhere.\012Gee… I sound like\na sales clerk.",
  ["6a:6306"] = "Looking at the\nground while I was\012walking made me\ndizzy.",
  ["6a:6340"] = "CELADON CITY\012The City of\nRainbow Dreams",
  ["6a:6369"] = "CELADON CITY\nPOKéMON GYM\011LEADER: ERIKA\012The Nature-Loving\nPrincess",
  ["6a:63a9"] = "Find What You\nNeed at CELADON\011DEPT.STORE!",
  ["6a:63d4"] = "CELADON MANSION",
  ["6a:63e5"] = "The Playground for\nEverybody--CELADON\011GAME CORNER",
  ["6a:6418"] = "TRAINER TIPS\012GUARD SPEC.\nprotects POKéMON\012against SPECIAL\nattacks such as\011fire and water.\012Get your items at\nCELADON DEPT.\011STORE!",
  ["6a:65e6"] = "Have you forgotten\nanything?",
  ["6a:6604"] = "Kyaaah!",
  ["6a:660d"] = "Before I became a\nteacher, I used to\012forget a lot of\nthings.",
  ["6a:664b"] = "On sunny days, I\nthink that the\012kids would rather\nbe playing in the\012schoolyard than\nstudying in class.",
  ["6a:66b3"] = "I didn't want to\nlose…",
  ["6a:66ca"] = "Studying is impor-\ntant, but exercise\011is just as vital.",
  ["6a:6703"] = "Hang on. I have to\nphone my mom.",
  ["6a:6725"] = "Sorry, Mom!\nI was beaten!",
  ["6a:6740"] = "My mom worries so\nmuch about me, I\012have to phone her\nall the time.",
  ["6a:6784"] = "Let's battle.\nI won't lose!",
  ["6a:679f"] = "I forgot to do my\nhomework!",
  ["6a:67bc"] = "Sayonara! I just\nlearned that in my\011Japanese class.",
  ["6a:67f1"] = "We're on a field\ntrip to LAVENDER\012RADIO TOWER for\nsocial studies.",
  ["6a:6833"] = "You're wickedly\ntough!",
  ["6a:684a"] = "I'm tired of walk-\ning. I need to\011take a break.",
  ["6a:687a"] = "My favorite class\nis gym!",
  ["6a:6895"] = "Oh, no!\nHow could I lose?",
  ["6a:68b0"] = "If POKéMON were a\nsubject at school,\011I'd be the best!",
  ["6a:68e3"] = "ROUTE 15\012FUCHSIA CITY -\nLAVENDER TOWN",
  ["6a:6a15"] = "VERMILION PORT is\nKANTO's seaside\011gateway.\012Luxury liners from\naround the world\011dock here.",
  ["6a:6a6f"] = "My POKéMON is\npreparing the land\011for construction.\012But I have no\nmoney to start the\011project…",
  ["6a:6aca"] = "MACHOP: Guooh\ngogogoh!",
  ["6a:6ae2"] = "A MACHOP is growl-\ning while stomping\011the ground flat.",
  ["6a:6b1a"] = "There are eight\nGYMS in KANTO.\012That big building\nis VERMILION's\011POKéMON GYM.",
  ["6a:6b64"] = "SNORLAX is snoring\npeacefully…",
  ["6a:6b84"] = "The POKéGEAR was\nplaced near the\011sleeping SNORLAX…\012…\012SNORLAX woke up!",
  ["6a:6bc8"] = "Skilled trainers\ngather in KANTO.\012GYM LEADERS are\nespecially strong.\012They won't be easy\nto defeat.",
  ["6a:6c2b"] = "You've started to\ncollect KANTO GYM\011BADGES?\012Don't you agree\nthat the trainers\011here are tough?",
  ["6a:6c88"] = "I guess you'll be\nfinished with your\012conquest of KANTO\nGYMS soon.\012Let me know if\nyou get all eight\011BADGES.",
  ["6a:6cf3"] = "Congratulations!\012You got all the\nKANTO GYM BADGES.\012I've got a reward\nfor your efforts.",
  ["6a:6d4a"] = "Having a variety\nof POKéMON types\012should give you an\nedge in battle.\012I'm sure the KANTO\nGYM BADGES will\011help you.",
  ["6a:6db9"] = "VERMILION CITY\012The Port of\nExquisite Sunsets",
  ["6a:6de7"] = "VERMILION CITY\nPOKéMON GYM\011LEADER: LT.SURGE\012The Lightning\nAmerican",
  ["6a:6e28"] = "POKéMON FAN CLUB\012All POKéMON Fans\nWelcome!",
  ["6a:6e4e"] = "DIGLETT'S CAVE",
  ["6a:6e5e"] = "VERMILION PORT\nENTRANCE",
  ["6a:6fa5"] = "I came to explore\nROCK TUNNEL.",
  ["6a:6fc5"] = "Whoa! Danger, man.",
  ["6a:6fd9"] = "My POKéMON were\nhurt before even\012entering ROCK\nTUNNEL.\012I'd better take\nthem to a POKéMON\011CENTER right away.",
  ["6a:703f"] = "Have you ever been\nto a picnic?\012They're so much\nfun!",
  ["6a:7074"] = "Ohhhh!",
  ["6a:707c"] = "We bake lots of\ngoodies and share\012them all around.\nThey're delicious!",
  ["6a:70c2"] = "Hey, you!\nDon't litter!",
  ["6a:70da"] = "I was just point-\ning out…",
  ["6a:70f6"] = "Sorry. You weren't\nlittering. It was\011my mistake.",
  ["6a:7127"] = "People shouldn't\nleave any litter\011behind.",
  ["6a:7151"] = "Ohh… I lost…",
  ["6a:715f"] = "Conserving energy\nis important, but\012the environment is\neven more vital.",
  ["6a:71a8"] = "She'll be coming\n'round MT.SILVER\011when she comes…\012MT.SILVER is in\nJOHTO, right?",
  ["6a:71f7"] = "I was too busy\nsinging…",
  ["6a:7210"] = "Battles are about\nconcentration.",
  ["6a:7232"] = "I'll tell you a\nsecret.\012But first, we\nbattle!",
  ["6a:7260"] = "Oh, dang!\nI lost that…",
  ["6a:7278"] = "The POWER PLANT is\nacross a small\011river.",
  ["6a:72a2"] = "ROUTE 9\012CERULEAN CITY -\nROCK TUNNEL",
  ["6a:7335"] = "CINNABAR GYM's\nBLAINE apparently\012lives alone in the\nSEAFOAM ISLANDS\011cave…",
  ["6a:737f"] = "It's been a year\nsince the volcano\011erupted.",
  ["6a:740a"] = "CINNABAR's volcano\nerupted.\012It hurled boulders\nthat cut off ROUTE\01119 indefinitely.\012I wonder if the\npeople of CINNABAR\011are safe…",
  ["6a:748a"] = "No CINNABAR citi-\nzens were injured\012by the eruption.\nThat's great!",
  ["6a:7548"] = "BLAINE: Waaah!\012My GYM in CINNABAR\nburned down.\012My fire-breathing\nPOKéMON and I are\012homeless because\nof the volcano.\012Waaah!\012But I'm back in\nbusiness as a GYM\012LEADER here in\nthis cave.\012If you can beat\nme, I'll give you\011a BADGE.\012Ha! You'd better\nhave BURN HEAL!",
  ["6a:7646"] = "BLAINE: Awesome.\nI've burned out…\012You've earned\nVOLCANOBADGE!",
  ["6a:7683"] = "{PLAYER} received\nVOLCANOBADGE.",
  ["6a:769d"] = "BLAINE: I did lose\nthis time, but I'm\012going to win the\nnext time.\012When I rebuild my\nCINNABAR GYM,\012we'll have to have\na rematch.",
  ["6a:771c"] = "BLAINE: My fire\nPOKéMON will be\012even stronger.\nJust you watch!",
  ["6a:7759"] = "Yo!\012… Huh? It's over\nalready?\012Sorry, sorry!\012CINNABAR GYM was\ngone, so I didn't\012know where to find\nyou.\012But, hey, you're\nplenty strong even\012without my advice.\nI knew you'd win!",
  ["6a:7806"] = "A POKéMON GYM can\nbe anywhere as\012long as the GYM\nLEADER is there.\012There's no need\nfor a building.",
  ["6b:40ec"] = "I came through the\ntunnel, but I\012still have plenty\nof energy left.",
  ["6b:4130"] = "Whoa! You've got\nmore zip than me!",
  ["6b:4153"] = "We HIKERS are at\nour best in the\011mountains.",
  ["6b:4180"] = "Hey, did you get a\nDUNSPARCE?\012I caught one too.\012Take a look at it\nin the light. It's\011got a funny face!",
  ["6b:41e7"] = "Pant, pant…\012I finally got\nthrough that cave.\012It was much bigger\nthan I'd expected.\012I got too tired to\nexplore the whole\012thing, so I came\noutside.",
  ["6b:4279"] = "ROUTE 33",
  ["6b:4314"] = "My bug POKéMON are\ntough. Prepare to\011lose!",
  ["6b:433d"] = "I was whipped…",
  ["6b:434d"] = "I'm going to look\nfor stronger bug\011POKéMON.",
  ["6b:4376"] = "If you walk in\ntall grass wearing\012shorts, do you get\nnicks and cuts?",
  ["6b:43bc"] = "Ouch, ouch, ouch!",
  ["6b:43cf"] = "They'll really\nsting when you\011take a bath.",
  ["6b:43fa"] = "Why don't girls\nlike bug POKéMON?",
  ["6b:4419"] = "No good!",
  ["6b:4423"] = "Bug POKéMON squish\nlike plush toys\012when you squeeze\ntheir bellies.\012I love how they\nfeel!",
  ["6b:447a"] = "ROUTE 2\012VIRIDIAN CITY -\nPEWTER CITY",
  ["6b:449f"] = "DIGLETT'S CAVE",
  ["6b:4583"] = "If trainers meet,\nthe first thing to\011do is battle.",
  ["6b:45b7"] = "Awww… I've got a\nlosing record…",
  ["6b:45d7"] = "For trainers, it's\na given that we'll\012battle whenever we\nmeet.",
  ["6b:4615"] = "You there!\nWant to battle?",
  ["6b:4631"] = "Down and out…",
  ["6b:4640"] = "You're strong.\012You obviously must\nhave trained hard.",
  ["6b:4675"] = "ROUTE 1\012PALLET TOWN -\nVIRIDIAN CITY",
  ["6b:46e7"] = "I'm raising POKé-\nMON too.\012They serve as my\nprivate guards.",
  ["6b:4720"] = "Technology is\nincredible!\012You can now trade\nPOKéMON across\011time like e-mail.",
  ["6b:476b"] = "PALLET TOWN\012A Tranquil Setting\nof Peace & Purity",
  ["6b:479d"] = "RED'S HOUSE",
  ["6b:47aa"] = "OAK POKéMON\nRESEARCH LAB",
  ["6b:47c1"] = "BLUE'S HOUSE",
  ["6b:4850"] = "Land ho! Gotta\nkeep going!",
  ["6b:486c"] = "Glug…",
  ["6b:4873"] = "This arrogant guy\nwas at CINNABAR's\011volcano.",
  ["6b:48a0"] = "If I win, you have\nto help me with my\011suntan lotion!",
  ["6b:48d6"] = "I'm worried about\nsunburn…",
  ["6b:48f1"] = "I have to watch\nout for blemishes\011caused by the sun.",
  ["6b:4927"] = "I'm bored by fish-\ning. Let's battle!",
  ["6b:494c"] = "Utter failure…",
  ["6b:495c"] = "I'll just go back\nto fishing…",
  ["6b:49d2"] = "Who are you?\012Well, it's plain\nto see that you're\011a trainer…\012My name's BLUE.\012I was once the\nCHAMPION, although\012it was for only a\nshort time…\012That meddling RED\ndid me in…\012Anyway, what do\nyou want? You want\012to challenge me or\nsomething?\012…I hate to say\nit, but I'm not in\012the mood for a\nbattle now.\012Take a good look\naround you…\012A volcano erupts,\nand just like\012that, a whole town\ndisappears.\012We can go on win-\nning and losing in\012POKéMON. But if\nnature so much as\012twitches, we can\nlose in a second.\012…\012That's the way it\nis…\012But, anyway, I'm\nstill a trainer.\012If I see a strong\nopponent, it makes\011me want to battle.\012If you want to\nbattle me, come to\011the VIRIDIAN GYM.\012I'll take you on\nthen.",
  ["6b:4c73"] = "There's a notice\nhere…\012CINNABAR GYM has\nrelocated to SEA-\011FOAM ISLANDS.\012BLAINE",
  ["6b:4cc2"] = "CINNABAR ISLAND\012The Fiery Town of\nBurning Desire",
  ["6b:4d68"] = "I feel so much\nlighter in water.",
  ["6b:4d8a"] = "Oh, no!",
  ["6b:4d93"] = "Swimming exercises\nyour full body.\012It's really good\nfor you.",
  ["6b:4dd0"] = "What an impressive\ncollection of GYM\012BADGES. We should\nbattle!",
  ["6b:4e10"] = "No!",
  ["6b:4e15"] = "SURF is no longer\nthe only HM move\011you use in water.",
  ["6b:4e4b"] = "I guess it's im-\npossible to swim\012all the way to\nJOHTO.",
  ["6b:4e83"] = "Aiyah!",
  ["6b:4e8b"] = "Besides the sea, I\ncan also swim in\011ponds and rivers.",
  ["6b:4ec2"] = "What does this\nsign say?\012CINNABAR GYM\nLEADER: BLAINE",
  ["6b:4f5c"] = "If you're looking\nfor POKéMON, you\012have to look in\nthe tall grass.",
  ["6b:4f9c"] = "Ayieee!",
  ["6b:4fa5"] = "Since you're so\nstrong, it must be\011fun to battle.",
  ["6b:4fd7"] = "CYCLING ROAD is a\nquick shortcut to\011CELADON.",
  ["6b:5005"] = "…Whew!",
  ["6b:500d"] = "If you don't have\na BICYCLE, you're\012not allowed to use\nthe shortcut.",
  ["6b:5051"] = "ROUTE 18\012CELADON CITY -\nFUCHSIA CITY",
  ["6b:5108"] = "Hey, you! You're\nfrom JOHTO, huh?",
  ["6b:512a"] = "Whoa, you kick!",
  ["6b:513b"] = "Don't get cocky,\nyou JOHTO punk!",
  ["6b:515c"] = "Wow. That's a cool\nBICYCLE!",
  ["6b:5178"] = "But you don't just\nlook cool…",
  ["6b:5196"] = "I look cool, but\nI'm weak, so I'm\011not really cool.\012I have to train\nharder…",
  ["6b:51e0"] = "Hey! Want to have\na speed battle?",
  ["6b:5203"] = "Yikes! You've got\nawesome torque!",
  ["6b:5225"] = "Hands-free riding\nis considered cool\011on CYCLING ROAD.",
  ["6b:525c"] = "We're fearless\nhighway stars!",
  ["6b:527a"] = "Arrrgh! Crash and\nburn!",
  ["6b:5293"] = "Reckless driving\ncauses accidents!\011Take it easy!",
  ["6b:532f"] = "CYCLING ROAD\012DOWNHILL COASTING\nALL THE WAY!",
  ["6b:5388"] = "What's this flyer?\012… Uncouth trainers\nhave been holding\012battles in the\nUNDERGROUND PATH.\012Because of rising\ncomplaints by lo-\011cal residents, the\011UNDERGROUND PATH\011has been sealed\011indefinitely.\012CELADON POLICE",
  ["6b:5456"] = "It's locked…",
  ["6b:54c2"] = "Let me tell you,\nI had a hard time\012catching my prized\nPOKéMON.",
  ["6b:54ff"] = "Awaaah!",
  ["6b:5508"] = "SQUIRTLE, CHARMAN-\nDER and BULBASAUR…\012I think that's a\nwell-balanced mix.",
  ["6b:5552"] = "My dream is to fly\nwith my beloved\011bird POKéMON.",
  ["6b:5581"] = "I can dream, but I\ncan't ever fly…",
  ["6b:55a4"] = "You have POKéMON\nthat know the HM\012move FLY, don't\nyou? I envy you.",
  ["6b:55e4"] = "Hi. Did you know…?\012POKéMON get more\nfriendly if you\012train them in a\nplace that they\011remember.",
  ["6b:5640"] = "Where did I meet\nthis PSYDUCK?",
  ["6b:5660"] = "If only there were\nan easy way to\012identify where I\ngot my POKéMON…",
  ["6b:5702"] = "That's quite some\nbuilding, eh?\012It's KANTO's RADIO\nTOWER.",
  ["6b:573a"] = "KANTO has many\ngood radio shows.",
  ["6b:575c"] = "People come from\nall over to pay\012their respects to\nthe departed souls\011of POKéMON.",
  ["6b:57ac"] = "You need a POKé\nFLUTE to wake\011sleeping POKéMON.\012Every trainer has\nto know that!",
  ["6b:57f7"] = "LAVENDER TOWN\012The Noble Purple\nTown",
  ["6b:581c"] = "KANTO RADIO\nSTATION\012Your Favorite\nPrograms On-Air\011Around the Clock!",
  ["6b:5861"] = "LAVENDER VOLUNTEER\nPOKéMON HOUSE",
  ["6b:5880"] = "SOUL HOUSE\012May the Souls of\nPOKéMON Rest Easy",
  ["6b:5957"] = "The road is closed\nuntil the problem\012at the POWER PLANT\nis solved.",
  ["6b:599b"] = "UNDERGROUND PATH\012CERULEAN CITY -\nVERMILION CITY",
  ["6b:59cc"] = "My PHANPY is the\ncutest in the\011world.",
  ["6b:59f3"] = "My PHANPY!",
  ["6b:59ff"] = "Look how adorable\nmy PHANPY acts!\012Isn't it cute\nenough to make\011your heart melt?",
  ["6b:5a4f"] = "My TEDDIURSA is\nthe cutest in the\011world.",
  ["6b:5a79"] = "My TEDDIURSA!",
  ["6b:5a88"] = "Look how adorable\nmy TEDDIURSA acts!\012Isn't it cute\nenough to make\011your heart melt?",
  ["6b:5b22"] = "The road is closed\nuntil the problem\012at the POWER PLANT\nis solved.",
  ["6b:5b66"] = "UNDERGROUND PATH\012CERULEAN CITY -\nVERMILION CITY",
  ["6b:5b97"] = "What's this?\012House for Sale…\nNobody lives here.",
  ["6b:5c2e"] = "Hey, kid! Me am a\nTEAM ROCKET member\011kind of guy!\012Come from another\ncountry, a trainer\011number one, me!\012Think I did, if\nstop the energy,\012be big panic for\nhere people!\012Secret it is my\nmission, so tell\011you I not!\012But! If win you do\nversus me, a man I\012be and mine secret\nto you I tell.\012Hey, kid! Battle\nbegin we do!",
  ["6b:5d67"] = "Ayieeeh! No, no,\nno, believe it I\011can't!\012Strong very much\nbe you! Match I am\011not to you!",
  ["6b:5dc0"] = "OK. Tell you mine\nsecret will I.\012MACHINE PART steal\nby me, hide it I\012did in GYM of the\nCERULEAN.\012Inside water put\nit I did. Look for\012in water center of\nGYM at.\012But you forget me\nnot!\012Beat you for sure\nwill TEAM ROCKET.\012Come from JOHTO\nwill they, mine\012friends, yes. Will\nrevenge they are.",
  ["6b:5ee1"] = "…\012You say what? TEAM\nROCKET bye-bye a\012go-go? Broken it\nis says you?\012Oh, no! Should I\ndo what now on\011from, me?",
  ["6b:5fb8"] = "Ah! The weather's\nas fine as ever.",
  ["6b:5fdb"] = "It's sunny, but\nI'm all wet…",
  ["6b:5ff7"] = "When it rains,\nit's hard to get\011ignition…",
  ["6b:6021"] = "Hmmm… I don't know\nwhat to do…",
  ["6b:6040"] = "I knew I'd lose…",
  ["6b:6051"] = "You looked strong.\012I was afraid to\ntake you on…",
  ["6b:6082"] = "I can run like the\nwind!",
  ["6b:609c"] = "Blown away!",
  ["6b:60a9"] = "I wear shorts the\nwhole year round.\012That's my fashion\npolicy.",
  ["6b:60e7"] = "Step right up and\ntake a look!",
  ["6b:6107"] = "Yow! That's hot!",
  ["6b:6118"] = "The greatest fire-\nbreather in KANTO,\011that's me.\012But not the best\ntrainer…",
  ["6b:6163"] = "MT.MOON SQUARE\012Just go up the\nstairs.",
  ["6b:6214"] = "I'm raising my\nPOKéMON. Want to\011battle with me?",
  ["6b:6241"] = "Ack! I lost that\none…",
  ["6b:6258"] = "If you have a\nspecific POKéMON\012that you want to\nraise, put it out\012first, then switch\nit right away.\012That's how to do\nit.",
  ["6b:62ce"] = "I have a feeling\nthat I can win.\012Let's see if I'm\nright!",
  ["6b:6306"] = "Aww, you are too\nstrong.",
  ["6b:6320"] = "I heard CLEFAIRY\nappear at MT.MOON.\012But where could\nthey be?",
  ["6b:635e"] = "Um…\nI…",
  ["6b:6369"] = "……I'll go train\nsome more…",
  ["6b:6384"] = "MT.MOON SQUARE\012Just go up the\nstairs.",
  ["6b:6421"] = "Hahahah!",
  ["6b:642b"] = "Hahaha-hachoo!",
  ["6b:643b"] = "Hay fever is\nmaking me sneeze!\011Ahahah-CHOO!",
  ["6b:6468"] = "You like POKéMON,\ndon't you?\012Me too!",
  ["6b:648a"] = "I'd have to say\nthat's my loss.",
  ["6b:64a9"] = "Look what you did\nto my POKéMON…\012I won't forget\nthis…",
  ["6b:64dc"] = "ROUTE 10\012CERULEAN CITY -\nLAVENDER TOWN",
  ["6b:653a"] = "INDIGO PLATEAU\012The Ultimate Goal\nfor Trainers!\012POKéMON LEAGUE HQ",
  ["6b:65a0"] = "Trainers who seek\npower climb MT.\012SILVER despite its\nmany dangers…\012With their trusted\nPOKéMON, they must\012feel they can go\nanywhere…",
  ["6b:6682"] = "Oh, dear.\nYou've found me.\012Please don't tell\nanyone about me.\012I'll give you this\nfor keeping my\011secret. Please?",
  ["6b:66f0"] = "It's tough being a\ntop celebrity.\012Everywhere I go,\npeople chase me.\012I just want to be\nleft alone…",
  ["6b:6752"] = "FEAROW: Feero!",
  ["6c:4000"] = "Good morning!\nWelcome to our\011POKéMON CENTER.",
  ["6c:402b"] = "Hello!\nWelcome to our\011POKéMON CENTER.",
  ["6c:404f"] = "Good evening!\nYou're out late.\012Welcome to our\nPOKéMON CENTER.",
  ["6c:408a"] = "Good morning!\012This is the POKé-\nMON COMMUNICATION\012CENTER--or the\nPOKéCOM CENTER.",
  ["6c:40d6"] = "Hello!\012This is the POKé-\nMON COMMUNICATION\012CENTER--or the\nPOKéCOM CENTER.",
  ["6c:411b"] = "Good to see you\nworking so late.\012This is the POKé-\nMON COMMUNICATION\012CENTER--or the\nPOKéCOM CENTER.",
  ["6c:417a"] = "We can heal your\nPOKéMON to perfect\011health.\012Shall we heal your\nPOKéMON?",
  ["6c:41bd"] = "OK, may I see your\nPOKéMON?",
  ["6c:41d7"] = "Thank you for\nwaiting.\012Your POKéMON are\nfully healed.",
  ["6c:420b"] = "We hope to see you\nagain.",
  ["6c:4241"] = "Your POKéMON\nappear to be\012infected by tiny\nlife forms.\012Your POKéMON are\nhealthy and seem\011to be fine.\012But we can't tell\nyou anything more\012at a POKéMON\nCENTER.",
  ["6c:42d6"] = "Your POKéMON\nappear to be\012infected by tiny\nlife forms.\012Your POKéMON are\nhealthy and seem\011to be fine.\012But we can't tell\nyou anything more.",
  ["6c:435a"] = "It's full of\ndifficult books.",
  ["6c:4378"] = "A whole collection\nof POKéMON picture\011books!",
  ["6c:43a3"] = "POKéMON magazines…\nPOKéMON PAL,\012POKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["6c:43d9"] = "TEAM ROCKET OATH\012Steal POKéMON for\nprofit!\012Exploit POKéMON\nfor profit!\012All POKéMON exist\nfor the glory of\011TEAM ROCKET!",
  ["6c:4448"] = "What is this?\012Oh, it's an\nincense burner!",
  ["6c:4472"] = "Lots of POKéMON\nmerchandise!",
  ["6c:448d"] = "It's the TOWN MAP.",
  ["6c:44a0"] = "My reflection!\nLookin' good!",
  ["6c:44be"] = "It's a TV.",
  ["6c:44c9"] = "POKéMON JOURNAL\nHOME PAGE…\012It hasn't been\nupdated…",
  ["6c:4526"] = "There's nothing in\nhere…",
  ["6c:457f"] = "Heal Your POKéMON!\nPOKéMON CENTER",
  ["6c:459c"] = "For All Your\nPOKéMON Needs\012POKéMON MART",
  ["6c:45bf"] = "We will now judge\nthe POKéMON you've\011caught.\012……\n……\012We have chosen the\nwinners!\012Are you ready for\nthis?",
  ["6c:4621"] = "{PLAYER}, the No.{STRBUF}\nfinisher, wins\011{STRBUF}!",
  ["6c:4648"] = "{PLAYER} received\n{STRBUF}.",
  ["6c:465b"] = "Please join us for\nthe next Contest!",
  ["6c:4681"] = "Everyone else gets\na BERRY as a con-\011solation prize!",
  ["6c:46b7"] = "We hope you do\nbetter next time.",
  ["6c:46d9"] = "We'll return the\nPOKéMON we kept\012for you.\nHere you go!",
  ["6c:470d"] = "Your party's full,\nso the POKéMON was\012sent to your BOX\nin BILL's PC.",
  ["6c:474e"] = "{STRBUF}\nPOKéMON GYM",
  ["6c:475c"] = "LEADER: {STRBUF}\012WINNING TRAINERS:\n{PLAYER}",
  ["6c:477f"] = "Welcome to the\nGAME CORNER.",
  ["6c:479c"] = "Do you need game\ncoins?\012Oh, you don't have\na COIN CASE for\011your coins.",
  ["6c:47e3"] = "Do you need some\ngame coins?\012It costs ¥1000 for\n50 coins. Do you\011want some?",
  ["6c:4830"] = "Thank you!\nHere are 50 coins.",
  ["6c:484f"] = "Thank you! Here\nare 500 coins.",
  ["6c:486f"] = "You don't have\nenough money.",
  ["6c:488c"] = "Whoops! Your COIN\nCASE is full.",
  ["6c:48ad"] = "No coins for you?\nCome again!",
  ["6c:48cc"] = "Oh? Your PACK is\nfull.\012We'll keep this\nfor you today, so\012come back when you\nmake room for it.",
  ["6c:492a"] = "Wow! You and your\nPOKéMON are really\011close!",
  ["6c:4954"] = "POKéMON get more\nfriendly if you\012spend time with\nthem.",
  ["6c:4989"] = "You haven't tamed\nyour POKéMON.\012If you aren't\nnice, it'll pout.",
  ["6c:49c4"] = "{PLAYER} registered\n{STRBUF}'s number.",
  ["6c:49e1"] = "{PLAYER} registered\n{STRBUF}'s number.",
  ["6c:49fe"] = "Your knowledge is\nimpressive!\012I like that!\012Want to trade\nbattle tips?\012I'll phone if I\nget good info.\012Would you tell me\nyour number?",
  ["6c:4a82"] = "Want to trade\nbattle tips?\012I'll phone if I\nget good info.\012Would you tell me\nyour number?",
  ["6c:4adb"] = "I'll call you if I\nhear anything!",
  ["6c:4afd"] = "Oh, OK. Too bad…\012Well, if you ever\nwant my number,\011come see me, OK?",
  ["6c:4b42"] = "Oh?\nYour phone's full.\012It can't register\nmy number.",
  ["6c:4b75"] = "Hi, I was waiting\nfor you to show!\012Let's get started\nright away!",
  ["6c:4bb6"] = "Your MARILL is so\ncute and adorable!\012You love POKéMON\njust like I do!\012Want to trade\nphone numbers?\012Let's chat! It'll\nbe so much fun!",
  ["6c:4c37"] = "Your MARILL is so\ncute and adorable!\012We should chat, it\nwill be fun.\012Can I have your\nphone number?",
  ["6c:4c9b"] = "To be honest, I\nwant a MARILL.\012But I make do with\nmy cute SNUBBULL.",
  ["6c:4ce0"] = "Oh… That's\ndisappointing…\012Goodbye, MARILL…",
  ["6c:4d0b"] = "Oh? Your phone's\nmemory is full.",
  ["6c:4d2c"] = "Oh? {PLAYER}? \nI waited here for\012you. I brought you\na little gift.",
  ["6c:4d69"] = "Oh?\nYou have no room.\012Please come back\nfor it later.",
  ["6c:4d9f"] = "Cool! That's the\nfirst time I've\011lost in a while!\012Hey, give me your\nphone number.\012You'd be fun to\nbattle, so I'll\012call you when I\nget stronger!",
  ["6c:4e2c"] = "Hey, give me your\nphone number.\012You'd be fun to\nbattle, so I'll\012call you when I\nget stronger!",
  ["6c:4e89"] = "Hey, let's battle\nagain!",
  ["6c:4ea2"] = "Looks like you're\na wimp…",
  ["6c:4ebc"] = "Hey! Your phone's\nalready full!",
  ["6c:4edc"] = "Hey! I'm tired of\nwaiting for you!",
  ["6c:4eff"] = "Oh… Your PACK's\nfull. I'll give it\011to you later.",
  ["6c:4f2f"] = "Man! You're as\ntough as ever!\012I've battled you\nover and over, but\012{PLAYER}, I haven't\nwon once.\012I bought tons of\nitems to toughen\012up my POKéMON, but\nto no avail…\012Items alone aren't\nthe answer.\012That must be what\nit is…\012Here, take this,\n{PLAYER}.\012I won't be needing\nit anymore…",
  ["6c:502e"] = "Wow, you're tough.\nI haven't battled\012that seriously in\na long time.\012Could I get your\nphone number?\012I'd like to battle\nagain when I heal\012{STRBUF} and the\nrest of my team.",
  ["6c:50d3"] = "Could I get your\nphone number?\012I'd like to battle\nagain when I heal\012{STRBUF} and the\nrest of my team.",
  ["6c:5136"] = "How should I beat\nyou? I'm tormented\012by those thoughts\nall the time…",
  ["6c:517b"] = "OK… I understand…\nBut if you change\012your mind, give me\na shout anytime.",
  ["6c:51c4"] = "Your phone's\nmemory is full.\012You can't register\nmy number.",
  ["6c:51fe"] = "Hi! I've been\nwaiting for you!\012This time, I'm\ngoing to win!",
  ["6c:5239"] = "It's been a while\nsince I lost…\012You're very good\nat battling.\012We should battle\nagain sometime.\012By challenging a\ntough trainer like\012you, I think I can\nget better too.\012So how about it?\012Would you give me\nyour phone number?",
  ["6c:5314"] = "By challenging a\ntough trainer like\012you, I think I can\nget better too.\012So how about it?\012Would you give me\nyour phone number?",
  ["6c:5392"] = "Let's battle again\nsometime!",
  ["6c:53af"] = "That's too bad…\012Let me know if you\nchange your mind.",
  ["6c:53e4"] = "Oh no. Your phone\nis out of memory.",
  ["6c:5409"] = "You sure kept me\nwaiting! Let's go!",
  ["6c:542d"] = "If my {STRBUF}\nsees anything\012pretty, it goes\nand gets it.\012Do you like pretty\nthings?\012I could share if\nit gets some more.\012What's your phone\nnumber? I'll call.\012Don't expect a\nwhole lot, OK?",
  ["6c:54e4"] = "Do you like pretty\nthings?\012I could share if\nFARFETCH'D goes\011and gets more.\012What's your phone\nnumber? I'll call.",
  ["6c:5553"] = "I'll call you as\nsoon as I get\011something pretty.",
  ["6c:5584"] = "You sure? Well,\ntell me if you\011change your mind.",
  ["6c:55b6"] = "Huh? Your phone\nlist is full.",
  ["6c:55d5"] = "Tweet! Tweeeet!\012Kept me waiting!\nGo, FARFETCH'D!",
  ["6c:5607"] = "Kept me waiting!\nLook, this is it!\012See? Isn't it some\nkind of pretty?",
  ["6c:564d"] = "Huh? You don't\nhave anywhere to\012put this. Better\ncome back for it.",
  ["6c:5690"] = "Not bad…\nIt's something to\012beat me, even by\nan unlikely fluke…\012I like you! Give\nme your number!\012You can be my\npractice partner!",
  ["6c:5710"] = "Give me your phone\nnumber!\012You are going to\nbe my practice\011partner!",
  ["6c:5755"] = "Don't be too proud\nabout beating me!\012It was a fluke!",
  ["6c:578a"] = "I don't believe\nit! You're going\011to regret this!",
  ["6c:57ba"] = "What? Your phone\nlist has no room!",
  ["6c:57de"] = "What took you?\nStart right away!",
  ["6c:5800"] = "Listen, can I get\nyour phone number?\012I'll ring you for\nsome battles.\012I'm a rookie too, \nso I think it'd be\011a good motivator.",
  ["6c:587b"] = "Can I get your\nphone number?\012I don't want to\nlose against you!\012We have to battle\nagain, OK?",
  ["6c:58d7"] = "I'll ring you\nwhenever I get the\011urge to battle!",
  ["6c:5908"] = "Oh, all right…\012But I won't lose\nto you again!",
  ["6c:5936"] = "Huh, what? Your\nphone's full.",
  ["6c:5954"] = "I've been waiting!\nLet's battle now!",
  ["6c:5978"] = "Hey, wait! Your\nPACK is stuffed!\012Well, we'll leave\nit till next time.",
  ["6c:59be"] = "And yet another\nloss…\012No doubt about\nit--you're tough.\012Being beaten this\noften actually\011feels good now!\012Here, take this. \nUse it to get even\012tougher. That will\ntoughen me up too!",
  ["6c:5a71"] = "You're awesome!\nI like you!\012I look for POKéMON\nhere every day.\012When I'm in the\ngrass, I find all\011kinds of BERRIES.\012If you'd like,\nI'll share some.\012Could I get your\nphone number?",
  ["6c:5b1d"] = "When I'm in the\ngrass, I find all\011kinds of BERRIES.\012If you'd like,\nI'll share some.\012Could I get your\nphone number?",
  ["6c:5b8e"] = "You'll hear from\nme as soon as I\012find anything that\nyou might like.",
  ["6c:5bd2"] = "Oh well. Don't be\nshy if you want to\011get my number.",
  ["6c:5c06"] = "Your phone list\nhas no room for my\011number.",
  ["6c:5c32"] = "I was waiting for\nyou. Let's battle!",
  ["6c:5c57"] = "Good to see you!\nSee? This is what\012I found.\nIt's for you!",
  ["6c:5c91"] = "Oops, your PACK's\nfull. Too bad.\012You should come\nback for it later.",
  ["6c:5cd5"] = "Don't young people\nfish anymore?\012I've seen rare\nPOKéMON while I've\011been fishing…\012You young people\nlike that, right?\012Want to trade\nphone numbers?\012I'll let you know\nif I see anything.",
  ["6c:5d85"] = "Hm? So you do want\nme to phone if I\011see rare POKéMON?",
  ["6c:5db9"] = "Yep, phone if I\nsee rare POKéMON.\012Don't worry, I\nwon't forget!",
  ["6c:5df4"] = "Oh…\nMy own kids won't\012even give me their\nphone numbers…\012Is that how young\npeople are today?",
  ["6c:5e50"] = "Your phone's\nmemory is full.\012It seems that\nyoung people all\011have POKéGEAR.",
  ["6c:5e98"] = "Hey, kid!\012No losing for me\nthis day!",
  ["6c:5ebe"] = "Oh? You're on a\nbig journey to see\011the sights? Neat!\012Let's be friends!\nCan I have your\011phone number?\012I want to hear\nabout everything\011you've seen!",
  ["6c:5f4e"] = "Let's be friends!\nCan I have your\011phone number?\012I want to hear\nabout everything\011you've seen!",
  ["6c:5faa"] = "I'll telephone you\nif I hear anything\011interesting.",
  ["6c:5fdd"] = "Aww… You won't be\nmy friend?",
  ["6c:5ffa"] = "Wait! Your phone\nlist is filled up!",
  ["6c:601f"] = "You're late! Let's\nget started now!",
  ["6c:6054"] = "MT.SILVER",
  ["6c:6086"] = "KANTO POWER PLANT",
  ["6d:4000"] = "Hello?\012Oh, hi, {PLAYER}!\nWorking hard?",
  ["6d:4021"] = "Oh, so you're in\n{STRBUF}…\012Isn't that where\n{STRBUF}\012is? Did you go\ntake a look?",
  ["6d:406b"] = "Really, you're in\n{STRBUF}?\012I've never gone\nthere. That's kind\011of neat, {PLAYER}.",
  ["6d:40b1"] = "What? You're in\n{STRBUF}?\012Come see your MOM\nsometime!",
  ["6d:40e4"] = "You're visiting\n{STRBUF}?\012How about coming\nhome for a bit?",
  ["6d:411c"] = "Wow, you're in\n{STRBUF}?\012Good luck on your\nPOKéMON quest!",
  ["6d:4150"] = "That sounds really\ntough.\012But, {PLAYER}, I\nknow you're really\012determined. You'll\nbe OK, right?",
  ["6d:41a7"] = "By the way, you've\nsaved up ¥{STRBUF}.\012Do you want to\nkeep on saving?",
  ["6d:41ea"] = "It's important to\nsave your money.",
  ["6d:420d"] = "Oh, {PLAYER},\nyou're not saving\012any money. Would\nyou like to save?",
  ["6d:4249"] = "By the way, you've\nsaved up ¥{STRBUF}.\012Want to start\nsaving again?",
  ["6d:4289"] = "OK. I'll save your\nmoney.",
  ["6d:42a3"] = "OK. I won't save\nyour money.",
  ["6d:42c0"] = "{PLAYER}, keep it\nup! I'm rooting\011for you, baby!",
  ["6d:42ea"] = "Hello?\012Oh, hi, {PLAYER}!\nWasn't PROF.ELM\011waiting for you?",
  ["6d:431d"] = "Hello?\012Oh, hi, {PLAYER}!\nYou're on a big\012mission for PROF.\nELM? Be good!",
  ["6d:435f"] = "Hello?\012Hi, {PLAYER}! If\nyou're done with\012your errand come\non home, dear.",
  ["6d:43a1"] = "Hello?\012…… {PLAYER}?\nI heard from PROF.\012ELM that you went\non a long trip.\012I wish you would\nhave told me…\012What about money?\nShould I save it?",
  ["6d:4427"] = "Good morning!\012This is the POKé-\nMON STORAGE SYSTEM\012ADMINISTRATION\nSERVICE.",
  ["6d:4470"] = "Good day!\012This is the POKé-\nMON STORAGE SYSTEM\012ADMINISTRATION\nSERVICE.",
  ["6d:44b5"] = "Good evening!\012This is the POKé-\nMON STORAGE SYSTEM\012ADMINISTRATION\nSERVICE.",
  ["6d:44fe"] = "Who's calling?\012{PLAYER}, is it?\nHang on a sec…\012……\n……",
  ["6d:452a"] = "Thanks for\nwaiting!\012{PLAYER}, your BOX\nhas room for {STRBUF}\011more POKéMON.\012Get out there and\nfill it up!",
  ["6d:4587"] = "Thanks for\nwaiting!\012{PLAYER}, your BOX\nhas room for only\011{STRBUF} more POKéMON.\012Maybe you should\nswitch your BOX.",
  ["6d:45ed"] = "Thanks for\nwaiting!\012{PLAYER}, your BOX\nis full!\012You'll have to\nswitch BOXES if\012you want to catch\nmore POKéMON.",
  ["6d:4652"] = "Hi, {PLAYER}?\nIt's me, BILL!\012Thanks for using\nmy STORAGE SYSTEM.\012That last POKéMON\nyou sent filled\011your BOX up.\012You'll have to\nswitch BOXES if\012you want to catch\nmore POKéMON.\012Bye now!",
  ["6d:46fc"] = "Hello, {PLAYER}?\012Try not to overdo\nit.\012Be sure to heal\nyour POKéMON if\011they are hurt.",
  ["6d:4749"] = "Hello, {PLAYER}?\012Did you meet MR.\nPOKéMON? Great!\011Come back safely!",
  ["6d:4784"] = "{PLAYER}? I'm very\nupset now.\012We had a POKéMON\nstolen from here.\012How could anyone\ndo that?",
  ["6d:47d5"] = "Hello, {PLAYER}?\012We're checking the\nEGG now. It does\012appear to be a\nPOKéMON EGG.",
  ["6d:481c"] = "Hello, {PLAYER}?\012Did you see my\nassistant? He's at\012the POKéMON CENTER\nin VIOLET CITY.",
  ["6d:4868"] = "Hello, {PLAYER}?\012How's the EGG? Has\nanything changed?\012If anything hap-\npens, please call.",
  ["6d:48bb"] = "Hello, {PLAYER}?\nHow is the EGG?\012What? It hatched?\nWow! What kind of\011POKéMON is it?\012Please come show\nme now!",
  ["6d:491f"] = "Hello, {PLAYER}?\012I just made a new\ndiscovery.\012The time it takes\nfor an EGG to\012hatch depends on\nthe POKéMON.",
  ["6d:4982"] = "Hello, {PLAYER}?\012It's still a\nmystery what kinds\012of moves hatched\nPOKéMON have.\012We're investigat-\ning that now.",
  ["6d:49e7"] = "Hello, {PLAYER}?\012I discovered an\nodd thing.\012Apparently there's\nsomething called\012POKéRUS that in-\nfects POKéMON.\012Yes, it's like a\nvirus, so it's\011called POKéRUS.\012It multiplies fast\nand infects other\012POKéMON too. But\nthat's all.\012It doesn't seem to\ndo anything, and\012it goes away over\ntime.\012I guess it's\nnothing to worry\011about. Bye!",
  ["6d:4b17"] = "H-hello? {PLAYER}?\nIt's a disaster!\012Uh, um, it's just\nterrible!\012What should I do?\nIt… Oh, no…\012Please get back\nhere now!",
  ["6d:4b87"] = "Hello, {PLAYER}? We\ndiscovered some-\012thing about the\nEGG!\012My assistant is at\nthe POKéMON CENTER\012in VIOLET CITY. \nCould you talk to\011him?",
  ["6d:4c06"] = "{PLAYER}, how are\nthings going?\012I called because\nsomething weird is\012happening with the\nradio broadcasts.\012They were talking\nabout TEAM ROCKET.\012{PLAYER}, do you\nknow anything\011about it?\012Maybe TEAM ROCKET\nhas returned. No,\012that just can't\nbe true.\012Sorry to bug you.\nTake care!",
  ["6d:4d09"] = "Hello, {PLAYER}?\012I have something\nhere for you.\012Could you swing by\nmy LAB?\012See you later!",
  ["6d:4dc5"] = "Hello. This is\n{STRBUF}…\012Good morning,\n{PLAYER}!",
  ["6d:4ded"] = "Hello. This is\n{STRBUF}…\012How's it going,\n{PLAYER}?",
  ["6d:4e16"] = "Hello. This is\n{STRBUF}…\012Good evening,\n{PLAYER}!",
  ["6d:4e3e"] = "{PLAYER}, good\nmorning!\012It's me, {STRBUF}.\nHow are you doing?",
  ["6d:4e72"] = "{PLAYER}, howdy!\012It's me, {STRBUF}.\nIsn't it nice out?",
  ["6d:4e9e"] = "{PLAYER}, good\nevening!\012It's me, {STRBUF}.\nGot a minute?",
  ["6d:4ecd"] = "How are your\nPOKéMON doing?\012My {STRBUF} is\nso curious, it's a\012problem. Maybe\nit's like me…",
  ["6d:4f21"] = "Hello, this is\n{STRBUF}.\012Oh! Good morning,\n{PLAYER}.",
  ["6d:4f4d"] = "Hello, this is\n{STRBUF}.\012Oh! Good day,\n{PLAYER}.",
  ["6d:4f75"] = "Hello, this is\n{STRBUF}.\012Oh! Good evening,\n{PLAYER}.",
  ["6d:4fa1"] = "Hello, {PLAYER}.\nGood morning.\012This is {STRBUF}.\nWere you asleep?",
  ["6d:4fda"] = "Hi, {PLAYER}.\nThis is {STRBUF}.\012How are you doing?",
  ["6d:5004"] = "Hi, {PLAYER}.\nThis is {STRBUF}.\012Were you awake?",
  ["6d:502b"] = "Keeping your\nPOKéMON happy?\012My {STRBUF} is\nhealthy. It eats a\011lot every day.",
  ["6d:5073"] = "Yeah, this is\n{STRBUF}.\012Huh? What's up,\n{PLAYER}?",
  ["6d:509b"] = "Yeah, this is\n{STRBUF}.\012Huh? What's up\n{PLAYER}?",
  ["6d:50c2"] = "Yeah, this is\n{STRBUF}.\012Huh? What's up\n{PLAYER}?",
  ["6d:50e9"] = "Yo, {PLAYER}!\nYou awake?\012It's me, {STRBUF}!\nHow's it going?",
  ["6d:511a"] = "Yo, {PLAYER}! You\nfree right now?\012It's me, {STRBUF}!\nHow's it going?",
  ["6d:5154"] = "Yo, {PLAYER}!\nWere you asleep?\012It's me, {STRBUF}!\nHow's it going?",
  ["6d:518b"] = "How are your\nPOKéMON doing?\012My POKéMON are a\nbit too energetic.\012{STRBUF},\nespecially.\012Every time it\nspots a trainer,\011it has to battle.\012It gets to be a\nbit much for me!",
  ["6d:522b"] = "My {STRBUF}'s\nlooking tougher\011than ever.\012It looks even\ntougher than me!",
  ["6d:5270"] = "Hello, this is\n{STRBUF} speaking…\012Hi, {PLAYER}!\nGood morning!",
  ["6d:52a5"] = "Hello, this is\n{STRBUF} speaking…\012Hi, {PLAYER}!",
  ["6d:52cc"] = "Hello, this is\n{STRBUF} speaking…\012Hi, {PLAYER}!\nGood evening!",
  ["6d:5301"] = "{PLAYER}, good\nmorning!\012It's me, {STRBUF}.\nHow are you doing?",
  ["6d:5335"] = "Hi, {PLAYER}!\012It's me, {STRBUF}.\nHow are you doing?",
  ["6d:535f"] = "{PLAYER}, good\nevening!\012It's me, {STRBUF}.\nHow are you doing?",
  ["6d:5393"] = "How are your\nPOKéMON doing?\012My {STRBUF}'s\ndoing as great as\011ever.\012Let's keep at it\nand become POKéMON\011CHAMPS!",
  ["6d:53f7"] = "Hello, this is\n{STRBUF}.\012Oh, {PLAYER}.\nGood morning.\012",
  ["6d:5424"] = "Hello, this is\n{STRBUF}.\012Oh. Hi, {PLAYER}.",
  ["6d:5446"] = "Hello, this is\n{STRBUF}.\012Oh, {PLAYER}.\nGood evening.",
  ["6d:5472"] = "Good morning,\n{PLAYER}!\012This is {STRBUF}.\nWere you sleeping?",
  ["6d:54a6"] = "{PLAYER}, hi!\nThis is {STRBUF}.\012Do you have some\ntime?",
  ["6d:54d4"] = "Hi, {PLAYER}.\nGood evening.\012This is {STRBUF}.\012I hope you were\nawake.",
  ["6d:5510"] = "Are you the kind\nof person who goes\012to POKéMON CENTERS\noften?\012I go every day.\nWatching out for\012the health of your\nPOKéMON is a basic\012part of being a\nPOKéMON trainer.",
  ["6d:55ae"] = "Hello, this is\n{STRBUF}…\012Oh, {PLAYER}?\nGood morning!",
  ["6d:55da"] = "Hello, this is\n{STRBUF}…\012Oh, {PLAYER}? Hi!",
  ["6d:55fc"] = "Hello, this is\n{STRBUF}…\012Oh, {PLAYER}?\nGood evening!",
  ["6d:5628"] = "Oh, {PLAYER}?\012Tweet! Yeah, it's\nme, {STRBUF}.",
  ["6d:564c"] = "Oh, {PLAYER}?\012Tweet! Yeah, it's\nme, {STRBUF}.",
  ["6d:5670"] = "Oh, {PLAYER}?\012Tweet! Yeah, it's\nme, {STRBUF}.",
  ["6d:5694"] = "Are your POKéMON\nstill cooking?\012My {STRBUF} has\ntoo much energy.\012Once it takes off,\nit won't come back\011for a while.",
  ["6d:5702"] = "Hello, this is\n{STRBUF}…\012Oh. Hi, {PLAYER}.\nWhat's up?",
  ["6d:572e"] = "Hello, this is\n{STRBUF}…\012Oh. Hi, {PLAYER}.\nWhat's up?",
  ["6d:575a"] = "Hello, this is\n{STRBUF}…\012Oh. Hi, {PLAYER}.\nWhat's up?",
  ["6d:5786"] = "You're slow! Hurry\nup and answer!\012It's me, {STRBUF}!",
  ["6d:57b7"] = "You're slow! Hurry\nup and answer!\012It's me, {STRBUF}!",
  ["6d:57e8"] = "You're slow! Hurry\nup and answer!\012It's me, {STRBUF}!",
  ["6d:5819"] = "Hey, how are your\nPOKéMON doing?\012What? Great?\nI see…\012What? My POKéMON?\012Of course they're\ndoing great! What\012kind of a question\nis that?",
  ["6d:589a"] = "Hi, {STRBUF} here!\012Oh, {PLAYER}? You\ndoing well?",
  ["6d:58c2"] = "Hi, {STRBUF} here!\012Oh, {PLAYER}? You\ndoing well?",
  ["6d:58ea"] = "Hi, {STRBUF} here!\012Oh, {PLAYER}? You\ndoing well?",
  ["6d:5912"] = "Yo, {PLAYER}!\nHow're you doing?\012This is {STRBUF},\ngot a minute?",
  ["6d:5948"] = "Yo, {PLAYER}! How's\nit going?\012This is {STRBUF}.\nGot a minute?",
  ["6d:597c"] = "Yo, {PLAYER}!\nHow're you doing?\012This is {STRBUF},\ngot a minute?",
  ["6d:59b2"] = "How are your\nPOKéMON doing?\012My {STRBUF}'s\nraring to go, just\011like always.\012It's the only one\nI have. I'm going\012to become a great\ntrainer with it!",
  ["6d:5a3b"] = "Hello? This is\n{STRBUF} speaking.\012Oh. Hi, {PLAYER}!\nGood morning!",
  ["6d:5a74"] = "Hello? This is\n{STRBUF} speaking.\012Oh, hi, {PLAYER}!",
  ["6d:5a9f"] = "Hello? This is\n{STRBUF} speaking.\012Oh, hi, {PLAYER}!\nGood evening!",
  ["6d:5ad8"] = "{PLAYER}, good\nmorning!\012It's me, {STRBUF}.\nIsn't it nice out?",
  ["6d:5b0b"] = "{PLAYER}, howdy!\012It's me, {STRBUF}.\nIsn't it nice out?",
  ["6d:5b37"] = "Good evening,\n{PLAYER}!\012It's me, {STRBUF}.\nWere you awake?",
  ["6d:5b68"] = "How are your\nPOKéMON doing?\012My POKéMON have\ntoo much energy to\012burn. It gets to\nbe a problem.\012Of all my POKéMON,\n{STRBUF} is the\011hardest to handle.\012Working with it is\nexhausting.",
  ["6d:5c10"] = "Yes? Ah, {PLAYER}.\012You're courteous\nenough to state\012your name when you\ncall on the phone.",
  ["6d:5c63"] = "Yes? Ah, {PLAYER}.\012You're courteous\nenough to state\012your name when you\ncall on the phone.",
  ["6d:5cb6"] = "Yes? Ah, {PLAYER}.\012You're courteous\nenough to state\012your name when you\ncall on the phone.",
  ["6d:5d09"] = "Hiya, it's Uncle\n{STRBUF}.",
  ["6d:5d21"] = "Hiya, it's Uncle\n{STRBUF}.",
  ["6d:5d39"] = "Hiya, it's Uncle\n{STRBUF}.",
  ["6d:5d51"] = "Are you taking\ngood care of your\012POKéMON? You have\nto be good to your\011partners!",
  ["6d:5d9f"] = "Hello, {STRBUF}\nspeaking.\012Oh, {PLAYER}.\nGood morning.",
  ["6d:5dcc"] = "Hello, {STRBUF}\nspeaking.\012Oh, {PLAYER}.\nHow are you?",
  ["6d:5df8"] = "Hello, {STRBUF}\nspeaking.\012Oh, {PLAYER}.\nGood evening.",
  ["6d:5e25"] = "Good morning,\n{PLAYER}.\012This is {STRBUF}.\nWere you sleeping?",
  ["6d:5e59"] = "Hi, {PLAYER}.\nThis is {STRBUF}.\012How are things\ngoing for you?",
  ["6d:5e8e"] = "Good evening,\n{PLAYER}.\012This is {STRBUF}.\nAre you awake?",
  ["6d:5ebe"] = "I had some time,\nso I called you.\012So anyway, how are\nyour POKéMON?\012Me, I take my\n{STRBUF} to the\012POKéMON CENTER in\nVIOLET every day,\012so it's doing just\nfantastic!\012I'm friends with\nthe receptionist!",
  ["6d:5f7a"] = "Yeah, {STRBUF} the\nHIKER here.\012Ah, {PLAYER}!",
  ["6d:5f9e"] = "Yeah, {STRBUF} the\nHIKER here.\012Ah, {PLAYER},\nright?",
  ["6d:5fc9"] = "Yeah, {STRBUF} the\nHIKER here.\012Ah, {PLAYER}, isn't\nit?",
  ["6d:5ff6"] = "Yo, {PLAYER}?\012This is {STRBUF}\nthe HIKER!",
  ["6d:6017"] = "Hey, is this\n{PLAYER}?\012This is {STRBUF}\nthe HIKER!",
  ["6d:6041"] = "{PLAYER}, you still\nawake?\012This is {STRBUF}\nthe HIKER!",
  ["6d:606f"] = "Are your POKéMON\nas feisty as ever?\012My {STRBUF} and\nme--we have energy\012to burn. We hike\nup mountains every\012day to work out\nall our energy.",
  ["6d:60f5"] = "Yes? This is\n{STRBUF} speaking.\012Hey, {PLAYER}!",
  ["6d:611b"] = "Yes? This is\n{STRBUF} speaking.\012This must be\n{PLAYER}.",
  ["6d:6149"] = "Yes? This is\n{STRBUF} speaking.\012Ah, {PLAYER}!",
  ["6d:616e"] = "Hello, this is\n{STRBUF}.\012{PLAYER}, right?",
  ["6d:618f"] = "Hello, this is\n{STRBUF}.\012{PLAYER}, what are\nyou doing?",
  ["6d:61bd"] = "Hello, this is\n{STRBUF}.\012{PLAYER}, sorry to\ncall you so late.",
  ["6d:61f2"] = "How do you raise\nyour POKéMON?\012I do all sorts\nof things, like\012leaving them in\nDAY-CARE and\012toughening them up\nwith items.",
  ["6d:626a"] = "Hello? This is\n{STRBUF}…\012Oh, {PLAYER}!\nGood morning!",
  ["6d:6296"] = "Hello? This is\n{STRBUF}…\012Oh, {PLAYER}!\nHi, how are you?",
  ["6d:62c5"] = "Hello? This is\n{STRBUF}…\012Oh, {PLAYER}!\nGood evening!",
  ["6d:62f1"] = "{PLAYER}?\012It's {STRBUF}.\nGood morning!",
  ["6d:630e"] = "{PLAYER}?\012It's {STRBUF}. Is\nthis a bad time?",
  ["6d:6331"] = "{PLAYER}?\012It's {STRBUF}.\nGot time to chat?",
  ["6d:6352"] = "Are your POKéMON\nstill tough?\012I train every day\nwith {STRBUF}.",
  ["6d:638c"] = "Hello? {STRBUF}\nhere…\012Hey, {PLAYER}!",
  ["6d:63a8"] = "Hello? {STRBUF}\nhere…\012Wow, {PLAYER}!",
  ["6d:63c4"] = "Hello? {STRBUF}\nhere…\012Yippee, {PLAYER}!",
  ["6d:63e3"] = "Uh, hello.\n{PLAYER}?\012It's your pal,\n{STRBUF}!",
  ["6d:6407"] = "Uh, hello,\n{PLAYER}?\012It's your buddy\n{STRBUF}!",
  ["6d:642c"] = "Uh, hello,\n{PLAYER}?\012It's your sidekick\n{STRBUF}!",
  ["6d:6454"] = "Yeah, hello.\nThis is {STRBUF}.\012…Huh, {PLAYER}? Yo!",
  ["6d:647e"] = "Yeah, hello, you\ngot {STRBUF}.\012…Huh, {PLAYER}? Yo!",
  ["6d:64a8"] = "Yeah, hello, you\ngot {STRBUF}.\012…Huh, {PLAYER}? Yo!",
  ["6d:64d2"] = "Yeah, hello?\n{STRBUF} calling.\012What are you up\nto, {PLAYER}?",
  ["6d:6506"] = "Yeah, hello?\n{STRBUF} calling.\012Where are you now,\n{PLAYER}?",
  ["6d:6539"] = "Yeah, hello?\n{STRBUF} calling.\012Are you awake now,\n{PLAYER}?",
  ["6d:656c"] = "I bet your POKéMON\nare a lot stronger\011than before.",
  ["6d:659d"] = "Yup, it's {STRBUF}!\012Is this {PLAYER}?\nGood morning!",
  ["6d:65c7"] = "Yup, it's {STRBUF}!\012Is that {PLAYER}?",
  ["6d:65e3"] = "Yup, it's {STRBUF}!\012Is that {PLAYER}?\nGood evening!",
  ["6d:660d"] = "Hello! It's me,\n{STRBUF}!",
  ["6d:6624"] = "Hello! It's me,\n{STRBUF}!",
  ["6d:663b"] = "Hello! It's me,\n{STRBUF}!",
  ["6d:6652"] = "{PLAYER}, are you\nraising your\011POKéMON properly?\012I read in a book\nthat you should\012raise any POKéMON\nyou catch with\011love and care.",
  ["6d:66c8"] = "Hi, {STRBUF} on the\nline.\012Hey! It's {PLAYER}!",
  ["6d:66ec"] = "Hi, {STRBUF} on the\nline.\012I know!\nIt's {PLAYER}!",
  ["6d:6713"] = "Hi, {STRBUF} on the\nline.\012{PLAYER}?\nWhat's up?",
  ["6d:6738"] = "Uh, {PLAYER}?\012It's me!\nIt's me, {STRBUF}!",
  ["6d:6757"] = "Uh, {PLAYER}?\012It's me!\nIt's me, {STRBUF}!",
  ["6d:6776"] = "Uh, {PLAYER}?\012It's me!\nIt's me, {STRBUF}!",
  ["6d:6795"] = "My {STRBUF} is\nso full of energy,\012it's a little\nscary.\012How are your\nPOKéMON doing?",
  ["6d:67e2"] = "Hello, this is\n{STRBUF}…\012Hi, {PLAYER}!\nGood morning!",
  ["6d:680e"] = "Hello, this is\n{STRBUF}…\012Hi, {PLAYER}, good\nday!",
  ["6d:6836"] = "Hello, this is\n{STRBUF}…\012Hi, {PLAYER}, good\nevening!",
  ["6d:6862"] = "Hi, {PLAYER}, good\nmorning!\012It's {STRBUF}.\nHow are you?",
  ["6d:6890"] = "Hi, {PLAYER}, good\nday!\012It's {STRBUF}.\nHow are you?",
  ["6d:68ba"] = "Hi, {PLAYER}, good\nevening!\012It's {STRBUF}.\nHow are you?",
  ["6d:68e8"] = "How are your\nPOKéMON doing?\012You know PROF.OAK,\nso of course your\011POKéMON are fine!\012My POKéMON are\ndoing well too.\012But then, I am\ntrying to become a\012POKéMON professor,\nso that shouldn't\011be a big surprise.",
  ["6d:69a8"] = "Hi, {PLAYER}?\012Good morning pika.\nWhat's up pika?",
  ["6d:69d2"] = "Hi, {PLAYER}?\012Good day pika,\nwhat's up pika?",
  ["6d:69f8"] = "Hi, {PLAYER}?\012Good evening pika,\nwhat's up pika?",
  ["6d:6a22"] = "{PLAYER} pika, good\nmorning!\012It's {STRBUF}, how\npika are you?",
  ["6d:6a56"] = "{PLAYER} pika, good\npika day!\012It's {STRBUF}, how\npika are you?",
  ["6d:6a8b"] = "{PLAYER} pika, good\nevening!\012It's {STRBUF}. Were\nyou pika awake?",
  ["6d:6ac2"] = "You have to hear\nthis! My lovable\012{STRBUF} looked\nat me and grinned!\012It must be because\nour hearts beat\011together as one!",
  ["6d:6b39"] = "Hello, this is\n{STRBUF}…\012Oh, Good morning,\n{PLAYER}.",
  ["6d:6b65"] = "Hello, this is\n{STRBUF}…\012That voice…\n{PLAYER}, right?",
  ["6d:6b92"] = "Hello, this is\n{STRBUF}…\012This must be\n{PLAYER}!",
  ["6d:6bb9"] = "Hello!\n{STRBUF} here…\012Good morning! The\nweather's great!",
  ["6d:6bef"] = "Hello!\n{STRBUF} here…\012What a perfect day\nfor fishing!",
  ["6d:6c23"] = "Hello!\n{STRBUF} here…\012It's a great night\nfor fishing!",
  ["6d:6c56"] = "How's your trip\ncoming along?\012I can't complain\nabout my fishing!",
  ["6d:6c96"] = "Yes? {STRBUF} here…\012Ah, {PLAYER}. What\ncan I do for you?",
  ["6d:6cc6"] = "Yes? {STRBUF} here…\012Ah, {PLAYER}. What\ncan I do for you?",
  ["6d:6cf6"] = "Yes? {STRBUF} here…\012Ah, {PLAYER}. What\ncan I do for you?",
  ["6d:6d26"] = "Hiya, {PLAYER}. How\nare you doing?\012Hey! It's me,\n{STRBUF}.",
  ["6d:6d57"] = "Hiya, {PLAYER}. How\nare you doing?\012Hey! It's me,\n{STRBUF}.",
  ["6d:6d88"] = "Hiya, {PLAYER}. How\nare you doing?\012Hey! It's me,\n{STRBUF}.",
  ["6d:6db9"] = "Oh yeah, I saw you\ncoming out of a\012POKéMON CENTER the\nother day.\012You heal your\nPOKéMON regularly,\012don't you?\nI'm impressed.\012Heh, my {STRBUF}\nis so tough, it\012doesn't need to go\nto POKéMON CENTERS\011often. Heheh!",
  ["6d:6e7c"] = "Yes? This is\n{STRBUF}.\012Oh, {PLAYER}.\nGood morning.",
  ["6d:6ea6"] = "Yes? This is\n{STRBUF}.\012Oh, {PLAYER}.\nHello.",
  ["6d:6ec9"] = "Yes? This is\n{STRBUF}.\012Oh, {PLAYER}, good\nevening.",
  ["6d:6ef3"] = "Is this {PLAYER}?\012Good morning. This\nis {STRBUF}.",
  ["6d:6f1c"] = "Is this {PLAYER}?\012Hi, it's {STRBUF}.",
  ["6d:6f37"] = "Is this {PLAYER}?\012Good evening. This\nis {STRBUF}.",
  ["6d:6f60"] = "Are your POKéMON\ndoing well?\012I hope you take\nthem to a POKéMON\011CENTER every day.\012Don't push them\ntoo hard.\012My {STRBUF} is\ncute and lively\012precisely because\nI take it to a\012POKéMON CENTER\nevery day.",
  ["6d:7019"] = "Yes, hello?\n{STRBUF} here!\012Morning, {PLAYER}!\012Are you using bird\nPOKéMON?",
  ["6d:7057"] = "Yes, hello?\n{STRBUF} here!\012Hi, {PLAYER}!\012Are your bird\nPOKéMON flying?",
  ["6d:7092"] = "Yes, hello?\n{STRBUF} here!\012Evening, {PLAYER}!\nAre you letting\012your bird POKéMON\nsee some action?",
  ["6d:70e7"] = "Good morning,\n{PLAYER}!\012It's {STRBUF}!\nGood morning!",
  ["6d:7112"] = "Hi, {PLAYER}!\012It's {STRBUF}!\nRemember me?",
  ["6d:7132"] = "Good evening,\n{PLAYER}!\012It's {STRBUF}!\nAre you free now?",
  ["6d:7161"] = "Are you and your\nPOKéMON fine?\012My {STRBUF}\nlooks like it will\012get tough enough\nto face and beat\012the legendary bird\nPOKéMON!",
  ["6d:71d5"] = "Hello, you have\nreached {STRBUF}…\012Ah, {PLAYER}.",
  ["6d:71fc"] = "Hello, you have\nreached {STRBUF}…\012Ah, {PLAYER}, is\nit?",
  ["6d:722a"] = "Hello, you have\nreached {STRBUF}…\012Ah, if it isn't\n{PLAYER}.",
  ["6d:725c"] = "Ah, it's {STRBUF}…\012Have you got a\nmoment?",
  ["6d:7283"] = "Ah, it's {STRBUF}…\012Can you talk now?",
  ["6d:72a5"] = "Ah, it's {STRBUF}…\012Sorry for calling\nso late.",
  ["6d:72d0"] = "Have your POKéMON\ngrown any?\012My {STRBUF} has\ngrown quite a bit.",
  ["6d:730b"] = "{STRBUF} here…\012{PLAYER}! Beautiful\nmorning, hey?",
  ["6d:7331"] = "{STRBUF} here…\012{PLAYER}! Beautiful\nweather, hey?",
  ["6d:7357"] = "{STRBUF} here…\012{PLAYER}! Beautiful\nmoonlight, hey?",
  ["6d:737f"] = "Hey, {PLAYER}!\nThis is {STRBUF}!",
  ["6d:7397"] = "Hey, {PLAYER}!\nThis is {STRBUF}!",
  ["6d:73af"] = "Hey, {PLAYER}!\nThis is {STRBUF}!",
  ["6d:73c7"] = "Yup, yup!\nIt's {STRBUF}!\012Hah, and here's\n{PLAYER}!",
  ["6d:73ef"] = "Yup, yup!\nIt's {STRBUF}!\012Hah, and here's\n{PLAYER}!",
  ["6d:7417"] = "Yup, yup!\nIt's {STRBUF}!\012Hah, and here's\n{PLAYER}!",
  ["6d:743f"] = "{PLAYER}, it's\n{STRBUF}!\012Have you had a\nproper breakfast?",
  ["6d:746f"] = "{PLAYER}, it's\n{STRBUF}!\012Have you had a\nproper lunch?",
  ["6d:749b"] = "{PLAYER}, it's\n{STRBUF}!\012Have you had a\nproper dinner?",
  ["6d:74c8"] = "Are your POKéMON\nlooking good?\012My {STRBUF} and\nme--we're looking\012mighty dandy!\nHahahah!",
  ["6d:751a"] = "Yes, this is\n{STRBUF}…\012Oh. Hi, {PLAYER}!\nGood morning!",
  ["6d:7548"] = "Yes, this is\n{STRBUF}…\012Oh, hi, {PLAYER}!\nYahoo!",
  ["6d:756f"] = "Yes, this is\n{STRBUF}…\012Oh, hi, {PLAYER}!",
  ["6d:758f"] = "{PLAYER}!\012It's {STRBUF}!\nGood morning!",
  ["6d:75ac"] = "{PLAYER}!\012It's {STRBUF}!\nWorking hard?",
  ["6d:75c9"] = "{PLAYER}!\012It's {STRBUF}!\nWere you up?",
  ["6d:75e5"] = "Are you raising\nyour POKéMON?\012Hey, {STRBUF}'s\n{STRBUF} is\011looking good!",
  ["6d:7624"] = "Good morning.",
  ["6f:5aa9"] = "I'm the DAY-CARE\nMAN. Want me to\011raise a POKéMON?",
  ["6f:5ad8"] = "I'm the DAY-CARE\nMAN. Do you know\011about EGGS?\012I was raising\nPOKéMON with my\011wife, you see.\012We were shocked to\nfind an EGG!\012How incredible is\nthat?\012So, want me to\nraise a POKéMON?",
  ["6f:5b85"] = "I'm the DAY-CARE\nLADY.\012Should I raise a\nPOKéMON for you?",
  ["6f:5bbb"] = "I'm the DAY-CARE\nLADY. Do you know\011about EGGS?\012My husband and I\nwere raising some\011POKéMON, you see.\012We were shocked to\nfind an EGG!\012How incredible\ncould that be?\012Should I raise a\nPOKéMON for you?",
  ["6f:5c79"] = "What should I\nraise for you?",
  ["6f:5c97"] = "Oh? But you have\njust one POKéMON.",
  ["6f:5cb8"] = "Sorry, but I can't\naccept an EGG.",
  ["6f:5cda"] = "Remove MAIL before\nyou come see me.",
  ["6f:5cff"] = "If you give me\nthat, what will\011you battle with?",
  ["6f:5d30"] = "OK. I'll raise\nyour {STRBUF}.",
  ["6f:5d4b"] = "Come back for it\nlater.",
  ["6f:5d64"] = "Are we geniuses or\nwhat? Want to see\011your {STRBUF}?",
  ["6f:5d96"] = "Your {STRBUF}\nhas grown a lot.\012By level, it's\ngrown by {NUM}.\012If you want your\nPOKéMON back, it\011will cost ¥{NUM}.",
  ["6f:5e04"] = "Perfect! Here's\nyour POKéMON.",
  ["6f:5e1f"] = "{PLAYER} got back\n{STRBUF}.",
  ["6f:5e32"] = "Huh? Back already?\nYour {STRBUF}\012needs a little\nmore time with us.\012If you want your\nPOKéMON back, it\011will cost ¥100.",
  ["6f:5ea2"] = "You have no room\nfor it.",
  ["6f:5ebc"] = "You don't have\nenough money.",
  ["6f:5ed9"] = "Oh, fine then.",
  ["6f:5ee9"] = "Come again.",
  ["6f:5ef6"] = "Not yet…",
  ["6f:5f00"] = "Ah, it's you!\012We were raising\nyour POKéMON, and\012my goodness, were\nwe surprised!\012Your POKéMON had\nan EGG!\012We don't know how\nit got there, but\012your POKéMON had\nit. You want it?",
  ["6f:5fa5"] = "{PLAYER} received\nthe EGG!",
  ["6f:5fba"] = "Take good care of\nit.",
  ["6f:5fd1"] = "Well then, I'll\nkeep it. Thanks!",
  ["6f:5ff2"] = "You have no room\nin your party.\011Come back later.",
  ["70:4db0"] = "Huh?\012",
  ["70:4dba"] = "{STRBUF} came\nout of its EGG!",
  ["70:4dd8"] = "Give a nickname to\n{STRBUF}?",
  ["70:4df3"] = "It's {STRBUF}\nthat was left with\011the DAY-CARE LADY.",
  ["70:4e24"] = "It's {STRBUF}\nthat was left with\011the DAY-CARE MAN.",
  ["70:4e54"] = "It's brimming with\nenergy.",
  ["70:4e6f"] = "It has no interest\nin {STRBUF}.",
  ["70:4e8d"] = "It appears to care\nfor {STRBUF}.",
  ["70:4eac"] = "It's friendly with\n{STRBUF}.",
  ["70:4ec6"] = "It shows interest\nin {STRBUF}.",
  ["70:4ee3"] = "There's no MAIL\nhere.",
  ["70:4ef9"] = "The cleared MAIL\nwas put away.",
  ["70:4f19"] = "The PACK is full.",
  ["70:4f2c"] = "The MAIL's message\nwill be lost. OK?",
  ["70:4f51"] = "It's already hold-\ning an item.",
  ["70:4f71"] = "An EGG can't hold\nany MAIL.",
  ["70:4f8d"] = "The MAIL was moved\nfrom the MAILBOX.",
  ["70:502b"] = "There is a POKéMON\nholding MAIL.\012Please remove the\nMAIL.",
  ["70:5b6f"] = "Please remove the\nMAIL first.",
  ["70:5c22"] = "The MAIL will lose\nits message. OK?",
  ["70:5c47"] = "MAIL detached from\n{STRBUF}.",
  ["70:5c62"] = "There's no space\nfor removing MAIL.",
  ["70:5c86"] = "Send the removed\nMAIL to your PC?",
  ["70:5ca9"] = "Your PC's MAILBOX\nis full.",
  ["70:5cc4"] = "The MAIL was sent\nto your PC.",
  ["70:5d35"] = "Hello! Sorry to\nkeep you waiting!\012Welcome to the\nworld of POKéMON!\012My name is OAK.\012People call me the\nPOKéMON PROF.",
  ["70:5da4"] = "This world is in-\nhabited by crea-\011tures that we call\011POKéMON.",
  ["70:5de5"] = "People and POKéMON\nlive together by\012supporting each\nother.\012Some people play\nwith POKéMON, some\011battle with them.",
  ["70:5e51"] = "But we don't know\neverything about\011POKéMON yet.\012There are still\nmany mysteries to\011solve.\012That's why I study\nPOKéMON every day.",
  ["71:4000"] = "Now, what did you\nsay your name was?",
  ["71:4026"] = "{PLAYER}, are you\nready?\012Your very own\nPOKéMON story is\011about to unfold.\012You'll face fun\ntimes and tough\011challenges.\012A world of dreams\nand adventures\012with POKéMON\nawaits! Let's go!\012I'll be seeing you\nlater!",
  ["71:4bfd"] = "How many?",
  ["71:4c08"] = "{NUM} {STRBUF}(S)\nwill be ¥{NUM}.",
  ["71:4c28"] = "Hello, dear.\012I sell inexpensive\nherbal medicine.\012They're good, but\na trifle bitter.\012Your POKéMON may\nnot like them.\012Hehehehe…",
  ["71:4ca3"] = "How many?",
  ["71:4cae"] = "{NUM} {STRBUF}(S)\nwill be ¥{NUM}.",
  ["71:4cce"] = "Thank you, dear.\nHehehehe…",
  ["71:4cea"] = "Oh? Your PACK is\nfull, dear.",
  ["71:4d08"] = "Hehehe… You don't\nhave the money.",
  ["71:4d2a"] = "Come again, dear.\nHehehehe…",
